class ValidationFailure(RuntimeError):
    """Raised only by the isolated self-test."""


@dataclass(frozen=True)
class Artifact:
    path: str
    sha256: str


@dataclass(frozen=True)
class PathRule:
    path: str
    match: str

    @property
    def folded(self) -> str:
        return normalize_path(self.path).casefold()

    def intersects(self, other: "PathRule") -> bool:
        left, right = self.folded, other.folded
        if self.match == "exact" and other.match == "exact":
            return left == right
        if self.match == "prefix" and other.match == "prefix":
            return is_equal_or_child(left, right) or is_equal_or_child(right, left)
        prefix, exact = (self, other) if self.match == "prefix" else (other, self)
        return is_equal_or_child(exact.folded, prefix.folded)

    def matches(self, path: str) -> bool:
        folded = normalize_path(path).casefold()
        return folded == self.folded if self.match == "exact" else is_equal_or_child(
            folded, self.folded
        )


class Problems:
    def __init__(self) -> None:
        self.messages: list[str] = []

    def add(self, context: str, message: str) -> None:
        self.messages.append(f"{context}: {message}")

    def require(self, condition: bool, context: str, message: str) -> None:
        if not condition:
            self.add(context, message)


def validate_c0005_branch_header(
    record: dict[str, Any],
    wave: str,
    facts: dict[str, Any],
    problems: Problems,
    *,
    expected_status: str,
    context: str,
) -> None:
    """Pure exact-header ratchet shared by planned/active validation and tests."""

    expected_fields = {
        "schema_version": 1,
        "record_kind": "phase_branch",
        "phase_id": PHASE_ID,
        "branch_id": facts["branch_id"],
        "wave_id": wave,
        "branch_name": facts["branch_name"],
        "lane_id": "claude-lane",
        "owner_id": "primary-human",
        "operator_ids": facts["operators"],
        "base_checkpoint_id": C0004_CHECKPOINT_ID,
        "base_sha": C0004_CODE_SHA,
        "baseline_projection_id": facts["projection_id"],
        "shared_request_ids": [facts["request_id"]],
        "status": expected_status,
    }
    for key, expected in expected_fields.items():
        problems.require(
            record.get(key) == expected,
            f"{context}.{key}",
            f"expected exact {expected_status} value {expected!r}",
        )


def validate_c0005_epoch_state(
    statuses: dict[str, Any],
    *,
    current_checkpoint_id: str,
    activation_review_exists: bool,
    c0005_checkpoint_exists: bool,
    problems: Problems,
    context: str,
) -> str | None:
    """Require one synchronous R04/R08 state across the C0005 boundary."""

    expected_waves = set(C0005_BRANCH_FACTS)
    problems.require(
        set(statuses) == expected_waves,
        f"{context}.status",
        f"expected statuses for exactly {sorted(expected_waves)}",
    )
    values = set(statuses.values())
    state = next(iter(values)) if len(values) == 1 else None
    allowed_states = (
        {"planned", "active", "delivered"}
        if current_checkpoint_id == C0004_CHECKPOINT_ID
        else {"accepted"}
        if current_checkpoint_id in {
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }
        else set()
    )
    problems.require(
        state in allowed_states,
        f"{context}.status",
        f"checkpoint {current_checkpoint_id} requires a synchronous state in "
        f"{sorted(allowed_states)}; found {statuses!r}",
    )
    if state == "planned":
        problems.require(
            not activation_review_exists,
            f"{context}.activation",
            "planned state must not create reviews/R04-R08-activation.md",
        )
    elif state in {"active", "delivered", "accepted", "retired"}:
        problems.require(
            activation_review_exists,
            f"{context}.activation",
            f"{state} state requires reviews/R04-R08-activation.md",
        )
    if current_checkpoint_id == C0004_CHECKPOINT_ID:
        problems.require(
            not c0005_checkpoint_exists,
            f"{context}.checkpoint",
            "pre-acceptance R04/R08 state must not create checkpoints/C0005.json",
        )
    elif current_checkpoint_id in {
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
        problems.require(
            c0005_checkpoint_exists,
            f"{context}.checkpoint",
            "accepted R04/R08 state requires checkpoints/C0005.json",
        )
    return state


def validate_c0005_branch_lifecycle(
    record: dict[str, Any],
    facts: dict[str, Any],
    state: str,
    problems: Problems,
    *,
    context: str,
) -> None:
    """Lifecycle/evidence ratchet for C0004-rooted workers.

    Planned/active keep a null delivery. Delivered pins the immutable tip with
    null integration. Accepted/retired change only exact C0005 lifecycle data.
    """

    if state in {"delivered", "accepted", "retired"}:
        expected_delivery = {
            "commit_sha": facts["delivery_sha"],
            "report": {
                "path": facts["delivery_report"][0],
                "sha256": facts["delivery_report"][1],
            },
            "scope_evidence": {
                "path": facts["delivery_scope"][0],
                "sha256": facts["delivery_scope"][1],
            },
        }
    else:
        expected_delivery = {"commit_sha": None, "report": None, "scope_evidence": None}
    terminal = state in {"accepted", "retired"}
    expected_integration = (
        {
            "accepted_checkpoint_id": C0005_CHECKPOINT_ID,
            "accepted_sha": C0005_CODE_SHA,
            "method": "merge",
        }
        if terminal
        else {
            "accepted_checkpoint_id": None,
            "accepted_sha": None,
            "method": None,
        }
    )
    retirement_common = {
        "remote_ref": facts["remote_ref"],
        "rule": "delivery_ancestor_of_green_checkpoint",
    }
    expected_retirement: dict[str, Any] | None
    if state == "accepted":
        expected_retirement = {
            "ancestry_checkpoint_id": None,
            **retirement_common,
            "retired_at": None,
            "retired_by": None,
            "status": "due",
        }
    elif state == "retired":
        retirement = record.get("retirement")
        retired_at = retirement.get("retired_at") if isinstance(retirement, dict) else None
        actual_without_time = (
            {key: value for key, value in retirement.items() if key != "retired_at"}
            if isinstance(retirement, dict)
            else {}
        )
        problems.require(
            actual_without_time
            == {
                "ancestry_checkpoint_id": C0005_CHECKPOINT_ID,
                **retirement_common,
                "retired_by": "primary-human",
                "status": "retired",
            }
            and isinstance(retired_at, str)
            and RFC3339_RE.fullmatch(retired_at) is not None,
            f"{context}.retirement",
            "retirement requires exact C0005 ancestry, primary-human authority, "
            "and RFC3339 time",
        )
        expected_retirement = None
    else:
        expected_retirement = {
            "ancestry_checkpoint_id": None,
            **retirement_common,
            "retired_at": None,
            "retired_by": None,
            "status": "not_due",
        }
    problems.require(
        record.get("delivery") == expected_delivery,
        f"{context}.delivery",
        "delivered/terminal worker must pin the exact immutable tip and evidence"
        if state in {"delivered", "accepted", "retired"}
        else "planned/active worker must retain the exact null delivery record",
    )
    problems.require(
        record.get("integration") == expected_integration,
        f"{context}.integration",
        "terminal worker must record exact C0005 merge acceptance"
        if terminal
        else "pre-acceptance worker must retain the exact null integration record",
    )
    if expected_retirement is not None:
        problems.require(
            record.get("retirement") == expected_retirement,
            f"{context}.retirement",
            "accepted worker must retain due/null retirement metadata"
            if state == "accepted"
            else "pre-acceptance worker must retain not-due retirement metadata",
        )

    refresh = record.get("refresh")
    evidence: Any = None
    if not isinstance(refresh, dict) or set(refresh) != {
        "decision",
        "evidence",
        "reviewed_checkpoint_id",
    }:
        problems.add(
            f"{context}.refresh",
            "expected exactly decision/evidence/reviewed_checkpoint_id",
        )
    else:
        problems.require(
            refresh.get("decision") == "current"
            and refresh.get("reviewed_checkpoint_id") == C0004_CHECKPOINT_ID,
            f"{context}.refresh",
            "must remain a current refresh against exact C0004",
        )
        evidence = refresh.get("evidence")
    parsed: list[Artifact] = []
    if not isinstance(evidence, list):
        problems.add(f"{context}.refresh.evidence", "expected a hash-pinned list")
    else:
        for index, item in enumerate(evidence):
            item_context = f"{context}.refresh.evidence[{index}]"
            if not isinstance(item, dict) or set(item) != {"path", "sha256"}:
                problems.add(item_context, "expected exactly {path, sha256}")
                continue
            path, digest = item.get("path"), item.get("sha256")
            if not isinstance(path, str) or not isinstance(digest, str):
                problems.add(item_context, "path and sha256 must be strings")
                continue
            if SHA256_RE.fullmatch(digest) is None:
                problems.add(item_context, "sha256 must be 64 hexadecimal characters")
                continue
            parsed.append(Artifact(normalize_path(path), digest.upper()))
    evidence_paths = [artifact.path for artifact in parsed]
    problems.require(
        evidence_paths == sorted(evidence_paths)
        and len(evidence_paths) == len(set(evidence_paths)),
        f"{context}.refresh.evidence",
        "evidence paths must remain sorted and unique",
    )
    activation = tuple(
        artifact
        for artifact in parsed
        if artifact.path == C0005_ACTIVATION_REVIEW_PATH
    )
    if state == "planned":
        problems.require(
            not activation
            and not any(
                any(token in path.casefold() for token in ("activation", "base-tip", "ref-tip", "worktree"))
                for path in evidence_paths
            ),
            f"{context}.refresh.evidence",
            "planned state may not carry activation/ref/worktree evidence",
        )
    elif state in {"active", "delivered", "accepted", "retired"}:
        problems.require(
            activation
            == (
                Artifact(
                    C0005_ACTIVATION_REVIEW_PATH,
                    C0005_ACTIVATION_REVIEW_SHA256,
                ),
            ),
            f"{context}.refresh.evidence",
            f"{state} state must hash-pin exactly the reviewed R04/R08 activation",
        )


def validate_c0005_request_lifecycle(
    request_records: dict[str, dict[str, Any]],
    union_matches_lifecycle: bool,
    problems: Problems,
    *,
    state: str,
    gate_evidence_sha256: str = C0005_CANDIDATE_GATES_SHA256,
    context: str,
) -> None:
    """Keep requests unresolved before C0005 and exact after acceptance."""

    unresolved = {
        "checkpoint_id": None,
        "commit_sha": None,
        "reason": None,
        "resolved_at": None,
        "resolved_by": None,
        "validation_evidence": [],
    }
    terminal = state in {"accepted", "retired"}
    expected_without_time = {
        "checkpoint_id": C0005_CHECKPOINT_ID,
        "commit_sha": C0005_CODE_SHA,
        "reason": C0005_APPLIED_RESOLUTION_REASON,
        "resolved_by": "primary-human",
        "validation_evidence": [
            {
                "path": f"{DEFAULT_PHASE_DIR.as_posix()}/checkpoints/C0005-gates.md",
                "sha256": gate_evidence_sha256,
            }
        ],
    }
    for request_id in ("R0009", "R0010"):
        record = request_records.get(request_id)
        if terminal:
            resolution = record.get("resolution") if isinstance(record, dict) else None
            resolved_at = resolution.get("resolved_at") if isinstance(resolution, dict) else None
            actual_without_time = (
                {key: value for key, value in resolution.items() if key != "resolved_at"}
                if isinstance(resolution, dict)
                else {}
            )
            problems.require(
                isinstance(record, dict)
                and record.get("status") == "applied"
                and actual_without_time == expected_without_time
                and isinstance(resolved_at, str)
                and RFC3339_RE.fullmatch(resolved_at) is not None,
                f"{context}[{request_id}]",
                "applied request must record exact C0005 evidence and authority",
            )
        else:
            problems.require(
                isinstance(record, dict)
                and record.get("status") == "active"
                and record.get("resolution") == unresolved,
                f"{context}[{request_id}]",
                "request must remain active, unresolved, and unapplied",
            )
    problems.require(
        union_matches_lifecycle,
        f"{context}.union",
        "all 37 union paths must match the exact lifecycle postimages",
    )


def validate_c0005_retired_projection(
    record: dict[str, Any],
    active_record: dict[str, Any],
    problems: Problems,
    *,
    context: str,
) -> None:
    """Permit acceptance to retire a projection and change nothing else."""

    expected = {**active_record, "status": "retired"}
    problems.require(
        record == expected,
        context,
        "C0005 acceptance may change only projection status from active to retired",
    )


def validate_c0005_milestone_lifecycle(
    milestone_map: dict[str, dict[str, Any]],
    state: str,
    problems: Problems,
    *,
    context: str,
    m07_accepted: bool = False,
) -> None:
    """Ratchet M04/M08 to accepted and make M07 ready only at C0005."""

    accepted = state == "accepted"
    for milestone_id in ("M04", "M08"):
        milestone = milestone_map.get(milestone_id)
        problems.require(
            isinstance(milestone, dict)
            and milestone.get("status") == ("accepted" if accepted else "ready")
            and milestone.get("accepted_checkpoint_id")
            == (C0005_CHECKPOINT_ID if accepted else None),
            f"{context}[{milestone_id}]",
            "must remain ready before C0005 and be accepted exactly at C0005",
        )
    m07 = milestone_map.get("M07")
    expected_m07_status = (
        "accepted"
        if m07_accepted
        else "ready"
        if accepted
        else "planned"
    )
    problems.require(
        isinstance(m07, dict)
        and m07.get("status") == expected_m07_status
        and m07.get("accepted_checkpoint_id")
        == (C0006_CHECKPOINT_ID if m07_accepted else None),
        f"{context}[M07]",
        "M07 must remain planned before C0005, become ready at C0005, and be "
        "accepted exactly at C0006",
    )


def validate_c0005_live_ancestry(
    returncode: int,
    problems: Problems,
    *,
    context: str,
) -> None:
    """Require the exact integrated code to remain reachable from live HEAD."""

    problems.require(
        returncode == 0,
        context,
        f"exact C0005 code {C0005_CODE_SHA} must be an ancestor of live HEAD",
    )


def ratchet_c0005_terminal_evidence(
    record: dict[str, Any],
    replacements: dict[str, str],
    problems: Problems,
    *,
    context: str,
) -> dict[str, Any]:
    """Refresh exactly the terminal P/R evidence hashes in a branch postimage."""

    expected = json.loads(json.dumps(record))
    refresh = expected.get("refresh")
    evidence = refresh.get("evidence") if isinstance(refresh, dict) else None
    if not isinstance(evidence, list):
        problems.add(context, "branch refresh evidence must be a list")
        return expected
    seen = Counter()
    for item in evidence:
        if not isinstance(item, dict):
            continue
        path = item.get("path")
        if path in replacements:
            digest = replacements[path]
            problems.require(
                SHA256_RE.fullmatch(digest) is not None,
                f"{context}[{path}]",
                "terminal evidence replacement must be an exact SHA-256",
            )
            item["sha256"] = digest
            seen[path] += 1
    problems.require(
        seen == Counter({path: 1 for path in replacements}),
        context,
        "branch must hash-pin exactly one terminal projection and request postimage",
    )
    return expected


def validate_c0005_final_gate_text(
    text: str,
    accepted_at: str,
    problems: Problems,
    *,
    context: str,
) -> None:
    """Require an authority-complete final report, not the candidate handoff."""

    lowered = text.casefold()
    invalid_acceptance_status_lines = [
        line
        for line in lowered.splitlines()
        if "acceptance status" in line
        and ("pending" in line or "blocked" in line or "expected to fail" in line)
    ]
    problems.require(
        re.search(
            r"(?is)(?:pending.{0,60}primary-human|primary-human.{0,60}pending)",
            text,
        )
        is None
        and not invalid_acceptance_status_lines,
        context,
        "final gate report must not retain pending primary-human acceptance",
    )
    for token, label in (
        (C0005_CHECKPOINT_ID, "checkpoint id"),
        (C0005_CODE_SHA, "integrated code SHA"),
        (accepted_at, "authorized acceptance time"),
        ("primary-human", "acceptance authority"),
        ("acceptance-control", "acceptance-control label"),
        (C0005_COMBINED_BASELINE_SHA256, "generated baseline evidence"),
        (C0005_INVENTORY_SHA256, "generated inventory evidence"),
        (C0005_INTEGRATOR_LEDGER_SHA256, "generated integration-ledger evidence"),
    ):
        problems.require(
            token.casefold() in lowered,
            context,
            f"final report must record {label} {token!r}",
        )
    problems.require(
        re.search(r"(?im)^.*acceptance status.*accepted.*$", text) is not None,
        context,
        "final report must state accepted status",
    )
    problems.require(
        re.search(
            r"(?is)(?:integrated|code).{0,240}(?:ci|gate|build).{0,240}"
            r"(?:success|successful|succeeded|pass)",
            text,
        )
        is not None
        and (
            re.search(r"(?is)acceptance-control.{0,600}(?:defer|later)", text)
            is not None
            or re.search(r"(?is)(?:defer|later).{0,600}acceptance-control", text)
            is not None
        )
        and "separate control" in lowered
        and re.search(
            r"(?is)(?:(?:sha|commit).{0,240}(?:ci|run|job)|"
            r"(?:ci|run|job).{0,240}(?:sha|commit))",
            text,
        )
        is not None,
        context,
        "final report must record successful code gates and defer exact acceptance-control "
        "SHA/CI attestation to the later separate control",
    )


def validate_c0005_union_materialization(
    path: str,
    expected_sha256: str | None,
    live_sha256: str | None,
    code_sha256: str | None,
    terminal: bool,
    problems: Problems,
    *,
    context: str,
) -> None:
    """Allow only an independently validated acceptance narrative after ad92."""

    acceptance_overlap = terminal and path in C0005_ACCEPTANCE_NARRATIVE_PATHS
    actual = code_sha256 if acceptance_overlap else live_sha256
    problems.require(
        expected_sha256 is not None and actual == expected_sha256,
        context,
        (
            "exact integrated code must retain the reviewed union postimage before "
            "the live acceptance narrative"
            if acceptance_overlap
            else "delivered tree must materialize the reviewed union postimage"
        ),
    )


def validate_c0005_acceptance_commit_shape(
    parent_sha: str,
    changed_paths: set[str],
    problems: Problems,
    *,
    context: str,
) -> None:
    """Hold the authority control to one direct child and exactly 19 paths."""

    problems.require(
        parent_sha == C0005_CODE_SHA,
        f"{context}.parent",
        f"acceptance-control HEAD must have direct parent {C0005_CODE_SHA}",
    )
    problems.require(
        changed_paths == C0005_ACCEPTANCE_CONTROL_PATHS
        and len(changed_paths) == len(C0005_ACCEPTANCE_CONTROL_PATHS) == 19,
        f"{context}.paths",
        "acceptance-control diff must contain every and only the exact 19 bounded paths; "
        f"missing={sorted(C0005_ACCEPTANCE_CONTROL_PATHS - changed_paths)}, "
        f"extra={sorted(changed_paths - C0005_ACCEPTANCE_CONTROL_PATHS)}",
    )


def validate_c0005_acceptance_narrative(
    text: str,
    problems: Problems,
    *,
    context: str,
    r07_active: bool = False,
    r07_delivered: bool = False,
) -> None:
    """Require each acceptance narrative to carry the same material facts."""

    for token, label in (
        (C0005_CHECKPOINT_ID, "C0005"),
        (C0005_CODE_SHA, "integrated code SHA"),
        ("2,818", "production total"),
        ("2,685", "classified total"),
        ("133", "unclassified total"),
    ):
        problems.require(token in text, context, f"narrative must record {label} {token!r}")
    problems.require(
        re.search(r"(?i)(?:\b0\b|\bzero\b)\s+mixed", text) is not None,
        context,
        "narrative must record zero mixed modules",
    )
    for milestone in ("M04", "M08"):
        problems.require(
            re.search(
                rf"(?is)(?:{milestone}.{{0,100}}accepted|accepted.{{0,100}}{milestone})",
                text,
            )
            is not None,
            context,
            f"narrative must record {milestone} accepted",
        )
    problems.require(
        re.search(r"(?is)(?:M07.{0,100}ready|ready.{0,100}M07)", text) is not None,
        context,
        "narrative must record M07 ready",
    )
    if r07_delivered:
        problems.require(
            re.search(r"(?is)(?:R07.{0,120}delivered|delivered.{0,120}R07)", text)
            is not None,
            context,
            "narrative must record the delivered-but-unaccepted R07 boundary",
        )
    elif r07_active:
        problems.require(
            re.search(r"(?is)(?:R07.{0,120}active|active.{0,120}R07)", text)
            is not None,
            context,
            "narrative must record the active R07 activation boundary",
        )
    else:
        problems.require(
            re.search(r"(?is)(?:R07.{0,120}blocked|blocked.{0,120}R07)", text)
            is not None,
            context,
            "narrative must record the still-blocked R07 activation boundary",
        )


def validate_c0005_activation_review_text(
    text: str,
    problems: Problems,
    *,
    context: str = C0005_ACTIVATION_REVIEW_PATH,
) -> None:
    """Validate hash-pinned external ref/worktree facts without Git/network I/O."""

    activated = re.search(
        r"^- Activation time \(RFC3339 UTC\): `([^`\r\n]+)`\.\s*$",
        text,
        re.MULTILINE,
    )
    problems.require(
        activated is not None
        and RFC3339_RE.fullmatch(activated.group(1)) is not None
        and activated.group(1).endswith("Z"),
        f"{context}.activation_time",
        "activation time must be an exact RFC3339 UTC timestamp",
    )
    exact_lines = {
        "- Activation authority: `primary-human`, exercising the authorized "
        "branch-registry, new-ref, named-worktree, activation-control, main commit/push, "
        "and CI-monitoring controls.",
        f"- Planned-control commit: `{C0005_PLANNED_CONTROL_SHA}`.",
        "- Planned-control Lean CI: run "
        f"`{C0005_PLANNED_CONTROL_CI_RUN}`, build job `{C0005_PLANNED_CONTROL_CI_JOB}`, "
        f"exact head `{C0005_PLANNED_CONTROL_SHA}`, conclusion `success`.",
        "- Immutable worker base: checkpoint "
        f"`{C0004_CHECKPOINT_ID}`, commit `{C0004_CODE_SHA}`.",
        "- C0004 raw dependency graph SHA-256: "
        f"`{C0004_RAW_DEPENDENCY_TSV_SHA256}`.",
    }
    text_lines = set(text.splitlines())
    for line in sorted(exact_lines):
        problems.require(
            line in text_lines,
            f"{context}.identity",
            f"activation review is missing exact line {line!r}",
        )

    for wave, facts in C0005_BRANCH_FACTS.items():
        expected_row = (
            f"| `{facts['branch_id']}` | `{wave}` | {facts['assignment']} | "
            f"`{facts['branch_name']}` | `{C0004_CODE_SHA}` | `{facts['remote_ref']}` | "
            f"`{C0004_CODE_SHA}` | `{facts['planned_worktree']}` | `{C0004_CODE_SHA}` | "
            f"`claude-lane` | `{json.dumps(facts['operators'])}` | "
            f"`{facts['implementation_operator']}` |"
        )
        problems.require(
            expected_row in text_lines,
            f"{context}.{facts['branch_id']}",
            "activation review must record the exact branch/base/ref/worktree/lane/operator row",
        )
        mapping = f"- `{facts['remote_ref']}:{facts['remote_ref']}`"
        lease = f"- `--force-with-lease={facts['remote_ref']}:`"
        for line, label in ((mapping, "explicit ref mapping"), (lease, "nonexistent-tip lease")):
            problems.require(
                line in text_lines,
                f"{context}.{facts['branch_id']}",
                f"activation review must record exact {label}",
            )

    required_fragments = (
        "Both local branches were created explicitly at exact C0004, never at the planned-control commit.",
        "Both remote refs were created in one atomic push with these explicit mappings:",
        "The atomic push used explicit nonexistent-tip leases for both new refs:",
        "The remote tips were independently re-read after creation and both equal exact C0004.",
        "Each named worktree has worktree-scoped `core.autocrlf=false`, `core.eol=lf`, and `core.safecrlf=false`.",
        "empty tracked and untracked status",
        "zero tracked `w/crlf` entries",
        "No implementation or build state exists in either worktree.",
        "`P0008` and `P0009` remain active and unchanged.",
        "`R0009` and `R0010` remain active and unchanged, with null resolutions.",
        "Their reviewed 37-path common-base union remains integrator-only and unapplied",
        f"`phase.json` remains byte-identical at SHA-256 `{C0005_PLANNED_PHASE_SHA256}`.",
        "C0004 remains current and immutable, and M04/M08 readiness remains unchanged.",
        "No worker commit, production or test edit, request application, Lean build, delivery, integration, or `C0005` checkpoint exists.",
        "serialize under `Local\\lean-reorganization-2026-08`",
        "Both workers remain frozen until the activation-control commit itself passes exact Lean CI, including its exact `build` job.",
        "does not begin R04 or R08 implementation.",
    )
    for fragment in required_fragments:
        problems.require(
            fragment in text,
            f"{context}.claims",
            f"activation review is missing exact fact {fragment!r}",
        )


