def r03_activation_fact(text: str, label: str) -> str | None:
    """Read one exact-value row from the activation review's fact table."""

    match = re.search(
        rf"^\|\s*{re.escape(label)}\s*\|\s*`([^`\r\n]+)`\s*\|\s*$",
        text,
        re.MULTILINE,
    )
    return match.group(1) if match is not None else None


def validate_r03_activation_review_text(
    text: str, problems: Problems, *, context: str = R03_ACTIVATION_REVIEW_PATH
) -> None:
    """Validate the human-reviewed external activation facts without Git/network I/O."""

    activated = re.search(r"^- Activated at: `([^`\r\n]+)`\s*$", text, re.MULTILINE)
    problems.require(
        activated is not None
        and RFC3339_RE.fullmatch(activated.group(1)) is not None,
        f"{context}.activated_at",
        "activation time must be an exact RFC3339 timestamp",
    )
    exact_lines = (
        (
            "- Authority: `primary-human`, exercising the explicitly granted "
            "branch-registry, activation-control, main-push, and worktree-creation authority",
            "primary-human activation authority",
        ),
        (f"- Branch / wave: `{R03_BRANCH_ID}` / `{R03_WAVE_ID}`", "branch/wave"),
        (f"- Lane / operator: `{R03_LANE_ID}` / `{R03_OPERATOR_ID}`", "lane/operator"),
        (f"- Current checkpoint: `{C0002_CHECKPOINT_ID}`", "current checkpoint"),
        (
            "- Accepted C0002 checkpoint and immutable worker base: "
            f"`{C0002_CODE_SHA}`",
            "accepted checkpoint/base",
        ),
        (f"- Planned-control commit: `{R03_PLANNED_CONTROL_SHA}`", "planned-control commit"),
        (
            "- Planned-control CI: Lean CI push run "
            f"`{R03_PLANNED_CONTROL_CI_RUN}`, job `{R03_PLANNED_CONTROL_CI_JOB}`, "
            "completed `success`",
            "planned-control CI",
        ),
    )
    text_lines = set(text.splitlines())
    for exact, label in exact_lines:
        problems.require(
            exact in text_lines,
            f"{context}.identity",
            f"activation review must record exact {label}",
        )

    expected_facts = {
        "Local branch": R03_BRANCH_NAME,
        "Local branch tip": C0002_CODE_SHA,
        "Remote ref": R03_REMOTE_REF,
        "Remote ref tip": C0002_CODE_SHA,
        "Named worktree": R03_PLANNED_WORKTREE,
        "Worktree HEAD": C0002_CODE_SHA,
    }
    actual_facts = {
        label: r03_activation_fact(text, label) for label in expected_facts
    }
    for label, expected in expected_facts.items():
        problems.require(
            actual_facts[label] == expected,
            f"{context}.tips",
            f"{label} must equal exact activation fact {expected!r}",
        )

    required_statements = (
        (
            "The planned-control gate was green for the exact planned-control commit "
            "before any B0005 ref or worktree was created.",
            "green planned-control ordering",
        ),
        ("explicit nonexistent-tip lease", "nonexistent-tip lease"),
        ("empty tracked and untracked status", "clean tracked/untracked worktree"),
        ("No worker commit, production edit, or R0005 application exists.", "no worker edit"),
        ("R07 remains unactivated and M07 remains `planned`.", "R07/M07 deferral"),
        (
            "Workers may edit only B0005-owned paths, B0005 destination prefixes, "
            "`NumStabilityTest/Reorganization/R03/`, and "
            "`docs/architecture/deliveries/R03/`.",
            "worker scope",
        ),
        ("All 121 R0005 paths remain integrator-only.", "R0005 integrator ownership"),
        (
            "R0005 is context-free; any disposable replay must use "
            "`git apply --unidiff-zero`.",
            "context-free replay command",
        ),
        ("No implementation began before activation-control CI.", "implementation ordering"),
        ("full `NumStability` and `NumStabilityTest` build", "full activation build"),
        ("`core.autocrlf=false`", "LF autocrlf setting"),
        ("`core.eol=lf`", "LF eol setting"),
        ("`core.safecrlf=false`", "LF safecrlf setting"),
    )
    for statement, label in required_statements:
        problems.require(
            statement in text,
            f"{context}.claims",
            f"activation review must record exact {label}",
        )


def validate_r03_epoch_snapshot(
    snapshot: R03EpochSnapshot,
    problems: Problems,
    *,
    expected_route_sha256: str,
    expected_r07_status: str = "planned",
) -> None:
    """Enforce the exact R03 lifecycle independently of file I/O."""

    context = "C0002-rooted R03 epoch"
    problems.require(
        snapshot.branch_base_checkpoint_id == C0002_CHECKPOINT_ID
        and snapshot.branch_base_sha == C0002_CODE_SHA,
        f"{context}.base",
        f"branch must use exact {C0002_CHECKPOINT_ID} code {C0002_CODE_SHA}",
    )
    problems.require(
        snapshot.selector_sha256 == R03_SELECTOR_SHA256
        and snapshot.projection_selector_sha256 == R03_SELECTOR_SHA256
        and snapshot.selector_rows == R03_OWNER_COUNT
        and snapshot.selector_matches_inventory,
        f"{context}.selector",
        "selector drift: branch/projection selector must be the exact sorted 47-owner C0002 R03 wave",
    )
    problems.require(
        snapshot.route_sha256 == expected_route_sha256,
        f"{context}.routes",
        f"route/hash drift: expected declaration-route SHA-256 {expected_route_sha256}",
    )
    terminal = snapshot.branch_status in {"accepted", "retired"}
    allowed_lane_operators = (
        # After R03 turns terminal the lane drops to codex-local alone until the
        # reviewed R05/R06 planning control re-expands it for B0006 only.
        {(R03_OPERATOR_ID,), R05R06_OPERATOR_PAIR} if terminal else {R03_OPERATOR_IDS}
    )
    problems.require(
        snapshot.operator_ids == R03_OPERATOR_IDS
        and snapshot.lane_operator_ids in allowed_lane_operators,
        f"{context}.authority",
        "unauthorized operator: branch history must retain the reviewed pair while "
        "codex-lane must carry the pair before C0003 and codex-local alone after it "
        "(or the reviewed B0006-scoped R05/R06 re-expansion)",
    )
    expected_activation = Artifact(
        R03_ACTIVATION_REVIEW_PATH, R03_ACTIVATION_REVIEW_SHA256
    )
    problems.require(
        snapshot.branch_status in {"planned", "active", "accepted", "retired"},
        f"{context}.activation",
        "branch status must be exactly planned, active, accepted, or retired",
    )
    if snapshot.branch_status == "planned":
        problems.require(
            not snapshot.activation_evidence,
            f"{context}.activation",
            "planned epoch may not carry activation/base-tip/ref-tip/worktree evidence",
        )
    elif snapshot.branch_status == "active":
        problems.require(
            snapshot.activation_evidence == (expected_activation,),
            f"{context}.activation",
            "active epoch must hash-pin exactly the reviewed R03 activation evidence",
        )
    elif terminal:
        problems.require(
            snapshot.activation_evidence == (expected_activation,),
            f"{context}.activation",
            "accepted/retired epoch must retain the exact historical activation evidence",
        )
    expected_delivery = {
        "commit_sha": None,
        "report": None,
        "scope_evidence": None,
    }
    expected_integration = {
        "method": None,
        "accepted_checkpoint_id": None,
        "accepted_sha": None,
    }
    expected_retirement = {
        "remote_ref": R03_REMOTE_REF,
        "rule": "delivery_ancestor_of_green_checkpoint",
        "status": "not_due",
        "retired_at": None,
        "retired_by": None,
        "ancestry_checkpoint_id": None,
    }
    expected_resolution = {
        "checkpoint_id": None,
        "commit_sha": None,
        "reason": None,
        "resolved_at": None,
        "resolved_by": None,
        "validation_evidence": [],
    }
    base_lifecycle = (
        snapshot.projection_base_checkpoint_id == C0002_CHECKPOINT_ID
        and snapshot.request_target_checkpoint_id == C0002_CHECKPOINT_ID
        and snapshot.request_target_base_sha == C0002_CODE_SHA
    )
    if terminal:
        expected_delivery = {
            "commit_sha": R03_DELIVERY_SHA,
            "report": {
                "path": R03_DELIVERY_REPORT[0],
                "sha256": R03_DELIVERY_REPORT[1],
            },
            "scope_evidence": {
                "path": R03_DELIVERY_SCOPE[0],
                "sha256": R03_DELIVERY_SCOPE[1],
            },
        }
        expected_integration = {
            "method": "merge",
            "accepted_checkpoint_id": C0003_CHECKPOINT_ID,
            "accepted_sha": C0003_CODE_SHA,
        }
        resolution = snapshot.request_resolution
        resolution_time = resolution.get("resolved_at")
        expected_resolution_without_time = {
            "checkpoint_id": C0003_CHECKPOINT_ID,
            "commit_sha": C0003_CODE_SHA,
            "reason": R03_ACCEPTED_RESOLUTION_REASON,
            "resolved_by": "primary-human",
            "validation_evidence": [
                {
                    "path": (
                        f"{R03_PHASE_PREFIX}/checkpoints/C0003-gates.md"
                    ),
                    "sha256": C0003_GATES_SHA256,
                }
            ],
        }
        actual_resolution_without_time = {
            key: value for key, value in resolution.items() if key != "resolved_at"
        }
        problems.require(
            snapshot.delivery == expected_delivery
            and snapshot.integration == expected_integration
            and base_lifecycle
            and snapshot.projection_status == "retired"
            and snapshot.request_status == "applied"
            and actual_resolution_without_time == expected_resolution_without_time
            and isinstance(resolution_time, str)
            and RFC3339_RE.fullmatch(resolution_time) is not None,
            f"{context}.lifecycle",
            "accepted/retired lifecycle requires exact delivery, merge integration, "
            "retired C0002 projection, and C0003/e20 applied-request resolution",
        )
        retirement_common = {
            "remote_ref": R03_REMOTE_REF,
            "rule": "delivery_ancestor_of_green_checkpoint",
        }
        if snapshot.branch_status == "accepted":
            expected_terminal_retirement = {
                **retirement_common,
                "status": "due",
                "retired_at": None,
                "retired_by": None,
                "ancestry_checkpoint_id": None,
            }
            problems.require(
                snapshot.retirement == expected_terminal_retirement,
                f"{context}.retirement",
                "accepted B0005 must have exact due retirement state",
            )
        else:
            retired_at = snapshot.retirement.get("retired_at")
            expected_retired_without_time = {
                **retirement_common,
                "status": "retired",
                "retired_by": "primary-human",
                "ancestry_checkpoint_id": C0003_CHECKPOINT_ID,
            }
            actual_retired_without_time = {
                key: value
                for key, value in snapshot.retirement.items()
                if key != "retired_at"
            }
            problems.require(
                actual_retired_without_time == expected_retired_without_time
                and isinstance(retired_at, str)
                and RFC3339_RE.fullmatch(retired_at) is not None,
                f"{context}.retirement",
                "retired B0005 must record primary-human, C0003 ancestry, and RFC3339 time",
            )
    else:
        problems.require(
            snapshot.delivery == expected_delivery
            and snapshot.integration == expected_integration
            and snapshot.retirement == expected_retirement
            and base_lifecycle
            and snapshot.projection_status == "active"
            and snapshot.request_status == "active"
            and snapshot.request_resolution == expected_resolution,
            f"{context}.lifecycle",
            "invalid lifecycle transition: planned/active branch with null delivery+integration, not_due retirement, active projection, and unresolved active request required",
        )
    problems.require(
        snapshot.r07_milestone_status == expected_r07_status,
        f"{context}.r07",
        f"R07/M07 must remain unactivated and {expected_r07_status}",
    )
    problems.require(
        not snapshot.worker_shared_leaks
        and (
            len(snapshot.request_unreserved_paths) == 91
            if terminal
            else not snapshot.request_unreserved_paths
        ),
        f"{context}.shared_paths",
        "shared-path leakage: worker paths must avoid shared controls; active requests "
        "must be fully reserved and terminal requests must release exactly 91 request-only paths",
    )


def normalize_path(value: str) -> str:
    return value.replace("\\", "/").rstrip("/")


def is_equal_or_child(path: str, parent: str) -> bool:
    return path == parent or path.startswith(parent + "/")


def module_from_path(path: str) -> str:
    path = normalize_path(path)
    return path[:-5].replace("/", ".") if path.endswith(".lean") else path.replace("/", ".")


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest().upper()


def canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def path_list_sha256(paths: Iterable[str]) -> str:
    payload = ("\n".join(sorted(paths)) + "\n").encode("utf-8")
    return hashlib.sha256(payload).hexdigest().upper()


def parse_authenticated_r07_contract(
    payload: bytes,
    problems: Problems,
    *,
    expected_sha256: str = R07_PLANNED_CONTROL_CONTRACT_SHA256,
    context: str = "R07 planned-control contract",
) -> dict[str, Any] | None:
    """Authenticate exact bytes before parsing the R07 contract."""

    actual_sha256 = hashlib.sha256(payload).hexdigest().upper()
    if actual_sha256 != expected_sha256:
        problems.add(
            context,
            "present contract SHA-256 mismatch: "
            f"expected {expected_sha256}, found {actual_sha256}",
        )
        return None
    try:
        value = json.loads(payload.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as error:
        problems.add(context, f"authenticated contract is malformed: {error}")
        return None
    if not isinstance(value, dict):
        problems.add(context, "authenticated contract must be a JSON object")
        return None
    return value


def validate_r07_contract_availability(
    *,
    head: str,
    contract_present: bool,
    contract_authenticated: bool,
    legacy_change_paths: set[str],
    problems: Problems,
    context: str = "R07 planned-control contract",
) -> None:
    """Permit absence only at a clean immutable C0005 accepted control."""

    if head == R07_ACCEPTED_CONTROL_SHA:
        if not contract_present:
            problems.require(
                not legacy_change_paths,
                f"{context}.legacy_worktree",
                "contract may be absent at accepted C0005 only in a clean worktree; "
                f"found={sorted(legacy_change_paths)}",
            )
        return
    problems.require(
        contract_authenticated,
        f"{context}.required",
        "every HEAD after the pinned accepted C0005 control must carry the exact "
        "authenticated R07 contract",
    )


def validate_r07_contract_identity(
    contract: dict[str, Any],
    problems: Problems,
    *,
    context: str = "R07 planned-control contract",
) -> None:
    """Pure identity/lifecycle ratchet for the authenticated R07 contract."""

    expected_keys = {
        "accepted_control_sha",
        "artifact_hash_scope",
        "artifacts",
        "base_checkpoint_id",
        "base_code_sha",
        "branch_id",
        "counts",
        "headers",
        "lifecycle",
        "phase_id",
        "projected_remaining_queue",
        "projection_id",
        "record_kind",
        "request_id",
        "review_id",
        "reviewed_at",
        "schema_version",
        "wave_id",
    }
    problems.require(
        set(contract) == expected_keys,
        f"{context}.schema",
        f"expected exactly {sorted(expected_keys)}",
    )
    expected_identity = {
        "schema_version": 1,
        "record_kind": "r07_planned_control_contract",
        "phase_id": PHASE_ID,
        "base_checkpoint_id": C0005_CHECKPOINT_ID,
        "base_code_sha": C0005_CODE_SHA,
        "branch_id": "B0010",
        "projection_id": "P0010",
        "request_id": "R0011",
        "wave_id": "R07",
        "review_id": "R07-C0005-semantic-v1",
    }
    for key, expected in expected_identity.items():
        problems.require(
            contract.get(key) == expected,
            f"{context}.{key}",
            f"expected {expected!r}",
        )
    problems.require(
        contract.get("accepted_control_sha") == R07_ACCEPTED_CONTROL_SHA,
        f"{context}.accepted_control_sha",
        f"must equal pinned accepted control {R07_ACCEPTED_CONTROL_SHA}",
    )
    reviewed_at = contract.get("reviewed_at")
    problems.require(
        isinstance(reviewed_at, str) and RFC3339_RE.fullmatch(reviewed_at) is not None,
        f"{context}.reviewed_at",
        "must be an RFC3339 timestamp",
    )
    problems.require(
        contract.get("lifecycle")
        == {
            "branch_status": "planned",
            "milestone_status": "ready",
            "projection_status": "active",
            "request_status": "active",
        },
        f"{context}.lifecycle",
        "must describe exactly planned B0010, ready M07, active P0010/R0011",
    )
    phase_prefix = DEFAULT_PHASE_DIR.as_posix()
    problems.require(
        contract.get("artifact_hash_scope")
        == {
            "lifecycle_mutable_paths": [
                f"{phase_prefix}/branches/B0010.json",
                f"{phase_prefix}/phase.json",
                f"{phase_prefix}/projections/P0010.json",
                f"{phase_prefix}/requests/R0011.json",
            ],
            "mode": "planned_state_only",
        },
        f"{context}.artifact_hash_scope",
        "artifact hashes are valid only for the exact planned lifecycle",
    )
    problems.require(
        contract.get("projected_remaining_queue") == {"R09": 72, "R10": 18},
        f"{context}.projected_remaining_queue",
        "must be exactly R09=72 and R10=18",
    )
    counts = contract.get("counts")
    if not isinstance(counts, dict):
        problems.add(f"{context}.counts", "expected an object")
    else:
        for key, value in counts.items():
            problems.require(
                isinstance(key, str)
                and isinstance(value, int)
                and not isinstance(value, bool)
                and value >= 0,
                f"{context}.counts.{key}",
                "count must be a nonnegative integer",
            )
        for total, parts in (
            ("declarations", ("public_declarations", "private_declarations")),
            ("consumer_edges", ("internal_import_edges", "external_import_edges")),
        ):
            if all(isinstance(counts.get(key), int) for key in (total, *parts)):
                problems.require(
                    counts[total] == sum(counts[key] for key in parts),
                    f"{context}.counts.{total}",
                    f"must equal {' + '.join(parts)}",
                )
    headers = contract.get("headers")
    if not isinstance(headers, dict):
        problems.add(f"{context}.headers", "expected an object")
    else:
        for name, header in headers.items():
            problems.require(
                isinstance(name, str)
                and isinstance(header, list)
                and bool(header)
                and all(isinstance(column, str) and column for column in header)
                and len(header) == len(set(header)),
                f"{context}.headers.{name}",
                "header must be a nonempty duplicate-free list of strings",
            )


def validate_r07_relation_snapshot(
    snapshot: dict[str, Any],
    problems: Problems,
    *,
    context: str = "R07 planned-control relations",
) -> None:
    """Pure cross-artifact set/count checks, shared by runtime and self-tests."""

    owners = snapshot.get("owners")
    selector = snapshot.get("selector")
    routes = snapshot.get("routes")
    wrappers = snapshot.get("wrappers")
    problems.require(
        isinstance(owners, set)
        and owners == selector == routes == wrappers,
        f"{context}.owners",
        "selector, inventory/module routes, and wrappers must name one exact owner set",
    )
    projection_declarations = snapshot.get("projection_declarations")
    route_declarations = snapshot.get("route_declarations")
    source_declarations = snapshot.get("source_declarations")
    problems.require(
        isinstance(projection_declarations, set)
        and projection_declarations == route_declarations == source_declarations,
        f"{context}.declarations",
        "projection, declaration routes, and source commands must have exact identities",
    )
    private_declarations = snapshot.get("private_declarations")
    normalization = snapshot.get("normalization")
    closure = snapshot.get("closure")
    problems.require(
        isinstance(private_declarations, set)
        and private_declarations == normalization
        and isinstance(closure, set)
        and private_declarations <= closure,
        f"{context}.private",
        "every and only private declaration must be normalized and included in closure",
    )
    destinations = snapshot.get("destinations")
    tiers = snapshot.get("destination_tiers")
    dag_nodes = snapshot.get("dag_nodes")
    problems.require(
        isinstance(destinations, set)
        and destinations == tiers
        and isinstance(dag_nodes, set)
        and dag_nodes <= destinations,
        f"{context}.destinations",
        "destination tiers and DAG endpoints must be exact routed destinations",
    )


def validate_r07_planned_commit_shape(
    *,
    head: str,
    accepted_control: str,
    parents: Sequence[str],
    changed_paths: set[str],
    expected_changed_paths: set[str],
    overlay_paths: set[str],
    problems: Problems,
    context: str = "R07 planned-control commit",
) -> None:
    """Pure precommit/direct-child shape check for the planned control."""

    if head != accepted_control:
        problems.require(
            list(parents) == [accepted_control],
            f"{context}.parent",
            "committed planned control must be a single-parent direct child of accepted C0005",
        )
    problems.require(
        changed_paths == expected_changed_paths,
        f"{context}.paths",
        (
            "precommit worktree"
            if head == accepted_control
            else "committed planned control"
        )
        + " must change exact reviewed paths; "
        f"missing={sorted(expected_changed_paths - changed_paths)}, "
        f"extra={sorted(changed_paths - expected_changed_paths)}",
    )
    if head != accepted_control:
        problems.require(
            not overlay_paths,
            f"{context}.worktree",
            "committed planned control must have no staged, unstaged, or nonignored "
            f"untracked overlay; found={sorted(overlay_paths)}",
        )


def validate_r09_r10_activation_state(
    root: Path,
    problems: Problems,
    *,
    context: str = "R09/R10 activation",
) -> None:
    """Validate the activation record, its authority, and both active branches.

    The pair analogue of validate_r07_activation_record.  Two divergences from
    that precedent are deliberate and are asserted here rather than assumed:
    the primary review is a primary_human_activation_authorization, and the
    remote-ref creation source may be the local push reflog when the repository
    CreateEvent feed has surfaced nothing.
    """

    act_path = root / R09_R10_ACTIVATION_PATH
    auth_path = root / R09_R10_ACTIVATION_AUTHORITY_PATH
    for path, rel, digest in (
        (act_path, R09_R10_ACTIVATION_PATH, R09_R10_ACTIVATION_SHA256),
        (auth_path, R09_R10_ACTIVATION_AUTHORITY_PATH,
         R09_R10_ACTIVATION_AUTHORITY_SHA256),
    ):
        if not path.is_file():
            problems.add(f"{context}.artifact", f"missing {rel}")
            return
        if sha256_path(path) != digest:
            problems.add(f"{context}.artifact",
                         f"{rel} must match exact SHA-256 {digest}")
            return

    record = json.loads(act_path.read_text(encoding="utf-8"))
    auth_record = json.loads(auth_path.read_text(encoding="utf-8"))

    problems.require(
        record.get("record_kind") == "r09_r10_activation_control"
        and record.get("schema_version") == 1
        and record.get("activation_id") == "R09-R10-C0006-activation-v1",
        f"{context}.identity",
        "activation record must keep its exact kind, version and id",
    )

    base = record.get("base") or {}
    problems.require(
        base.get("accepted_control_sha") == C0006_ACCEPTED_CONTROL_SHA
        and base.get("checkpoint_id") == "C0006"
        and base.get("code_sha") == C0006_CODE_SHA,
        f"{context}.base",
        "activation must be rooted at exact accepted C0006 code",
    )

    authority = record.get("authority") or {}
    primary = authority.get("primary_review") or {}
    problems.require(
        authority.get("decision") == "approved"
        and authority.get("reviewer_id") == "primary-human"
        and authority.get("review_id") == "R09-R10-C0006-activation-v1"
        and primary.get("path") == R09_R10_ACTIVATION_AUTHORITY_PATH
        and primary.get("sha256") == R09_R10_ACTIVATION_AUTHORITY_SHA256,
        f"{context}.authority",
        "activation must cite the exact primary-human activation authorization",
    )
    problems.require(
        auth_record.get("record_kind") == "primary_human_activation_authorization"
        and auth_record.get("decision") == "approved"
        and auth_record.get("reviewer_id") == "primary-human"
        and auth_record.get("base_code_sha") == C0006_CODE_SHA
        and auth_record.get("planned_control_sha") == R09_R10_PLANNED_CONTROL_SHA
        and isinstance((auth_record.get("basis") or {}).get("did_not_include"), list)
        and (auth_record.get("basis") or {}).get("did_not_include"),
        f"{context}.authority.record",
        "the authorization must be an approved primary-human activation grant "
        "at exact C0006 code that states what it does not include",
    )

    planned = record.get("planned_control") or {}
    problems.require(
        planned.get("commit_sha") == R09_R10_PLANNED_CONTROL_SHA
        and planned.get("narrative_refresh_sha") == R09_R10_NARRATIVE_REFRESH_SHA,
        f"{context}.planned_control",
        "activation must pin the exact planned control and its narrative refresh",
    )

    ci = record.get("planned_control_ci") or {}
    run = ci.get("run") or {}
    job = ci.get("job") or {}
    suite = ci.get("check_suite") or {}
    problems.require(
        run.get("id") == R09_R10_PLANNED_CONTROL_CI_RUN
        and run.get("head_sha") == R09_R10_PLANNED_CONTROL_SHA
        and run.get("conclusion") == "success"
        and job.get("id") == R09_R10_PLANNED_CONTROL_CI_JOB
        and job.get("run_id") == R09_R10_PLANNED_CONTROL_CI_RUN
        and job.get("conclusion") == "success"
        and suite.get("id") == R09_R10_PLANNED_CONTROL_CI_SUITE
        and suite.get("head_sha") == R09_R10_PLANNED_CONTROL_SHA
        and suite.get("conclusion") == "success",
        f"{context}.planned_control_ci",
        "activation must prove the exact planned control passed Lean CI",
    )
    problems.require(
        all(step.get("conclusion") == "success"
            for step in (job.get("steps") or [])) and bool(job.get("steps")),
        f"{context}.planned_control_ci.steps",
        "every recorded planned-control job step must have succeeded",
    )

    scope = record.get("evidence_scope") or {}
    problems.require(
        scope.get("worker_state") == "frozen_pending_activation_control_ci",
        f"{context}.evidence_scope",
        "activation must keep both workers frozen pending activation-control CI",
    )

    branches = record.get("branches") or {}
    problems.require(
        set(branches) == {"B0011", "B0012"},
        f"{context}.branches",
        "activation must cover exactly the B0011/B0012 pair",
    )
    expected_lane = {"B0011": "claude-lane", "B0012": "codex-lane"}
    expected_wave = {"B0011": "R09", "B0012": "R10"}
    # The sidecar correction re-digests both branch records. Expect the
    # corrected digests once its review is present, the activation-time ones
    # before that, so both states stay exactly pinned.
    if (root / R09_R10_CORRECTION_REVIEW_PATH).is_file():
        expected_active = {"B0011": B0011_CORRECTED_SHA256,
                           "B0012": B0012_CORRECTED_SHA256}
    else:
        expected_active = {"B0011": B0011_ACTIVE_SHA256,
                           "B0012": B0012_ACTIVE_SHA256}
    for bid in sorted(set(branches) & {"B0011", "B0012"}):
        block = branches[bid] or {}
        creation = block.get("creation") or {}
        worktree = block.get("worktree") or {}
        problems.require(
            block.get("branch_id") == bid
            and block.get("wave_id") == expected_wave[bid]
            and block.get("lane_id") == expected_lane[bid]
            and block.get("local_tip") == C0006_CODE_SHA
            and block.get("remote_tip") == C0006_CODE_SHA
            and block.get("local_ref") == block.get("remote_ref"),
            f"{context}.{bid}.branch",
            f"{bid} must be created at exact C0006 code on matching refs",
        )
        problems.require(
            creation.get("base_sha") == C0006_CODE_SHA
            and creation.get("remote_lease_expected_tip") == "absent"
            and creation.get("remote_push_refspec")
            == f"{C0006_CODE_SHA}:{block.get('local_ref')}"
            and bool(creation.get("remote_ref_creation_source")),
            f"{context}.{bid}.creation",
            f"{bid} must record an absent-lease push of exact C0006 code and "
            "name the source of its remote-ref creation time",
        )
        problems.require(
            worktree.get("head_sha") == C0006_CODE_SHA
            and worktree.get("lake_present") is False
            and worktree.get("olean_count") == 0
            and worktree.get("tracked_crlf_count") == 0
            and worktree.get("clean_status_rows") == 0
            and (worktree.get("config") or {}).get("core.eol") == "lf",
            f"{context}.{bid}.worktree",
            f"{bid} worktree must be clean, LF-configured, and free of .lake "
            "and olean material at exact C0006 code",
        )
        branch_file = root / DEFAULT_PHASE_DIR.as_posix() / "branches" / f"{bid}.json"
        if not branch_file.is_file():
            problems.add(f"{context}.{bid}.record", f"missing {bid}.json")
            continue
        problems.require(
            sha256_path(branch_file) == expected_active[bid],
            f"{context}.{bid}.record",
            f"expected exact active {bid} SHA-256 {expected_active[bid]}",
        )
        record_json = json.loads(branch_file.read_text(encoding="utf-8"))
        evidence = {
            row.get("path"): row.get("sha256")
            for row in (record_json.get("refresh") or {}).get("evidence") or []
        }
        problems.require(
            record_json.get("status") == "active"
            and evidence.get(R09_R10_ACTIVATION_PATH) == R09_R10_ACTIVATION_SHA256
            and evidence.get(R09_R10_ACTIVATION_AUTHORITY_PATH)
            == R09_R10_ACTIVATION_AUTHORITY_SHA256,
            f"{context}.{bid}.active",
            f"{bid} must be active and carry both hash-pinned activation "
            "evidence rows",
        )


