def validate_r07_active_branch_delta(
    planned: dict[str, Any],
    active: dict[str, Any],
    problems: Problems,
    *,
    context: str = "R07 active branch delta",
) -> None:
    """Allow exactly planned->active plus one sorted activation evidence row."""

    expected = json.loads(canonical_json(planned))
    expected["status"] = "active"
    refresh = expected.get("refresh")
    if not isinstance(refresh, dict) or not isinstance(refresh.get("evidence"), list):
        problems.add(context, "historical planned branch lacks refresh evidence")
        return
    activation = {"path": R07_ACTIVATION_PATH, "sha256": R07_ACTIVATION_SHA256}
    refresh["evidence"] = sorted(
        [*refresh["evidence"], activation], key=lambda row: row["path"]
    )
    problems.require(
        active == expected,
        context,
        "B0010 may change only planned->active plus the sorted activation evidence row",
    )


def validate_r07_delivered_branch_delta(
    active: dict[str, Any],
    delivered: dict[str, Any],
    problems: Problems,
    *,
    context: str = "R07 delivered branch delta",
) -> None:
    """Allow only active->delivered plus the immutable delivery references."""

    expected = json.loads(canonical_json(active))
    expected["status"] = "delivered"
    expected["delivery"] = {
        "commit_sha": R07_DELIVERY_SHA,
        "report": {
            "path": R07_DELIVERY_REPORT_PATH,
            "sha256": R07_DELIVERY_REPORT_SHA256,
        },
        "scope_evidence": {
            "path": R07_DELIVERY_SCOPE_PATH,
            "sha256": R07_DELIVERY_SCOPE_SHA256,
        },
    }
    problems.require(
        delivered == expected,
        context,
        "B0010 may change only active->delivered plus the exact immutable delivery references",
    )


