def next_retirement_status(branch_status: str) -> str | None:
    if branch_status in {"planned", "active", "delivered"}:
        return "not_due"
    if branch_status == "accepted":
        return "due"
    if branch_status == "retired":
        return "retired"
    return None


def flatten_strings(value: Any) -> Iterator[str]:
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for key, item in value.items():
            yield str(key)
            yield from flatten_strings(item)
    elif isinstance(value, list):
        for item in value:
            yield from flatten_strings(item)


def remove_lean_comments(text: str) -> str:
    """Replace nested comments while preserving enough layout for import scans."""

    result: list[str] = []
    index = 0
    depth = 0
    in_string = False
    escaped = False
    while index < len(text):
        pair = text[index : index + 2]
        char = text[index]
        if depth:
            if pair == "/-":
                depth += 1
                result.extend("  ")
                index += 2
            elif pair == "-/":
                depth -= 1
                result.extend("  ")
                index += 2
            else:
                result.append("\n" if char == "\n" else " ")
                index += 1
            continue
        if in_string:
            result.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            index += 1
            continue
        if pair == "/-":
            depth = 1
            result.extend("  ")
            index += 2
        elif pair == "--":
            newline = text.find("\n", index + 2)
            if newline < 0:
                result.extend(" " * (len(text) - index))
                break
            result.extend(" " * (newline - index))
            result.append("\n")
            index = newline + 1
        else:
            result.append(char)
            if char == '"':
                in_string = True
            index += 1
    return "".join(result)


class CompletionValidator:
    def __init__(self, root: Path, phase_dir: Path) -> None:
        self.root = root.resolve()
        self.phase_dir = (
            phase_dir.resolve()
            if phase_dir.is_absolute()
            else (self.root / phase_dir).resolve()
        )
        self.problems = Problems()
        self.phase: dict[str, Any] = {}
        self.scope: list[dict[str, str]] = []
        self.scope_by_path: dict[str, dict[str, str]] = {}
        self.shared_rules: list[PathRule] = []
        self.branch_records: dict[str, dict[str, Any]] = {}
        self.branch_evidence: dict[str, list[Artifact]] = defaultdict(list)
        self.requests: dict[str, dict[str, Any]] = {}
        self.current_checkpoint_id = CHECKPOINT_ID
        self._git_tree_blobs: dict[str, dict[str, str]] = {}
        self._r03_expected_tree_attempted = False
        self._r03_expected_tree: str | None = None
        self.r07_contract: dict[str, Any] | None = None
        self.r07_contract_artifacts: dict[str, str] = {}
        self.r07_state = "absent"

    def relative(self, path: Path) -> str:
        try:
            return path.resolve().relative_to(self.root).as_posix()
        except ValueError:
            return str(path)

    def resolve_repo_path(self, value: str, context: str) -> Path | None:
        value = normalize_path(value)
        pure = PurePosixPath(value)
        if pure.is_absolute() or ".." in pure.parts or value in {"", "."}:
            self.problems.add(context, f"invalid repository-relative path {value!r}")
            return None
        path = (self.root / Path(*pure.parts)).resolve()
        try:
            path.relative_to(self.root)
        except ValueError:
            self.problems.add(context, f"path escapes repository: {value!r}")
            return None
        return path

    def read_json(self, path: Path, context: str) -> dict[str, Any] | None:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            self.problems.add(context, f"cannot read JSON: {error}")
            return None
        if not isinstance(value, dict):
            self.problems.add(context, "expected a JSON object")
            return None
        return value

    def git_json(
        self, commit: str, path: Path, context: str
    ) -> dict[str, Any] | None:
        """Load an exact historical JSON object without trusting live bytes."""

        relative = self.relative(path)
        process = self.git_bytes("show", f"{commit}:{relative}", check=False)
        if process.returncode != 0:
            self.problems.add(context, f"cannot read {relative} at {commit}")
            return None
        try:
            value = json.loads(process.stdout.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as error:
            self.problems.add(context, f"cannot parse {relative} at {commit}: {error}")
            return None
        if not isinstance(value, dict):
            self.problems.add(context, "historical JSON must be an object")
            return None
        return value

    def read_tsv(
        self,
        path: Path,
        context: str,
        expected_header: Sequence[str] | None = None,
    ) -> tuple[tuple[str, ...], list[dict[str, str]]]:
        try:
            raw = path.read_bytes()
        except OSError as error:
            self.problems.add(context, f"cannot read TSV: {error}")
            return (), []
        if b"\r" in raw:
            self.problems.add(context, "TSV must use LF line endings")
        if raw and not raw.endswith(b"\n"):
            self.problems.add(context, "TSV must end with a newline")
        try:
            text = raw.decode("utf-8-sig")
            reader = csv.DictReader(text.splitlines(), delimiter="\t")
            header = tuple(reader.fieldnames or ())
            rows = [dict(row) for row in reader]
        except (UnicodeError, csv.Error) as error:
            self.problems.add(context, f"cannot parse TSV: {error}")
            return (), []
        if expected_header is not None and header != tuple(expected_header):
            self.problems.add(
                context,
                "header must be exactly: " + "\t".join(expected_header),
            )
        if any(None in row or any(value is None for value in row.values()) for row in rows):
            self.problems.add(context, "malformed row or wrong column count")
        return header, rows

    def artifact(self, value: Any, context: str) -> Artifact | None:
        if not isinstance(value, dict) or set(value) != {"path", "sha256"}:
            self.problems.add(context, "expected exactly {path, sha256}")
            return None
        path_value, digest = value.get("path"), value.get("sha256")
        if not isinstance(path_value, str) or not isinstance(digest, str):
            self.problems.add(context, "path and sha256 must be strings")
            return None
        if not SHA256_RE.fullmatch(digest):
            self.problems.add(context, "sha256 must be 64 hexadecimal characters")
            return None
        path = self.resolve_repo_path(path_value, context)
        if path is None:
            return None
        if not path.is_file():
            self.problems.add(context, f"missing artifact {path_value}")
            return None
        actual = sha256_path(path)
        if actual != digest.upper():
            self.problems.add(
                context,
                f"SHA-256 mismatch for {path_value}: expected {digest.upper()}, found {actual}",
            )
        return Artifact(normalize_path(path_value), digest.upper())

    def historical_artifact(
        self, value: Any, commit: str, context: str
    ) -> Artifact | None:
        """Authenticate one artifact from an immutable commit, not the overlay."""

        if not isinstance(value, dict) or set(value) != {"path", "sha256"}:
            self.problems.add(context, "expected exactly {path, sha256}")
            return None
        path_value, digest = value.get("path"), value.get("sha256")
        if not isinstance(path_value, str) or not isinstance(digest, str):
            self.problems.add(context, "path and sha256 must be strings")
            return None
        if not SHA256_RE.fullmatch(digest):
            self.problems.add(context, "sha256 must be 64 hexadecimal characters")
            return None
        if self.resolve_repo_path(path_value, context) is None:
            return None
        normalized = normalize_path(path_value)
        shown = self.git_bytes("show", f"{commit}:{normalized}", check=False)
        if shown.returncode:
            self.problems.add(context, f"missing artifact {normalized} at {commit}")
            return None
        actual = hashlib.sha256(shown.stdout).hexdigest().upper()
        if actual != digest.upper():
            self.problems.add(
                context,
                f"SHA-256 mismatch for {normalized} at {commit}: "
                f"expected {digest.upper()}, found {actual}",
            )
        return Artifact(normalized, digest.upper())

    def git(self, *args: str, check: bool = True, env: dict[str, str] | None = None) -> subprocess.CompletedProcess[str]:
        process = subprocess.run(
            ["git", *args],
            cwd=self.root,
            env=env,
            text=True,
            encoding="utf-8",
            errors="replace",
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        if check and process.returncode:
            raise RuntimeError(
                f"git {' '.join(args)} failed ({process.returncode}): "
                f"{process.stderr.strip() or process.stdout.strip()}"
            )
        return process

    def git_bytes(
        self,
        *args: str,
        check: bool = True,
        env: dict[str, str] | None = None,
    ) -> subprocess.CompletedProcess[bytes]:
        process = subprocess.run(
            ["git", *args],
            cwd=self.root,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        if check and process.returncode:
            detail = (process.stderr or process.stdout).decode(
                "utf-8", errors="replace"
            ).strip()
            raise RuntimeError(
                f"git {' '.join(args)} failed ({process.returncode}): {detail}"
            )
        return process

    def git_live_change_paths(self, base: str, context: str) -> set[str]:
        """Return every tracked/index/worktree and nonignored untracked path."""

        paths: set[str] = set()
        commands = (
            ("diff", "--name-only", "--no-renames", base, "--"),
            ("diff", "--cached", "--name-only", "--no-renames", base, "--"),
            ("diff", "--name-only", "--no-renames", "--"),
            ("ls-files", "--others", "--exclude-standard"),
        )
        for command in commands:
            result = self.git(*command, check=False)
            if result.returncode:
                self.problems.add(
                    context,
                    f"cannot enumerate {' '.join(command)}: "
                    + (result.stderr.strip() or result.stdout.strip()),
                )
                continue
            paths.update(
                normalize_path(path)
                for path in result.stdout.splitlines()
                if path.strip()
            )
        return paths

    def git_blob_payloads(
        self,
        oids: Iterable[str],
        context: str,
        *,
        env: dict[str, str] | None = None,
    ) -> dict[str, bytes]:
        """Read many Git blobs with one ``cat-file --batch`` process."""

        requested = sorted(set(oids))
        if not requested:
            return {}
        process = subprocess.run(
            ["git", "cat-file", "--batch"],
            cwd=self.root,
            env=env,
            input=("\n".join(requested) + "\n").encode("ascii"),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        if process.returncode:
            self.problems.add(
                context,
                "cannot batch-read Git blobs: "
                + (process.stderr or process.stdout).decode(
                    "utf-8", errors="replace"
                ).strip(),
            )
            return {}
        stream = io.BytesIO(process.stdout)
        payloads: dict[str, bytes] = {}
        for requested_oid in requested:
            header = stream.readline().rstrip(b"\n")
            try:
                returned_oid, kind, raw_size = header.decode("ascii").split()
                size = int(raw_size)
            except (UnicodeError, ValueError):
                self.problems.add(
                    context,
                    f"malformed cat-file batch header for {requested_oid}: {header!r}",
                )
                break
            payload = stream.read(size)
            terminator = stream.read(1)
            if (
                returned_oid != requested_oid
                or kind != "blob"
                or len(payload) != size
                or terminator != b"\n"
            ):
                self.problems.add(
                    context,
                    f"malformed cat-file batch payload for {requested_oid}",
                )
                break
            payloads[requested_oid] = payload
        return payloads

    def reconstruct_r03_expected_tree(self) -> str | None:
        """Replay R0005 from its reachable merge in a disposable Git index."""

        if self._r03_expected_tree_attempted:
            return self._r03_expected_tree
        self._r03_expected_tree_attempted = True
        context = "C0003 R0005 replay tree"
        patch_path = self.root / R03_EVIDENCE_PATHS["request_patch"]
        if not patch_path.is_file():
            self.problems.add(
                context,
                f"missing committed replay patch {self.relative(patch_path)}",
            )
            return None
        expected_patch_sha256 = R03_ARTIFACT_SHA256["request_patch"]
        actual_patch_sha256 = sha256_path(patch_path)
        if not isinstance(expected_patch_sha256, str):
            self.problems.add(context, "R0005 patch digest constant is not ratcheted")
            return None
        if actual_patch_sha256 != expected_patch_sha256:
            self.problems.add(
                context,
                "committed R0005 patch drifted: expected SHA-256 "
                f"{expected_patch_sha256}, found {actual_patch_sha256}",
            )
            return None

        with tempfile.TemporaryDirectory(
            prefix="completion-r03-expected-tree-"
        ) as directory:
            index = Path(directory) / "index"
            env = os.environ.copy()
            env["GIT_INDEX_FILE"] = str(index)
            read = self.git(
                "read-tree", R03_MERGE_SHA, check=False, env=env
            )
            if read.returncode:
                self.problems.add(
                    context,
                    "cannot initialize disposable index from reachable R03 merge "
                    f"{R03_MERGE_SHA}: {read.stderr.strip() or read.stdout.strip()}",
                )
                return None
            applied = self.git(
                "apply",
                "--cached",
                "--unidiff-zero",
                "--whitespace=nowarn",
                str(patch_path),
                check=False,
                env=env,
            )
            if applied.returncode:
                self.problems.add(
                    context,
                    "R0005 patch does not replay from exact R03 merge: "
                    f"{applied.stderr.strip() or applied.stdout.strip()}",
                )
                return None
            written = self.git("write-tree", check=False, env=env)
            actual_tree = written.stdout.strip()
            if written.returncode or SHA1_RE.fullmatch(actual_tree) is None:
                self.problems.add(
                    context,
                    "cannot write disposable R0005 postimage tree: "
                    f"{written.stderr.strip() or written.stdout.strip()}",
                )
                return None
            if not validate_reconstructed_r03_tree(
                actual_tree, self.problems, context=context
            ):
                return None
            self._r03_expected_tree = actual_tree
            return actual_tree

    def run(self) -> Problems:
        self.load_r07_planned_contract()
        self.validate_pointer()
        self.load_phase()
        self.validate_checkpoint_and_scope()
        self.validate_branches()
        self.validate_routes_and_tests()
        self.validate_projections()
        self.validate_overlap_reviews()
        self.validate_requests_and_postimages()
        self.validate_next_wave_controls()
        self.validate_r03_epoch()
        self.validate_r05_r06_epoch()
        self.validate_r04_r08_epoch()
        self.validate_milestone_dag()
        if self.r07_contract is not None:
            self.validate_r07_planned_control()
        return self.problems

    def load_r07_planned_contract(self) -> None:
        """Enable R07 only when the exact reviewed contract bytes are present."""

        path = self.root / R07_PLANNED_CONTROL_CONTRACT_PATH
        head_result = self.git("rev-parse", "HEAD", check=False)
        head = head_result.stdout.strip() if head_result.returncode == 0 else ""
        if head_result.returncode:
            self.problems.add(
                R07_PLANNED_CONTROL_CONTRACT_PATH,
                "cannot resolve live HEAD while authenticating R07 contract: "
                + (head_result.stderr.strip() or head_result.stdout.strip()),
            )
        contract_present = path.exists()
        legacy_change_paths = (
            self.git_live_change_paths(
                R07_ACCEPTED_CONTROL_SHA,
                f"{R07_PLANNED_CONTROL_CONTRACT_PATH}.legacy_worktree",
            )
            if not contract_present and head == R07_ACCEPTED_CONTROL_SHA
            else set()
        )
        if not contract_present:
            validate_r07_contract_availability(
                head=head,
                contract_present=False,
                contract_authenticated=False,
                legacy_change_paths=legacy_change_paths,
                problems=self.problems,
                context=R07_PLANNED_CONTROL_CONTRACT_PATH,
            )
            return
        try:
            payload = path.read_bytes()
        except OSError as error:
            self.problems.add(
                R07_PLANNED_CONTROL_CONTRACT_PATH,
                f"cannot read present contract: {error}",
            )
            validate_r07_contract_availability(
                head=head,
                contract_present=True,
                contract_authenticated=False,
                legacy_change_paths=set(),
                problems=self.problems,
                context=R07_PLANNED_CONTROL_CONTRACT_PATH,
            )
            return
        contract = parse_authenticated_r07_contract(
            payload,
            self.problems,
            context=R07_PLANNED_CONTROL_CONTRACT_PATH,
        )
        validate_r07_contract_availability(
            head=head,
            contract_present=True,
            contract_authenticated=contract is not None,
            legacy_change_paths=set(),
            problems=self.problems,
            context=R07_PLANNED_CONTROL_CONTRACT_PATH,
        )
        if contract is None:
            return
        self.r07_contract = contract
        validate_r07_contract_identity(contract, self.problems)

    def r07_tsv(
        self, filename: str, header_key: str
    ) -> list[dict[str, str]]:
        """Read one B0010 TSV using the authenticated contract header."""

        assert self.r07_contract is not None
        headers = self.r07_contract.get("headers")
        expected = headers.get(header_key) if isinstance(headers, dict) else None
        path = self.phase_dir / "branches" / filename
        _header, rows = self.read_tsv(
            path,
            self.relative(path),
            expected if isinstance(expected, list) else (),
        )
        return rows

    @staticmethod
    def r07_imports(payload: bytes) -> list[str]:
        try:
            text = payload.decode("utf-8")
        except UnicodeError:
            return []
        return IMPORT_RE.findall(remove_lean_comments(text))

    @staticmethod
    def r07_source_command_bytes(
        payload: bytes, span: tuple[int, int, int, int]
    ) -> bytes | None:
        """Slice Lean compiler coordinates (zero-based lines, UTF-16 columns)."""

        lines = payload.splitlines(keepends=True) or [b""]
        offsets = [0]
        for line in lines:
            offsets.append(offsets[-1] + len(line))

        def offset(line_number: int, column: int) -> int | None:
            if line_number == len(lines) and column == 0:
                return len(payload)
            if line_number < 0 or line_number >= len(lines) or column < 0:
                return None
            content = lines[line_number]
            if content.endswith(b"\r\n"):
                content = content[:-2]
            elif content.endswith((b"\r", b"\n")):
                content = content[:-1]
            try:
                decoded = content.decode("utf-8")
            except UnicodeError:
                return None
            if column == 0:
                return offsets[line_number]
            units = 0
            byte_count = 0
            for character in decoded:
                next_units = units + (2 if ord(character) > 0xFFFF else 1)
                if next_units > column:
                    return None
                units = next_units
                byte_count += len(character.encode("utf-8"))
                if units == column:
                    return offsets[line_number] + byte_count
            return None

        start = offset(span[0], span[1])
        end = offset(span[2], span[3])
        if start is None or end is None or end <= start:
            return None
        return payload[start:end]

    def parse_r07_projection(
        self, path: Path
    ) -> tuple[
        dict[str, tuple[str, str, str]],
        list[tuple[str, str, str]],
        dict[str, int],
    ]:
        """Parse the authenticated format-2 projection without generator code."""

        context = self.relative(path)
        declarations: dict[str, tuple[str, str, str]] = {}
        edges: list[tuple[str, str, str]] = []
        union: set[tuple[str, str]] = set()
        try:
            with gzip.open(path, "rt", encoding="utf-8", newline="") as handle:
                first = handle.readline().rstrip("\n")
                if first != "format\t2":
                    self.problems.add(
                        context, "projection graph must start with format<TAB>2"
                    )
                for number, line in enumerate(handle, 2):
                    fields = line.rstrip("\n").split("\t")
                    if not fields or fields == [""]:
                        continue
                    if fields[0] == "declaration" and len(fields) == 5:
                        _tag, name, owner, kind, visibility = fields
                        if name in declarations:
                            self.problems.add(
                                context,
                                f"duplicate declaration {name!r} at line {number}",
                            )
                        declarations[name] = (owner, kind, visibility)
                    elif (
                        fields[0] == "edge"
                        and len(fields) == 4
                        and fields[1] in {"signature", "body"}
                    ):
                        _tag, kind, source, target = fields
                        edges.append((kind, source, target))
                        union.add((source, target))
                    else:
                        self.problems.add(
                            context, f"malformed format-2 row at line {number}"
                        )
        except (OSError, UnicodeError, gzip.BadGzipFile) as error:
            self.problems.add(context, f"cannot parse projection graph: {error}")
        counts = {
            "declarations": len(declarations),
            "signature_edges": sum(kind == "signature" for kind, _s, _t in edges),
            "body_edges": sum(kind == "body" for kind, _s, _t in edges),
            "union_edges": len(union),
        }
        return declarations, edges, counts

    def replay_r07_request(
        self,
        base_sha: str,
        patch_path: Path,
        paths: set[str],
        expected_tree: str,
    ) -> dict[str, bytes]:
        """Replay R0011 in a disposable index and return exact postimage bytes."""

        context = "R0011 disposable-index replay"
        postimages: dict[str, bytes] = {}
        with tempfile.TemporaryDirectory(prefix="completion-r07-r0011-") as directory:
            index = Path(directory) / "index"
            env = os.environ.copy()
            env["GIT_INDEX_FILE"] = str(index)
            read = self.git("read-tree", base_sha, check=False, env=env)
            if read.returncode:
                self.problems.add(
                    context,
                    "cannot initialize exact base tree: "
                    + (read.stderr.strip() or read.stdout.strip()),
                )
                return postimages
            applied = self.git(
                "apply",
                "--cached",
                "--unidiff-zero",
                "--whitespace=nowarn",
                str(patch_path),
                check=False,
                env=env,
            )
            if applied.returncode:
                self.problems.add(
                    context,
                    "patch does not apply to exact C0005 base: "
                    + (applied.stderr.strip() or applied.stdout.strip()),
                )
                return postimages
            changed = {
                normalize_path(line)
                for line in self.git(
                    "diff", "--cached", "--name-only", base_sha, env=env
                ).stdout.splitlines()
                if line.strip()
            }
            self.problems.require(
                changed == paths,
                f"{context}.paths",
                "patch must change every and only R0011 paths; "
                f"missing={sorted(paths - changed)}, extra={sorted(changed - paths)}",
            )
            written = self.git("write-tree", check=False, env=env)
            tree = written.stdout.strip()
            self.problems.require(
                written.returncode == 0 and tree == expected_tree,
                f"{context}.tree",
                f"expected exact reviewed tree {expected_tree}, found {tree!r}",
            )
            if written.returncode:
                return postimages
            for path in sorted(paths):
                shown = self.git_bytes("show", f"{tree}:{path}", check=False)
                if shown.returncode:
                    self.problems.add(
                        f"{context}[{path}]", "missing postimage in replayed tree"
                    )
                else:
                    postimages[path] = shown.stdout
        return postimages

    def replay_r07_correction(
        self,
        base_sha: str,
        request_patch_path: Path,
        request_paths: set[str],
        request_tree: str,
        correction_patch_path: Path,
    ) -> dict[str, bytes]:
        """Replay R0011 then its four-path correction in one disposable index."""

        context = "R0011 corrected disposable-index replay"
        postimages: dict[str, bytes] = {}
        correction_paths = set(R07_CORRECTION_POSTIMAGES)
        with tempfile.TemporaryDirectory(prefix="completion-r07-correction-") as directory:
            index = Path(directory) / "index"
            env = os.environ.copy()
            env["GIT_INDEX_FILE"] = str(index)
            read = self.git("read-tree", base_sha, check=False, env=env)
            if read.returncode:
                self.problems.add(
                    context,
                    "cannot initialize exact base tree: "
                    + (read.stderr.strip() or read.stdout.strip()),
                )
                return postimages
            request_applied = self.git(
                "apply",
                "--cached",
                "--unidiff-zero",
                "--whitespace=nowarn",
                str(request_patch_path),
                check=False,
                env=env,
            )
            if request_applied.returncode:
                self.problems.add(
                    context,
                    "R0011 does not apply before its correction: "
                    + (request_applied.stderr.strip() or request_applied.stdout.strip()),
                )
                return postimages
            request_written = self.git("write-tree", check=False, env=env)
            actual_request_tree = request_written.stdout.strip()
            self.problems.require(
                request_written.returncode == 0 and actual_request_tree == request_tree,
                f"{context}.request_tree",
                f"expected exact R0011 tree {request_tree}, found {actual_request_tree!r}",
            )
            if request_written.returncode or actual_request_tree != request_tree:
                return postimages
            correction_applied = self.git(
                "apply",
                "--cached",
                "--unidiff-zero",
                "--whitespace=nowarn",
                str(correction_patch_path),
                check=False,
                env=env,
            )
            if correction_applied.returncode:
                self.problems.add(
                    context,
                    "correction does not apply after exact R0011: "
                    + (
                        correction_applied.stderr.strip()
                        or correction_applied.stdout.strip()
                    ),
                )
                return postimages
            changed = {
                normalize_path(line)
                for line in self.git(
                    "diff", "--cached", "--name-only", request_tree, env=env
                ).stdout.splitlines()
                if line.strip()
            }
            self.problems.require(
                changed == correction_paths,
                f"{context}.paths",
                "correction must change every and only its four reviewed paths; "
                f"missing={sorted(correction_paths - changed)}, "
                f"extra={sorted(changed - correction_paths)}",
            )
            corrected_written = self.git("write-tree", check=False, env=env)
            corrected_tree = corrected_written.stdout.strip()
            self.problems.require(
                corrected_written.returncode == 0
                and corrected_tree == R07_CORRECTION_TREE,
                f"{context}.tree",
                f"expected exact corrected shared tree {R07_CORRECTION_TREE}, "
                f"found {corrected_tree!r}",
            )
            if corrected_written.returncode:
                return postimages
            for path in sorted(request_paths | correction_paths):
                shown = self.git_bytes(
                    "show", f"{corrected_tree}:{path}", check=False
                )
                if shown.returncode:
                    self.problems.add(
                        f"{context}[{path}]", "missing postimage in corrected tree"
                    )
                else:
                    postimages[path] = shown.stdout
        return postimages

    def validate_r07_planned_control(self) -> None:
        """Validate C0005-rooted R07 planning through CI-attested integration."""

        contract = self.r07_contract
        assert contract is not None
        context = "authenticated R07 planned control"
        activation_path = self.root / R07_ACTIVATION_PATH
        activation_present = activation_path.is_file()
        authorization_path = self.root / R07_INTEGRATION_AUTHORIZATION_PATH
        delivered_present = authorization_path.is_file()
        integration_ci_path = self.root / R07_INTEGRATION_CONTROL_CI_PATH
        closeout_present = integration_ci_path.is_file()
        accepted_present = (
            self.phase_dir / "checkpoints/C0006.json"
        ).is_file()
        self.r07_accepted = accepted_present
        self.r07_state = (
            "accepted"
            if accepted_present
            else "integrated"
            if closeout_present
            else "delivered"
            if delivered_present
            else "active"
            if activation_present
            else "planned"
        )
        self.problems.require(
            not delivered_present or activation_present,
            f"{context}.lifecycle",
            "delivered mode requires the exact earlier activation record",
        )
        self.problems.require(
            not closeout_present or delivered_present,
            f"{context}.lifecycle",
            "integration-CI closeout requires exact delivery and integration authority",
        )
        self.problems.require(
            not accepted_present or closeout_present,
            f"{context}.lifecycle",
            "C0006 acceptance requires the exact integration-CI closeout first",
        )
        counts = contract.get("counts")
        headers = contract.get("headers")
        if not isinstance(counts, dict) or not isinstance(headers, dict):
            return

        # The contract digest authenticates the expected artifact map.  Each
        # live artifact is then hashed independently; duplicate or unsafe paths
        # cannot hide behind the map representation.
        artifact_rows = contract.get("artifacts")
        artifact_map: dict[str, str] = {}
        valid_artifacts = isinstance(artifact_rows, list)
        if isinstance(artifact_rows, list):
            for index, row in enumerate(artifact_rows):
                row_context = f"{context}.artifacts[{index}]"
                artifact = self.historical_artifact(
                    row, R07_PLANNED_CONTROL_SHA, row_context
                )
                if artifact is None or artifact.path in artifact_map:
                    valid_artifacts = False
                    if artifact is not None:
                        self.problems.add(row_context, "duplicate artifact path")
                    continue
                artifact_map[artifact.path] = artifact.sha256
        self.problems.require(
            valid_artifacts
            and len(artifact_map) == counts.get("artifact_rows")
            and list(artifact_map) == sorted(artifact_map),
            f"{context}.artifacts",
            "artifact rows must be unique, sorted, and match declared cardinality",
        )
        self.problems.require(
            R07_PLANNED_CONTROL_CONTRACT_PATH not in artifact_map,
            f"{context}.artifacts",
            "the self-authenticating contract must not list itself as an artifact",
        )
        self.r07_contract_artifacts = artifact_map

        # The immutable planned commit is the authority for every contract
        # artifact.  Live bytes must stay identical except for B0010's tightly
        # controlled activation delta.
        branch_path_string = (
            f"{DEFAULT_PHASE_DIR.as_posix()}/branches/B0010.json"
        )
        # At accepted C0006 the acceptance control legitimately advances the
        # phase, projection, and request records; their live state is held to
        # the exact acceptance expectations below instead of the frozen
        # planning bytes.
        live_exempt = {branch_path_string} | (
            set(C0006_ACCEPTANCE_EXEMPT_CONTRACT_PATHS)
            if accepted_present
            else set()
        )
        if isinstance(artifact_rows, list):
            for index, row in enumerate(artifact_rows):
                if isinstance(row, dict) and row.get("path") not in live_exempt:
                    self.artifact(row, f"{context}.live_artifacts[{index}]")
        planned_metadata = self.git(
            "show",
            "-s",
            "--format=%T%n%P%n%cI%n%s",
            R07_PLANNED_CONTROL_SHA,
            check=False,
        )
        planned_lines = planned_metadata.stdout.splitlines()
        self.problems.require(
            planned_metadata.returncode == 0
            and planned_lines
            == [
                R07_PLANNED_CONTROL_TREE,
                R07_ACCEPTED_CONTROL_SHA,
                "2026-08-21T08:07:27-04:00",
                "chore(reorg): plan R07 matrix powers epoch",
            ],
            f"{context}.planned_commit.identity",
            "planned commit must retain exact tree, sole parent, time, and message",
        )
        historical_contract = self.git_bytes(
            "show",
            f"{R07_PLANNED_CONTROL_SHA}:{R07_PLANNED_CONTROL_CONTRACT_PATH}",
            check=False,
        )
        self.problems.require(
            historical_contract.returncode == 0
            and hashlib.sha256(historical_contract.stdout).hexdigest().upper()
            == R07_PLANNED_CONTROL_CONTRACT_SHA256,
            f"{context}.planned_commit.contract",
            "planned commit must contain the exact authenticated contract",
        )

        base_sha = contract.get("base_code_sha")
        accepted_sha = contract.get("accepted_control_sha")
        if not isinstance(base_sha, str) or not isinstance(accepted_sha, str):
            return
        parent = self.git("rev-parse", f"{accepted_sha}^", check=False)
        parents = self.git("show", "-s", "--format=%P", accepted_sha, check=False)
        self.problems.require(
            parent.returncode == 0
            and parent.stdout.strip() == base_sha
            and parents.returncode == 0
            and parents.stdout.split() == [base_sha],
            f"{context}.accepted_control",
            "accepted control must be a single-parent direct child of exact C0005 code",
        )
        ancestry = self.git(
            "merge-base", "--is-ancestor", accepted_sha, "HEAD", check=False
        )
        self.problems.require(
            ancestry.returncode == 0,
            f"{context}.accepted_control",
            "accepted control must be an ancestor of live HEAD",
        )

        prefix = DEFAULT_PHASE_DIR.as_posix()
        paths = {
            "branch": self.phase_dir / "branches/B0010.json",
            "projection": self.phase_dir / "projections/P0010.json",
            "request": self.phase_dir / "requests/R0011.json",
            "packet": self.phase_dir / "reviews/R07-review-packet.json",
            "review": self.phase_dir / "reviews/R07-primary-human-review.json",
            "ci": self.phase_dir / "reviews/C0005-acceptance-control-ci.json",
            "render": self.phase_dir / "reviews/R07-R0011-render-review.json",
            "projection_review": self.phase_dir / "reviews/R07-projection-review.json",
            "overlap": self.phase_dir / "branches/B0010-overlap-review.json",
        }
        records = {
            name: self.read_json(path, self.relative(path))
            for name, path in paths.items()
        }
        if any(value is None for value in records.values()):
            return
        branch = records["branch"] or {}
        planned_branch = self.git_json(
            R07_PLANNED_CONTROL_SHA,
            paths["branch"],
            f"{context}.planned_branch",
        )
        if planned_branch is None:
            return
        activation: dict[str, Any] | None = None
        active_branch: dict[str, Any] | None = None
        if activation_present:
            self.problems.require(
                sha256_path(activation_path) == R07_ACTIVATION_SHA256,
                R07_ACTIVATION_PATH,
                f"expected exact activation SHA-256 {R07_ACTIVATION_SHA256}",
            )
            activation = self.read_json(activation_path, R07_ACTIVATION_PATH)
            if activation is not None:
                validate_r07_activation_record(
                    activation, self.problems, context=R07_ACTIVATION_PATH
                )
            active_branch = self.git_json(
                R07_ACTIVATION_CONTROL_SHA,
                paths["branch"],
                f"{context}.branch.historical_active",
            )
            historical_active_bytes = self.git_bytes(
                "show",
                f"{R07_ACTIVATION_CONTROL_SHA}:{self.relative(paths['branch'])}",
                check=False,
            )
            self.problems.require(
                historical_active_bytes.returncode == 0
                and hashlib.sha256(historical_active_bytes.stdout).hexdigest().upper()
                == R07_ACTIVE_BRANCH_SHA256,
                f"{context}.branch.historical_active_hash",
                "activation commit must retain exact active B0010 bytes",
            )
            if active_branch is not None:
                validate_r07_active_branch_delta(
                    planned_branch,
                    active_branch,
                    self.problems,
                    context=f"{context}.branch.activation_delta",
                )
            if delivered_present:
                if not accepted_present:
                    # At accepted C0006 the live record legitimately carries the
                    # acceptance lifecycle; its exact shape is enforced by the
                    # accepted-state branch checks above.
                    self.problems.require(
                        sha256_path(paths["branch"]) == R07_DELIVERED_BRANCH_SHA256,
                        f"{context}.branch.delivered_hash",
                        f"expected exact delivered B0010 SHA-256 {R07_DELIVERED_BRANCH_SHA256}",
                    )
                    if active_branch is not None:
                        validate_r07_delivered_branch_delta(
                            active_branch,
                            branch,
                            self.problems,
                            context=f"{context}.branch.delivery_delta",
                        )
            else:
                self.problems.require(
                    sha256_path(paths["branch"]) == R07_ACTIVE_BRANCH_SHA256,
                    f"{context}.branch.active_hash",
                    f"expected exact active B0010 SHA-256 {R07_ACTIVE_BRANCH_SHA256}",
                )
                validate_r07_active_branch_delta(
                    planned_branch,
                    branch,
                    self.problems,
                    context=f"{context}.branch.activation_delta.live",
                )
        else:
            self.problems.require(
                sha256_path(paths["branch"]) == R07_PLANNED_BRANCH_SHA256
                and branch == planned_branch,
                f"{context}.branch.planned_hash",
                "planned mode must retain exact historical B0010 bytes",
            )
        projection = records["projection"] or {}
        request = records["request"] or {}
        packet = records["packet"] or {}
        review = records["review"] or {}
        ci = records["ci"] or {}
        render = records["render"] or {}
        projection_review = records["projection_review"] or {}
        overlap = records["overlap"] or {}

        if delivered_present:
            delivered_artifacts = [
                (R07_ACTIVATION_CONTROL_CI_PATH, R07_ACTIVATION_CONTROL_CI_SHA256),
                (
                    R07_INTEGRATION_AUTHORIZATION_PATH,
                    R07_INTEGRATION_AUTHORIZATION_SHA256,
                ),
                (R07_DELIVERY_REPORT_PATH, R07_DELIVERY_REPORT_SHA256),
                (R07_DELIVERY_SCOPE_PATH, R07_DELIVERY_SCOPE_SHA256),
                (R07_CORRECTION_PATH, R07_CORRECTION_SHA256),
            ]
            if closeout_present:
                delivered_artifacts.append(
                    (
                        R07_INTEGRATION_CONTROL_CI_PATH,
                        R07_INTEGRATION_CONTROL_CI_SHA256,
                    )
                )
            for delivered_path, delivered_digest in delivered_artifacts:
                self.artifact(
                    {"path": delivered_path, "sha256": delivered_digest},
                    f"{context}.delivered_artifact[{delivered_path}]",
                )
            activation_ci = self.read_json(
                self.root / R07_ACTIVATION_CONTROL_CI_PATH,
                R07_ACTIVATION_CONTROL_CI_PATH,
            )
            if activation_ci is not None:
                validate_r07_activation_control_ci(
                    activation_ci,
                    self.problems,
                    context=R07_ACTIVATION_CONTROL_CI_PATH,
                )
            authorization = self.read_json(
                authorization_path, R07_INTEGRATION_AUTHORIZATION_PATH
            )
            if authorization is not None:
                validate_r07_integration_authorization(
                    authorization,
                    self.problems,
                    context=R07_INTEGRATION_AUTHORIZATION_PATH,
                )
            if closeout_present:
                integration_ci = self.read_json(
                    integration_ci_path, R07_INTEGRATION_CONTROL_CI_PATH
                )
                if integration_ci is not None:
                    validate_r07_integration_control_ci(
                        integration_ci,
                        self.problems,
                        context=R07_INTEGRATION_CONTROL_CI_PATH,
                    )

        expected_review = {
            "schema_version": 1,
            "record_kind": "primary_human_semantic_review",
            "phase_id": PHASE_ID,
            "review_id": contract.get("review_id"),
            "reviewer_id": "primary-human",
            "decision": "approved",
            "reviewed_at": contract.get("reviewed_at"),
            "base_checkpoint_id": C0005_CHECKPOINT_ID,
            "base_code_sha": base_sha,
            "accepted_control_sha": accepted_sha,
        }
        for key, expected in expected_review.items():
            self.problems.require(
                review.get(key) == expected,
                f"{context}.review.{key}",
                f"expected {expected!r}",
            )
        reviewed_artifacts = review.get("artifacts")
        reviewed_map: dict[str, tuple[str, str]] = {}
        if isinstance(reviewed_artifacts, list):
            for index, row in enumerate(reviewed_artifacts):
                if (
                    not isinstance(row, dict)
                    or set(row) != {"path", "role", "sha256"}
                    or not all(isinstance(row.get(key), str) for key in row)
                    or row["path"] in reviewed_map
                ):
                    self.problems.add(
                        f"{context}.review.artifacts[{index}]",
                        "expected unique path/role/sha256 strings",
                    )
                    continue
                reviewed_map[row["path"]] = (row["role"], row["sha256"].upper())
        packet_artifacts = packet.get("artifacts")
        packet_map: dict[str, str] = {}
        if isinstance(packet_artifacts, list):
            for index, row in enumerate(packet_artifacts):
                if (
                    not isinstance(row, dict)
                    or set(row) != {"path", "sha256"}
                    or not isinstance(row.get("path"), str)
                    or not isinstance(row.get("sha256"), str)
                    or row["path"] in packet_map
                ):
                    self.problems.add(
                        f"{context}.packet.artifacts[{index}]",
                        "expected unique path/sha256 strings",
                    )
                    continue
                packet_map[row["path"]] = row["sha256"].upper()
        packet_path = self.relative(paths["packet"])
        self.problems.require(
            len(packet_map) == 24
            and len(reviewed_map) == 25
            and set(reviewed_map) == set(packet_map) | {packet_path}
            and all(
                reviewed_map[path][1] == digest
                for path, digest in packet_map.items()
                if path in reviewed_map
            )
            and reviewed_map.get(packet_path, (None, None))[1]
            == artifact_map.get(packet_path),
            f"{context}.review.artifacts",
            "primary review must cover exactly the 24 packet artifacts plus the packet",
        )
        expected_packet = {
            "schema_version": 1,
            "record_kind": "r07_review_packet",
            "accepted_control_sha": accepted_sha,
            "base_checkpoint_id": C0005_CHECKPOINT_ID,
            "base_code_sha": base_sha,
            "decision_requested": "primary-human exact semantic and planned-control approval",
            "exclusions": [
                "R07 integration",
                "R07 self-acceptance",
                "checkpoint acceptance",
                "branch retirement",
            ],
            "ids": {
                "branch": "B0010",
                "milestone": "M07",
                "projection": "P0010",
                "request": "R0011",
                "wave": "R07",
            },
            "graph_sha256": C0005_RAW_DEPENDENCY_TSV_SHA256,
        }
        for key, expected in expected_packet.items():
            self.problems.require(
                packet.get(key) == expected,
                f"{context}.packet.{key}",
                f"expected {expected!r}",
            )

        accepted = ci.get("accepted_control")
        run = ci.get("run")
        job = ci.get("job")
        suite = ci.get("check_suite")
        check_run = ci.get("check_run")
        cardinality = ci.get("cardinality")
        ci_ok = all(
            isinstance(value, dict)
            for value in (accepted, run, job, suite, check_run, cardinality)
        )
        if ci_ok:
            assert isinstance(accepted, dict)
            assert isinstance(run, dict)
            assert isinstance(job, dict)
            assert isinstance(suite, dict)
            assert isinstance(check_run, dict)
            assert isinstance(cardinality, dict)
            steps = job.get("steps")
            ci_ok = (
                ci.get("schema_version") == 1
                and ci.get("record_kind") == "checkpoint_external_ci_attestation"
                and accepted.get("checkpoint_id") == C0005_CHECKPOINT_ID
                and accepted.get("commit_sha") == accepted_sha
                and accepted.get("parent_code_sha") == base_sha
                and run.get("head_sha") == accepted_sha
                and run.get("head_branch") == "main"
                and run.get("event") == "push"
                and run.get("status") == "completed"
                and run.get("conclusion") == "success"
                and job.get("head_sha") == accepted_sha
                and job.get("status") == "completed"
                and job.get("conclusion") == "success"
                and suite.get("head_sha") == accepted_sha
                and suite.get("after_sha") == accepted_sha
                and suite.get("before_sha") == base_sha
                and suite.get("status") == "completed"
                and suite.get("conclusion") == "success"
                and check_run.get("head_sha") == accepted_sha
                and check_run.get("status") == "completed"
                and check_run.get("conclusion") == "success"
                and cardinality.get("artifact_count") == 0
                and cardinality.get("job_count") == 1
                and cardinality.get("pull_request_count") == 0
                and cardinality.get("referenced_workflow_count") == 0
                and cardinality.get("job_ids") == [job.get("id")]
                and isinstance(steps, list)
                and bool(steps)
                and all(
                    isinstance(step, dict)
                    and step.get("status") == "completed"
                    and step.get("conclusion") == "success"
                    for step in steps
                )
            )
        self.problems.require(
            ci_ok,
            f"{context}.ci",
            "CI attestation must prove the exact accepted-control main push and sole build job green",
        )

        branch_identity = {
            "schema_version": 1,
            "record_kind": "phase_branch",
            "phase_id": PHASE_ID,
            "branch_id": "B0010",
            "wave_id": "R07",
            "branch_name": "codex/reorg-completion-2026-08-r07-matrix-functions-powers-ch18",
            "lane_id": "codex-lane",
            "owner_id": "primary-human",
            "operator_ids": ["codex-local"],
            "base_checkpoint_id": C0005_CHECKPOINT_ID,
            "base_sha": base_sha,
            "baseline_projection_id": "P0010",
            "shared_request_ids": ["R0011"],
            "status": (
                "accepted"
                if accepted_present
                else "delivered"
                if delivered_present
                else "active"
                if activation_present
                else "planned"
            ),
        }
        for key, expected in branch_identity.items():
            self.problems.require(
                branch.get(key) == expected,
                f"{context}.branch.{key}",
                f"expected {expected!r}",
            )
        expected_delivery = (
            {
                "commit_sha": R07_DELIVERY_SHA,
                "report": {
                    "path": R07_DELIVERY_REPORT_PATH,
                    "sha256": R07_DELIVERY_REPORT_SHA256,
                },
                "scope_evidence": {
                    "path": R07_DELIVERY_SCOPE_PATH,
                    "sha256": R07_DELIVERY_SCOPE_SHA256,
                },
            }
            if delivered_present
            else {"commit_sha": None, "report": None, "scope_evidence": None}
        )
        expected_integration = (
            {
                "accepted_checkpoint_id": C0006_CHECKPOINT_ID,
                "accepted_sha": C0006_CODE_SHA,
                "method": "merge",
            }
            if accepted_present
            else {"accepted_checkpoint_id": None, "accepted_sha": None, "method": None}
        )
        expected_retirement_status = "due" if accepted_present else "not_due"
        self.problems.require(
            branch.get("delivery") == expected_delivery
            and branch.get("integration") == expected_integration
            and isinstance(branch.get("retirement"), dict)
            and branch["retirement"].get("status") == expected_retirement_status
            and branch["retirement"].get("retired_at") is None
            and branch["retirement"].get("retired_by") is None,
            f"{context}.branch.lifecycle",
            "branch must carry the exact mode-specific delivery, integration, and retirement state",
        )
        m07 = next(
            (
                row
                for row in self.phase.get("milestones", [])
                if isinstance(row, dict) and row.get("milestone_id") == "M07"
            ),
            None,
        )
        self.problems.require(
            isinstance(m07, dict)
            and m07.get("status") == ("accepted" if accepted_present else "ready")
            and m07.get("accepted_checkpoint_id")
            == (C0006_CHECKPOINT_ID if accepted_present else None),
            f"{context}.milestone.lifecycle",
            "M07 must remain ready through integration and be accepted exactly at C0006",
        )

        projection_identity = {
            "schema_version": 1,
            "record_kind": "baseline_projection",
            "phase_id": PHASE_ID,
            "projection_id": "P0010",
            "wave_id": "R07",
            "base_checkpoint_id": C0005_CHECKPOINT_ID,
            "status": "retired" if accepted_present else "active",
            "superseded_by": None,
        }
        for key, expected in projection_identity.items():
            self.problems.require(
                projection.get(key) == expected,
                f"{context}.projection.{key}",
                f"expected {expected!r}",
            )
        request_identity = {
            "schema_version": 1,
            "record_kind": "shared_file_request",
            "phase_id": PHASE_ID,
            "request_id": "R0011",
            "wave_id": "R07",
            "lane_id": "codex-lane",
            "requester_id": "primary-human",
            "target_checkpoint_id": C0005_CHECKPOINT_ID,
            "target_base_sha": base_sha,
            "valid_through_checkpoint_id": C0005_CHECKPOINT_ID,
            "status": "applied" if accepted_present else "active",
            "supersedes": None,
            "superseded_by": None,
            "created_at": contract.get("reviewed_at"),
        }
        for key, expected in request_identity.items():
            self.problems.require(
                request.get(key) == expected,
                f"{context}.request.{key}",
                f"expected {expected!r}",
            )
        if accepted_present:
            gates_live = self.phase_dir / "checkpoints/C0006-gates.md"
            gates_digest = (
                sha256_path(gates_live) if gates_live.is_file() else "<missing>"
            )
            resolution = request.get("resolution")
            resolved_at = (
                resolution.get("resolved_at")
                if isinstance(resolution, dict)
                else None
            )
            actual_without_time = (
                {k: v for k, v in resolution.items() if k != "resolved_at"}
                if isinstance(resolution, dict)
                else {}
            )
            self.problems.require(
                actual_without_time
                == {
                    "checkpoint_id": C0006_CHECKPOINT_ID,
                    "commit_sha": C0006_CODE_SHA,
                    "reason": C0006_APPLIED_RESOLUTION_REASON,
                    "resolved_by": "primary-human",
                    "validation_evidence": [
                        {
                            "path": (
                                f"{DEFAULT_PHASE_DIR.as_posix()}"
                                "/checkpoints/C0006-gates.md"
                            ),
                            "sha256": gates_digest,
                        }
                    ],
                }
                and isinstance(resolved_at, str)
                and RFC3339_RE.fullmatch(resolved_at) is not None,
                f"{context}.request.resolution",
                "applied R0011 must record exact C0006 evidence and authority",
            )
        else:
            self.problems.require(
                request.get("resolution")
                == {
                    "checkpoint_id": None,
                    "commit_sha": None,
                    "reason": None,
                    "resolved_at": None,
                    "resolved_by": None,
                    "validation_evidence": [],
                },
                f"{context}.request.resolution",
                "active request must remain unresolved",
            )

        selector_path = self.phase_dir / "selectors/R07.tsv"
        _selector_header, selector_rows = self.read_tsv(
            selector_path,
            self.relative(selector_path),
            headers.get("selector", ()),
        )
        # Inventory has the phase inventory schema, not the two-column selector
        # header authenticated for R07.tsv.
        _inventory_header, inventory_rows = self.read_tsv(
            self.phase_dir / "branches/B0010-inventory.tsv",
            f"{prefix}/branches/B0010-inventory.tsv",
            SCOPE_HEADER,
        )
        module_rows = self.r07_tsv("B0010-module-routes.tsv", "module_routes")
        wrapper_rows = self.r07_tsv("B0010-wrapper-imports.tsv", "wrapper_plan")
        declaration_rows = self.r07_tsv(
            "B0010-declaration-routes.tsv", "declaration_routes"
        )
        source_rows = self.r07_tsv("B0010-source-commands.tsv", "source_commands")
        closure_rows = self.r07_tsv("B0010-private-closure.tsv", "private_closure")
        normalization_rows = self.r07_tsv(
            "B0010-private-normalization.tsv", "private_normalization"
        )
        dag_rows = self.r07_tsv("B0010-destination-dag.tsv", "destination_dag")
        # Destination records have a richer fixed schema than tier assignments.
        _destination_header, destination_rows = self.read_tsv(
            self.phase_dir / "branches/B0010-destinations.tsv",
            f"{prefix}/branches/B0010-destinations.tsv",
            ("module", "tier", "existence", "base_blob_oid", "rationale"),
        )
        consumer_rows = self.r07_tsv("B0010-consumers.tsv", "consumers")
        test_rows = self.r07_tsv("B0010-test-plan.tsv", "test_plan")
        tier_rows = self.r07_tsv("B0010-tier-assignments.tsv", "tier_assignments")
        _scope_header, scope_rows = self.read_tsv(
            self.phase_dir / "branches/B0010-scope-rules.tsv",
            f"{prefix}/branches/B0010-scope-rules.tsv",
            ("scope", "match", "path", "authority_id", "rationale"),
        )
        post_move_rows = self.r07_tsv(
            "B0010-post-move-import-manifest.tsv", "post_move_import_manifest"
        )
        external_supply_rows = self.r07_tsv(
            "B0010-external-owner-supply.tsv", "external_owner_supply"
        )
        request_plan_path = self.phase_dir / "requests/R0011-request-plan.tsv"
        _request_plan_header, request_plan_rows = self.read_tsv(
            request_plan_path,
            self.relative(request_plan_path),
            headers.get("request_plan", ()),
        )
        request_post_path = self.phase_dir / "requests/R0011-postimages.tsv"
        _post_header, post_rows = self.read_tsv(
            request_post_path,
            self.relative(request_post_path),
            ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
        )
        request_manifest_path = self.phase_dir / "requests/R0011-import-manifest.tsv"
        _manifest_header, request_manifest_rows = self.read_tsv(
            request_manifest_path,
            self.relative(request_manifest_path),
            ("path", "pre_imports", "post_imports", "added_imports", "removed_imports"),
        )

        graph_ref = projection.get("projection_graph")
        graph_path = (
            self.root / graph_ref.get("path")
            if isinstance(graph_ref, dict) and isinstance(graph_ref.get("path"), str)
            else self.phase_dir / "projections/P0010.tsv.gz"
        )
        projection_declarations, edges, graph_counts = self.parse_r07_projection(
            graph_path
        )
        self.problems.require(
            projection.get("expected_counts") == graph_counts
            and projection_review.get("counts")
            == {
                "body_edges": graph_counts["body_edges"],
                "declarations": graph_counts["declarations"],
                "signature_edges": graph_counts["signature_edges"],
                "union_edges": graph_counts["union_edges"],
            },
            f"{context}.projection.counts",
            "P0010 record, projection review, and actual format-2 counts must agree",
        )

        selector_pairs = [
            (row.get("module", ""), normalize_path(row.get("path", "")))
            for row in selector_rows
        ]
        selector_by_module = dict(selector_pairs)
        selector_modules = set(selector_by_module)
        selector_paths = set(selector_by_module.values())
        self.problems.require(
            len(selector_pairs) == counts.get("owners")
            and len(selector_by_module) == len(selector_pairs)
            and len(selector_paths) == len(selector_pairs)
            and all(path_from_module(module) == path for module, path in selector_pairs)
            and selector_pairs == sorted(selector_pairs),
            f"{context}.selector",
            "selector must be sorted, duplicate-free, and contain exact module/path identities",
        )
        base_blobs = self.git_tree_blobs(base_sha)
        inventory_by_module = {
            row.get("module", ""): row for row in inventory_rows
        }
        self.problems.require(
            len(inventory_by_module) == len(inventory_rows)
            and set(inventory_by_module) == selector_modules
            and all(
                row.get("path") == selector_by_module.get(module)
                and row.get("base_blob_oid") == base_blobs.get(row.get("path", ""))
                and row.get("phase_scope") == "in_scope"
                and row.get("lane_id") == "codex-lane"
                and row.get("wave_id") == "R07"
                for module, row in inventory_by_module.items()
            )
            and Counter(row.get("current_tier") for row in inventory_rows)
            == Counter({"unclassified": 43, "reusable": 2}),
            f"{context}.inventory",
            "inventory must be the exact 43-unclassified plus two naming-only C0005 owners",
        )

        owned_rules = self.parse_rules(branch.get("owned_paths"), f"{context}.branch.owned_paths")
        destination_rules = self.parse_rules(
            branch.get("destination_prefixes"),
            f"{context}.branch.destination_prefixes",
        )
        forbidden_rules = self.parse_rules(
            branch.get("forbidden_paths"), f"{context}.branch.forbidden_paths"
        )
        self.problems.require(
            {(rule.match, rule.path) for rule in owned_rules}
            == {("exact", path) for path in selector_paths},
            f"{context}.branch.owned_paths",
            "owned paths must equal every and only frozen R07 owner",
        )
        self.problems.require(
            len(destination_rules) == counts.get("branch_prefixes")
            and all(rule.match == "prefix" for rule in destination_rules),
            f"{context}.branch.destination_prefixes",
            "destination authority must contain only the reviewed prefixes",
        )

        module_by_owner = {row.get("owner_module", ""): row for row in module_rows}
        wrapper_by_owner = {row.get("owner_module", ""): row for row in wrapper_rows}
        projection_identity_set = {
            (owner, name, kind, visibility)
            for name, (owner, kind, visibility) in projection_declarations.items()
        }
        declaration_identity_set = {
            (
                row.get("baseline_owner_module", ""),
                row.get("baseline_declaration_name", ""),
                row.get("kind", ""),
                row.get("visibility", ""),
            )
            for row in declaration_rows
        }
        source_identity_set = {
            (
                row.get("owner_module", ""),
                row.get("baseline_declaration_name", ""),
                projection_declarations.get(
                    row.get("baseline_declaration_name", ""), ("", "", "")
                )[1],
                projection_declarations.get(
                    row.get("baseline_declaration_name", ""), ("", "", "")
                )[2],
            )
            for row in source_rows
        }
        destination_by_module = {
            row.get("module", ""): row for row in destination_rows
        }
        destination_modules = set(destination_by_module)
        route_by_name = {
            row.get("baseline_declaration_name", ""): row
            for row in declaration_rows
        }
        self.problems.require(
            len(module_by_owner) == len(module_rows)
            and set(module_by_owner) == selector_modules
            and len(wrapper_by_owner) == len(wrapper_rows)
            and set(wrapper_by_owner) == selector_modules,
            f"{context}.module_routes",
            "module and wrapper plans must cover exact selected owners",
        )
        self.problems.require(
            len(route_by_name) == len(declaration_rows)
            and projection_identity_set == declaration_identity_set == source_identity_set
            and set(route_by_name) == set(projection_declarations),
            f"{context}.declaration_routes",
            "projection, declaration-route, and source-command identities must agree",
        )
        routed_counts = Counter(
            row.get("baseline_owner_module") for row in declaration_rows
        )
        routed_destinations: dict[str, set[str]] = defaultdict(set)
        public_destinations: dict[str, set[str]] = defaultdict(set)
        for row in declaration_rows:
            owner = row.get("baseline_owner_module", "")
            destination = row.get("destination_module", "")
            routed_destinations[owner].add(destination)
            if row.get("visibility") == "public":
                public_destinations[owner].add(destination)
        for owner, row in module_by_owner.items():
            listed = set(split_values(row.get("destination_modules", "")))
            self.problems.require(
                row.get("path") == selector_by_module.get(owner)
                and row.get("base_blob_oid")
                == inventory_by_module.get(owner, {}).get("base_blob_oid")
                and row.get("review_status") == "reviewed"
                and row.get("compatibility_action") == "import_only_wrapper"
                and row.get("declaration_count", "").isdigit()
                and int(row.get("declaration_count", "0")) == routed_counts[owner]
                and listed == routed_destinations[owner],
                f"{context}.module_routes[{owner}]",
                "module route must bind inventory, exact declaration count/destinations, and wrapper retention",
            )

        self.problems.require(
            len(destination_by_module) == len(destination_rows)
            and set().union(*routed_destinations.values()) == destination_modules
            and all(
                row.get("existence") == "new_casefold_vacant"
                and row.get("base_blob_oid") == "-"
                and path_from_module(module) not in base_blobs
                and row.get("tier") in {"reusable", "internal", "source"}
                for module, row in destination_by_module.items()
            )
            and Counter(row.get("tier") for row in destination_rows)
            == Counter({"reusable": 26, "internal": 3, "source": 1}),
            f"{context}.destinations",
            "all 30 semantic destinations must be routed, casefold-vacant new leaves with exact tiers",
        )

        owner_payloads = self.git_blob_payloads(
            {
                row.get("base_blob_oid", "")
                for row in inventory_rows
                if SHA1_RE.fullmatch(row.get("base_blob_oid", ""))
            },
            f"{context} owner preimages",
        )
        internal_destinations = {
            module
            for module, row in destination_by_module.items()
            if row.get("tier") == "internal"
        }
        for owner, row in wrapper_by_owner.items():
            oid = row.get("base_blob_oid", "")
            payload = owner_payloads.get(oid)
            base_imports = self.r07_imports(payload) if payload is not None else []
            preserved = split_values(row.get("preserved_imports", ""))
            appended = split_values(row.get("appended_imports", ""))
            post = split_values(row.get("post_imports", ""))
            self.problems.require(
                row.get("path") == selector_by_module.get(owner)
                and oid == inventory_by_module.get(owner, {}).get("base_blob_oid")
                and preserved == base_imports
                and appended == sorted(public_destinations[owner])
                and post == preserved + appended
                and len(post) == len(set(post))
                and not (set(appended) & internal_destinations),
                f"{context}.wrapper_imports[{owner}]",
                "wrapper must preserve exact historical imports, append exact public routes, and hide internal leaves",
            )

        owner_projection_orders: dict[str, dict[str, int]] = defaultdict(dict)
        for name, (owner, _kind, _visibility) in projection_declarations.items():
            owner_projection_orders[owner][name] = len(owner_projection_orders[owner])
        source_by_name = {
            row.get("baseline_declaration_name", ""): row for row in source_rows
        }
        coordinate_fields = (
            "start_line_0",
            "start_column_0",
            "end_line_0",
            "end_column_0",
            "selection_start_line_0",
            "selection_start_column_0",
            "selection_end_line_0",
            "selection_end_column_0",
        )
        for name, row in route_by_name.items():
            owner = row.get("baseline_owner_module", "")
            source = source_by_name.get(name, {})
            self.problems.require(
                row.get("projection_order", "").isdigit()
                and int(row.get("projection_order", "0"))
                == owner_projection_orders[owner].get(name)
                and row.get("source_ordinal") == source.get("source_ordinal")
                and row.get("destination_module") in destination_modules
                and row.get("route_class") in {"relocate_whole", "relocate_split"},
                f"{context}.declaration_routes[{name}]",
                "route must preserve projection/source order and target one reviewed destination",
            )
        for name, row in source_by_name.items():
            owner = row.get("owner_module", "")
            oid = row.get("base_blob_oid", "")
            payload = owner_payloads.get(oid)
            numeric = all(row.get(field, "").isdigit() for field in coordinate_fields)
            command = None
            if payload is not None and numeric:
                command = self.r07_source_command_bytes(
                    payload,
                    tuple(int(row[field]) for field in coordinate_fields[:4]),
                )
            self.problems.require(
                row.get("path") == selector_by_module.get(owner)
                and oid == inventory_by_module.get(owner, {}).get("base_blob_oid")
                and row.get("ilean_path") == owner.replace(".", "/") + ".ilean"
                and SHA256_RE.fullmatch(row.get("ilean_sha256", "")) is not None
                and numeric
                and command is not None
                and hashlib.sha256(command or b"").hexdigest().upper()
                == row.get("command_sha256")
                and row.get("source_ordinal", "").isdigit(),
                f"{context}.source_commands[{name}]",
                "source command must bind the exact C0005 blob and compiler coordinate byte slice",
            )
        for owner in selector_modules:
            ordinals = {
                int(row["source_ordinal"])
                for row in source_rows
                if row.get("owner_module") == owner
                and row.get("source_ordinal", "").isdigit()
            }
            self.problems.require(
                ordinals == set(range(len(ordinals))),
                f"{context}.source_commands[{owner}]",
                "source ordinals must form one zero-based command range",
            )

        private_names = {
            name
            for name, (_owner, _kind, visibility) in projection_declarations.items()
            if visibility == "private"
        }
        public_names = set(projection_declarations) - private_names
        normalization_by_old = {
            row.get("old_private", ""): row for row in normalization_rows
        }
        self.problems.require(
            len(normalization_by_old) == len(normalization_rows)
            and set(normalization_by_old) == private_names,
            f"{context}.private_normalization",
            "normalization must cover every and only private declaration",
        )
        for name in private_names:
            route = route_by_name.get(name, {})
            normalized = normalization_by_old.get(name, {})
            new_name = normalized.get("new_private")
            self.problems.require(
                normalized.get("destination_module") == route.get("destination_module")
                and route.get("normalization_decision") == f"rename:{new_name}"
                and isinstance(new_name, str)
                and new_name.startswith(
                    "_private." + route.get("destination_module", "") + "."
                ),
                f"{context}.private_normalization[{name}]",
                "private identity must be renamed into its routed destination",
            )
        self.problems.require(
            all(
                row.get("normalization_decision") == "-"
                for row in declaration_rows
                if row.get("visibility") == "public"
            ),
            f"{context}.private_normalization",
            "public declaration names must remain unchanged",
        )

        reverse: dict[str, set[str]] = defaultdict(set)
        for _kind, source, target in edges:
            if source in projection_declarations and target in projection_declarations:
                reverse[target].add(source)
        closure_expected = set(private_names)
        frontier = list(private_names)
        while frontier:
            target = frontier.pop()
            for dependent in reverse.get(target, set()):
                if dependent not in closure_expected:
                    closure_expected.add(dependent)
                    frontier.append(dependent)
        closure_by_name = {row.get("declaration", ""): row for row in closure_rows}
        self.problems.require(
            len(closure_by_name) == len(closure_rows)
            and set(closure_by_name) == closure_expected
            and all(
                row.get("selected_owner") == "yes"
                and row.get("owner_module")
                == projection_declarations.get(name, (None, None, None))[0]
                and row.get("visibility")
                == projection_declarations.get(name, (None, None, None))[2]
                and row.get("closure_role")
                == ("private_seed" if name in private_names else "reverse_dependent_boundary")
                for name, row in closure_by_name.items()
            ),
            f"{context}.private_closure",
            "private closure must be the complete selected-owner reverse-dependency closure",
        )

        dag_expected: Counter[tuple[str, str, str]] = Counter()
        for kind, source, target in edges:
            source_route = route_by_name.get(source)
            target_route = route_by_name.get(target)
            if source_route is None or target_route is None:
                continue
            source_destination = source_route.get("destination_module", "")
            target_destination = target_route.get("destination_module", "")
            if source_destination != target_destination:
                dag_expected[(source_destination, target_destination, kind)] += 1
        dag_actual: Counter[tuple[str, str, str]] = Counter()
        dag_graph: dict[str, set[str]] = defaultdict(set)
        dag_nodes: set[str] = set()
        for row in dag_rows:
            source = row.get("from_destination", "")
            target = row.get("to_destination", "")
            dag_nodes.update((source, target))
            dag_graph[source].add(target)
            for kind, column in (("signature", "signature_edges"), ("body", "body_edges")):
                value = row.get(column, "")
                if value.isdigit() and int(value):
                    dag_actual[(source, target, kind)] += int(value)
        self.problems.require(
            dag_actual == dag_expected
            and len(dag_rows) == counts.get("destination_dag_rows"),
            f"{context}.destination_dag",
            "DAG rows must exactly aggregate cross-destination signature/body edges",
        )
        self.check_acyclic(dag_graph, f"{context}.destination_dag")

        validate_r07_relation_snapshot(
            {
                "owners": selector_modules,
                "selector": set(inventory_by_module),
                "routes": set(module_by_owner),
                "wrappers": set(wrapper_by_owner),
                "projection_declarations": projection_identity_set,
                "route_declarations": declaration_identity_set,
                "source_declarations": source_identity_set,
                "private_declarations": private_names,
                "normalization": set(normalization_by_old),
                "closure": set(closure_by_name),
                "destinations": destination_modules,
                "destination_tiers": set(destination_by_module),
                "dag_nodes": dag_nodes,
            },
            self.problems,
            context=f"{context}.relations",
        )

        consumer_keys = {
            (
                row.get("consumer_module", ""),
                row.get("consumer_path", ""),
                row.get("consumer_scope", ""),
                row.get("old_import", ""),
                row.get("new_import", ""),
            )
            for row in consumer_rows
        }
        consumer_paths = {row.get("consumer_path", "") for row in consumer_rows}
        consumer_oids = {
            base_blobs.get(path, "") for path in consumer_paths if path in base_blobs
        }
        consumer_payloads = self.git_blob_payloads(
            {oid for oid in consumer_oids if SHA1_RE.fullmatch(oid)},
            f"{context} consumer preimages",
        )
        outside_consumer_pairs = {
            (row.get("consumer_module", ""), row.get("consumer_path", ""))
            for row in consumer_rows
            if row.get("consumer_scope") == "outside"
        }
        for row in consumer_rows:
            consumer_module = row.get("consumer_module", "")
            consumer_path = row.get("consumer_path", "")
            scope = row.get("consumer_scope", "")
            old_import = row.get("old_import", "")
            new_import = row.get("new_import", "")
            new_imports = split_values(new_import)
            payload = consumer_payloads.get(base_blobs.get(consumer_path, ""))
            base_imports = self.r07_imports(payload) if payload is not None else []
            self.problems.require(
                module_from_path(consumer_path) == consumer_module
                and scope in {"selected_owner", "outside"}
                and old_import in selector_modules
                and old_import in base_imports
                and all(
                    replacement == old_import
                    or replacement in destination_modules
                    or replacement
                    in set(
                        split_values(
                            wrapper_by_owner.get(old_import, {}).get(
                                "post_imports", ""
                            )
                        )
                    )
                    or path_from_module(replacement)
                    in {
                        normalize_path(path)
                        for path in request.get("paths", [])
                        if isinstance(path, str)
                    }
                    for replacement in new_imports
                )
                and (
                    scope == "outside"
                    or (
                        consumer_module in selector_modules
                        and consumer_path == selector_by_module.get(consumer_module)
                    )
                ),
                f"{context}.consumers[{consumer_module}->{old_import}]",
                "consumer edge must witness an exact C0005 direct import and reviewed replacement",
            )
        self.problems.require(
            len(consumer_keys) == len(consumer_rows)
            and Counter(row.get("consumer_scope") for row in consumer_rows)
            == Counter({"selected_owner": 48, "outside": 73})
            and len(outside_consumer_pairs) == counts.get("external_consumers"),
            f"{context}.consumers",
            "consumer map must have 48 selected-owner and 73 outside edges across 24 consumers",
        )

        test_by_class: dict[str, list[dict[str, str]]] = defaultdict(list)
        for row in test_rows:
            test_by_class[row.get("test_class", "")].append(row)
        self.problems.require(
            Counter({key: len(value) for key, value in test_by_class.items()})
            == Counter(
                {
                    "all": 1,
                    "canonical_only": 30,
                    "consumer": 24,
                    "dependency_boundary": 1,
                    "old_only": 45,
                    "private_normalization": 1,
                }
            )
            and len({row.get("target") for row in test_rows}) == len(test_rows),
            f"{context}.tests",
            "test plan must contain exact isolated canonical/old/consumer and aggregate gates",
        )
        canonical_imports = {
            split_values(row.get("imports", ""))[0]
            for row in test_by_class.get("canonical_only", [])
            if len(split_values(row.get("imports", ""))) == 1
        }
        old_imports = {
            split_values(row.get("imports", ""))[0]
            for row in test_by_class.get("old_only", [])
            if len(split_values(row.get("imports", ""))) == 1
        }
        consumer_imports = {
            (
                split_values(row.get("imports", ""))[0],
                path_from_module(split_values(row.get("imports", ""))[0]),
            )
            for row in test_by_class.get("consumer", [])
            if len(split_values(row.get("imports", ""))) == 1
        }
        public_by_destination: dict[str, set[str]] = defaultdict(set)
        for name in public_names:
            public_by_destination[
                route_by_name[name].get("destination_module", "")
            ].add(name)
        for row in test_by_class.get("canonical_only", []):
            imports = split_values(row.get("imports", ""))
            destination = imports[0] if len(imports) == 1 else ""
            expected = set(split_values(row.get("expected_declarations", "")))
            expected_ok = (
                expected == public_by_destination[destination]
                if public_by_destination[destination]
                else destination_by_module.get(destination, {}).get("tier") == "internal"
                and row.get("expected_declarations", "").startswith(
                    "direct compile/import witness"
                )
            )
            self.problems.require(
                destination in destination_modules
                and expected_ok
                and set(split_values(row.get("forbidden_imports", "")))
                == selector_modules,
                f"{context}.tests[{row.get('target', '')}]",
                "canonical-only test must import one destination, check its public declarations, and forbid all wrappers",
            )
        self.problems.require(
            canonical_imports == destination_modules
            and old_imports == selector_modules
            and consumer_imports == outside_consumer_pairs,
            f"{context}.tests",
            "isolated tests must cover every destination, wrapper, and outside consumer exactly once",
        )

        request_paths_raw = request.get("paths")
        request_paths = (
            {normalize_path(path) for path in request_paths_raw}
            if isinstance(request_paths_raw, list)
            and all(isinstance(path, str) for path in request_paths_raw)
            else set()
        )
        self.problems.require(
            isinstance(request_paths_raw, list)
            and request_paths_raw == sorted(request_paths)
            and len(request_paths) == counts.get("request_paths")
            and request.get("blocks") == ["R07"]
            and request.get("depends_on") == [],
            f"{context}.request.paths",
            "R0011 must block only R07 and contain 46 sorted unique paths",
        )
        preimage_rows = request.get("preimage_blobs")
        preimages: dict[str, str | None] = {}
        if isinstance(preimage_rows, list):
            for index, row in enumerate(preimage_rows):
                if (
                    not isinstance(row, dict)
                    or set(row) != {"blob_oid", "path"}
                    or not isinstance(row.get("path"), str)
                    or (
                        row.get("blob_oid") is not None
                        and (
                            not isinstance(row.get("blob_oid"), str)
                            or SHA1_RE.fullmatch(row.get("blob_oid", "")) is None
                        )
                    )
                    or row["path"] in preimages
                ):
                    self.problems.add(
                        f"{context}.request.preimage_blobs[{index}]",
                        "expected unique path and null/lowercase blob_oid",
                    )
                    continue
                preimages[row["path"]] = row["blob_oid"]
        self.problems.require(
            set(preimages) == request_paths
            and isinstance(preimage_rows, list)
            and [row.get("path") for row in preimage_rows if isinstance(row, dict)]
            == sorted(request_paths)
            and all(preimages[path] == base_blobs.get(path) for path in request_paths),
            f"{context}.request.preimage_blobs",
            "R0011 preimages must be exact C0005 blobs (null only for new files)",
        )
        new_request_paths = {path for path, oid in preimages.items() if oid is None}
        self.problems.require(
            len(new_request_paths) == 12
            and all(path.endswith(".lean") for path in new_request_paths),
            f"{context}.request.preimage_blobs",
            "R0011 must add exactly 12 declaration-free public umbrellas",
        )
        shared_exact = {
            rule.path for rule in self.shared_rules if rule.match == "exact"
        }
        self.problems.require(
            accepted_present or request_paths <= shared_exact,
            f"{context}.shared_paths",
            "every R0011 path must be held by exact primary-human reservation "
            "until the request is applied at C0006",
        )

        request_plan_by_path = {row.get("path", ""): row for row in request_plan_rows}
        post_by_path = {row.get("path", ""): row for row in post_rows}
        self.problems.require(
            len(request_plan_by_path) == len(request_plan_rows)
            and set(request_plan_by_path) == request_paths
            and len(post_by_path) == len(post_rows)
            and set(post_by_path) == request_paths,
            f"{context}.request.evidence",
            "request plan and postimage ledger must cover every and only R0011 paths",
        )
        preimage_payloads = self.git_blob_payloads(
            {oid for oid in preimages.values() if isinstance(oid, str)},
            f"{context} R0011 preimages",
        )
        for path in request_paths:
            plan = request_plan_by_path.get(path, {})
            post = post_by_path.get(path, {})
            oid = preimages.get(path)
            payload = preimage_payloads.get(oid) if isinstance(oid, str) else None
            pre_sha = (
                hashlib.sha256(payload).hexdigest().upper()
                if payload is not None
                else "-"
            )
            self.problems.require(
                plan.get("base_blob_oid") == (oid if oid is not None else "-")
                and post.get("preimage_blob_oid") == (oid if oid is not None else "-")
                and post.get("preimage_sha256") == pre_sha
                and SHA256_RE.fullmatch(post.get("postimage_sha256", "")) is not None,
                f"{context}.request.evidence[{path}]",
                "request plan/ledger must pin exact preimage blob, preimage bytes, and postimage digest",
            )

        patch_ref = request.get("patch")
        patch_path = (
            self.root / patch_ref.get("path")
            if isinstance(patch_ref, dict) and isinstance(patch_ref.get("path"), str)
            else self.phase_dir / "requests/R0011.patch"
        )
        render_ok = (
            render.get("base_checkpoint_id") == C0005_CHECKPOINT_ID
            and render.get("base_sha") == base_sha
            and render.get("status") == "ready"
            and render.get("path_count") == len(request_paths)
            and render.get("path_list_sha256") == path_list_sha256(request_paths)
            and isinstance(render.get("forward_tree"), str)
            and SHA1_RE.fullmatch(render.get("forward_tree", "")) is not None
            and isinstance(patch_ref, dict)
            and render.get("patch_sha256") == patch_ref.get("sha256")
            and render.get("postimage_ledger_sha256")
            == artifact_map.get(self.relative(request_post_path))
            and render.get("request_plan_sha256")
            == artifact_map.get(self.relative(request_plan_path))
            and render.get("import_manifest_sha256")
            == artifact_map.get(self.relative(request_manifest_path))
        )
        self.problems.require(
            render_ok,
            f"{context}.request.render_review",
            "render review must bind exact base, path list, patch, ledgers, and forward tree",
        )
        postimage_payloads = self.replay_r07_request(
            base_sha,
            patch_path,
            request_paths,
            render.get("forward_tree", ""),
        )
        render_postimages = render.get("postimages")
        self.problems.require(
            isinstance(render_postimages, dict)
            and set(render_postimages) == request_paths
            and all(
                hashlib.sha256(postimage_payloads.get(path, b"")).hexdigest().upper()
                == post_by_path.get(path, {}).get("postimage_sha256")
                == render_postimages.get(path)
                for path in request_paths
            ),
            f"{context}.request.postimages",
            "replayed bytes, postimage ledger, and render review must agree for all 46 paths",
        )
        if delivered_present:
            if accepted_present:
                # The applied request record advances at acceptance; hold the
                # reviewed bytes to the exact C0006 code history instead.
                historical_request = self.git_bytes(
                    "show",
                    f"{C0006_CODE_SHA}:{self.relative(paths['request'])}",
                    check=False,
                )
                request_bytes_exact = (
                    historical_request.returncode == 0
                    and hashlib.sha256(historical_request.stdout).hexdigest().upper()
                    == R07_R0011_REQUEST_SHA256
                )
            else:
                request_bytes_exact = (
                    sha256_path(paths["request"]) == R07_R0011_REQUEST_SHA256
                )
            request_exact = (
                request_bytes_exact
                and len(request_paths) == 46
                and path_list_sha256(request_paths) == R07_R0011_PATH_LIST_SHA256
                and isinstance(patch_ref, dict)
                and patch_ref.get("sha256") == R07_R0011_PATCH_SHA256
                and sha256_path(patch_path) == R07_R0011_PATCH_SHA256
                and artifact_map.get(self.relative(request_post_path))
                == R07_R0011_POSTIMAGES_SHA256
                and artifact_map.get(self.relative(request_manifest_path))
                == R07_R0011_IMPORT_MANIFEST_SHA256
                and artifact_map.get(self.relative(request_plan_path))
                == R07_R0011_PLAN_SHA256
                and render.get("forward_tree") == R07_R0011_TREE
            )
            self.problems.require(
                request_exact,
                f"{context}.request.delivered_identity",
                "delivered mode must retain the exact reviewed 46-path R0011 request, patch, ledgers, manifest, plan, and replay tree",
            )
            correction_paths = set(R07_CORRECTION_POSTIMAGES)
            self.problems.require(
                correction_paths & request_paths
                == correction_paths - {"tools/architecture/check_layout.py"},
                f"{context}.request.correction_scope",
                "the correction must alter exactly three R0011 paths plus check_layout.py",
            )
            corrected_postimages = self.replay_r07_correction(
                base_sha,
                patch_path,
                request_paths,
                R07_R0011_TREE,
                self.root / R07_CORRECTION_PATH,
            )
            expected_live = dict(postimage_payloads)
            expected_live.update(
                {
                    path: corrected_postimages.get(path, b"")
                    for path in correction_paths
                }
            )
            # A later reviewed epoch supersedes an earlier terminal ratchet, as
            # R07's superseded C0004's. Once the R09/R10 integration is present,
            # R07's live replay no longer describes these files; the union
            # ledger is validated against the attested audited base, and live
            # bytes are governed by the per-batch gates.
            r09_r10_integrated = (
                self.root / R09_R10_INTEGRATION_AUTH_PATH
            ).is_file()
            if r09_r10_integrated:
                amendment = self.root / R09_R10_TIER_AMENDMENT_PATH
                self.problems.require(
                    amendment.is_file()
                    and sha256_path(amendment) == R09_R10_TIER_AMENDMENT_SHA256,
                    f"{context}.request.tier_amendment",
                    "the reviewed tier amendment must be present with its exact "
                    "pinned bytes",
                )
                union_rows = [
                    line.split("\t")
                    for line in (self.root / R09_R10_UNION_POSTIMAGES_PATH)
                    .read_text(encoding="utf-8").splitlines()[1:]
                    if line.strip()
                ]
                self.problems.require(
                    len(union_rows) == 25,
                    f"{context}.request.union_ledger",
                    "the reviewed R0012/R0013 union must carry exactly 25 paths",
                )
                for row in union_rows:
                    expected = row[3].upper()
                    if row[0] == R09_R10_AMENDED_UNION_PATH:
                        expected = R09_R10_AMENDED_UNION_SHA256
                    blob = self.git_bytes(
                        "cat-file", "blob",
                        f"{R09_R10_UNION_FREEZE_ATTESTED_SHA}:{row[0]}",
                        check=False,
                    )
                    if blob.returncode:
                        self.problems.add(
                            f"{context}.request.union_postimage[{row[0]}]",
                            "cannot read the union postimage at the attested "
                            "audited base",
                        )
                        continue
                    self.problems.require(
                        hashlib.sha256(blob.stdout).hexdigest().upper()
                        == expected,
                        f"{context}.request.union_postimage[{row[0]}]",
                        "the audited base must carry the reviewed R0012/R0013 "
                        "union postimage, or the amended postimage for the "
                        "re-anchored row",
                    )
            for path in sorted(request_paths | correction_paths):
                if r09_r10_integrated:
                    break
                live_path = self.root / Path(*PurePosixPath(path).parts)
                try:
                    live_payload = live_path.read_bytes()
                except OSError as error:
                    self.problems.add(
                        f"{context}.request.live_postimage[{path}]",
                        f"cannot read exact live postimage: {error}",
                    )
                    continue
                self.problems.require(
                    live_payload == expected_live.get(path),
                    f"{context}.request.live_postimage[{path}]",
                    "live bytes must equal the sequential exact R0011+correction replay",
                )
            for path, digest in R07_CORRECTION_POSTIMAGES.items():
                self.problems.require(
                    hashlib.sha256(corrected_postimages.get(path, b""))
                    .hexdigest()
                    .upper()
                    == digest,
                    f"{context}.request.correction_postimage[{path}]",
                    f"expected exact corrected postimage SHA-256 {digest}",
                )

        manifest_by_path = {
            row.get("path", ""): row for row in request_manifest_rows
        }
        lean_request_paths = {path for path in request_paths if path.endswith(".lean")}
        self.problems.require(
            len(manifest_by_path) == len(request_manifest_rows)
            and set(manifest_by_path) == lean_request_paths,
            f"{context}.request.import_manifest",
            "import manifest must cover every and only the 43 Lean postimages",
        )
        for path, row in manifest_by_path.items():
            oid = preimages.get(path)
            pre_imports = (
                self.r07_imports(preimage_payloads.get(oid, b""))
                if isinstance(oid, str)
                else []
            )
            post_imports = self.r07_imports(postimage_payloads.get(path, b""))
            listed_pre = split_values(row.get("pre_imports", ""))
            listed_post = split_values(row.get("post_imports", ""))
            self.problems.require(
                listed_pre == pre_imports
                and listed_post == post_imports
                and set(split_values(row.get("added_imports", "")))
                == set(post_imports) - set(pre_imports)
                and set(split_values(row.get("removed_imports", "")))
                == set(pre_imports) - set(post_imports),
                f"{context}.request.import_manifest[{path}]",
                "manifest must independently reproduce exact pre/post imports and set differences",
            )

        post_move_groups: dict[tuple[str, str], list[dict[str, str]]] = defaultdict(list)
        for row in post_move_rows:
            post_move_groups[(row.get("module", ""), row.get("role", ""))].append(row)
        post_move_imports: dict[tuple[str, str], list[str]] = {}
        valid_post_move = True
        for key, rows in post_move_groups.items():
            orders = [row.get("import_order", "") for row in rows]
            imports = [row.get("lean_import_line", "") for row in rows]
            if (
                not all(order.isdigit() for order in orders)
                or [int(order) for order in orders] != list(range(1, len(rows) + 1))
                or not all(line.startswith("import ") for line in imports)
                or len(imports) != len(set(imports))
                or any(
                    row.get("provenance")
                    not in {
                        "c0005_direct",
                        "c0005_expanded",
                        "c0005_direct+c0005_expanded",
                        "produced_destination",
                        "route_dag",
                    }
                    for row in rows
                )
            ):
                valid_post_move = False
            post_move_imports[key] = [line.removeprefix("import ") for line in imports]
        compatibility_modules = {
            module for module, role in post_move_groups if role == "compatibility"
        }
        produced_modules = {
            module for module, role in post_move_groups if role == "produced_destination"
        }
        aggregate_modules = {
            module for module, role in post_move_groups if role == "aggregate"
        }
        self.problems.require(
            valid_post_move
            and compatibility_modules == selector_modules
            and produced_modules == destination_modules
            and aggregate_modules == {module_from_path(path) for path in new_request_paths}
            and not {
                role
                for _module, role in post_move_groups
                if role not in {"compatibility", "produced_destination", "aggregate"}
            },
            f"{context}.post_move_import_manifest",
            "post-move manifest must cover exact wrappers, destinations, and 12 umbrellas with ordered imports",
        )
        for owner in selector_modules:
            self.problems.require(
                post_move_imports.get((owner, "compatibility"), [])
                == split_values(wrapper_by_owner.get(owner, {}).get("post_imports", "")),
                f"{context}.post_move_import_manifest[{owner}]",
                "compatibility manifest must equal exact wrapper post-import plan",
            )
        for path in new_request_paths:
            module = module_from_path(path)
            self.problems.require(
                post_move_imports.get((module, "aggregate"), [])
                == self.r07_imports(postimage_payloads.get(path, b"")),
                f"{context}.post_move_import_manifest[{module}]",
                "aggregate manifest must equal replayed R0011 umbrella imports",
            )
        for source, targets in dag_graph.items():
            imports = set(
                post_move_imports.get((source, "produced_destination"), [])
            )
            self.problems.require(
                targets <= imports,
                f"{context}.post_move_import_manifest[{source}]",
                "every routed DAG dependency must be a direct destination import",
            )

        supply_keys = {
            (row.get("destination_module", ""), row.get("referenced_owner_module", ""))
            for row in external_supply_rows
        }
        self.problems.require(
            len(supply_keys) == len(external_supply_rows)
            and all(
                destination in destination_modules
                and owner not in selector_modules
                and owner not in destination_modules
                and row.get("signature_edge_count", "").isdigit()
                and row.get("body_edge_count", "").isdigit()
                and int(row.get("signature_edge_count", "0"))
                + int(row.get("body_edge_count", "0"))
                > 0
                and row.get("recursive_frontier_direct") == "1"
                and row.get("post_r0011_supply") == "direct"
                and owner
                in set(
                    post_move_imports.get(
                        (destination, "produced_destination"), []
                    )
                )
                for row in external_supply_rows
                for destination, owner in [
                    (
                        row.get("destination_module", ""),
                        row.get("referenced_owner_module", ""),
                    )
                ]
            )
            and sum(
                int(row.get("signature_edge_count", "0"))
                for row in external_supply_rows
            )
            == 60
            and sum(
                int(row.get("body_edge_count", "0")) for row in external_supply_rows
            )
            == 125,
            f"{context}.external_owner_supply",
            "external owner supply must be unique, nonempty, and directly imported after R0011",
        )

        tier_by_module = {row.get("module", ""): row for row in tier_rows}
        new_aggregate_modules = {module_from_path(path) for path in new_request_paths}
        self.problems.require(
            len(tier_by_module) == len(tier_rows)
            and set(tier_by_module)
            == selector_modules | destination_modules | new_aggregate_modules
            and all(
                tier_by_module.get(owner, {}).get("tier") == "compatibility"
                for owner in selector_modules
            )
            and all(
                tier_by_module.get(module, {}).get("tier") == row.get("tier")
                for module, row in destination_by_module.items()
            )
            and all(
                tier_by_module.get(module, {}).get("tier") == "aggregate"
                for module in new_aggregate_modules
            )
            and Counter(row.get("tier") for row in tier_rows)
            == Counter(
                {
                    "compatibility": 45,
                    "reusable": 26,
                    "aggregate": 12,
                    "internal": 3,
                    "source": 1,
                }
            ),
            f"{context}.tier_assignments",
            "tiers must classify exact wrappers, destinations, and declaration-free umbrellas",
        )

        scope_sets: dict[tuple[str, str], set[str]] = defaultdict(set)
        for row in scope_rows:
            scope_sets[(row.get("scope", ""), row.get("match", ""))].add(
                normalize_path(row.get("path", ""))
            )
        forbidden_exact = {rule.path for rule in forbidden_rules if rule.match == "exact"}
        forbidden_prefix = {rule.path for rule in forbidden_rules if rule.match == "prefix"}
        destination_prefixes = {rule.path for rule in destination_rules}
        self.problems.require(
            scope_sets[("worker_owned", "exact")] == selector_paths
            and scope_sets[("worker_destination", "prefix")] == destination_prefixes
            and scope_sets[("integrator_shared_request", "exact")] == request_paths
            and scope_sets[("worker_forbidden", "exact")] == forbidden_exact
            and scope_sets[("worker_forbidden", "prefix")] == forbidden_prefix
            and len(scope_rows) == counts.get("scope_rows")
            and all(
                row.get("authority_id")
                == (
                    "codex-local"
                    if row.get("scope") in {"worker_owned", "worker_destination"}
                    else "primary-human"
                )
                for row in scope_rows
            ),
            f"{context}.scope_rules",
            "scope rules must exactly mirror branch owner/destination/forbidden and R0011 sets",
        )
        owned_path_rules = [PathRule(path, "exact") for path in selector_paths]
        self.problems.require(
            not any(
                owned.intersects(forbidden)
                for owned in owned_path_rules
                for forbidden in forbidden_rules
            )
            and not any(
                destination.intersects(forbidden)
                for destination in destination_rules
                for forbidden in forbidden_rules
            ),
            f"{context}.scope_rules",
            "worker authority must not intersect forbidden rules",
        )

        self.problems.require(
            overlap.get("base_checkpoint_id") == C0005_CHECKPOINT_ID
            and overlap.get("base_code_sha") == base_sha
            and overlap.get("wave_id") == "R07"
            and overlap.get("status") == "review_candidate"
            and overlap.get("projected_remaining_queue")
            == contract.get("projected_remaining_queue")
            and overlap.get("scope_rule_count") == len(scope_rows)
            and overlap.get("consumer_counts")
            == {
                "external_consumers": len(outside_consumer_pairs),
                "external_import_edges": sum(
                    row.get("consumer_scope") == "outside" for row in consumer_rows
                ),
                "internal_import_edges": sum(
                    row.get("consumer_scope") == "selected_owner"
                    for row in consumer_rows
                ),
                "total_import_edges": len(consumer_rows),
            },
            f"{context}.overlap_review",
            "overlap review must bind exact consumers/scope and projected R09/R10 queue",
        )
        destination_contract = overlap.get("destination_contract")
        production_destination_prefixes = {
            rule.path
            for rule in destination_rules
            if rule.path.startswith("NumStability/")
        }
        self.problems.require(
            isinstance(destination_contract, dict)
            and destination_contract.get("all_new_casefold_vacant") is True
            and destination_contract.get("count") == len(destination_modules)
            and destination_contract.get("reusable_count") == 26
            and destination_contract.get("internal_count") == 3
            and destination_contract.get("source_count") == 1
            and destination_contract.get("prefix_count")
            == len(production_destination_prefixes)
            and {
                normalize_path(path)
                for path in destination_contract.get("prefixes", [])
                if isinstance(path, str)
            }
            == production_destination_prefixes
            and destination_contract.get("branch_prefix_count")
            == len(destination_rules)
            and {
                normalize_path(path)
                for path in destination_contract.get("branch_prefixes", [])
                if isinstance(path, str)
            }
            == destination_prefixes,
            f"{context}.overlap_review.destination_contract",
            "destination overlap contract must reproduce exact tiers and branch/production prefixes",
        )

        base_casefold = {path.casefold() for path in base_blobs}
        self.problems.require(
            all(
                path_from_module(module).casefold() not in base_casefold
                and sum(
                    PathRule(prefix_path, "prefix").matches(path_from_module(module))
                    for prefix_path in production_destination_prefixes
                )
                == 1
                for module in destination_modules
            ),
            f"{context}.destinations.casefold",
            "every destination must be casefold-vacant and owned by exactly one production prefix",
        )

        def sidecar_lines(relative: str) -> list[str]:
            path = self.root / relative
            try:
                raw = path.read_bytes()
            except OSError as error:
                self.problems.add(relative, f"cannot read sidecar: {error}")
                return []
            self.problems.require(
                b"\r" not in raw and (not raw or raw.endswith(b"\n")),
                relative,
                "sidecar must use LF and end with a newline",
            )
            try:
                return raw.decode("utf-8").splitlines()
            except UnicodeError as error:
                self.problems.add(relative, f"sidecar is not UTF-8: {error}")
                return []

        branch_prefix_lines = sidecar_lines(
            f"{prefix}/branches/B0010-branch-prefixes.txt"
        )
        production_prefix_lines = sidecar_lines(
            f"{prefix}/branches/B0010-destination-prefixes.txt"
        )
        destination_module_lines = sidecar_lines(
            f"{prefix}/branches/B0010-destination-modules.txt"
        )
        shared_path_lines = sidecar_lines(
            f"{prefix}/branches/B0010-shared-request-paths.txt"
        )
        test_module_lines = sidecar_lines(
            f"{prefix}/branches/B0010-test-modules.txt"
        )
        self.problems.require(
            branch_prefix_lines == sorted(branch_prefix_lines)
            and {normalize_path(path) for path in branch_prefix_lines}
            == destination_prefixes
            and production_prefix_lines == sorted(production_prefix_lines)
            and {normalize_path(path) for path in production_prefix_lines}
            == production_destination_prefixes
            and destination_module_lines == sorted(destination_modules)
            and shared_path_lines == sorted(request_paths)
            and test_module_lines
            == sorted(module_from_path(row.get("target", "")) for row in test_rows),
            f"{context}.sidecars",
            "prefix, destination, shared-request, and test sidecars must exactly reproduce reviewed tables",
        )

        try:
            with gzip.open(graph_path, "rb") as handle:
                graph_payload_sha = hashlib.sha256(handle.read()).hexdigest().upper()
        except (OSError, gzip.BadGzipFile):
            graph_payload_sha = None
        self.problems.require(
            projection_review.get("base_checkpoint_id") == C0005_CHECKPOINT_ID
            and projection_review.get("base_code_sha") == base_sha
            and projection_review.get("projection_id") == "P0010"
            and projection_review.get("wave_id") == "R07"
            and projection_review.get("status") == "review_candidate"
            and projection_review.get("graph_sha256")
            == C0005_RAW_DEPENDENCY_TSV_SHA256
            and projection_review.get("gzip_sha256")
            == artifact_map.get(f"{prefix}/projections/P0010.tsv.gz")
            and projection_review.get("payload_sha256") == graph_payload_sha
            and projection_review.get("selector_count") == len(selector_rows)
            and projection_review.get("selected_inventory_count")
            == len(inventory_rows),
            f"{context}.projection_review",
            "projection review must bind exact base graph, compressed/payload hashes, selector, and inventory",
        )

        c0005_inventory_paths = {
            row.get("path", "")
            for row in self.read_tsv(
                self.phase_dir / "checkpoints/C0005-inventory.tsv",
                f"{prefix}/checkpoints/C0005-inventory.tsv",
                SCOPE_HEADER,
            )[1]
        }
        self.problems.require(
            c0005_inventory_paths - selector_paths <= forbidden_exact
            and not (selector_paths & forbidden_exact),
            f"{context}.scope_rules.production_complement",
            "every non-R07 C0005 production path must be worker-forbidden and no owner may be forbidden",
        )

        # Projection record arguments are derived again from selector and
        # destination rows; only artifact digests come from the authenticated
        # contract rather than duplicated Python constants.
        checker = projection.get("checker")
        selector_ref = projection.get("selector")
        combined_ref = projection.get("combined_baseline")
        expected_projection_args = (
            [f"--allow-module={module}" for module in sorted(selector_modules | destination_modules)]
            + [
                "--candidate=<candidate-format2.tsv>",
                "--private-map-sha256="
                + artifact_map.get(
                    f"{prefix}/branches/B0010-private-normalization.tsv", ""
                ),
                f"--private-map={prefix}/branches/B0010-private-normalization.tsv",
                "--projection-sha256="
                + artifact_map.get(f"{prefix}/projections/P0010.tsv.gz", ""),
                f"--projection={prefix}/projections/P0010.tsv.gz",
            ]
        )
        self.problems.require(
            isinstance(checker, dict)
            and checker.get("artifact")
            == {
                "path": "tools/architecture/check_completion_phase_projection.py",
                "sha256": NEXT_PROJECTION_CHECKER_SHA256,
            }
            and checker.get("arguments") == expected_projection_args
            and selector_ref
            == {
                "artifact": {
                    "path": f"{prefix}/selectors/R07.tsv",
                    "sha256": artifact_map.get(f"{prefix}/selectors/R07.tsv"),
                },
                "kind": "module_path_tsv",
            }
            and combined_ref
            == {
                "path": f"{prefix}/baselines/C0005-combined.json",
                "sha256": C0005_COMBINED_BASELINE_SHA256,
            },
            f"{context}.projection",
            "P0010 must bind exact selector, C0005 baseline, checker, owners, destinations, and private map",
        )

        refresh = branch.get("refresh")
        refresh_map: dict[str, str] = {}
        refresh_rows: list[dict[str, Any]] = []
        if isinstance(refresh, dict) and isinstance(refresh.get("evidence"), list):
            for row in refresh["evidence"]:
                if (
                    isinstance(row, dict)
                    and set(row) == {"path", "sha256"}
                    and isinstance(row.get("path"), str)
                    and isinstance(row.get("sha256"), str)
                ):
                    refresh_rows.append(row)
                    refresh_map[row["path"]] = row["sha256"].upper()
        refresh_exclusions = {f"{prefix}/phase.json", f"{prefix}/branches/B0010.json"}
        expected_refresh_map = {
            path: digest
            for path, digest in artifact_map.items()
            if path not in refresh_exclusions
        }
        if activation_present:
            expected_refresh_map[R07_ACTIVATION_PATH] = R07_ACTIVATION_SHA256
        if accepted_present:
            # Acceptance re-pins exactly the terminal projection and request
            # postimages inside the branch evidence (C0005 ratchet pattern).
            for terminal_rel in (
                f"{prefix}/projections/P0010.json",
                f"{prefix}/requests/R0011.json",
            ):
                terminal_path = self.root / terminal_rel
                if terminal_rel in expected_refresh_map and terminal_path.is_file():
                    expected_refresh_map[terminal_rel] = sha256_path(terminal_path)
        self.problems.require(
            isinstance(refresh, dict)
            and refresh.get("decision") == "current"
            and refresh.get("reviewed_checkpoint_id") == C0005_CHECKPOINT_ID
            and len(refresh_rows) == len(refresh_map)
            and [row["path"] for row in refresh_rows] == sorted(refresh_map)
            and refresh_map == expected_refresh_map,
            f"{context}.branch.refresh",
            "branch refresh must be unique/sorted and cite exact planned artifacts plus activation when active",
        )

        # Recompute every cardinality carried by the contract.  This prevents a
        # self-consistent but incomplete sidecar set from passing by hash alone.
        actual_counts = {
            "artifact_rows": len(artifact_map),
            "branch_prefixes": len(destination_rules),
            "consumer_edges": len(consumer_rows),
            "declarations": len(projection_declarations),
            "destination_dag_body_edges": sum(
                int(row.get("body_edges", "0")) for row in dag_rows
            ),
            "destination_dag_rows": len(dag_rows),
            "destination_dag_signature_edges": sum(
                int(row.get("signature_edges", "0")) for row in dag_rows
            ),
            "destinations": len(destination_rows),
            "external_consumers": len(outside_consumer_pairs),
            "external_import_edges": sum(
                row.get("consumer_scope") == "outside" for row in consumer_rows
            ),
            "external_owner_supply_rows": len(external_supply_rows),
            "forbidden_exact": len(forbidden_exact),
            "forbidden_prefix": len(forbidden_prefix),
            "internal_import_edges": sum(
                row.get("consumer_scope") == "selected_owner" for row in consumer_rows
            ),
            "module_routes": len(module_rows),
            "owners": len(selector_rows),
            "post_move_import_rows": len(post_move_rows),
            "private_closure": len(closure_rows),
            "private_declarations": len(private_names),
            "private_normalization": len(normalization_rows),
            "public_declarations": len(public_names),
            "request_paths": len(request_paths),
            "scope_rows": len(scope_rows),
            "source_commands": len(source_rows),
            "test_rows": len(test_rows),
            "tier_rows": len(tier_rows),
            "wrapper_rows": len(wrapper_rows),
        }
        self.problems.require(
            counts == actual_counts,
            f"{context}.counts",
            "contract counts must equal independently recomputed artifact cardinalities; "
            f"expected={counts}, actual={actual_counts}",
        )

        # Reauthenticate the immutable planned commit independently of the live
        # lifecycle.  Its exact 61-path diff remains the only planning authority.
        expected_changed: set[str] = {
            R07_PLANNED_CONTROL_CONTRACT_PATH,
            "tools/architecture/check_completion_phase.py",
            "tools/architecture/check_phase.py",
        }
        for path, digest in artifact_map.items():
            historical = self.git_bytes(
                "show", f"{R07_ACCEPTED_CONTROL_SHA}:{path}", check=False
            )
            historical_digest = (
                hashlib.sha256(historical.stdout).hexdigest().upper()
                if historical.returncode == 0
                else None
            )
            if historical_digest != digest:
                expected_changed.add(path)
        self.problems.require(
            len(expected_changed) == 61,
            f"{context}.planned_commit.expected_paths",
            "authenticated contract must derive exactly 61 planned-control paths; "
            f"found {len(expected_changed)}",
        )
        planned_diff = self.git(
            "diff",
            "--name-only",
            "--no-renames",
            R07_ACCEPTED_CONTROL_SHA,
            R07_PLANNED_CONTROL_SHA,
            "--",
            check=False,
        )
        planned_changed = {
            normalize_path(path)
            for path in planned_diff.stdout.splitlines()
            if path.strip()
        }
        planned_status = self.git(
            "diff",
            "--name-status",
            "--no-renames",
            R07_ACCEPTED_CONTROL_SHA,
            R07_PLANNED_CONTROL_SHA,
            "--",
            check=False,
        )
        status_codes = [
            line.split("\t", 1)[0]
            for line in planned_status.stdout.splitlines()
            if line.strip()
        ]
        self.problems.require(
            planned_diff.returncode == 0
            and planned_status.returncode == 0
            and path_list_sha256(planned_changed)
            == "19AC31C273E79EC6666894D7395F1C05052872B338FCC7FD196ABBAAED3A91D6"
            and Counter(status_codes) == Counter({"A": 58, "M": 3}),
            f"{context}.planned_commit.census",
            "planned commit must retain exact 61=58A+3M path census and list digest",
        )
        validate_r07_planned_commit_shape(
            head=R07_PLANNED_CONTROL_SHA,
            accepted_control=R07_ACCEPTED_CONTROL_SHA,
            parents=[R07_ACCEPTED_CONTROL_SHA],
            changed_paths=planned_changed,
            expected_changed_paths=expected_changed,
            overlay_paths=set(),
            problems=self.problems,
            context=f"{context}.planned_commit",
        )

        head_result = self.git("rev-parse", "HEAD", check=False)
        head = head_result.stdout.strip()
        self.problems.require(
            head_result.returncode == 0,
            f"{context}.live_head",
            "cannot resolve live HEAD",
        )
        if activation_present:
            activation_metadata = self.git(
                "show",
                "-s",
                "--format=%T%n%P%n%cI%n%s",
                R07_ACTIVATION_CONTROL_SHA,
                check=False,
            )
            self.problems.require(
                activation_metadata.returncode == 0
                and activation_metadata.stdout.splitlines()
                == [
                    R07_ACTIVATION_CONTROL_TREE,
                    R07_PLANNED_CONTROL_SHA,
                    "2026-08-21T08:55:29-04:00",
                    "chore(reorg): activate R07 matrix powers epoch",
                ],
                f"{context}.activation_commit.identity",
                "activation control must retain exact tree, parent, time, and message",
            )
            activation_diff = self.git(
                "diff",
                "--name-only",
                "--no-renames",
                R07_PLANNED_CONTROL_SHA,
                R07_ACTIVATION_CONTROL_SHA,
                "--",
                check=False,
            )
            activation_changed = {
                normalize_path(path)
                for path in activation_diff.stdout.splitlines()
                if path.strip()
            }
            validate_r07_activation_commit_shape(
                head=R07_ACTIVATION_CONTROL_SHA,
                parents=[R07_PLANNED_CONTROL_SHA],
                changed_paths=activation_changed,
                overlay_paths=set(),
                problems=self.problems,
                context=f"{context}.activation_commit.history",
            )
            if delivered_present:
                delivery_metadata = self.git(
                    "show",
                    "-s",
                    "--format=%T%n%P%n%cI%n%s",
                    R07_DELIVERY_SHA,
                    check=False,
                )
                self.problems.require(
                    delivery_metadata.returncode == 0
                    and delivery_metadata.stdout.splitlines()
                    == [
                        R07_DELIVERY_TREE,
                        C0005_CODE_SHA,
                        "2026-08-22T22:34:43-04:00",
                        "refactor(reorg): deliver R07 matrix powers epoch",
                    ],
                    f"{context}.delivery.identity",
                    "delivery must retain exact tree, C0005 parent, time, and message",
                )
                delivery_status = self.git(
                    "diff",
                    "--name-status",
                    "--no-renames",
                    C0005_CODE_SHA,
                    R07_DELIVERY_SHA,
                    "--",
                    check=False,
                )
                actual_delivery_rows: dict[str, str] = {}
                malformed_delivery_rows: list[str] = []
                for line in delivery_status.stdout.splitlines():
                    fields = line.split("\t", 1)
                    if len(fields) != 2 or fields[0] not in {"A", "M"}:
                        malformed_delivery_rows.append(line)
                    else:
                        actual_delivery_rows[normalize_path(fields[1])] = fields[0]
                try:
                    scope_text = (self.root / R07_DELIVERY_SCOPE_PATH).read_text(
                        encoding="utf-8"
                    )
                except (OSError, UnicodeError) as error:
                    self.problems.add(
                        f"{context}.delivery.scope", f"cannot read scope: {error}"
                    )
                    scope_text = ""
                declared_delivery_rows = {
                    match.group(2): match.group(1)
                    for match in re.finditer(
                        r"^\| ([AM]) \| `([^`]+)` \|$", scope_text, re.MULTILINE
                    )
                }
                delivery_paths = set(actual_delivery_rows)
                production_paths = {
                    path for path in delivery_paths if path.startswith("NumStability/")
                }
                test_paths = {
                    path
                    for path in delivery_paths
                    if path.startswith("NumStabilityTest/Reorganization/R07/")
                }
                evidence_paths = {
                    path
                    for path in delivery_paths
                    if path.startswith("docs/architecture/deliveries/R07/")
                }
                self.problems.require(
                    delivery_status.returncode == 0
                    and not malformed_delivery_rows
                    and len(actual_delivery_rows) == 166
                    and Counter(actual_delivery_rows.values())
                    == Counter({"A": 153, "M": 13})
                    and declared_delivery_rows == actual_delivery_rows
                    and len(production_paths) == 43
                    and len(test_paths) == 102
                    and len(evidence_paths) == 21
                    and production_paths | test_paths | evidence_paths == delivery_paths,
                    f"{context}.delivery.scope",
                    "delivery and hash-pinned scope must agree on exact 166=153A+13M paths split 43 production/102 tests/21 evidence",
                )
                self.problems.require(
                    delivery_paths.isdisjoint(request_paths)
                    and delivery_paths.isdisjoint(R07_INTEGRATION_STATIC_CHANGED_PATHS),
                    f"{context}.delivery.scope_overlap",
                    "immutable worker delivery must not contain integrator-owned R0011/control paths",
                )
                merge_metadata = self.git(
                    "show",
                    "-s",
                    "--format=%T%n%P%n%cI%n%s",
                    R07_MERGE_SHA,
                    check=False,
                )
                self.problems.require(
                    merge_metadata.returncode == 0
                    and merge_metadata.stdout.splitlines()
                    == [
                        R07_MERGE_TREE,
                        f"{R07_ACTIVATION_CONTROL_SHA} {R07_DELIVERY_SHA}",
                        "2026-08-22T22:56:43-04:00",
                        "merge(reorg): integrate immutable R07 delivery",
                    ],
                    f"{context}.merge.identity",
                    "R07 delivery must be preserved by the exact two-parent true merge",
                )
                merge_first_parent_diff = self.git(
                    "diff",
                    "--name-status",
                    "--no-renames",
                    R07_ACTIVATION_CONTROL_SHA,
                    R07_MERGE_SHA,
                    "--",
                    check=False,
                )
                self.problems.require(
                    merge_first_parent_diff.returncode == 0
                    and merge_first_parent_diff.stdout == delivery_status.stdout,
                    f"{context}.merge.first_parent_delta",
                    "true merge first-parent delta must reproduce the immutable 166-path delivery exactly",
                )
                merge_ancestry = self.git(
                    "merge-base", "--is-ancestor", R07_MERGE_SHA, "HEAD", check=False
                )
                self.problems.require(
                    merge_ancestry.returncode == 0,
                    f"{context}.merge.ancestry",
                    "exact R07 true merge must be an ancestor of live HEAD",
                )
                integration_expected = request_paths | set(
                    R07_INTEGRATION_STATIC_CHANGED_PATHS
                )
                integration_committed = head != R07_MERGE_SHA or closeout_present
                if integration_committed:
                    integration_metadata = self.git(
                        "show",
                        "-s",
                        "--format=%T%n%P%n%cI%n%s",
                        R07_INTEGRATION_CONTROL_SHA,
                        check=False,
                    )
                    self.problems.require(
                        integration_metadata.returncode == 0
                        and integration_metadata.stdout.splitlines()
                        == [
                            R07_INTEGRATION_CONTROL_TREE,
                            R07_MERGE_SHA,
                            "2026-08-22T23:47:14-04:00",
                            "refactor(reorganization): integrate R07 under R0011",
                        ],
                        f"{context}.integration_control.identity",
                        "integration control must retain exact tree, sole merge parent, time, and subject",
                    )
                    historical_integration_diff = self.git(
                        "diff",
                        "--name-only",
                        "--no-renames",
                        R07_MERGE_SHA,
                        R07_INTEGRATION_CONTROL_SHA,
                        "--",
                        check=False,
                    )
                    historical_integration_paths = {
                        normalize_path(path)
                        for path in historical_integration_diff.stdout.splitlines()
                        if path.strip()
                    }
                    if historical_integration_diff.returncode:
                        self.problems.add(
                            f"{context}.integration_control.history",
                            "cannot read exact historical integration-control diff",
                        )
                    validate_r07_integration_commit_shape(
                        head=R07_INTEGRATION_CONTROL_SHA,
                        parents=[R07_MERGE_SHA],
                        changed_paths=historical_integration_paths,
                        expected_changed_paths=integration_expected,
                        overlay_paths=set(),
                        problems=self.problems,
                        context=f"{context}.integration_control.history",
                    )
                    integration_ancestry = self.git(
                        "merge-base",
                        "--is-ancestor",
                        R07_INTEGRATION_CONTROL_SHA,
                        "HEAD",
                        check=False,
                    )
                    self.problems.require(
                        integration_ancestry.returncode == 0,
                        f"{context}.integration_control.ancestry",
                        "exact 54-path integration control must be an ancestor of live HEAD",
                    )
                cache_result = self.git(
                    "ls-files",
                    "--others",
                    "--exclude-standard",
                    "--",
                    ".cache",
                    check=False,
                )
                untracked_material = (
                    {
                        normalize_path(path)
                        for path in cache_result.stdout.splitlines()
                        if path.strip()
                    }
                    if cache_result.returncode == 0
                    else set()
                )
                if cache_result.returncode:
                    self.problems.add(
                        f"{context}.integration_control.material",
                        "cannot enumerate disposable untracked .cache material",
                    )
                if closeout_present:
                    if head == R07_INTEGRATION_CONTROL_SHA:
                        closeout_parents: list[str] = []
                        closeout_subject: str | None = None
                        closeout_changed = (
                            self.git_live_change_paths(
                                R07_INTEGRATION_CONTROL_SHA,
                                f"{context}.integration_closeout.precommit",
                            )
                            - untracked_material
                        )
                        closeout_overlay: set[str] = set()
                    else:
                        # The closeout is committed.  A later reviewed
                        # narrative refresh may sit on top of it, so read the
                        # closeout's own shape from the exact pinned control
                        # rather than assuming HEAD is the closeout.
                        closeout_source = (
                            "HEAD"
                            if head == R07_CLOSEOUT_CONTROL_SHA
                            else R07_CLOSEOUT_CONTROL_SHA
                        )
                        closeout_metadata = self.git(
                            "show", "-s", "--format=%P%n%s", closeout_source, check=False
                        )
                        closeout_lines = closeout_metadata.stdout.splitlines()
                        closeout_parents = (
                            closeout_lines[0].split() if closeout_lines else []
                        )
                        closeout_subject = (
                            closeout_lines[1] if len(closeout_lines) == 2 else None
                        )
                        closeout_diff = self.git(
                            "diff",
                            "--name-only",
                            "--no-renames",
                            R07_INTEGRATION_CONTROL_SHA,
                            closeout_source,
                            "--",
                            check=False,
                        )
                        closeout_changed = {
                            normalize_path(path)
                            for path in closeout_diff.stdout.splitlines()
                            if path.strip()
                        }
                        if closeout_metadata.returncode or closeout_diff.returncode:
                            self.problems.add(
                                f"{context}.integration_closeout.git",
                                "cannot read closeout parent, subject, or diff",
                            )
                        closeout_overlay = (
                            self.git_live_change_paths(
                                "HEAD", f"{context}.integration_closeout.worktree"
                            )
                            - untracked_material
                            if head == R07_CLOSEOUT_CONTROL_SHA
                            else set()
                        )
                    validate_r07_closeout_commit_shape(
                        head=head,
                        parents=closeout_parents,
                        subject=closeout_subject,
                        changed_paths=closeout_changed,
                        overlay_paths=closeout_overlay,
                        problems=self.problems,
                        context=f"{context}.integration_closeout",
                    )
                    if head not in {
                        R07_INTEGRATION_CONTROL_SHA,
                        R07_CLOSEOUT_CONTROL_SHA,
                    }:
                        refresh_source = (
                            C0006_CODE_SHA
                            if accepted_present and head != C0006_CODE_SHA
                            else "HEAD"
                        )
                        refresh_metadata = self.git(
                            "show", "-s", "--format=%P%n%s", refresh_source, check=False
                        )
                        refresh_lines = refresh_metadata.stdout.splitlines()
                        refresh_parents = (
                            refresh_lines[0].split() if refresh_lines else []
                        )
                        refresh_subject = (
                            refresh_lines[1] if len(refresh_lines) == 2 else None
                        )
                        refresh_diff = self.git(
                            "diff",
                            "--name-only",
                            "--no-renames",
                            R07_CLOSEOUT_CONTROL_SHA,
                            refresh_source,
                            "--",
                            check=False,
                        )
                        refresh_changed = {
                            normalize_path(path)
                            for path in refresh_diff.stdout.splitlines()
                            if path.strip()
                        }
                        if refresh_metadata.returncode or refresh_diff.returncode:
                            self.problems.add(
                                f"{context}.narrative_refresh.git",
                                "cannot read refresh parent, subject, or diff",
                            )
                        refresh_overlay = (
                            self.git_live_change_paths(
                                "HEAD", f"{context}.narrative_refresh.worktree"
                            )
                            - untracked_material
                            if refresh_source == "HEAD" and not accepted_present
                            else set()
                        )
                        validate_r07_narrative_refresh_commit_shape(
                            parents=refresh_parents,
                            subject=refresh_subject,
                            changed_paths=refresh_changed,
                            overlay_paths=refresh_overlay,
                            problems=self.problems,
                            context=f"{context}.narrative_refresh",
                        )
                    if accepted_present:
                        acceptance_head = self.git(
                            "rev-parse", "HEAD", check=False
                        ).stdout.strip()
                        if acceptance_head == C0006_CODE_SHA:
                            acceptance_parents: list[str] = []
                            acceptance_subject: str | None = None
                            acceptance_changed = (
                                self.git_live_change_paths(
                                    C0006_CODE_SHA,
                                    f"{context}.c0006_acceptance.precommit",
                                )
                                - untracked_material
                            )
                            acceptance_overlay: set[str] = set()
                        else:
                            # The acceptance control is committed; a later
                            # reviewed narrative refresh may sit on top of it,
                            # so read the acceptance's own shape from the
                            # exact pinned control rather than assuming HEAD.
                            acceptance_source = (
                                "HEAD"
                                if acceptance_head == C0006_ACCEPTED_CONTROL_SHA
                                else C0006_ACCEPTED_CONTROL_SHA
                            )
                            acceptance_metadata = self.git(
                                "show", "-s", "--format=%P%n%s",
                                acceptance_source, check=False
                            )
                            acceptance_lines = acceptance_metadata.stdout.splitlines()
                            acceptance_parents = (
                                acceptance_lines[0].split() if acceptance_lines else []
                            )
                            acceptance_subject = (
                                acceptance_lines[1]
                                if len(acceptance_lines) == 2
                                else None
                            )
                            acceptance_diff = self.git(
                                "diff",
                                "--name-only",
                                "--no-renames",
                                C0006_CODE_SHA,
                                acceptance_source,
                                "--",
                                check=False,
                            )
                            acceptance_changed = {
                                normalize_path(path)
                                for path in acceptance_diff.stdout.splitlines()
                                if path.strip()
                            }
                            if (
                                acceptance_metadata.returncode
                                or acceptance_diff.returncode
                            ):
                                self.problems.add(
                                    f"{context}.c0006_acceptance.git",
                                    "cannot read acceptance parent, subject, or diff",
                                )
                            acceptance_overlay = (
                                self.git_live_change_paths(
                                    "HEAD", f"{context}.c0006_acceptance.worktree"
                                )
                                - untracked_material
                                if acceptance_source == "HEAD"
                                else set()
                            )
                        validate_c0006_acceptance_commit_shape(
                            head=acceptance_head,
                            parents=acceptance_parents,
                            subject=acceptance_subject,
                            changed_paths=acceptance_changed,
                            overlay_paths=acceptance_overlay,
                            problems=self.problems,
                            context=f"{context}.c0006_acceptance",
                        )
                        if acceptance_head not in {
                            C0006_CODE_SHA,
                            C0006_ACCEPTED_CONTROL_SHA,
                        }:
                            c0006_refresh_metadata = self.git(
                                "show", "-s", "--format=%P%n%s", "HEAD", check=False
                            )
                            c0006_refresh_lines = (
                                c0006_refresh_metadata.stdout.splitlines()
                            )
                            c0006_refresh_parents = (
                                c0006_refresh_lines[0].split()
                                if c0006_refresh_lines
                                else []
                            )
                            c0006_refresh_subject = (
                                c0006_refresh_lines[1]
                                if len(c0006_refresh_lines) == 2
                                else None
                            )
                            c0006_refresh_diff = self.git(
                                "diff",
                                "--name-only",
                                "--no-renames",
                                C0006_ACCEPTED_CONTROL_SHA,
                                "HEAD",
                                "--",
                                check=False,
                            )
                            c0006_refresh_changed = {
                                normalize_path(path)
                                for path in c0006_refresh_diff.stdout.splitlines()
                                if path.strip()
                            }
                            if (
                                c0006_refresh_metadata.returncode
                                or c0006_refresh_diff.returncode
                            ):
                                self.problems.add(
                                    f"{context}.c0006_refresh.git",
                                    "cannot read refresh parent, subject, or diff",
                                )
                            c0006_refresh_overlay = (
                                self.git_live_change_paths(
                                    "HEAD", f"{context}.c0006_refresh.worktree"
                                )
                                - untracked_material
                            )
                            c0007_refresh_is_ancestor = self.git(
                                "merge-base",
                                "--is-ancestor",
                                C0007_NARRATIVE_REFRESH_SHA,
                                acceptance_head,
                                check=False,
                            ).returncode == 0
                            # Two reviewed states sit past the acceptance
                            # control: the narrative refresh, and the R09/R10
                            # planned control that succeeds it. While the
                            # planning artifacts are still uncommitted, HEAD is
                            # the refresh and the overlay is the planning path
                            # set, so that precommit shape is validated here
                            # rather than rejected as a dirty refresh.
                            planning_precommit = (
                                acceptance_head == C0006_NARRATIVE_REFRESH_SHA
                                and bool(c0006_refresh_overlay)
                            )
                            if acceptance_head == C0006_NARRATIVE_REFRESH_SHA:
                                self.problems.require(
                                    c0006_refresh_parents
                                    == [C0006_ACCEPTED_CONTROL_SHA],
                                    f"{context}.c0006_refresh.parent",
                                    "C0006 narrative refresh must be a "
                                    "single-parent direct child of the exact "
                                    "acceptance control",
                                )
                                self.problems.require(
                                    c0006_refresh_subject
                                    == C0006_NARRATIVE_REFRESH_SUBJECT,
                                    f"{context}.c0006_refresh.subject",
                                    "C0006 narrative refresh must retain the "
                                    "exact reviewed subject",
                                )
                                self.problems.require(
                                    c0006_refresh_changed
                                    == set(C0006_NARRATIVE_REFRESH_CHANGED_PATHS),
                                    f"{context}.c0006_refresh.paths",
                                    "C0006 narrative refresh must change exactly "
                                    "the approved README and checker paths; "
                                    f"found={sorted(c0006_refresh_changed)}",
                                )
                            if planning_precommit:
                                extra = c0006_refresh_overlay - set(
                                    R09_R10_PLANNED_CONTROL_CHANGED_PATHS)
                                self.problems.require(
                                    not extra,
                                    f"{context}.r09_r10_planned.precommit",
                                    "the only overlay permitted on the C0006 "
                                    "narrative refresh is the reviewed R09/R10 "
                                    f"planned-control path set; found extra={sorted(extra)}",
                                )
                            elif acceptance_head == C0006_NARRATIVE_REFRESH_SHA:
                                self.problems.require(
                                    not c0006_refresh_overlay,
                                    f"{context}.c0006_refresh.worktree",
                                    "C0006 narrative refresh must have a clean "
                                    f"overlay; found={sorted(c0006_refresh_overlay)}",
                                )
                            elif (
                                acceptance_head != R09_R10_PLANNED_CONTROL_SHA
                                and c0006_refresh_parents
                                == [R09_R10_PLANNED_CONTROL_SHA]
                            ):
                                # narrative refresh recording the planned pair
                                refresh_diff = self.git(
                                    "diff",
                                    "--name-only",
                                    "--no-renames",
                                    R09_R10_PLANNED_CONTROL_SHA,
                                    "HEAD",
                                    "--",
                                    check=False,
                                )
                                refresh_changed = {
                                    normalize_path(path)
                                    for path in refresh_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                if refresh_diff.returncode:
                                    self.problems.add(
                                        f"{context}.r09_r10_refresh.git",
                                        "cannot read planning-refresh diff",
                                    )
                                self.problems.require(
                                    c0006_refresh_subject
                                    == R09_R10_NARRATIVE_REFRESH_SUBJECT,
                                    f"{context}.r09_r10_refresh.subject",
                                    "the R09/R10 planning narrative refresh must "
                                    "retain the exact reviewed subject",
                                )
                                self.problems.require(
                                    refresh_changed
                                    == set(R09_R10_NARRATIVE_REFRESH_CHANGED_PATHS),
                                    f"{context}.r09_r10_refresh.paths",
                                    "the R09/R10 planning narrative refresh must "
                                    "change exactly the approved README and checker "
                                    f"paths; found={sorted(refresh_changed)}",
                                )
                                activation_precommit_extra = (
                                    c0006_refresh_overlay
                                    - set(R09_R10_ACTIVATION_CONTROL_CHANGED_PATHS)
                                )
                                self.problems.require(
                                    not activation_precommit_extra,
                                    f"{context}.r09_r10_refresh.worktree",
                                    "the only overlay permitted on the R09/R10 "
                                    "planning narrative refresh is the reviewed "
                                    "activation-control path set; found extra="
                                    f"{sorted(activation_precommit_extra)}",
                                )
                            elif acceptance_head == R09_R10_INTEGRATION_CONTROL_SHA:
                                # closeout precommit: HEAD is the integration
                                # control and the overlay is the reviewed
                                # closeout path set.
                                closeout_precommit_extra = (
                                    c0006_refresh_overlay
                                    - set(R09_R10_CLOSEOUT_CHANGED_PATHS)
                                )
                                self.problems.require(
                                    not closeout_precommit_extra,
                                    f"{context}.r09_r10_closeout.precommit",
                                    "the only overlay permitted on the R09/R10 "
                                    "integration control is the reviewed closeout "
                                    f"path set; found extra={sorted(closeout_precommit_extra)}",
                                )
                            elif c0006_refresh_parents == [R09_R10_INTEGRATION_CONTROL_SHA]:
                                closeout_diff = self.git(
                                    "diff", "--name-only", "--no-renames",
                                    R09_R10_INTEGRATION_CONTROL_SHA, "HEAD", "--",
                                    check=False,
                                )
                                closeout_changed = {
                                    normalize_path(path)
                                    for path in closeout_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                self.problems.require(
                                    c0006_refresh_subject == R09_R10_CLOSEOUT_SUBJECT,
                                    f"{context}.r09_r10_closeout.subject",
                                    "the R09/R10 closeout must retain the exact "
                                    "reviewed subject",
                                )
                                self.problems.require(
                                    closeout_changed
                                    == set(R09_R10_CLOSEOUT_CHANGED_PATHS),
                                    f"{context}.r09_r10_closeout.paths",
                                    "the R09/R10 closeout must change exactly the "
                                    "approved narrative, attestation and checker "
                                    "paths; "
                                    f"missing={sorted(set(R09_R10_CLOSEOUT_CHANGED_PATHS) - closeout_changed)}, "
                                    f"extra={sorted(closeout_changed - set(R09_R10_CLOSEOUT_CHANGED_PATHS))}",
                                )
                                # acceptance precommit: at commit time HEAD is
                                # still the closeout, so the reviewed C0007
                                # acceptance path set is the one overlay allowed.
                                closeout_overlay_extra = (
                                    c0006_refresh_overlay
                                    - set(C0007_ACCEPTANCE_CONTROL_PATHS)
                                )
                                self.problems.require(
                                    not closeout_overlay_extra,
                                    f"{context}.r09_r10_closeout.worktree",
                                    "the only overlay permitted on the R09/R10 "
                                    "closeout is the reviewed C0007 acceptance "
                                    f"path set; found extra={sorted(closeout_overlay_extra)}",
                                )
                                attestation = self.root / R09_R10_INTEGRATION_CONTROL_CI_PATH
                                self.problems.require(
                                    attestation.is_file()
                                    and sha256_path(attestation)
                                    == R09_R10_INTEGRATION_CONTROL_CI_SHA256,
                                    f"{context}.r09_r10_closeout.ci_artifact",
                                    "the integration-control CI attestation must be "
                                    "present with its exact pinned bytes",
                                )
                                if attestation.is_file():
                                    record = self.read_json(
                                        attestation, R09_R10_INTEGRATION_CONTROL_CI_PATH
                                    )
                                    run = record.get("run") or {}
                                    job = record.get("job") or {}
                                    suite = record.get("check_suite") or {}
                                    self.problems.require(
                                        run.get("id") == R09_R10_INTEGRATION_CONTROL_CI_RUN
                                        and run.get("head_sha") == R09_R10_INTEGRATION_CONTROL_SHA
                                        and run.get("conclusion") == "success"
                                        and job.get("id") == R09_R10_INTEGRATION_CONTROL_CI_JOB
                                        and job.get("conclusion") == "success"
                                        and suite.get("id") == R09_R10_INTEGRATION_CONTROL_CI_SUITE
                                        and suite.get("conclusion") == "success",
                                        f"{context}.r09_r10_closeout.ci",
                                        "the closeout must prove the exact integration "
                                        "control passed Lean CI",
                                    )
                            elif c0006_refresh_parents == [R09_R10_CLOSEOUT_SHA]:
                                # C0007 acceptance control: the commit that
                                # accepts the R09/R10 epoch and lands the
                                # closeout's deferred self-pin.
                                acceptance_diff = self.git(
                                    "diff", "--name-only", "--no-renames",
                                    R09_R10_CLOSEOUT_SHA, "HEAD", "--",
                                    check=False,
                                )
                                acceptance_changed = {
                                    normalize_path(path)
                                    for path in acceptance_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                # one source of truth: the same pure shape
                                # function the adversarial self-tests exercise.
                                # refresh precommit: at commit time HEAD is
                                # still the acceptance, so the reviewed
                                # narrative-refresh set is the one overlay
                                # allowed on it.
                                validate_c0007_acceptance_commit_shape(
                                    head=acceptance_head,
                                    parents=c0006_refresh_parents,
                                    subject=c0006_refresh_subject,
                                    changed_paths=acceptance_changed,
                                    overlay_paths=(
                                        c0006_refresh_overlay
                                        - set(C0007_NARRATIVE_REFRESH_CHANGED_PATHS)
                                    ),
                                    problems=self.problems,
                                    context=f"{context}.c0007_acceptance",
                                )
                                checkpoint_path = (
                                    self.phase_dir / "checkpoints/C0007.json"
                                )
                                self.problems.require(
                                    checkpoint_path.is_file(),
                                    f"{context}.c0007_acceptance.record",
                                    "the C0007 acceptance must create "
                                    "checkpoints/C0007.json",
                                )
                                if checkpoint_path.is_file():
                                    c0007 = self.read_json(
                                        checkpoint_path,
                                        f"{context}.c0007_acceptance.record",
                                    )
                                    self.problems.require(
                                        c0007.get("commit_sha") == C0007_CODE_SHA
                                        and c0007.get("checkpoint_id") == "C0007"
                                        and c0007.get("parent_checkpoint_id")
                                        == C0006_CHECKPOINT_ID,
                                        f"{context}.c0007_acceptance.identity",
                                        "C0007 must record the exact closeout code "
                                        "commit and its C0006 parent",
                                    )
                                    self.problems.require(
                                        c0007.get("metrics") == C0007_METRICS,
                                        f"{context}.c0007_acceptance.metrics",
                                        "C0007 must record the exact accepted "
                                        f"metrics {C0007_METRICS}",
                                    )
                                    self.problems.require(
                                        c0007.get("milestones_satisfied")
                                        == C0007_MILESTONES,
                                        f"{context}.c0007_acceptance.milestones",
                                        "C0007 must satisfy exactly M01 through M12",
                                    )
                            elif acceptance_head == C0007_NARRATIVE_REFRESH_SHA:
                                # C0007 narrative refresh: records the
                                # acceptance control's own SHA and CI, which
                                # that commit could not contain.
                                self.problems.require(
                                    c0006_refresh_parents
                                    == [C0007_ACCEPTED_CONTROL_SHA],
                                    f"{context}.c0007_refresh.parent",
                                    "the exact C0007 narrative refresh must be a "
                                    "single-parent direct child of the acceptance "
                                    "control",
                                )
                                refresh_diff = self.git(
                                    "diff", "--name-only", "--no-renames",
                                    C0007_ACCEPTED_CONTROL_SHA,
                                    C0007_NARRATIVE_REFRESH_SHA,
                                    "--",
                                    check=False,
                                )
                                refresh_changed = {
                                    normalize_path(path)
                                    for path in refresh_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                self.problems.require(
                                    c0006_refresh_subject
                                    == C0007_NARRATIVE_REFRESH_SUBJECT,
                                    f"{context}.c0007_refresh.subject",
                                    "the C0007 narrative refresh must retain the "
                                    "exact reviewed subject",
                                )
                                self.problems.require(
                                    refresh_changed
                                    == set(C0007_NARRATIVE_REFRESH_CHANGED_PATHS),
                                    f"{context}.c0007_refresh.paths",
                                    "the C0007 narrative refresh must change exactly "
                                    "the README, the acceptance-control attestation "
                                    "and the checker; "
                                    f"missing={sorted(set(C0007_NARRATIVE_REFRESH_CHANGED_PATHS) - refresh_changed)}, "
                                    f"extra={sorted(refresh_changed - set(C0007_NARRATIVE_REFRESH_CHANGED_PATHS))}",
                                )
                                self.problems.require(
                                    not c0006_refresh_overlay,
                                    f"{context}.c0007_refresh.worktree",
                                    "the C0007 narrative refresh must have a clean "
                                    f"overlay; found={sorted(c0006_refresh_overlay)}",
                                )
                            elif acceptance_head == R09_R10_R10_MERGE_SHA:
                                integration_precommit_extra = (
                                    c0006_refresh_overlay
                                    - set(R09_R10_INTEGRATION_CHANGED_PATHS)
                                )
                                self.problems.require(
                                    not integration_precommit_extra,
                                    f"{context}.r09_r10_integration.precommit",
                                    "the only overlay permitted on the R09/R10 "
                                    "second true merge is the reviewed "
                                    "integration path set; found extra="
                                    f"{sorted(integration_precommit_extra)}",
                                )
                            elif c0006_refresh_parents == [R09_R10_R10_MERGE_SHA]:
                                integration_diff = self.git(
                                    "diff", "--name-only", "--no-renames",
                                    R09_R10_R10_MERGE_SHA, "HEAD", "--",
                                    check=False,
                                )
                                integration_changed = {
                                    normalize_path(path)
                                    for path in integration_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                self.problems.require(
                                    c0006_refresh_subject
                                    == R09_R10_INTEGRATION_CONTROL_SUBJECT,
                                    f"{context}.r09_r10_integration.subject",
                                    "the R09/R10 integration control must retain "
                                    "the exact reviewed subject",
                                )
                                self.problems.require(
                                    integration_changed
                                    == set(R09_R10_INTEGRATION_CHANGED_PATHS),
                                    f"{context}.r09_r10_integration.paths",
                                    "the R09/R10 integration control must change "
                                    "exactly the approved paths; "
                                    f"missing={sorted(set(R09_R10_INTEGRATION_CHANGED_PATHS) - integration_changed)}, "
                                    f"extra={sorted(integration_changed - set(R09_R10_INTEGRATION_CHANGED_PATHS))}",
                                )
                                self.problems.require(
                                    not c0006_refresh_overlay,
                                    f"{context}.r09_r10_integration.worktree",
                                    "the R09/R10 integration control must have a "
                                    "clean overlay; found="
                                    f"{sorted(c0006_refresh_overlay)}",
                                )
                                for label, tip in (("R09", R09_DELIVERY_SHA),
                                                   ("R10", R10_DELIVERY_SHA)):
                                    preserved = self.git(
                                        "merge-base", "--is-ancestor", tip, "HEAD",
                                        check=False,
                                    )
                                    self.problems.require(
                                        preserved.returncode == 0,
                                        f"{context}.r09_r10_integration.{label}_tip",
                                        f"the immutable {label} delivery {tip} must "
                                        "be preserved as an ancestor",
                                    )
                                for bid, digest in (
                                    ("B0011", B0011_DELIVERED_SHA256),
                                    ("B0012", B0012_DELIVERED_SHA256),
                                ):
                                    record = (
                                        self.root / DEFAULT_PHASE_DIR.as_posix()
                                        / "branches" / f"{bid}.json"
                                    )
                                    self.problems.require(
                                        record.is_file()
                                        and sha256_path(record) == digest,
                                        f"{context}.r09_r10_integration.{bid}",
                                        f"expected exact delivered {bid} SHA-256 "
                                        f"{digest}",
                                    )
                            elif (
                                acceptance_head != R09_R10_ACTIVATION_CONTROL_SHA
                                and c0006_refresh_parents
                                == [R09_R10_ACTIVATION_CONTROL_SHA]
                            ):
                                # sidecar correction over the activation control
                                correction_diff = self.git(
                                    "diff",
                                    "--name-only",
                                    "--no-renames",
                                    R09_R10_ACTIVATION_CONTROL_SHA,
                                    "HEAD",
                                    "--",
                                    check=False,
                                )
                                correction_changed = {
                                    normalize_path(path)
                                    for path in correction_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                if correction_diff.returncode:
                                    self.problems.add(
                                        f"{context}.r09_r10_correction.git",
                                        "cannot read sidecar-correction diff",
                                    )
                                self.problems.require(
                                    c0006_refresh_subject
                                    == R09_R10_CORRECTION_SUBJECT,
                                    f"{context}.r09_r10_correction.subject",
                                    "the R09/R10 sidecar correction must retain "
                                    "the exact reviewed subject",
                                )
                                self.problems.require(
                                    correction_changed
                                    == set(R09_R10_CORRECTION_CHANGED_PATHS),
                                    f"{context}.r09_r10_correction.paths",
                                    "the R09/R10 sidecar correction must change "
                                    "exactly the approved sidecar, branch record, "
                                    "review and checker paths; "
                                    f"missing={sorted(set(R09_R10_CORRECTION_CHANGED_PATHS) - correction_changed)}, "
                                    f"extra={sorted(correction_changed - set(R09_R10_CORRECTION_CHANGED_PATHS))}",
                                )
                                self.problems.require(
                                    not c0006_refresh_overlay,
                                    f"{context}.r09_r10_correction.worktree",
                                    "the R09/R10 sidecar correction must have a "
                                    "clean overlay; found="
                                    f"{sorted(c0006_refresh_overlay)}",
                                )
                                validate_r09_r10_activation_state(
                                    self.root,
                                    self.problems,
                                    context=f"{context}.r09_r10_correction",
                                )
                            elif (
                                acceptance_head != R09_R10_NARRATIVE_REFRESH_SHA
                                and c0006_refresh_parents
                                == [R09_R10_NARRATIVE_REFRESH_SHA]
                            ):
                                # activation control activating the planned pair
                                activation_diff = self.git(
                                    "diff",
                                    "--name-only",
                                    "--no-renames",
                                    R09_R10_NARRATIVE_REFRESH_SHA,
                                    "HEAD",
                                    "--",
                                    check=False,
                                )
                                activation_changed = {
                                    normalize_path(path)
                                    for path in activation_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                if activation_diff.returncode:
                                    self.problems.add(
                                        f"{context}.r09_r10_activation.git",
                                        "cannot read activation-control diff",
                                    )
                                self.problems.require(
                                    c0006_refresh_subject
                                    == R09_R10_ACTIVATION_CONTROL_SUBJECT,
                                    f"{context}.r09_r10_activation.subject",
                                    "the R09/R10 activation control must retain "
                                    "the exact reviewed subject",
                                )
                                self.problems.require(
                                    activation_changed
                                    == set(R09_R10_ACTIVATION_CONTROL_CHANGED_PATHS),
                                    f"{context}.r09_r10_activation.paths",
                                    "the R09/R10 activation control must change "
                                    "exactly the approved narrative, branch, "
                                    "review and checker paths; "
                                    f"missing={sorted(set(R09_R10_ACTIVATION_CONTROL_CHANGED_PATHS) - activation_changed)}, "
                                    f"extra={sorted(activation_changed - set(R09_R10_ACTIVATION_CONTROL_CHANGED_PATHS))}",
                                )
                                correction_extra = (
                                    c0006_refresh_overlay
                                    - set(R09_R10_CORRECTION_CHANGED_PATHS)
                                )
                                self.problems.require(
                                    not correction_extra,
                                    f"{context}.r09_r10_activation.worktree",
                                    "the only overlay permitted on the R09/R10 "
                                    "activation control is the reviewed sidecar-"
                                    "correction path set; found extra="
                                    f"{sorted(correction_extra)}",
                                )
                                validate_r09_r10_activation_state(
                                    self.root,
                                    self.problems,
                                    context=f"{context}.r09_r10_activation",
                                )
                            elif c0007_refresh_is_ancestor:
                                # Descendants of the exact, authenticated
                                # refresh are ordinary continuation after the
                                # accepted C0007/R09-R10 epoch. Keep this arm
                                # last so later epoch transitions can add more
                                # specific validators above it.
                                pass
                            else:
                                r09_r10_planned_diff = self.git(
                                    "diff",
                                    "--name-only",
                                    "--no-renames",
                                    C0006_NARRATIVE_REFRESH_SHA,
                                    "HEAD",
                                    "--",
                                    check=False,
                                )
                                r09_r10_planned_changed = {
                                    normalize_path(path)
                                    for path in r09_r10_planned_diff.stdout.splitlines()
                                    if path.strip()
                                }
                                if r09_r10_planned_diff.returncode:
                                    self.problems.add(
                                        f"{context}.r09_r10_planned.git",
                                        "cannot read planned-control diff",
                                    )
                                self.problems.require(
                                    c0006_refresh_parents
                                    == [C0006_NARRATIVE_REFRESH_SHA],
                                    f"{context}.r09_r10_planned.parent",
                                    "the R09/R10 planned control must be a "
                                    "single-parent direct child of the exact "
                                    "C0006 narrative refresh",
                                )
                                self.problems.require(
                                    c0006_refresh_subject
                                    == R09_R10_PLANNED_CONTROL_SUBJECT,
                                    f"{context}.r09_r10_planned.subject",
                                    "the R09/R10 planned control must retain the "
                                    "exact reviewed subject",
                                )
                                self.problems.require(
                                    r09_r10_planned_changed
                                    == set(R09_R10_PLANNED_CONTROL_CHANGED_PATHS),
                                    f"{context}.r09_r10_planned.paths",
                                    "the R09/R10 planned control must change "
                                    "exactly the reviewed planning paths; missing="
                                    f"{sorted(set(R09_R10_PLANNED_CONTROL_CHANGED_PATHS) - r09_r10_planned_changed)}, "
                                    f"extra={sorted(r09_r10_planned_changed - set(R09_R10_PLANNED_CONTROL_CHANGED_PATHS))}",
                                )
                                planned_overlay_extra = (
                                    c0006_refresh_overlay
                                    - set(R09_R10_NARRATIVE_REFRESH_CHANGED_PATHS)
                                )
                                self.problems.require(
                                    not planned_overlay_extra,
                                    f"{context}.r09_r10_planned.worktree",
                                    "the only overlay permitted on the R09/R10 "
                                    "planned control is the reviewed narrative "
                                    "refresh path set; found extra="
                                    f"{sorted(planned_overlay_extra)}",
                                )
                            if c0007_refresh_is_ancestor:
                                # The live attestation remains part of the
                                # accepted control state for every descendant,
                                # not only at the exact refresh commit.
                                attestation = (
                                    self.root / C0007_ACCEPTANCE_CONTROL_CI_PATH
                                )
                                self.problems.require(
                                    attestation.is_file()
                                    and sha256_path(attestation)
                                    == C0007_ACCEPTANCE_CONTROL_CI_SHA256,
                                    f"{context}.c0007_refresh.ci_artifact",
                                    "the acceptance-control CI attestation must be "
                                    "present with its exact pinned bytes",
                                )
                                if attestation.is_file():
                                    att = self.read_json(
                                        attestation, f"{context}.c0007_refresh.ci"
                                    )
                                    att_run = att.get("run") or {}
                                    att_job = att.get("job") or {}
                                    att_suite = att.get("check_suite") or {}
                                    self.problems.require(
                                        att_run.get("id")
                                        == C0007_ACCEPTANCE_CONTROL_CI_RUN
                                        and att_run.get("head_sha")
                                        == C0007_ACCEPTED_CONTROL_SHA
                                        and att_run.get("conclusion") == "success"
                                        and att_job.get("id")
                                        == C0007_ACCEPTANCE_CONTROL_CI_JOB
                                        and att_job.get("conclusion") == "success"
                                        and att_suite.get("id")
                                        == C0007_ACCEPTANCE_CONTROL_CI_SUITE
                                        and att_suite.get("conclusion") == "success",
                                        f"{context}.c0007_refresh.ci",
                                        "the refresh must prove the exact C0007 "
                                        "acceptance control passed Lean CI",
                                    )
                        narrative_fragments = (
                            "C0006",
                            C0006_CODE_SHA,
                            R07_DELIVERY_SHA,
                            "true merge",
                            R07_MERGE_SHA,
                            R07_INTEGRATION_CONTROL_SHA,
                            (
                                "2,860 production modules: 2,770 classified, 90 "
                                "unclassified, and 0 mixed"
                            ),
                            "R09=72 and R10=18",
                            (
                                f"passed GitHub Lean CI run {R07_INTEGRATION_CONTROL_CI_RUN} "
                                f"(job {R07_INTEGRATION_CONTROL_CI_JOB})"
                            ),
                            "M07 is accepted at C0006",
                            "B0010 is accepted with retirement due",
                            "P0010 is retired and R0011 is applied",
                            (
                                "Branch retirement remains a separate later "
                                "control."
                            ),
                        )
                    else:
                        narrative_fragments = (
                        "M07 remains ready and B0010/R07 is delivered",
                        R07_DELIVERY_SHA,
                        "true merge",
                        R07_MERGE_SHA,
                        R07_ACTIVATION_CONTROL_SHA,
                        R07_CORRECTION_SHA256,
                        R07_INTEGRATION_CONTROL_SHA,
                        (
                            "2,860 production modules: 2,770 classified, 90 "
                            "unclassified, and 0 mixed"
                        ),
                        "R09=72 and R10=18",
                        (
                            f"passed GitHub Lean CI run {R07_INTEGRATION_CONTROL_CI_RUN} "
                            f"(job {R07_INTEGRATION_CONTROL_CI_JOB})"
                        ),
                        "R07 code is integrated on `main`",
                        (
                            "B0010 remains delivered and unaccepted with null integration "
                            "metadata"
                        ),
                        "P0010 and R0011 remain active, R0011 remains unresolved, and M07 remains ready",
                        (
                            "No R07 self-acceptance, checkpoint acceptance, R0011 resolution, "
                            "P0010 retirement, or branch retirement is recorded."
                        ),
                        )
                else:
                    if head == R07_MERGE_SHA:
                        integration_parents: list[str] = []
                        integration_changed = (
                            self.git_live_change_paths(
                                R07_MERGE_SHA,
                                f"{context}.integration_control.precommit",
                            )
                            - untracked_material
                        )
                        integration_overlay: set[str] = set()
                    else:
                        integration_parent_result = self.git(
                            "show", "-s", "--format=%P", "HEAD", check=False
                        )
                        integration_parents = integration_parent_result.stdout.split()
                        integration_diff = self.git(
                            "diff",
                            "--name-only",
                            "--no-renames",
                            R07_MERGE_SHA,
                            "HEAD",
                            "--",
                            check=False,
                        )
                        integration_changed = {
                            normalize_path(path)
                            for path in integration_diff.stdout.splitlines()
                            if path.strip()
                        }
                        if (
                            integration_parent_result.returncode
                            or integration_diff.returncode
                        ):
                            self.problems.add(
                                f"{context}.integration_control.git",
                                "cannot read integration-control parent/diff",
                            )
                        integration_overlay = (
                            self.git_live_change_paths(
                                "HEAD", f"{context}.integration_control.worktree"
                            )
                            - untracked_material
                        )
                    validate_r07_integration_commit_shape(
                        head=head,
                        parents=integration_parents,
                        changed_paths=integration_changed,
                        expected_changed_paths=integration_expected,
                        overlay_paths=integration_overlay,
                        problems=self.problems,
                        context=f"{context}.integration_control",
                    )
                    narrative_fragments = (
                        "M07 remains ready and B0010/R07 is delivered",
                        R07_DELIVERY_SHA,
                        "true merge",
                        R07_MERGE_SHA,
                        R07_ACTIVATION_CONTROL_SHA,
                        R07_CORRECTION_SHA256,
                        (
                            "2,860 production modules: 2,770 classified, 90 "
                            "unclassified, and 0 mixed"
                        ),
                        "R09=72 and R10=18",
                        "P0010 and R0011 remain active, R0011 remains unresolved",
                        "Exact integration-control Lean CI is pending before closeout",
                        (
                            "No R07 self-acceptance, checkpoint acceptance, R0011 "
                            "resolution, or branch retirement is recorded."
                        ),
                    )
            else:
                if head == R07_PLANNED_CONTROL_SHA:
                    activation_parents = []
                    live_activation_changed = self.git_live_change_paths(
                        R07_PLANNED_CONTROL_SHA,
                        f"{context}.activation_commit.precommit",
                    )
                    activation_overlay = set()
                else:
                    live_activation_parent = self.git(
                        "show", "-s", "--format=%P", "HEAD", check=False
                    )
                    activation_parents = live_activation_parent.stdout.split()
                    live_activation_diff = self.git(
                        "diff",
                        "--name-only",
                        "--no-renames",
                        R07_PLANNED_CONTROL_SHA,
                        "HEAD",
                        "--",
                        check=False,
                    )
                    live_activation_changed = {
                        normalize_path(path)
                        for path in live_activation_diff.stdout.splitlines()
                        if path.strip()
                    }
                    activation_overlay = self.git_live_change_paths(
                        "HEAD", f"{context}.activation_commit.worktree"
                    )
                validate_r07_activation_commit_shape(
                    head=head,
                    parents=activation_parents,
                    changed_paths=live_activation_changed,
                    overlay_paths=activation_overlay,
                    problems=self.problems,
                    context=f"{context}.activation_commit.live",
                )
                narrative_fragments = (
                    "B0010/R07 is active",
                    R07_PLANNED_CONTROL_SHA,
                    f"Lean CI run {R07_PLANNED_CONTROL_CI_RUN}",
                    f"job {R07_PLANNED_CONTROL_CI_JOB}",
                    "codex/reorg-completion-2026-08-r07-matrix-functions-powers-ch18",
                    C0005_CODE_SHA,
                    r"C:\Users\qed_s\higham-worktrees\completion-r07-codex",
                    "frozen until the separate activation-control commit passes Lean CI",
                    "No R07 implementation, delivery, integration, self-acceptance, checkpoint acceptance, or branch retirement is recorded",
                )
            for narrative_path in (
                self.root / "README.md",
                self.root / "docs/architecture/phases/README.md",
                self.phase_dir / "README.md",
            ):
                try:
                    narrative = narrative_path.read_text(encoding="utf-8")
                except (OSError, UnicodeError) as error:
                    self.problems.add(
                        self.relative(narrative_path),
                        f"cannot read activation narrative: {error}",
                    )
                    continue
                normalized_narrative = " ".join(narrative.split())
                for fragment in narrative_fragments:
                    self.problems.require(
                        fragment in normalized_narrative,
                        self.relative(narrative_path),
                        f"missing exact {self.r07_state} narrative fragment {fragment!r}",
                    )
        else:
            self.problems.require(
                head == R07_PLANNED_CONTROL_SHA,
                f"{context}.planned_mode.head",
                "without activation evidence HEAD must be the exact planned control",
            )
            planned_overlay = self.git_live_change_paths(
                R07_PLANNED_CONTROL_SHA, f"{context}.planned_mode.worktree"
            )
            self.problems.require(
                not planned_overlay,
                f"{context}.planned_mode.worktree",
                "planned mode must have a clean overlay; "
                f"found={sorted(planned_overlay)}",
            )

    def validate_pointer(self) -> None:
        path = self.root / ACTIVE_POINTER
        pointer = self.read_json(path, ACTIVE_POINTER.as_posix())
        if pointer is None:
            return
        expected = {
            "schema_version": 1,
            "record_kind": "active_reorganization_phase",
            "phase_id": PHASE_ID,
            "path": DEFAULT_PHASE_DIR.as_posix(),
        }
        self.problems.require(
            pointer == expected,
            ACTIVE_POINTER.as_posix(),
            f"must exactly equal {canonical_json(expected)}",
        )

    def load_phase(self) -> None:
        context = self.relative(self.phase_dir / "phase.json")
        phase = self.read_json(self.phase_dir / "phase.json", context)
        if phase is None:
            return
        self.phase = phase
        exact = {
            "schema_version": 1,
            "record_kind": "reorganization_phase",
            "phase_id": PHASE_ID,
            "origin_checkpoint_id": CHECKPOINT_ID,
            "status": "active",
        }
        for key, expected in exact.items():
            self.problems.require(
                phase.get(key) == expected,
                f"phase.json.{key}",
                f"expected {expected!r}, found {phase.get(key)!r}",
            )
        current = phase.get("current_checkpoint_id")
        allowed_checkpoints = {
            CHECKPOINT_ID,
            SUCCESSOR_CHECKPOINT_ID,
            C0002_CHECKPOINT_ID,
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }
        self.problems.require(
            current in allowed_checkpoints,
            "phase.json.current_checkpoint_id",
            f"expected one of {sorted(allowed_checkpoints)}, found {current!r}",
        )
        if current in allowed_checkpoints:
            self.current_checkpoint_id = current
        base = phase.get("base_policy")
        if not isinstance(base, dict):
            self.problems.add("phase.json.base_policy", "expected an object")
        else:
            self.problems.require(
                base.get("immutable_origin_sha") == CODE_SHA,
                "phase.json.base_policy.immutable_origin_sha",
                f"expected {CODE_SHA}",
            )
        authority = phase.get("authority")
        if not isinstance(authority, dict):
            self.problems.add("phase.json.authority", "expected an object")
        else:
            for key in ("integration_authority_id", "release_manager_id"):
                self.problems.require(
                    authority.get(key) == "primary-human",
                    f"phase.json.authority.{key}",
                    "expected primary-human",
                )
            self.problems.require(
                authority.get("build_lock_name") == BUILD_LOCK,
                "phase.json.authority.build_lock_name",
                f"expected {BUILD_LOCK}",
            )
            shared_auth = authority.get("shared_path_authority_ids")
            self.problems.require(
                isinstance(shared_auth, list) and set(shared_auth) == {"primary-human"},
                "phase.json.authority.shared_path_authority_ids",
                "expected exactly primary-human",
            )
            lanes = authority.get("lanes") if isinstance(authority.get("lanes"), list) else []
            operators = {
                operator
                for lane in lanes
                if isinstance(lane, dict)
                for operator in lane.get("operator_ids", [])
                if isinstance(operator, str)
            }
            self.problems.require(
                {"codex-local", "claude-local"} <= operators,
                "phase.json.authority.lanes",
                "local lanes must include codex-local and claude-local",
            )
        scope_ref = self.artifact(phase.get("scope"), "phase.json.scope")
        if scope_ref is not None:
            self.problems.require(
                scope_ref.path == self.relative(self.phase_dir / "scope.tsv"),
                "phase.json.scope.path",
                "must point to successor scope.tsv",
            )
        self.shared_rules = self.parse_rules(phase.get("shared_paths"), "phase.json.shared_paths")
        shared_exact = {rule.path for rule in self.shared_rules if rule.match == "exact"}
        missing = sorted(SHARED_CONSUMERS - shared_exact)
        if missing:
            self.problems.add(
                "phase.json.shared_paths",
                "missing exact integrator-shared consumer(s): " + ", ".join(missing),
            )
        if self.current_checkpoint_id == C0002_CHECKPOINT_ID:
            # C0002 released eleven future-owner reservations after R11/R12.
            # R0005 independently needs four of those same files as exact R03
            # consumer postimages, so a new active request may re-reserve only
            # this reviewed subset; the other seven must remain released.
            stale = sorted(
                (C0002_RELEASED_SHARED_PATHS - R03_RERESERVED_C0002_PATHS)
                & shared_exact
            )
            self.problems.require(
                not stale,
                "phase.json.shared_paths",
                "C0002 must keep the seven non-R03 future R05/R09 owner reservations released; "
                f"still present: {stale}",
            )
            self.problems.require(
                R03_RERESERVED_C0002_PATHS <= shared_exact,
                "phase.json.shared_paths",
                "active R0005 must exactly re-reserve its four reviewed C0002 consumer paths",
            )
        elif self.current_checkpoint_id in {
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            try:
                accepted_phase = json.loads(
                    self.git(
                        "show",
                        (
                            f"{C0002_ACCEPTANCE_CONTROL_SHA}:"
                            f"{(DEFAULT_PHASE_DIR / 'phase.json').as_posix()}"
                        ),
                    ).stdout
                )
            except (RuntimeError, json.JSONDecodeError) as error:
                self.problems.add(
                    "phase.json.shared_paths",
                    f"cannot load exact C0002 accepted shared-path set: {error}",
                )
            else:
                accepted_shared = accepted_phase.get("shared_paths")
                live_shared = phase.get("shared_paths")
                if self.current_checkpoint_id == C0003_CHECKPOINT_ID:
                    self.problems.require(
                        isinstance(accepted_shared, list)
                        and len(accepted_shared) == 160
                        and isinstance(live_shared, list)
                        and len(live_shared)
                        == 160 + R05R06_ADDED_SHARED_PATH_COUNT
                        and all(rule in live_shared for rule in accepted_shared),
                        "phase.json.shared_paths",
                        "C0003 must retain the exact 160-rule C0002 accepted shared-path "
                        "set plus exactly the 60 reviewed R0006/R0007 consumer paths",
                    )
                elif self.current_checkpoint_id == C0004_CHECKPOINT_ID:
                    phase_path = self.phase_dir / "phase.json"
                    historical_phase_path = (DEFAULT_PHASE_DIR / "phase.json").as_posix()
                    try:
                        historical_phase = self.git(
                            "show",
                            f"{C0004_ACCEPTANCE_CONTROL_SHA}:{historical_phase_path}",
                        ).stdout.encode("utf-8")
                    except RuntimeError as error:
                        historical_phase = b""
                        self.problems.add(
                            "phase.json",
                            f"cannot load accepted C0004 phase control: {error}",
                        )
                    self.problems.require(
                        isinstance(accepted_shared, list)
                        and len(accepted_shared) == 160
                        and isinstance(live_shared, list)
                        and len(live_shared) == 192
                        and all(rule in live_shared for rule in accepted_shared),
                        "phase.json.shared_paths",
                        "the C0005 planning epoch must retain the accepted 160-rule set "
                        "and add exactly 32 reviewed R0009/R0010 exact reservations",
                    )
                    if historical_phase:
                        self.problems.require(
                            hashlib.sha256(historical_phase).hexdigest().upper()
                            == C0004_PHASE_SHA256,
                            "phase.json historical C0004 control",
                            f"accepted C0004 phase control must hash to {C0004_PHASE_SHA256}",
                        )
                    if phase_path.is_file():
                        self.problems.require(
                            sha256_path(phase_path) == C0005_PLANNED_PHASE_SHA256,
                            "phase.json",
                            "live planned phase control must hash to "
                            f"{C0005_PLANNED_PHASE_SHA256}",
                        )
                else:
                    phase_path = self.phase_dir / "phase.json"
                    if self.r07_contract is not None:
                        accepted_sha = self.r07_contract.get("accepted_control_sha")
                        accepted_phase = (
                            self.git_json(
                                accepted_sha,
                                phase_path,
                                "phase.json accepted C0005 control",
                            )
                            if isinstance(accepted_sha, str)
                            else None
                        )
                        if accepted_phase is not None:
                            accepted_present = (
                                self.phase_dir / "checkpoints/C0006.json"
                            ).is_file()
                            expected_phase = json.loads(json.dumps(accepted_phase))
                            expected_phase["shared_paths"] = phase.get("shared_paths")
                            if accepted_present:
                                # C0006 acceptance advances exactly the
                                # checkpoint pointer and the M07 milestone.
                                expected_phase["current_checkpoint_id"] = (
                                    C0006_CHECKPOINT_ID
                                )
                                for milestone in expected_phase.get(
                                    "milestones", []
                                ):
                                    if (
                                        isinstance(milestone, dict)
                                        and milestone.get("milestone_id") == "M07"
                                    ):
                                        milestone["status"] = "accepted"
                                        milestone["accepted_checkpoint_id"] = (
                                            C0006_CHECKPOINT_ID
                                        )
                                # the R09/R10 planned control may also carry
                                # the reviewed codex-lane operator pair
                                for _lane in (
                                    expected_phase.get("authority", {})
                                    .get("lanes", [])
                                ):
                                    if (
                                        isinstance(_lane, dict)
                                        and _lane.get("lane_id") == R03_LANE_ID
                                        and isinstance(
                                            _lane.get("operator_ids"), list
                                        )
                                    ):
                                        _live = [
                                            l
                                            for l in phase.get("authority", {})
                                            .get("lanes", [])
                                            if isinstance(l, dict)
                                            and l.get("lane_id") == R03_LANE_ID
                                        ]
                                        if _live and sorted(
                                            _live[0].get("operator_ids") or []
                                        ) == sorted(R09R10_OPERATOR_PAIR):
                                            _lane["operator_ids"] = list(
                                                _live[0]["operator_ids"]
                                            )
                            if (
                                self.phase_dir / "checkpoints/C0007.json"
                            ).is_file():
                                # C0007 acceptance advances the pointer again
                                # and accepts exactly the R09/R10 pair. The
                                # B0012-scoped codex-lane expansion was
                                # authorized only while R10 was operated, so it
                                # expires here and the lane reverts to the
                                # accepted single operator carried above.
                                expected_phase["current_checkpoint_id"] = (
                                    C0007_CHECKPOINT_ID
                                )
                                for milestone in expected_phase.get(
                                    "milestones", []
                                ):
                                    if (
                                        isinstance(milestone, dict)
                                        and milestone.get("milestone_id")
                                        in {"M09", "M10"}
                                    ):
                                        milestone["status"] = "accepted"
                                        milestone["accepted_checkpoint_id"] = (
                                            C0007_CHECKPOINT_ID
                                        )
                            if (
                                self.phase_dir / "checkpoints/C0008.json"
                            ).is_file():
                                # C0008 acceptance advances the pointer a final
                                # time, accepts M13 with its I01 wave, and is
                                # the evidence checkpoint for bounded-phase
                                # completion. Repository-wide completion is
                                # untouched here: it stays incomplete with null
                                # evidence, so this arm cannot weaken it.
                                expected_phase["current_checkpoint_id"] = (
                                    C0008_CHECKPOINT_ID
                                )
                                for milestone in expected_phase.get(
                                    "milestones", []
                                ):
                                    if (
                                        isinstance(milestone, dict)
                                        and milestone.get("milestone_id") == "M13"
                                    ):
                                        milestone["status"] = "accepted"
                                        milestone["accepted_checkpoint_id"] = (
                                            C0008_CHECKPOINT_ID
                                        )
                                _bounded = expected_phase.get(
                                    "completion", {}
                                ).get("bounded_phase")
                                if isinstance(_bounded, dict):
                                    _bounded["status"] = "complete"
                                    _bounded["evidence_checkpoint_id"] = (
                                        C0008_CHECKPOINT_ID
                                    )
                            self.problems.require(
                                phase == expected_phase,
                                "phase.json R07 planned lifecycle",
                                "R07 planning may change only exact shared-path "
                                "reservations, plus the checkpoint pointer, "
                                "M07 acceptance at C0006, M09/M10 acceptance at "
                                "C0007, and M13 acceptance with bounded-phase "
                                "completion at C0008",
                            )
                            accepted_rules = self.parse_rules(
                                accepted_phase.get("shared_paths"),
                                "phase.json accepted C0005 shared_paths",
                            )
                            accepted_keys = {
                                (rule.match, rule.path) for rule in accepted_rules
                            }
                            live_keys = {
                                (rule.match, rule.path) for rule in self.shared_rules
                            }
                            if accepted_present:
                                # Accepted C0006 restores C0005's exact 160
                                # rules; the R09/R10 planned control then adds
                                # exactly the reviewed successor reservations.
                                planned_keys = accepted_keys | {
                                    ("exact", path)
                                    for path in R09_R10_PLANNED_SHARED_RESERVATIONS
                                }
                                self.problems.require(
                                    len(accepted_rules) == 160
                                    and live_keys in (accepted_keys, planned_keys),
                                    "phase.json.shared_paths",
                                    "accepted C0006 must release the 36 R0011 "
                                    "reservations and restore C0005's exact 160 "
                                    "rules, optionally plus the reviewed R09/R10 "
                                    "planned reservations; unexpected="
                                    f"{sorted(live_keys - planned_keys)}, missing="
                                    f"{sorted(accepted_keys - live_keys)}",
                                )
                            else:
                                self.problems.require(
                                    len(accepted_rules) == 160
                                    and accepted_keys <= live_keys
                                    and len(self.shared_rules) == 196
                                    and len(shared_exact) == 191
                                    and sum(
                                        rule.match == "prefix"
                                        for rule in self.shared_rules
                                    )
                                    == 5
                                    and all(
                                        match == "exact"
                                        for match, _path in live_keys - accepted_keys
                                    ),
                                    "phase.json.shared_paths",
                                    "authenticated R07 planning must retain C0005's 160 rules "
                                    "and add exactly 36 exact reservations (191 exact/five prefix)",
                                )
                        planned_phase = None
                        accepted_c0004 = None
                    else:
                        planned_phase = self.git_json(
                            C0005_CODE_SHA, phase_path, "phase.json C0005 code state"
                        )
                        accepted_c0004 = self.git_json(
                            C0004_ACCEPTANCE_CONTROL_SHA,
                            phase_path,
                            "phase.json C0004 accepted state",
                        )
                    if planned_phase is not None and accepted_c0004 is not None:
                        expected_phase = json.loads(json.dumps(planned_phase))
                        expected_phase["current_checkpoint_id"] = C0005_CHECKPOINT_ID
                        expected_phase["shared_paths"] = accepted_c0004.get("shared_paths")
                        for lane in expected_phase.get("authority", {}).get("lanes", []):
                            if lane.get("lane_id") == "claude-lane":
                                lane["operator_ids"] = ["claude-local"]
                        for milestone in expected_phase.get("milestones", []):
                            milestone_id = milestone.get("milestone_id")
                            if milestone_id in {"M04", "M08"}:
                                milestone["status"] = "accepted"
                                milestone["accepted_checkpoint_id"] = C0005_CHECKPOINT_ID
                            elif milestone_id == "M07":
                                milestone["status"] = "ready"
                        self.problems.require(
                            phase == expected_phase,
                            "phase.json C0005 acceptance lifecycle",
                            "C0005 may change only the checkpoint pointer, M04/M08, "
                            "M07, the temporary lane grant, and temporary reservations",
                        )
                        expected_shared = accepted_c0004.get("shared_paths")
                        expected_exact = {
                            rule.get("path")
                            for rule in expected_shared or []
                            if isinstance(rule, dict) and rule.get("match") == "exact"
                        }
                        live_prefix = [
                            rule.path for rule in self.shared_rules if rule.match == "prefix"
                        ]
                        expected_prefix = [
                            normalize_path(rule.get("path", ""))
                            for rule in expected_shared or []
                            if isinstance(rule, dict) and rule.get("match") == "prefix"
                        ]
                        self.problems.require(
                            len(expected_shared or []) == 160
                            and len(shared_exact) == 155
                            and shared_exact == expected_exact
                            and live_prefix == expected_prefix,
                            "phase.json.shared_paths",
                            "C0005 must restore exact 155-exact/five-prefix C0004 sharing",
                        )
        readme = self.phase_dir / "README.md"
        try:
            text = readme.read_text(encoding="utf-8")
        except OSError as error:
            self.problems.add(self.relative(readme), f"cannot read phase README: {error}")
        else:
            for token in ("predecessor", "C0008", CODE_SHA):
                if token not in text:
                    self.problems.add(self.relative(readme), f"missing predecessor root token {token!r}")

    def parse_rules(self, value: Any, context: str) -> list[PathRule]:
        if not isinstance(value, list):
            self.problems.add(context, "expected a list")
            return []
        result: list[PathRule] = []
        for index, item in enumerate(value):
            item_context = f"{context}[{index}]"
            if not isinstance(item, dict) or set(item) != {"path", "match"}:
                self.problems.add(item_context, "expected exactly {path, match}")
                continue
            path, match = item.get("path"), item.get("match")
            if not isinstance(path, str) or match not in {"exact", "prefix"}:
                self.problems.add(item_context, "invalid path rule")
                continue
            normalized = normalize_path(path)
            if normalized != path.rstrip("/").replace("\\", "/"):
                self.problems.add(item_context, "path rule must use normalized repository separators")
            result.append(PathRule(normalized, match))
        keys = [(rule.path.casefold(), rule.match) for rule in result]
        if len(keys) != len(set(keys)):
            self.problems.add(context, "duplicate case-insensitive path rule")
        return result

    def validate_checkpoint_and_scope(self) -> None:
        checkpoint_path = self.phase_dir / "checkpoints/C0000.json"
        checkpoint = self.read_json(checkpoint_path, self.relative(checkpoint_path))
        if checkpoint is None:
            return
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": CHECKPOINT_ID,
            "commit_sha": CODE_SHA,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"checkpoints/C0000.json.{key}",
                f"expected {expected!r}",
            )
        if self.current_checkpoint_id in {
            SUCCESSOR_CHECKPOINT_ID,
            C0002_CHECKPOINT_ID,
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.validate_successor_checkpoint()
        if self.current_checkpoint_id in {
            C0002_CHECKPOINT_ID,
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.validate_c0002_checkpoint()
        if self.current_checkpoint_id in {
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.validate_c0003_checkpoint()
        if self.current_checkpoint_id in {
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.validate_c0004_checkpoint()
        if self.current_checkpoint_id in {
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.validate_c0005_checkpoint()
        if self.current_checkpoint_id == C0006_CHECKPOINT_ID:
            self.validate_c0006_checkpoint()
        if self.current_checkpoint_id == C0008_CHECKPOINT_ID:
            self.validate_c0008_checkpoint()
        inventory_ref = self.artifact(
            checkpoint.get("inventory"), "checkpoints/C0000.json.inventory"
        )
        scope_path = self.phase_dir / "scope.tsv"
        _, scope = self.read_tsv(scope_path, self.relative(scope_path), SCOPE_HEADER)
        self.scope = scope
        self.scope_by_path = {row.get("path", ""): row for row in scope}
        self.problems.require(
            len(scope) == 2593,
            self.relative(scope_path),
            f"expected 2,593 production rows, found {len(scope)}",
        )
        if len(self.scope_by_path) != len(scope):
            self.problems.add(self.relative(scope_path), "duplicate scope path")
        if inventory_ref is not None:
            inventory_path = self.root / inventory_ref.path
            _, inventory = self.read_tsv(
                inventory_path, inventory_ref.path, SCOPE_HEADER
            )
            if inventory != scope:
                self.problems.add(
                    inventory_ref.path,
                    "C0000 inventory must byte-semantically equal successor scope.tsv",
                )
        predecessor_path = self.root / PREDECESSOR_DIR / "checkpoints/C0008-inventory.tsv"
        _, predecessor = self.read_tsv(
            predecessor_path,
            (PREDECESSOR_DIR / "checkpoints/C0008-inventory.tsv").as_posix(),
            SCOPE_HEADER,
        )
        predecessor_by_path = {row.get("path", ""): row for row in predecessor}
        self.problems.require(
            len(predecessor) == 2593,
            "predecessor C0008 inventory",
            f"expected 2,593 rows, found {len(predecessor)}",
        )
        debt = {row["path"] for row in predecessor if row.get("debt_flags") != "-"}
        clean_w90 = {
            row["path"]
            for row in predecessor
            if row.get("debt_flags") == "-" and row.get("wave_id") == "W90"
        }
        self.problems.require(len(debt) == 467, "residual accounting", f"expected 467 debt rows, found {len(debt)}")
        self.problems.require(len(clean_w90) == 15, "residual accounting", f"expected 15 debt-free W90 outliers, found {len(clean_w90)}")
        for path, old in predecessor_by_path.items():
            new = self.scope_by_path.get(path)
            if new is None:
                self.problems.add("scope.tsv", f"missing immutable C0008 path {path}")
                continue
            for key in ("module", "path", "base_blob_oid", "current_tier", "debt_flags"):
                if new.get(key) != old.get(key):
                    self.problems.add(
                        f"scope.tsv[{path}]",
                        f"immutable {key} drift: {old.get(key)!r} -> {new.get(key)!r}",
                    )
        in_scope = {row["path"] for row in scope if row.get("phase_scope") == "in_scope"}
        complete = {row["path"] for row in scope if row.get("phase_scope") == "already_complete"}
        self.problems.require(len(in_scope) == 492, "scope.tsv", f"expected 492 in_scope rows, found {len(in_scope)}")
        self.problems.require(len(complete) == 2101, "scope.tsv", f"expected 2,101 already_complete rows, found {len(complete)}")
        expected_editable = (debt | clean_w90) - {MATRIX_ALGEBRA}
        expected_in_scope = expected_editable | SHARED_CONSUMERS
        missing = sorted(expected_in_scope - in_scope)
        extra = sorted(in_scope - expected_in_scope)
        if missing or extra:
            self.problems.add(
                "scope.tsv residual assignment",
                f"expected exact 492-row set; missing={missing}, extra={extra}",
            )
        matrix = self.scope_by_path.get(MATRIX_ALGEBRA)
        if matrix is None:
            self.problems.add("scope.tsv", f"missing protected {MATRIX_ALGEBRA}")
        else:
            self.problems.require(
                matrix.get("phase_scope") == "already_complete"
                and matrix.get("lane_id") == "-"
                and matrix.get("wave_id") == "-",
                f"scope.tsv[{MATRIX_ALGEBRA}]",
                "must be protected already_complete with lane_id/wave_id '-'",
            )
        for path in SHARED_CONSUMERS:
            row = self.scope_by_path.get(path)
            if row is None:
                self.problems.add("scope.tsv", f"missing shared consumer {path}")
                continue
            self.problems.require(
                row.get("phase_scope") == "in_scope" and row.get("wave_id") == "I01",
                f"scope.tsv[{path}]",
                "integrator-shared consumer must be in_scope in I01",
            )
        for row in scope:
            disposition = row.get("phase_scope")
            if disposition == "in_scope":
                if row.get("lane_id") in {"", "-"} or row.get("wave_id") in {"", "-"}:
                    self.problems.add(
                        f"scope.tsv[{row.get('path')}]",
                        "in_scope row requires a lane and wave",
                    )
            elif disposition == "already_complete":
                if row.get("lane_id") != "-" or row.get("wave_id") != "-":
                    self.problems.add(
                        f"scope.tsv[{row.get('path')}]",
                        "already_complete row must use '-' lane and wave",
                    )
            else:
                self.problems.add(
                    f"scope.tsv[{row.get('path')}]",
                    f"completion scope permits only in_scope/already_complete, found {disposition!r}",
                )
        for wave, paths in (("R01", R01_PATHS), ("R02", R02_PATHS)):
            actual = {
                row["path"]
                for row in scope
                if row.get("phase_scope") == "in_scope" and row.get("wave_id") == wave
            }
            if actual != paths:
                self.problems.add(
                    f"scope.tsv wave {wave}",
                    f"must equal exact selector paths; missing={sorted(paths-actual)}, extra={sorted(actual-paths)}",
                )
        accounting = self.phase_dir / "reviews/residual-accounting.md"
        try:
            text = accounting.read_text(encoding="utf-8")
        except OSError as error:
            self.problems.add(self.relative(accounting), f"cannot read residual review: {error}")
        else:
            compact = text.replace(",", "")
            for token in ("467", "15", "481", "492", "2101", MATRIX_ALGEBRA):
                if token not in compact:
                    self.problems.add(self.relative(accounting), f"missing accounting token {token!r}")

    def validate_successor_checkpoint(self) -> None:
        context = "checkpoints/C0001.json"
        path = self.phase_dir / "checkpoints/C0001.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
            "parent_checkpoint_id": CHECKPOINT_ID,
            "commit_sha": INTEGRATED_CODE_SHA,
            "accepted_by": "primary-human",
            "milestones_satisfied": SUCCESSOR_MILESTONES,
            "unblocks": [],
            "metrics": SUCCESSOR_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        accepted_at = checkpoint.get("accepted_at")
        self.problems.require(
            isinstance(accepted_at, str)
            and RFC3339_RE.fullmatch(accepted_at) is not None,
            f"{context}.accepted_at",
            "expected an RFC3339 timestamp with timezone",
        )

        inventory = self.artifact(checkpoint.get("inventory"), f"{context}.inventory")
        expected_inventory = self.relative(
            self.phase_dir / "checkpoints/C0001-inventory.tsv"
        )
        if inventory is not None:
            self.problems.require(
                inventory.path == expected_inventory,
                f"{context}.inventory.path",
                f"expected {expected_inventory}",
            )
            _, rows = self.read_tsv(
                self.root / inventory.path,
                inventory.path,
                SCOPE_HEADER,
            )
            self.problems.require(
                len(rows) == SUCCESSOR_METRICS["production_modules"],
                inventory.path,
                "row count must equal the exact C0001 production-module metric",
            )
            paths = [row.get("path", "") for row in rows]
            self.problems.require(
                len(paths) == len(set(paths)),
                inventory.path,
                "C0001 inventory paths must be unique",
            )

        baseline = checkpoint.get("combined_baseline")
        if not isinstance(baseline, dict):
            self.problems.add(f"{context}.combined_baseline", "expected an object")
        else:
            self.problems.require(
                baseline.get("format_version") == 2,
                f"{context}.combined_baseline.format_version",
                "expected exact format version 2",
            )
            artifact = self.artifact(
                baseline.get("artifact"),
                f"{context}.combined_baseline.artifact",
            )
            summary = self.artifact(
                baseline.get("summary_artifact"),
                f"{context}.combined_baseline.summary_artifact",
            )
            expected_artifact = self.relative(
                self.phase_dir / "baselines/C0001-combined.json"
            )
            expected_summary = self.relative(
                self.phase_dir / "baselines/C0001-combined.md"
            )
            if artifact is not None:
                self.problems.require(
                    artifact.path == expected_artifact,
                    f"{context}.combined_baseline.artifact.path",
                    f"expected {expected_artifact}",
                )
                document = self.read_json(
                    self.root / artifact.path,
                    f"{context}.combined_baseline.artifact",
                )
                metadata = document.get("metadata") if document is not None else None
                self.problems.require(
                    isinstance(metadata, dict)
                    and metadata.get("commit") == INTEGRATED_CODE_SHA
                    and metadata.get("library_source_clean") is True
                    and metadata.get("library_source_dirty_paths") == [],
                    f"{context}.combined_baseline.artifact.metadata",
                    "must record the exact clean integrated code commit",
                )
            if summary is not None:
                self.problems.require(
                    summary.path == expected_summary,
                    f"{context}.combined_baseline.summary_artifact.path",
                    f"expected {expected_summary}",
                )
            self.problems.require(
                isinstance(baseline.get("generation_command"), str)
                and bool(baseline.get("generation_command", "").strip()),
                f"{context}.combined_baseline.generation_command",
                "must record a nonempty generation command",
            )

        gates = checkpoint.get("gates")
        if not isinstance(gates, list):
            self.problems.add(f"{context}.gates", "expected a list")
        else:
            gate_ids = [
                gate.get("gate_id")
                for gate in gates
                if isinstance(gate, dict)
            ]
            self.problems.require(
                len(gate_ids) == len(gates)
                and len(gate_ids) == len(set(gate_ids))
                and set(gate_ids) == SUCCESSOR_GATE_IDS,
                f"{context}.gates",
                "must contain every and only the 12 exact C0001 acceptance gates",
            )
            expected_evidence = self.relative(
                self.phase_dir / "checkpoints/C0001-gates.md"
            )
            for index, gate in enumerate(gates):
                if not isinstance(gate, dict):
                    self.problems.add(f"{context}.gates[{index}]", "expected an object")
                    continue
                gate_id = gate.get("gate_id")
                gate_context = f"{context}.gates[{gate_id or index}]"
                self.problems.require(
                    gate.get("status") == "PASS"
                    and gate.get("commit_sha") == INTEGRATED_CODE_SHA,
                    gate_context,
                    "must record PASS at the exact integrated code commit",
                )
                evidence = self.artifact(
                    gate.get("evidence"), f"{gate_context}.evidence"
                )
                if evidence is not None:
                    self.problems.require(
                        evidence.path == expected_evidence,
                        f"{gate_context}.evidence.path",
                        f"expected {expected_evidence}",
                    )

        milestones = self.phase.get("milestones")
        milestone_map = {
            item.get("milestone_id"): item
            for item in milestones
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        } if isinstance(milestones, list) else {}
        for milestone_id in SUCCESSOR_MILESTONES:
            milestone = milestone_map.get(milestone_id)
            self.problems.require(
                isinstance(milestone, dict)
                and milestone.get("status") == "accepted"
                and milestone.get("accepted_checkpoint_id")
                == SUCCESSOR_CHECKPOINT_ID,
                f"phase.json.milestones[{milestone_id}]",
                "must be accepted at exact checkpoint C0001",
            )
        self.validate_successor_history()

    def validate_successor_history(self) -> None:
        for commit, parents, label in (
            (R01_MERGE_SHA, R01_MERGE_PARENTS, "R01 merge"),
            (R02_MERGE_SHA, R02_MERGE_PARENTS, "R02 merge"),
        ):
            process = self.git(
                "rev-list", "--parents", "-n", "1", commit, check=False
            )
            actual = process.stdout.strip().split()
            expected = [commit, *parents]
            self.problems.require(
                process.returncode == 0 and actual == expected,
                f"C0001 {label} ancestry",
                f"expected exact commit/parent vector {expected}, found {actual}",
            )
        for ancestor, label in (
            (R01_MERGE_SHA, "R01 merge"),
            (R02_MERGE_SHA, "R02 merge"),
            (BRANCH_FACTS["B0001"]["delivery_sha"], "R01 delivery"),
            (BRANCH_FACTS["B0002"]["delivery_sha"], "R02 delivery"),
        ):
            ancestry = self.git(
                "merge-base",
                "--is-ancestor",
                ancestor,
                INTEGRATED_CODE_SHA,
                check=False,
            )
            self.problems.require(
                ancestry.returncode == 0,
                f"C0001 {label} ancestry",
                f"{ancestor} must be an ancestor of exact integrated code {INTEGRATED_CODE_SHA}",
            )

    def validate_c0002_checkpoint(self) -> None:
        context = "checkpoints/C0002.json"
        path = self.phase_dir / "checkpoints/C0002.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": C0002_CHECKPOINT_ID,
            "parent_checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
            "commit_sha": C0002_CODE_SHA,
            "accepted_by": "primary-human",
            "milestones_satisfied": C0002_MILESTONES,
            "unblocks": [],
            "metrics": C0002_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        accepted_at = checkpoint.get("accepted_at")
        self.problems.require(
            isinstance(accepted_at, str)
            and RFC3339_RE.fullmatch(accepted_at) is not None,
            f"{context}.accepted_at",
            "expected an RFC3339 timestamp with timezone",
        )

        inventory = self.artifact(checkpoint.get("inventory"), f"{context}.inventory")
        expected_inventory = self.relative(
            self.phase_dir / "checkpoints/C0002-inventory.tsv"
        )
        if inventory is not None:
            self.problems.require(
                inventory.path == expected_inventory
                and inventory.sha256 == C0002_INVENTORY_SHA256,
                f"{context}.inventory",
                f"must pin {expected_inventory} at {C0002_INVENTORY_SHA256}",
            )
            _, rows = self.read_tsv(
                self.root / inventory.path, inventory.path, SCOPE_HEADER
            )
            paths = [row.get("path", "") for row in rows]
            self.problems.require(
                len(rows) == C0002_METRICS["production_modules"]
                and len(paths) == len(set(paths)),
                inventory.path,
                "must contain 2,642 unique production-module rows",
            )
            dispositions = Counter(row.get("phase_scope", "") for row in rows)
            debt_rows = sum(row.get("debt_flags", "") != "-" for row in rows)
            self.problems.require(
                dispositions == Counter({"already_complete": 2262, "in_scope": 380})
                and debt_rows == 356,
                inventory.path,
                "must record exact C0002 2,262/380 disposition and 356-row debt accounting",
            )
            if (self.root / inventory.path).is_file():
                self.problems.require(
                    sha256_path(self.root / inventory.path) == C0002_INVENTORY_SHA256,
                    inventory.path,
                    "C0002 inventory content drifted",
                )

        baseline = checkpoint.get("combined_baseline")
        if not isinstance(baseline, dict):
            self.problems.add(f"{context}.combined_baseline", "expected an object")
        else:
            self.problems.require(
                baseline.get("format_version") == 2
                and isinstance(baseline.get("generation_command"), str)
                and bool(baseline.get("generation_command", "").strip()),
                f"{context}.combined_baseline",
                "requires format 2 and a nonempty generation command",
            )
            artifact = self.artifact(
                baseline.get("artifact"), f"{context}.combined_baseline.artifact"
            )
            summary = self.artifact(
                baseline.get("summary_artifact"),
                f"{context}.combined_baseline.summary_artifact",
            )
            expected_artifact = self.relative(
                self.phase_dir / "baselines/C0002-combined.json"
            )
            expected_summary = self.relative(
                self.phase_dir / "baselines/C0002-combined.md"
            )
            if artifact is not None:
                self.problems.require(
                    artifact.path == expected_artifact
                    and artifact.sha256 == C0002_COMBINED_BASELINE_SHA256,
                    f"{context}.combined_baseline.artifact",
                    "must pin the exact C0002 format-2 JSON baseline",
                )
                document = self.read_json(
                    self.root / artifact.path,
                    f"{context}.combined_baseline.artifact",
                )
                metadata = document.get("metadata") if document is not None else None
                source = document.get("source") if document is not None else None
                self.problems.require(
                    isinstance(metadata, dict)
                    and metadata.get("commit") == C0002_CODE_SHA
                    and metadata.get("library_source_clean") is True
                    and metadata.get("library_source_dirty_paths") == [],
                    f"{context}.combined_baseline.artifact.metadata",
                    "must record the exact clean C0002 code commit",
                )
                self.problems.require(
                    isinstance(source, dict)
                    and source.get("module_count") == 2642
                    and source.get("line_count") == 4001883
                    and source.get("nonblank_line_count") == 1452020
                    and source.get("byte_count") == 74555226
                    and source.get("direct_import_count") == 27407
                    and source.get("internal_direct_import_count") == 16479
                    and source.get("external_direct_import_count") == 10928,
                    f"{context}.combined_baseline.artifact.source",
                    "source totals must equal the exact C0002 measurements",
                )
                if (self.root / artifact.path).is_file():
                    self.problems.require(
                        sha256_path(self.root / artifact.path)
                        == C0002_COMBINED_BASELINE_SHA256,
                        artifact.path,
                        "C0002 baseline content drifted",
                    )
            if summary is not None:
                self.problems.require(
                    summary.path == expected_summary
                    and summary.sha256 == C0002_COMBINED_SUMMARY_SHA256,
                    f"{context}.combined_baseline.summary_artifact",
                    "must pin the exact C0002 Markdown summary",
                )
                if (self.root / summary.path).is_file():
                    self.problems.require(
                        sha256_path(self.root / summary.path)
                        == C0002_COMBINED_SUMMARY_SHA256,
                        summary.path,
                        "C0002 baseline summary content drifted",
                    )

        gates = checkpoint.get("gates")
        expected_evidence = self.relative(
            self.phase_dir / "checkpoints/C0002-gates.md"
        )
        if not isinstance(gates, list):
            self.problems.add(f"{context}.gates", "expected a list")
        else:
            gate_ids = [
                gate.get("gate_id") for gate in gates if isinstance(gate, dict)
            ]
            self.problems.require(
                len(gate_ids) == len(gates)
                and len(gate_ids) == len(set(gate_ids))
                and set(gate_ids) == SUCCESSOR_GATE_IDS,
                f"{context}.gates",
                "must contain every and only the 12 exact C0002 acceptance gates",
            )
            for index, gate in enumerate(gates):
                if not isinstance(gate, dict):
                    self.problems.add(f"{context}.gates[{index}]", "expected an object")
                    continue
                gate_id = gate.get("gate_id")
                gate_context = f"{context}.gates[{gate_id or index}]"
                self.problems.require(
                    gate.get("status") == "PASS"
                    and gate.get("commit_sha") == C0002_CODE_SHA,
                    gate_context,
                    "must record PASS at the exact C0002 code commit",
                )
                evidence = self.artifact(
                    gate.get("evidence"), f"{gate_context}.evidence"
                )
                if evidence is not None:
                    self.problems.require(
                        evidence.path == expected_evidence
                        and evidence.sha256 == C0002_GATES_SHA256,
                        f"{gate_context}.evidence",
                        "must pin the exact C0002 gate report",
                    )
        gate_path = self.root / expected_evidence
        if gate_path.is_file():
            self.problems.require(
                sha256_path(gate_path) == C0002_GATES_SHA256,
                expected_evidence,
                "C0002 gate report content drifted",
            )

        ledger_path = self.phase_dir / "checkpoints/C0002-integrator-paths.tsv"
        if ledger_path.is_file():
            _, ledger = self.read_tsv(
                ledger_path,
                self.relative(ledger_path),
                ("status", "category", "path"),
            )
            actual_paths = {row.get("path", "") for row in ledger}
            changed = self.git(
                "diff",
                "--name-only",
                f"{R12_MERGE_SHA}..{C0002_CODE_SHA}",
            ).stdout.splitlines()
            self.problems.require(
                len(ledger) == 146
                and len(actual_paths) == 146
                and actual_paths == set(changed)
                and sha256_path(ledger_path) == C0002_INTEGRATOR_LEDGER_SHA256,
                self.relative(ledger_path),
                "must exactly ledger the 146-path post-R12 integration range",
            )
        else:
            self.problems.add(self.relative(ledger_path), "missing C0002 integrator ledger")

        milestones = self.phase.get("milestones")
        milestone_map = {
            item.get("milestone_id"): item
            for item in milestones
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        } if isinstance(milestones, list) else {}
        for milestone_id in C0002_MILESTONES:
            milestone = milestone_map.get(milestone_id)
            expected_checkpoint = (
                SUCCESSOR_CHECKPOINT_ID
                if milestone_id in SUCCESSOR_MILESTONES
                else C0002_CHECKPOINT_ID
            )
            self.problems.require(
                isinstance(milestone, dict)
                and milestone.get("status") == "accepted"
                and milestone.get("accepted_checkpoint_id") == expected_checkpoint,
                f"phase.json.milestones[{milestone_id}]",
                f"must be accepted at exact checkpoint {expected_checkpoint}",
            )
        self.validate_c0002_history()

    def validate_c0002_history(self) -> None:
        for commit, parents, label in (
            (R11_MERGE_SHA, R11_MERGE_PARENTS, "R11 merge"),
            (R12_MERGE_SHA, R12_MERGE_PARENTS, "R12 merge"),
        ):
            process = self.git(
                "rev-list", "--parents", "-n", "1", commit, check=False
            )
            actual = process.stdout.strip().split()
            expected = [commit, *parents]
            self.problems.require(
                process.returncode == 0 and actual == expected,
                f"C0002 {label} ancestry",
                f"expected exact commit/parent vector {expected}, found {actual}",
            )
        for ancestor, label in (
            (R11_MERGE_SHA, "R11 merge"),
            (R12_MERGE_SHA, "R12 merge"),
            (NEXT_BRANCH_FACTS["B0003"]["delivery_sha"], "R11 delivery"),
            (NEXT_BRANCH_FACTS["B0004"]["delivery_sha"], "R12 delivery"),
        ):
            ancestry = self.git(
                "merge-base", "--is-ancestor", ancestor, C0002_CODE_SHA, check=False
            )
            self.problems.require(
                ancestry.returncode == 0,
                f"C0002 {label} ancestry",
                f"{ancestor} must be an ancestor of exact C0002 code {C0002_CODE_SHA}",
            )

    def validate_c0003_checkpoint(self) -> None:
        """Validate the exact R03 acceptance checkpoint and integration audit."""

        context = "checkpoints/C0003.json"
        path = self.phase_dir / "checkpoints/C0003.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": C0003_CHECKPOINT_ID,
            "parent_checkpoint_id": C0002_CHECKPOINT_ID,
            "commit_sha": C0003_CODE_SHA,
            "accepted_by": "primary-human",
            "milestones_satisfied": C0003_MILESTONES,
            "unblocks": [],
            "metrics": C0003_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        accepted_at = checkpoint.get("accepted_at")
        self.problems.require(
            isinstance(accepted_at, str)
            and RFC3339_RE.fullmatch(accepted_at) is not None,
            f"{context}.accepted_at",
            "expected an RFC3339 timestamp with timezone",
        )

        inventory = self.artifact(checkpoint.get("inventory"), f"{context}.inventory")
        inventory_path = self.phase_dir / "checkpoints/C0003-inventory.tsv"
        expected_inventory = self.relative(inventory_path)
        inventory_rows: list[dict[str, str]] = []
        if inventory is not None:
            self.problems.require(
                inventory.path == expected_inventory
                and inventory.sha256 == C0003_INVENTORY_SHA256,
                f"{context}.inventory",
                f"must pin {expected_inventory} at {C0003_INVENTORY_SHA256}",
            )
            _, inventory_rows = self.read_tsv(
                self.root / inventory.path, inventory.path, SCOPE_HEADER
            )
            paths = [row.get("path", "") for row in inventory_rows]
            self.problems.require(
                len(inventory_rows) == C0003_METRICS["production_modules"]
                and len(paths) == len(set(paths)),
                inventory.path,
                "must contain 2,690 unique production-module rows",
            )
            dispositions = Counter(
                row.get("phase_scope", "") for row in inventory_rows
            )
            debt_rows = sum(
                row.get("debt_flags", "") != "-" for row in inventory_rows
            )
            self.problems.require(
                dispositions == C0003_INVENTORY_DISPOSITIONS
                and debt_rows == C0003_INVENTORY_DEBT_ROWS,
                inventory.path,
                "must record exact C0003 2,356/334 disposition and 310-row debt accounting",
            )
            self.problems.require(
                all(row.get("wave_id") != R03_WAVE_ID for row in inventory_rows),
                inventory.path,
                "accepted R03 may leave no C0003 inventory row in R03 scope",
            )
            i01_rows = [
                row for row in inventory_rows if row.get("wave_id") == "I01"
            ]
            self.problems.require(
                len(i01_rows) == 12
                and C0003_I01_COUNTEREXAMPLE_ROW in i01_rows,
                inventory.path,
                "I01 must contain exactly 12 rows including the exact cycle-repair counterexample row",
            )

            c0002_inventory_path = self.phase_dir / "checkpoints/C0002-inventory.tsv"
            _, c0002_rows = self.read_tsv(
                c0002_inventory_path,
                self.relative(c0002_inventory_path),
                SCOPE_HEADER,
            )
            c0002_paths = {row.get("path", "") for row in c0002_rows}
            c0003_by_path = {
                row.get("path", ""): row for row in inventory_rows
            }
            new_paths = set(c0003_by_path) - c0002_paths
            self.problems.require(
                c0002_paths <= set(c0003_by_path) and len(new_paths) == 48,
                inventory.path,
                "C0003 inventory must retain every C0002 path and add exactly 48 production modules",
            )
            for new_path in sorted(new_paths):
                row = c0003_by_path[new_path]
                self.problems.require(
                    row.get("phase_scope") == "already_complete"
                    and row.get("debt_flags") == "-"
                    and row.get("lane_id") == "-"
                    and row.get("wave_id") == "-",
                    f"{inventory.path}[{new_path}]",
                    "every new R03 production module must be debt-free and already complete",
                )

            selector_path = self.phase_dir / "selectors/R03.tsv"
            _, selector_rows = self.read_tsv(
                selector_path, self.relative(selector_path), SELECTOR_HEADER
            )
            selector_paths = {row.get("path", "") for row in selector_rows}
            self.problems.require(
                len(selector_rows) == R03_OWNER_COUNT
                and len(selector_paths) == R03_OWNER_COUNT,
                inventory.path,
                "the exact 47 R03 selector rows must remain identifiable at C0003",
            )
            for selected_path in sorted(selector_paths):
                row = c0003_by_path.get(selected_path, {})
                self.problems.require(
                    row.get("phase_scope") == "already_complete"
                    and row.get("debt_flags") == "-"
                    and row.get("lane_id") == "-"
                    and row.get("wave_id") == "-",
                    f"{inventory.path}[{selected_path}]",
                    "every accepted R03 owner must be debt-free and outside active scope",
                )

            code_blobs = self.git_tree_blobs(C0003_CODE_SHA)
            for row in inventory_rows:
                row_path = row.get("path", "")
                self.problems.require(
                    row.get("base_blob_oid") == code_blobs.get(row_path),
                    f"{inventory.path}[{row_path}].base_blob_oid",
                    "must pin the exact C0003 Git blob",
                )
            if (self.root / inventory.path).is_file():
                self.problems.require(
                    sha256_path(self.root / inventory.path)
                    == C0003_INVENTORY_SHA256,
                    inventory.path,
                    "C0003 inventory content drifted",
                )

        baseline = checkpoint.get("combined_baseline")
        if not isinstance(baseline, dict):
            self.problems.add(f"{context}.combined_baseline", "expected an object")
        else:
            expected_command = (
                "python -B tools/architecture/generate_baseline.py --output-dir "
                "docs/architecture/phases/2026-08-repository-reorganization-"
                "completion/baselines --name C0003-combined "
                "--keep-dependency-tsv benchmark-results/C0003-combined.tsv"
            )
            self.problems.require(
                baseline.get("format_version") == 2
                and baseline.get("generation_command") == expected_command,
                f"{context}.combined_baseline",
                "requires the exact deterministic C0003 format-2 generation command",
            )
            artifact = self.artifact(
                baseline.get("artifact"), f"{context}.combined_baseline.artifact"
            )
            summary = self.artifact(
                baseline.get("summary_artifact"),
                f"{context}.combined_baseline.summary_artifact",
            )
            expected_artifact = self.relative(
                self.phase_dir / "baselines/C0003-combined.json"
            )
            expected_summary = self.relative(
                self.phase_dir / "baselines/C0003-combined.md"
            )
            if artifact is not None:
                self.problems.require(
                    artifact.path == expected_artifact
                    and artifact.sha256 == C0003_COMBINED_BASELINE_SHA256,
                    f"{context}.combined_baseline.artifact",
                    "must pin the exact C0003 format-2 JSON baseline",
                )
                document = self.read_json(
                    self.root / artifact.path,
                    f"{context}.combined_baseline.artifact",
                )
                metadata = document.get("metadata") if document is not None else None
                source = document.get("source") if document is not None else None
                tier_audit = source.get("tier_audit") if isinstance(source, dict) else None
                self.problems.require(
                    isinstance(metadata, dict)
                    and metadata.get("commit") == C0003_CODE_SHA
                    and metadata.get("library_source_clean") is True
                    and metadata.get("library_source_dirty_paths") == [],
                    f"{context}.combined_baseline.artifact.metadata",
                    "must record the exact clean C0003 code commit",
                )
                self.problems.require(
                    isinstance(source, dict)
                    and all(
                        source.get(key) == value
                        for key, value in C0003_SOURCE_FACTS.items()
                    ),
                    f"{context}.combined_baseline.artifact.source",
                    f"source totals must equal exact C0003 measurements {C0003_SOURCE_FACTS}",
                )
                self.problems.require(
                    isinstance(tier_audit, dict)
                    and tier_audit.get("module_counts_by_tier")
                    == C0003_TIER_COUNTS
                    and tier_audit.get("unclassified_module_count") == 254
                    and tier_audit.get("classified_module_count") == 2436,
                    f"{context}.combined_baseline.artifact.source.tier_audit",
                    "tier counts must equal the exact C0003 2,436/254 classification",
                )
                if (self.root / artifact.path).is_file():
                    self.problems.require(
                        sha256_path(self.root / artifact.path)
                        == C0003_COMBINED_BASELINE_SHA256,
                        artifact.path,
                        "C0003 baseline content drifted",
                    )
            if summary is not None:
                self.problems.require(
                    summary.path == expected_summary
                    and summary.sha256 == C0003_COMBINED_SUMMARY_SHA256,
                    f"{context}.combined_baseline.summary_artifact",
                    "must pin the exact C0003 Markdown summary",
                )
                if (self.root / summary.path).is_file():
                    self.problems.require(
                        sha256_path(self.root / summary.path)
                        == C0003_COMBINED_SUMMARY_SHA256,
                        summary.path,
                        "C0003 baseline summary content drifted",
                    )

        gates = checkpoint.get("gates")
        expected_evidence = self.relative(
            self.phase_dir / "checkpoints/C0003-gates.md"
        )
        if not isinstance(gates, list):
            self.problems.add(f"{context}.gates", "expected a list")
        else:
            gate_ids = [
                gate.get("gate_id") for gate in gates if isinstance(gate, dict)
            ]
            self.problems.require(
                len(gate_ids) == len(gates)
                and len(gate_ids) == len(set(gate_ids))
                and set(gate_ids) == SUCCESSOR_GATE_IDS,
                f"{context}.gates",
                "must contain every and only the 12 exact C0003 acceptance gates",
            )
            for index, gate in enumerate(gates):
                if not isinstance(gate, dict):
                    self.problems.add(f"{context}.gates[{index}]", "expected an object")
                    continue
                gate_id = gate.get("gate_id")
                gate_context = f"{context}.gates[{gate_id or index}]"
                self.problems.require(
                    gate.get("status") == "PASS"
                    and gate.get("commit_sha") == C0003_CODE_SHA,
                    gate_context,
                    "must record PASS at the exact C0003 code commit",
                )
                evidence = self.artifact(
                    gate.get("evidence"), f"{gate_context}.evidence"
                )
                if evidence is not None:
                    self.problems.require(
                        evidence.path == expected_evidence
                        and evidence.sha256 == C0003_GATES_SHA256,
                        f"{gate_context}.evidence",
                        "must pin the exact C0003 gate report",
                    )
        gate_path = self.root / expected_evidence
        if gate_path.is_file():
            self.problems.require(
                sha256_path(gate_path) == C0003_GATES_SHA256,
                expected_evidence,
                "C0003 gate report content drifted",
            )
            try:
                gate_text = gate_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(expected_evidence, f"cannot read gate report: {error}")
            else:
                for token in (
                    C0003_CODE_SHA,
                    R03_ROUTE_SHA,
                    R03_DELIVERY_SHA,
                    R03_MERGE_SHA,
                    R03_EXPECTED_POSTIMAGE_TREE,
                    C0003_RAW_DEPENDENCY_TSV_SHA256,
                    "2,393 unique paths: 2,209 additions and 184 modifications",
                    "115 request paths remain byte-identical",
                    "exactly six have reviewed bounded follow-ups",
                    "exactly 27 paths",
                    "exactly 142 paths",
                    "The 91 R0005-only",
                    "shared reservations are released; all 30",
                ):
                    self.problems.require(
                        token in gate_text,
                        expected_evidence,
                        f"gate report must record exact C0003 fact {token!r}",
                    )
        else:
            self.problems.add(expected_evidence, "missing C0003 gate report")

        ledger_path = self.phase_dir / "checkpoints/C0003-integrator-paths.tsv"
        if ledger_path.is_file():
            _, ledger = self.read_tsv(
                ledger_path,
                self.relative(ledger_path),
                ("status", "category", "path"),
            )
            ledger_pairs = [
                (row.get("status", ""), row.get("path", "")) for row in ledger
            ]
            changed_rows: list[tuple[str, str]] = []
            for row in self.git(
                "diff", "--name-status", R03_ROUTE_SHA, C0003_CODE_SHA
            ).stdout.splitlines():
                fields = row.split("\t")
                if len(fields) == 2:
                    changed_rows.append((fields[0], fields[1]))
                else:
                    self.problems.add(
                        self.relative(ledger_path),
                        f"route diff contains unsupported rename/copy row {row!r}",
                    )
            ledger_by_path = {
                row.get("path", ""): row for row in ledger
            }
            self.problems.require(
                len(ledger) == 2393
                and len(ledger_by_path) == 2393
                and ledger_pairs == changed_rows
                and Counter(row.get("status", "") for row in ledger)
                == C0003_ROUTE_STATUS_COUNTS
                and Counter(row.get("category", "") for row in ledger)
                == C0003_ROUTE_CATEGORY_COUNTS
                and sha256_path(ledger_path) == C0003_INTEGRATOR_LEDGER_SHA256,
                self.relative(ledger_path),
                "must exactly ledger the 2,393-path 2,209A/184M route-to-integration range",
            )

            request_path = self.phase_dir / "requests/R0005.json"
            request = self.read_json(request_path, self.relative(request_path))
            request_paths = set(request.get("paths", [])) if request is not None else set()
            reviewed_request = {
                row.get("path", "")
                for row in ledger
                if row.get("category") == "reviewed_request"
            }
            deviation_paths = set(C0003_REQUEST_DEVIATION_CATEGORIES)
            actual_deviation_categories = {
                path_value: ledger_by_path.get(path_value, {}).get("category")
                for path_value in deviation_paths
            }
            extra_paths = {
                row.get("path", "")
                for row in ledger
                if row.get("category") in C0003_EXTRA_CATEGORIES
            }
            immutable_delivery = {
                row.get("path", "")
                for row in ledger
                if row.get("category") == "immutable_delivery"
            }
            self.problems.require(
                len(reviewed_request) == 115
                and request_paths == reviewed_request | deviation_paths
                and actual_deviation_categories
                == C0003_REQUEST_DEVIATION_CATEGORIES,
                self.relative(ledger_path),
                "R0005 ledger split must be exactly 115 byte-identical paths plus the six corrected deviations",
            )
            self.problems.require(
                len(extra_paths) == 21,
                self.relative(ledger_path),
                "integration follow-up allowlist must contain exactly 21 paths",
            )
            reconstructed_tree = self.reconstruct_r03_expected_tree()
            expected_diff: set[str] = set()
            if reconstructed_tree is not None:
                expected_process = self.git(
                    "diff",
                    "--name-only",
                    reconstructed_tree,
                    C0003_CODE_SHA,
                    check=False,
                )
                if expected_process.returncode:
                    self.problems.add(
                        self.relative(ledger_path),
                        "cannot diff reconstructed R0005 postimage tree against "
                        f"C0003: {expected_process.stderr.strip() or expected_process.stdout.strip()}",
                    )
                else:
                    expected_diff = set(expected_process.stdout.splitlines())
            merge_diff = set(
                self.git(
                    "diff", "--name-only", R03_MERGE_SHA, C0003_CODE_SHA
                ).stdout.splitlines()
            )
            delivery_diff = set(
                self.git(
                    "diff", "--name-only", C0002_CODE_SHA, R03_DELIVERY_SHA
                ).stdout.splitlines()
            )
            if reconstructed_tree is not None:
                self.problems.require(
                    len(expected_diff) == 27
                    and expected_diff == deviation_paths | extra_paths,
                    self.relative(ledger_path),
                    "expected-postimage diff must be exactly six request deviations plus 21 extras",
                )
            self.problems.require(
                len(merge_diff) == 142
                and merge_diff == request_paths | extra_paths,
                self.relative(ledger_path),
                "merge-to-integration diff must be exactly 121 request paths plus 21 extras",
            )
            self.problems.require(
                len(delivery_diff) == 2254
                and immutable_delivery == delivery_diff - extra_paths,
                self.relative(ledger_path),
                "immutable-delivery category must equal the delivery diff minus its three bounded follow-ups",
            )
        else:
            self.problems.add(self.relative(ledger_path), "missing C0003 integrator ledger")

        milestones = self.phase.get("milestones")
        milestone_map = {
            item.get("milestone_id"): item
            for item in milestones
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        } if isinstance(milestones, list) else {}
        for milestone_id in C0003_MILESTONES:
            milestone = milestone_map.get(milestone_id)
            expected_checkpoint = (
                SUCCESSOR_CHECKPOINT_ID
                if milestone_id in SUCCESSOR_MILESTONES
                else C0002_CHECKPOINT_ID
                if milestone_id in {"M11", "M12"}
                else C0003_CHECKPOINT_ID
            )
            self.problems.require(
                isinstance(milestone, dict)
                and milestone.get("status") == "accepted"
                and milestone.get("accepted_checkpoint_id") == expected_checkpoint,
                f"phase.json.milestones[{milestone_id}]",
                f"must be accepted at exact checkpoint {expected_checkpoint}",
            )
        if self.current_checkpoint_id == C0003_CHECKPOINT_ID:
            for milestone_id in ("M05", "M06"):
                milestone = milestone_map.get(milestone_id, {})
                self.problems.require(
                    milestone.get("status") == "ready"
                    and milestone.get("accepted_checkpoint_id") is None,
                    f"phase.json.milestones[{milestone_id}]",
                    "must become dependency-ready without activation or acceptance",
                )
            self.problems.require(
                milestone_map.get("M07", {}).get("status") == "planned"
                and milestone_map.get("M07", {}).get("accepted_checkpoint_id") is None,
                "phase.json.milestones[M07]",
                "R07 must remain planned and unaccepted at C0003",
            )
        self.validate_c0003_history()

    def validate_c0003_history(self) -> None:
        expected_vectors = (
            (R03_DELIVERY_SHA, [R03_DELIVERY_SHA, C0002_CODE_SHA], "delivery"),
            (
                R03_MERGE_SHA,
                [R03_MERGE_SHA, R03_ROUTE_SHA, R03_DELIVERY_SHA],
                "true merge",
            ),
            (C0003_CODE_SHA, [C0003_CODE_SHA, R03_MERGE_SHA], "integration"),
        )
        for commit, expected, label in expected_vectors:
            process = self.git("rev-list", "--parents", "-n", "1", commit, check=False)
            actual = process.stdout.strip().split()
            self.problems.require(
                process.returncode == 0 and actual == expected,
                f"C0003 R03 {label} ancestry",
                f"expected exact commit/parent vector {expected}, found {actual}",
            )
        reconstructed_tree = self.reconstruct_r03_expected_tree()
        if reconstructed_tree is not None:
            self.problems.require(
                reconstructed_tree == R03_EXPECTED_POSTIMAGE_TREE,
                "C0003 R0005 replay tree",
                f"expected exact reconstructed tree {R03_EXPECTED_POSTIMAGE_TREE}",
            )

    def validate_c0004_checkpoint(self) -> None:
        """Validate the exact R05/R06 acceptance checkpoint and 111-path audit."""

        context = "checkpoints/C0004.json"
        path = self.phase_dir / "checkpoints/C0004.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": C0004_CHECKPOINT_ID,
            "parent_checkpoint_id": C0003_CHECKPOINT_ID,
            "commit_sha": C0004_CODE_SHA,
            "accepted_at": C0004_ACCEPTED_AT,
            "accepted_by": "primary-human",
            "milestones_satisfied": C0004_MILESTONES,
            "unblocks": [],
            "metrics": C0004_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        if path.is_file():
            self.problems.require(
                sha256_path(path) == C0004_CHECKPOINT_SHA256,
                context,
                f"checkpoint record must hash to {C0004_CHECKPOINT_SHA256}",
            )

        inventory = self.artifact(checkpoint.get("inventory"), f"{context}.inventory")
        inventory_path = self.phase_dir / "checkpoints/C0004-inventory.tsv"
        expected_inventory = self.relative(inventory_path)
        inventory_rows: list[dict[str, str]] = []
        if inventory is not None:
            self.problems.require(
                inventory == Artifact(expected_inventory, C0004_INVENTORY_SHA256),
                f"{context}.inventory",
                "must pin the exact C0004 inventory",
            )
            _, inventory_rows = self.read_tsv(
                inventory_path, expected_inventory, SCOPE_HEADER
            )
            paths = [row.get("path", "") for row in inventory_rows]
            dispositions = Counter(
                row.get("phase_scope", "") for row in inventory_rows
            )
            debt_rows = sum(
                row.get("debt_flags", "") != "-" for row in inventory_rows
            )
            waves = Counter(
                row.get("wave_id", "")
                for row in inventory_rows
                if row.get("phase_scope") == "in_scope"
            )
            self.problems.require(
                len(inventory_rows) == C0004_METRICS["production_modules"]
                and len(paths) == len(set(paths))
                and paths == sorted(paths)
                and dispositions == C0004_INVENTORY_DISPOSITIONS
                and debt_rows == C0004_INVENTORY_DEBT_ROWS
                and waves == C0004_IN_SCOPE_WAVES,
                expected_inventory,
                "must be the exact sorted 2,766-row C0004 inventory with reviewed "
                "2,555/211 disposition, 200-row debt, and in-scope wave census",
            )
            _, previous_rows = self.read_tsv(
                self.phase_dir / "checkpoints/C0003-inventory.tsv",
                self.relative(self.phase_dir / "checkpoints/C0003-inventory.tsv"),
                SCOPE_HEADER,
            )
            previous_paths = {row.get("path", "") for row in previous_rows}
            inventory_by_path = {
                row.get("path", ""): row for row in inventory_rows
            }
            new_paths = set(inventory_by_path) - previous_paths
            self.problems.require(
                previous_paths <= set(inventory_by_path)
                and len(new_paths) == 76,
                expected_inventory,
                "must retain every C0003 production path and add exactly 76 modules",
            )
            completed_shape = {
                "phase_scope": "already_complete",
                "debt_flags": "-",
                "lane_id": "-",
                "wave_id": "-",
            }
            for new_path in sorted(new_paths):
                row = inventory_by_path[new_path]
                self.problems.require(
                    all(row.get(key) == value for key, value in completed_shape.items()),
                    f"{expected_inventory}[{new_path}]",
                    "new R05/R06 production modules must be debt-free and already complete",
                )
            selector_paths: set[str] = set()
            for wave in ("R05", "R06"):
                selector_path = self.phase_dir / f"selectors/{wave}.tsv"
                _, selector_rows = self.read_tsv(
                    selector_path,
                    self.relative(selector_path),
                    SELECTOR_HEADER,
                )
                selector_paths.update(row.get("path", "") for row in selector_rows)
            self.problems.require(
                len(selector_paths) == 123,
                expected_inventory,
                "must retain the exact 123 unique R05/R06 selector owners",
            )
            for selected_path in sorted(selector_paths):
                row = inventory_by_path.get(selected_path, {})
                self.problems.require(
                    all(row.get(key) == value for key, value in completed_shape.items()),
                    f"{expected_inventory}[{selected_path}]",
                    "accepted R05/R06 owners must be debt-free and outside active scope",
                )
            self.problems.require(
                all(row.get("wave_id") not in {"R05", "R06"} for row in inventory_rows),
                expected_inventory,
                "accepted R05/R06 may leave no C0004 inventory row in R05/R06 scope",
            )
            code_blobs = self.git_tree_blobs(C0004_CODE_SHA)
            for row in inventory_rows:
                row_path = row.get("path", "")
                self.problems.require(
                    row.get("base_blob_oid") == code_blobs.get(row_path),
                    f"{expected_inventory}[{row_path}].base_blob_oid",
                    "must pin the exact C0004 Git blob",
                )
            if inventory_path.is_file():
                self.problems.require(
                    sha256_path(inventory_path) == C0004_INVENTORY_SHA256,
                    expected_inventory,
                    "C0004 inventory content drifted",
                )

        baseline = checkpoint.get("combined_baseline")
        if not isinstance(baseline, dict):
            self.problems.add(f"{context}.combined_baseline", "expected an object")
        else:
            expected_command = (
                "python -B tools/architecture/generate_baseline.py --output-dir "
                "docs/architecture/phases/2026-08-repository-reorganization-"
                "completion/baselines --name C0004-combined "
                "--keep-dependency-tsv benchmark-results/C0004-combined.tsv"
            )
            self.problems.require(
                baseline.get("format_version") == 2
                and baseline.get("generation_command") == expected_command,
                f"{context}.combined_baseline",
                "requires the exact deterministic C0004 format-2 generation command",
            )
            refs = (
                (
                    "artifact",
                    self.phase_dir / "baselines/C0004-combined.json",
                    C0004_COMBINED_BASELINE_SHA256,
                ),
                (
                    "summary_artifact",
                    self.phase_dir / "baselines/C0004-combined.md",
                    C0004_COMBINED_SUMMARY_SHA256,
                ),
            )
            for key, artifact_path, digest in refs:
                ref = self.artifact(
                    baseline.get(key), f"{context}.combined_baseline.{key}"
                )
                expected_path = self.relative(artifact_path)
                self.problems.require(
                    ref == Artifact(expected_path, digest),
                    f"{context}.combined_baseline.{key}",
                    f"must pin {expected_path} at {digest}",
                )
                if artifact_path.is_file():
                    self.problems.require(
                        sha256_path(artifact_path) == digest,
                        expected_path,
                        "C0004 baseline artifact content drifted",
                    )
            artifact_path = self.phase_dir / "baselines/C0004-combined.json"
            document = self.read_json(
                artifact_path, self.relative(artifact_path)
            )
            metadata = document.get("metadata") if isinstance(document, dict) else None
            source = document.get("source") if isinstance(document, dict) else None
            tier_audit = source.get("tier_audit") if isinstance(source, dict) else None
            self.problems.require(
                isinstance(metadata, dict)
                and metadata.get("commit") == C0004_CODE_SHA
                and metadata.get("library_source_clean") is True
                and metadata.get("library_source_dirty_paths") == [],
                f"{context}.combined_baseline.artifact.metadata",
                "must record the exact clean C0004 code commit",
            )
            self.problems.require(
                isinstance(source, dict)
                and all(source.get(key) == value for key, value in C0004_SOURCE_FACTS.items()),
                f"{context}.combined_baseline.artifact.source",
                f"source totals must equal exact C0004 measurements {C0004_SOURCE_FACTS}",
            )
            self.problems.require(
                isinstance(tier_audit, dict)
                and tier_audit.get("module_counts_by_tier") == C0004_TIER_COUNTS
                and tier_audit.get("unclassified_module_count") == 191
                and tier_audit.get("classified_module_count") == 2575,
                f"{context}.combined_baseline.artifact.source.tier_audit",
                "tier counts must equal the exact C0004 2,575/191 classification",
            )
        gates = checkpoint.get("gates")
        evidence_path = self.phase_dir / "checkpoints/C0004-gates.md"
        expected_evidence = self.relative(evidence_path)
        if not isinstance(gates, list):
            self.problems.add(f"{context}.gates", "expected a list")
        else:
            ids = [gate.get("gate_id") for gate in gates if isinstance(gate, dict)]
            self.problems.require(
                len(ids) == len(gates) == len(SUCCESSOR_GATE_IDS)
                and len(ids) == len(set(ids))
                and set(ids) == SUCCESSOR_GATE_IDS,
                f"{context}.gates",
                "must contain every and only the 12 exact C0004 acceptance gates",
            )
            for index, gate in enumerate(gates):
                if not isinstance(gate, dict):
                    self.problems.add(f"{context}.gates[{index}]", "expected an object")
                    continue
                gate_id = gate.get("gate_id", index)
                gate_ref = self.artifact(
                    gate.get("evidence"), f"{context}.gates[{gate_id}].evidence"
                )
                self.problems.require(
                    gate.get("status") == "PASS"
                    and gate.get("commit_sha") == C0004_CODE_SHA
                    and gate_ref == Artifact(expected_evidence, C0004_GATES_SHA256),
                    f"{context}.gates[{gate_id}]",
                    "must record PASS at exact C0004 with exact gate evidence",
                )
        self.problems.require(
            evidence_path.is_file()
            and sha256_path(evidence_path) == C0004_GATES_SHA256,
            expected_evidence,
            "C0004 gate report content drifted",
        )
        if evidence_path.is_file():
            try:
                gate_text = evidence_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(expected_evidence, f"cannot read gate report: {error}")
            else:
                for token in (
                    C0004_CODE_SHA,
                    C0004_ACCEPTANCE_CONTROL_PARENT_SHA,
                    R05_MERGE_SHA,
                    R06_MERGE_SHA,
                    C0004_RAW_DEPENDENCY_TSV_SHA256,
                    "111",
                    "61",
                    "27",
                ):
                    self.problems.require(
                        token in gate_text,
                        expected_evidence,
                        f"gate report must record exact C0004 fact {token!r}",
                    )

        ledger_path = self.phase_dir / "checkpoints/C0004-integrator-paths.tsv"
        _, ledger = self.read_tsv(
            ledger_path,
            self.relative(ledger_path),
            ("status", "category", "path"),
        )
        ledger_pairs = [(row.get("status", ""), row.get("path", "")) for row in ledger]
        changed_rows: list[tuple[str, str]] = []
        for row in self.git(
            "diff", "--name-status", C0004_ACCEPTANCE_CONTROL_PARENT_SHA, C0004_CODE_SHA
        ).stdout.splitlines():
            fields = row.split("\t")
            if len(fields) == 2:
                changed_rows.append((fields[0], fields[1]))
            else:
                self.problems.add(
                    self.relative(ledger_path),
                    f"integration diff contains unsupported rename/copy row {row!r}",
                )
        ledger_by_category = {
            category: {
                row.get("path", "")
                for row in ledger
                if row.get("category") == category
            }
            for category in C0004_LEDGER_CATEGORY_COUNTS
        }
        predecessor_path = self.root / R0008_PREDECESSOR_POSTIMAGES[0]
        _, predecessor_rows = self.read_tsv(
            predecessor_path,
            self.relative(predecessor_path),
            R0008_MANIFEST_HEADER,
        )
        union_paths = {row.get("path", "") for row in predecessor_rows}
        expected_union = (
            union_paths - set(R0008_UNION_OVERLAP) - set(C0004_AGGREGATE_FOLLOWUPS)
        )
        self.problems.require(
            len(ledger) == 111
            and len({row.get("path", "") for row in ledger}) == 111
            and ledger_pairs == changed_rows
            and Counter(row.get("status", "") for row in ledger)
            == C0004_LEDGER_STATUS_COUNTS
            and Counter(row.get("category", "") for row in ledger)
            == C0004_LEDGER_CATEGORY_COUNTS
            and ledger_path.is_file()
            and sha256_path(ledger_path) == C0004_INTEGRATOR_LEDGER_SHA256,
            self.relative(ledger_path),
            "must exactly ledger the 111-path 106M/5A post-R06 integration range",
        )
        self.problems.require(
            ledger_by_category.get("reviewed_integration_amendment")
            == set(R0008_PATHS)
            and ledger_by_category.get("reviewed_union") == expected_union
            and len(expected_union) == 61
            and ledger_by_category.get("aggregate_followup")
            == set(C0004_AGGREGATE_FOLLOWUPS),
            self.relative(ledger_path),
            "ledger must split exactly into the 27-path amendment, 61 terminal "
            "union postimages, and six aggregate follow-ups",
        )

        milestones = self.phase.get("milestones")
        by_id = {
            item.get("milestone_id"): item
            for item in milestones or []
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        }
        expected_acceptance = {
            "M01": SUCCESSOR_CHECKPOINT_ID,
            "M02": SUCCESSOR_CHECKPOINT_ID,
            "M03": C0003_CHECKPOINT_ID,
            "M05": C0004_CHECKPOINT_ID,
            "M06": C0004_CHECKPOINT_ID,
            "M11": C0002_CHECKPOINT_ID,
            "M12": C0002_CHECKPOINT_ID,
        }
        for milestone_id, accepted_checkpoint in expected_acceptance.items():
            milestone = by_id.get(milestone_id, {})
            self.problems.require(
                milestone.get("status") == "accepted"
                and milestone.get("accepted_checkpoint_id") == accepted_checkpoint,
                f"phase.json.milestones[{milestone_id}]",
                f"must be accepted at exact checkpoint {accepted_checkpoint}",
            )
        if self.current_checkpoint_id == C0004_CHECKPOINT_ID:
            for milestone_id in ("M04", "M08"):
                milestone = by_id.get(milestone_id, {})
                self.problems.require(
                    milestone.get("status") == "ready"
                    and milestone.get("accepted_checkpoint_id") is None,
                    f"phase.json.milestones[{milestone_id}]",
                    "must be dependency-ready and unaccepted at C0004",
                )
            for milestone_id in ("M07", "M09", "M10", "M13"):
                milestone = by_id.get(milestone_id, {})
                self.problems.require(
                    milestone.get("status") == "planned"
                    and milestone.get("accepted_checkpoint_id") is None,
                    f"phase.json.milestones[{milestone_id}]",
                    "must remain planned and unaccepted at C0004",
                )
        self.validate_c0004_history()

    def validate_c0004_history(self) -> None:
        """Require the exact two worker merges and single-parent integration."""

        for commit, parents, label in (
            (R05_MERGE_SHA, R05_MERGE_PARENTS, "R05 merge"),
            (R06_MERGE_SHA, R06_MERGE_PARENTS, "R06 merge"),
            (
                C0004_CODE_SHA,
                (C0004_ACCEPTANCE_CONTROL_PARENT_SHA,),
                "integration",
            ),
        ):
            process = self.git("rev-list", "--parents", "-n", "1", commit, check=False)
            actual = process.stdout.strip().split()
            expected = [commit, *parents]
            self.problems.require(
                process.returncode == 0 and actual == expected,
                f"C0004 {label} ancestry",
                f"expected exact commit/parent vector {expected}, found {actual}",
            )
        for wave in ("R05", "R06"):
            delivery = R05R06_PLANNED_FACTS[wave]["delivery_sha"]
            ancestry = self.git(
                "merge-base", "--is-ancestor", delivery, C0004_CODE_SHA, check=False
            )
            self.problems.require(
                ancestry.returncode == 0,
                f"C0004 {wave} delivery ancestry",
                f"{delivery} must be an ancestor of exact C0004 code {C0004_CODE_SHA}",
            )

    def validate_c0005_prepared_evidence(
        self, *, candidate_gates: bool = True
    ) -> None:
        """Validate authority-neutral C0005 evidence at exact integrated code."""

        baseline_path = self.phase_dir / "baselines/C0005-combined.json"
        summary_path = self.phase_dir / "baselines/C0005-combined.md"
        inventory_path = self.phase_dir / "checkpoints/C0005-inventory.tsv"
        ledger_path = self.phase_dir / "checkpoints/C0005-integrator-paths.tsv"
        gates_path = self.phase_dir / "checkpoints/C0005-gates.md"
        for path, digest in (
            (baseline_path, C0005_COMBINED_BASELINE_SHA256),
            (summary_path, C0005_COMBINED_SUMMARY_SHA256),
            (inventory_path, C0005_INVENTORY_SHA256),
            (ledger_path, C0005_INTEGRATOR_LEDGER_SHA256),
        ):
            self.problems.require(
                path.is_file() and sha256_path(path) == digest,
                self.relative(path),
                f"prepared C0005 artifact must hash to {digest}",
            )

        baseline = self.read_json(baseline_path, self.relative(baseline_path))
        metadata = baseline.get("metadata") if isinstance(baseline, dict) else None
        source = baseline.get("source") if isinstance(baseline, dict) else None
        tiers = source.get("tier_audit") if isinstance(source, dict) else None
        declarations = baseline.get("declarations") if isinstance(baseline, dict) else None
        self.problems.require(
            isinstance(metadata, dict)
            and metadata.get("commit") == C0005_CODE_SHA
            and metadata.get("branch") == "main"
            and metadata.get("library_source_clean") is True
            and metadata.get("library_source_dirty_paths") == [],
            "C0005 baseline.metadata",
            "must record exact clean C0005 main code",
        )
        self.problems.require(
            isinstance(source, dict)
            and all(source.get(key) == value for key, value in C0005_SOURCE_FACTS.items()),
            "C0005 baseline.source",
            f"source totals must equal {C0005_SOURCE_FACTS}",
        )
        self.problems.require(
            isinstance(tiers, dict)
            and tiers.get("module_counts_by_tier") == C0005_TIER_COUNTS
            and tiers.get("classified_module_count") == 2685
            and tiers.get("unclassified_module_count") == 133,
            "C0005 baseline.tier_audit",
            "must reproduce 2,685 classified, 133 unclassified, and zero mixed",
        )
        self.problems.require(
            isinstance(declarations, dict)
            and declarations.get("format_version") == 2
            and declarations.get("module_count") == 1696
            and declarations.get("declaration_count") == 56903,
            "C0005 baseline.declarations",
            "must retain exact format-2 declaration totals",
        )

        _, inventory = self.read_tsv(
            inventory_path, self.relative(inventory_path), SCOPE_HEADER
        )
        paths = [row.get("path", "") for row in inventory]
        dispositions = Counter(row.get("phase_scope", "") for row in inventory)
        waves = Counter(
            row.get("wave_id", "")
            for row in inventory
            if row.get("phase_scope") == "in_scope"
        )
        debt_rows = sum(row.get("debt_flags") != "-" for row in inventory)
        self.problems.require(
            len(inventory) == 2818
            and len(paths) == len(set(paths))
            and paths == sorted(paths)
            and dispositions == C0005_INVENTORY_DISPOSITIONS
            and waves == C0005_IN_SCOPE_WAVES
            and debt_rows == C0005_INVENTORY_DEBT_ROWS,
            self.relative(inventory_path),
            "must be exact 2,818-row 2,671/147 inventory with 136 debt rows",
        )
        _, previous = self.read_tsv(
            self.phase_dir / "checkpoints/C0004-inventory.tsv",
            self.relative(self.phase_dir / "checkpoints/C0004-inventory.tsv"),
            SCOPE_HEADER,
        )
        previous_paths = {row.get("path", "") for row in previous}
        by_path = {row.get("path", ""): row for row in inventory}
        new_paths = set(by_path) - previous_paths
        complete = {
            "phase_scope": "already_complete",
            "debt_flags": "-",
            "lane_id": "-",
            "wave_id": "-",
        }
        self.problems.require(
            previous_paths <= set(by_path) and len(new_paths) == 52,
            self.relative(inventory_path),
            "must retain C0004 and add exactly 52 modules",
        )
        selected: set[str] = set()
        for wave in ("R04", "R08"):
            selector_path = self.phase_dir / f"selectors/{wave}.tsv"
            _, rows = self.read_tsv(
                selector_path, self.relative(selector_path), SELECTOR_HEADER
            )
            selected.update(row.get("path", "") for row in rows)
        self.problems.require(
            len(selected) == 64,
            self.relative(inventory_path),
            "must retain exactly 64 distinct R04/R08 owners",
        )
        for checked_path in sorted(new_paths | selected):
            row = by_path.get(checked_path, {})
            self.problems.require(
                all(row.get(key) == value for key, value in complete.items()),
                f"{self.relative(inventory_path)}[{checked_path}]",
                "R04/R08 output and owner rows must be debt-free and complete",
            )
        code_blobs = self.git_tree_blobs(C0005_CODE_SHA)
        for row in inventory:
            row_path = row.get("path", "")
            self.problems.require(
                row.get("module") == module_from_path(row_path)
                and row.get("base_blob_oid") == code_blobs.get(row_path),
                f"{self.relative(inventory_path)}[{row_path}]",
                "must pin exact C0005 module identity and Git blob",
            )

        _, ledger = self.read_tsv(
            ledger_path, self.relative(ledger_path), ("status", "category", "path")
        )
        changed_rows = []
        for line in self.git(
            "diff", "--name-status", C0005_R08_MERGE_SHA, C0005_CODE_SHA
        ).stdout.splitlines():
            fields = line.split("\t")
            if len(fields) == 2:
                changed_rows.append((fields[0], fields[1]))
            else:
                self.problems.add(self.relative(ledger_path), f"rename/copy row {line!r}")
        ledger_pairs = [(row.get("status", ""), row.get("path", "")) for row in ledger]
        self.problems.require(
            len(ledger) == 45
            and len({row.get("path", "") for row in ledger}) == 45
            and ledger_pairs == changed_rows
            and Counter(row.get("status", "") for row in ledger)
            == C0005_LEDGER_STATUS_COUNTS
            and Counter(row.get("category", "") for row in ledger)
            == C0005_LEDGER_CATEGORY_COUNTS,
            self.relative(ledger_path),
            "must exactly ledger the 45-path 44M/1A integration range",
        )
        if candidate_gates:
            self.problems.require(
                gates_path.is_file()
                and sha256_path(gates_path) == C0005_CANDIDATE_GATES_SHA256,
                self.relative(gates_path),
                "prepared candidate gate report must retain exact SHA-256 "
                f"{C0005_CANDIDATE_GATES_SHA256}",
            )
            try:
                gate_text = gates_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(self.relative(gates_path), f"cannot read: {error}")
            else:
                for token in (
                    "Acceptance status: **pending primary-human control**",
                    C0005_CODE_SHA,
                    C0005_R04_MERGE_SHA,
                    C0005_R08_MERGE_SHA,
                    C0005_UNION_INTEGRATION_SHA,
                    C0005_COMBINED_BASELINE_SHA256,
                    C0005_COMBINED_SUMMARY_SHA256,
                    C0005_INVENTORY_SHA256,
                    C0005_INTEGRATOR_LEDGER_SHA256,
                    C0005_RAW_DEPENDENCY_TSV_SHA256,
                    "R07 remains blocked",
                ):
                    self.problems.require(
                        token in gate_text,
                        self.relative(gates_path),
                        f"candidate report must record {token!r}",
                    )
        self.validate_c0005_history()

    def validate_c0008_checkpoint(self) -> None:
        """Validate the primary-human C0008 acceptance of the M13/I01 wave."""

        context = "checkpoints/C0008.json"
        path = self.phase_dir / "checkpoints/C0008.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        expected_keys = {
            "accepted_at", "accepted_by", "checkpoint_id", "combined_baseline",
            "commit_sha", "gates", "inventory", "metrics", "milestones_satisfied",
            "parent_checkpoint_id", "phase_id", "record_kind", "schema_version",
            "unblocks",
        }
        self.problems.require(
            set(checkpoint) == expected_keys,
            context,
            f"checkpoint keys must be exactly {sorted(expected_keys)}",
        )
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": C0008_CHECKPOINT_ID,
            "parent_checkpoint_id": C0008_PARENT_CHECKPOINT_ID,
            "commit_sha": C0008_CODE_SHA,
            "accepted_by": "primary-human",
            "milestones_satisfied": C0008_MILESTONES,
            "unblocks": [],
            "metrics": C0008_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        accepted_at = checkpoint.get("accepted_at")
        self.problems.require(
            isinstance(accepted_at, str)
            and RFC3339_RE.fullmatch(accepted_at) is not None,
            f"{context}.accepted_at",
            "primary-human acceptance requires an RFC3339 timestamp",
        )

        # Gate census, including the explicit test contract.
        gate_failures = validate_c0008_gate_records(checkpoint.get("gates"))
        for failure in gate_failures:
            self.problems.add(f"{context}.gates", failure)

        # Generated evidence pins.
        baseline_path = self.phase_dir / "baselines/C0008-combined.json"
        summary_path = self.phase_dir / "baselines/C0008-combined.md"
        inventory_path = self.phase_dir / "checkpoints/C0008-inventory.tsv"
        ledger_path = self.phase_dir / "checkpoints/C0008-integration-paths.tsv"
        gates_path = self.phase_dir / "checkpoints/C0008-gates.md"
        for artifact_path, digest in (
            (baseline_path, C0008_COMBINED_BASELINE_SHA256),
            (summary_path, C0008_COMBINED_SUMMARY_SHA256),
            (inventory_path, C0008_INVENTORY_SHA256),
            (ledger_path, C0008_INTEGRATION_LEDGER_SHA256),
            (gates_path, C0008_GATES_SHA256),
        ):
            self.problems.require(
                artifact_path.is_file() and sha256_path(artifact_path) == digest,
                self.relative(artifact_path),
                f"accepted C0008 artifact must hash to {digest}",
            )
        baseline = self.read_json(baseline_path, self.relative(baseline_path))
        metadata = baseline.get("metadata") if isinstance(baseline, dict) else None
        source = baseline.get("source") if isinstance(baseline, dict) else None
        tiers = source.get("tier_audit") if isinstance(source, dict) else None
        declarations = (
            baseline.get("declarations") if isinstance(baseline, dict) else None
        )
        self.problems.require(
            isinstance(metadata, dict)
            and metadata.get("commit") == C0008_CODE_SHA
            and metadata.get("branch") == "main"
            and metadata.get("library_source_clean") is True
            and metadata.get("library_source_dirty_paths") == [],
            "C0008 baseline.metadata",
            "must record exact clean C0008 main code",
        )
        self.problems.require(
            isinstance(source, dict)
            and all(
                source.get(key) == value
                for key, value in C0008_SOURCE_FACTS.items()
            ),
            "C0008 baseline.source",
            f"source totals must equal {C0008_SOURCE_FACTS}",
        )
        self.problems.require(
            isinstance(tiers, dict)
            and tiers.get("module_counts_by_tier") == C0008_TIER_COUNTS
            and tiers.get("classified_module_count") == 2928,
            "C0008 baseline.tier_audit",
            "must reproduce 2,928 classified modules with zero mixed and the "
            "exact post-I01 role census",
        )
        self.problems.require(
            isinstance(declarations, dict)
            and declarations.get("format_version") == 2
            and declarations.get("module_count") == C0008_DECLARATION_MODULE_COUNT
            and declarations.get("declaration_count") == C0008_DECLARATION_COUNT,
            "C0008 baseline.declarations",
            "the I01 wave is declaration-preserving: format-2 totals must equal "
            "the exact C0007 figures",
        )

        # The changed-path ledger from the C0007 code commit to this checkpoint.
        _, ledger = self.read_tsv(
            ledger_path,
            self.relative(ledger_path),
            ("status", "category", "path"),
        )
        self.problems.require(
            len(ledger) == C0008_INTEGRATION_LEDGER_ROWS,
            self.relative(ledger_path),
            f"expected {C0008_INTEGRATION_LEDGER_ROWS} changed-path rows, "
            f"found {len(ledger)}",
        )
        paths = [row.get("path", "") for row in ledger]
        self.problems.require(
            paths == sorted(paths) and len(set(paths)) == len(paths),
            self.relative(ledger_path),
            "changed-path rows must be sorted and unique",
        )
        self.problems.require(
            any(
                row.get("category") == "i01_implementation"
                and row.get("path") == C0003_I01_COUNTEREXAMPLE_ROW["path"]
                for row in ledger
            ),
            self.relative(ledger_path),
            "the ledger must attribute the counterexample split to the I01 "
            "implementation landing",
        )

    def validate_c0006_checkpoint(self) -> None:
        """Validate the primary-human C0006 acceptance of the R07 epoch."""

        context = "checkpoints/C0006.json"
        path = self.phase_dir / "checkpoints/C0006.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        expected_keys = {
            "accepted_at", "accepted_by", "checkpoint_id", "combined_baseline",
            "commit_sha", "gates", "inventory", "metrics", "milestones_satisfied",
            "parent_checkpoint_id", "phase_id", "record_kind", "schema_version",
            "unblocks",
        }
        self.problems.require(
            set(checkpoint) == expected_keys,
            context,
            f"checkpoint keys must be exactly {sorted(expected_keys)}",
        )
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": C0006_CHECKPOINT_ID,
            "parent_checkpoint_id": C0005_CHECKPOINT_ID,
            "commit_sha": C0006_CODE_SHA,
            "accepted_by": "primary-human",
            "milestones_satisfied": C0006_MILESTONES,
            "unblocks": [],
            "metrics": C0006_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        accepted_at = checkpoint.get("accepted_at")
        self.problems.require(
            isinstance(accepted_at, str)
            and RFC3339_RE.fullmatch(accepted_at) is not None,
            f"{context}.accepted_at",
            "primary-human acceptance requires an RFC3339 timestamp",
        )

        # Generated evidence pins.
        baseline_path = self.phase_dir / "baselines/C0006-combined.json"
        summary_path = self.phase_dir / "baselines/C0006-combined.md"
        inventory_path = self.phase_dir / "checkpoints/C0006-inventory.tsv"
        ledger_path = self.phase_dir / "checkpoints/C0006-integrator-paths.tsv"
        for artifact_path, digest in (
            (baseline_path, C0006_COMBINED_BASELINE_SHA256),
            (summary_path, C0006_COMBINED_SUMMARY_SHA256),
            (inventory_path, C0006_INVENTORY_SHA256),
            (ledger_path, C0006_INTEGRATOR_LEDGER_SHA256),
        ):
            self.problems.require(
                artifact_path.is_file() and sha256_path(artifact_path) == digest,
                self.relative(artifact_path),
                f"accepted C0006 artifact must hash to {digest}",
            )
        baseline = self.read_json(baseline_path, self.relative(baseline_path))
        metadata = baseline.get("metadata") if isinstance(baseline, dict) else None
        source = baseline.get("source") if isinstance(baseline, dict) else None
        tiers = source.get("tier_audit") if isinstance(source, dict) else None
        declarations = (
            baseline.get("declarations") if isinstance(baseline, dict) else None
        )
        self.problems.require(
            isinstance(metadata, dict)
            and metadata.get("commit") == C0006_CODE_SHA
            and metadata.get("branch") == "main"
            and metadata.get("library_source_clean") is True
            and metadata.get("library_source_dirty_paths") == [],
            "C0006 baseline.metadata",
            "must record exact clean C0006 main code",
        )
        self.problems.require(
            isinstance(source, dict)
            and all(
                source.get(key) == value
                for key, value in C0006_SOURCE_FACTS.items()
            ),
            "C0006 baseline.source",
            f"source totals must equal {C0006_SOURCE_FACTS}",
        )
        self.problems.require(
            isinstance(tiers, dict)
            and tiers.get("module_counts_by_tier") == C0006_TIER_COUNTS
            and tiers.get("classified_module_count") == 2770
            and tiers.get("unclassified_module_count") == 90,
            "C0006 baseline.tier_audit",
            "must reproduce 2,770 classified, 90 unclassified, and zero mixed",
        )
        self.problems.require(
            isinstance(declarations, dict)
            and declarations.get("format_version") == 2
            and declarations.get("module_count")
            == C0006_DECLARATION_MODULE_COUNT
            and declarations.get("declaration_count") == C0006_DECLARATION_COUNT,
            "C0006 baseline.declarations",
            "must retain exact format-2 declaration totals",
        )

        # Inventory census.
        _, inventory = self.read_tsv(
            inventory_path, self.relative(inventory_path), SCOPE_HEADER
        )
        paths = [row.get("path", "") for row in inventory]
        dispositions = Counter(row.get("phase_scope", "") for row in inventory)
        waves = Counter(
            row.get("wave_id", "")
            for row in inventory
            if row.get("phase_scope") == "in_scope"
        )
        debt_rows = sum(row.get("debt_flags") != "-" for row in inventory)
        code_blobs = self.git_tree_blobs(C0006_CODE_SHA)
        blob_mismatches = sum(
            1
            for row in inventory
            if row.get("base_blob_oid") != code_blobs.get(row.get("path", ""))
        )
        self.problems.require(
            len(inventory) == 2860
            and len(paths) == len(set(paths))
            and paths == sorted(paths)
            and dispositions == C0006_INVENTORY_DISPOSITIONS
            and waves == C0006_IN_SCOPE_WAVES
            and debt_rows == C0006_INVENTORY_DEBT_ROWS
            and blob_mismatches == 0,
            self.relative(inventory_path),
            "must be the exact 2,860-row 2,758/102 inventory with 91 debt rows "
            "pinned to the C0006 tree",
        )

        # Integration ledger equals the merge-to-checkpoint range.
        _, ledger = self.read_tsv(
            ledger_path, self.relative(ledger_path), ("status", "category", "path")
        )
        changed_rows = []
        for line in self.git(
            "diff", "--name-status", "--no-renames", R07_MERGE_SHA, C0006_CODE_SHA
        ).stdout.splitlines():
            fields = line.split("\t")
            if len(fields) == 2:
                changed_rows.append((fields[0], fields[1]))
            else:
                self.problems.add(
                    self.relative(ledger_path), f"rename/copy row {line!r}"
                )
        ledger_pairs = [(row.get("status", ""), row.get("path", "")) for row in ledger]
        self.problems.require(
            len(ledger) == 57
            and len({row.get("path", "") for row in ledger}) == 57
            and ledger_pairs == changed_rows
            and Counter(row.get("status", "") for row in ledger)
            == C0006_LEDGER_STATUS_COUNTS
            and Counter(row.get("category", "") for row in ledger)
            == C0006_LEDGER_CATEGORY_COUNTS,
            self.relative(ledger_path),
            "must exactly ledger the 57-path 42M/15A integration range",
        )

        # Gates.
        gates_path = self.phase_dir / "checkpoints/C0006-gates.md"
        final_gates_sha256 = (
            sha256_path(gates_path) if gates_path.is_file() else "<missing>"
        )
        try:
            final_gate_text = gates_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(self.relative(gates_path), f"cannot read: {error}")
        else:
            validate_c0006_final_gate_text(
                final_gate_text,
                str(accepted_at),
                self.problems,
                context=self.relative(gates_path),
            )
        gates = checkpoint.get("gates")
        if not isinstance(gates, list):
            self.problems.add(f"{context}.gates", "expected a list")
        else:
            gate_ids = [gate.get("gate_id") for gate in gates if isinstance(gate, dict)]
            self.problems.require(
                len(gates) == len(gate_ids) == len(SUCCESSOR_GATE_IDS)
                and len(gate_ids) == len(set(gate_ids))
                and set(gate_ids) == SUCCESSOR_GATE_IDS,
                f"{context}.gates",
                "must contain every and only the 12 acceptance gates",
            )
            for index, gate in enumerate(gates):
                if not isinstance(gate, dict):
                    self.problems.add(f"{context}.gates[{index}]", "expected an object")
                    continue
                gate_id = gate.get("gate_id", index)
                evidence = gate.get("evidence")
                self.problems.require(
                    gate.get("status") == "PASS"
                    and gate.get("commit_sha") == C0006_CODE_SHA
                    and gate.get("executor_id") in {"primary-human", "github-actions"}
                    and evidence
                    == {
                        "path": (
                            f"{DEFAULT_PHASE_DIR.as_posix()}"
                            "/checkpoints/C0006-gates.md"
                        ),
                        "sha256": final_gates_sha256,
                    },
                    f"{context}.gates[{gate_id}]",
                    "gate must PASS at exact C0006 and link the final report digest",
                )
        self.problems.require(
            checkpoint.get("inventory")
            == {
                "path": (
                    f"{DEFAULT_PHASE_DIR.as_posix()}"
                    "/checkpoints/C0006-inventory.tsv"
                ),
                "sha256": C0006_INVENTORY_SHA256,
            },
            f"{context}.inventory",
            "must pin exact accepted C0006 inventory",
        )
        generation_command = (
            "python -B tools/architecture/generate_baseline.py --output-dir "
            f"{DEFAULT_PHASE_DIR.as_posix()}/baselines --name C0006-combined "
            "--keep-dependency-tsv benchmark-results/C0006-combined.tsv"
        )
        self.problems.require(
            checkpoint.get("combined_baseline")
            == {
                "artifact": {
                    "path": (
                        f"{DEFAULT_PHASE_DIR.as_posix()}"
                        "/baselines/C0006-combined.json"
                    ),
                    "sha256": C0006_COMBINED_BASELINE_SHA256,
                },
                "format_version": 2,
                "generation_command": generation_command,
                "summary_artifact": {
                    "path": (
                        f"{DEFAULT_PHASE_DIR.as_posix()}"
                        "/baselines/C0006-combined.md"
                    ),
                    "sha256": C0006_COMBINED_SUMMARY_SHA256,
                },
            },
            f"{context}.combined_baseline",
            "must pin exact generated format-2 baseline",
        )

        # Narratives.
        for narrative in C0006_ACCEPTANCE_NARRATIVE_PATHS:
            narrative_path = self.root / narrative
            try:
                narrative_text = narrative_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(
                    narrative, f"cannot read acceptance narrative: {error}"
                )
                continue
            validate_c0006_acceptance_narrative(
                narrative_text,
                self.problems,
                context=narrative,
            )

        # R0011 resolution time must equal acceptance time.
        request = self.read_json(
            self.phase_dir / "requests/R0011.json", f"{context}.R0011"
        )
        resolution = request.get("resolution") if isinstance(request, dict) else None
        resolved_at = (
            resolution.get("resolved_at") if isinstance(resolution, dict) else None
        )
        self.problems.require(
            resolved_at == accepted_at,
            f"{context}.accepted_at",
            "R0011 resolution time must equal checkpoint acceptance time",
        )

    def validate_c0005_checkpoint(self) -> None:
        """Validate future primary-human acceptance without inventing its time."""

        self.validate_c0005_prepared_evidence(candidate_gates=False)
        context = "checkpoints/C0005.json"
        path = self.phase_dir / "checkpoints/C0005.json"
        checkpoint = self.read_json(path, self.relative(path))
        if checkpoint is None:
            return
        expected_keys = {
            "accepted_at", "accepted_by", "checkpoint_id", "combined_baseline",
            "commit_sha", "gates", "inventory", "metrics", "milestones_satisfied",
            "parent_checkpoint_id", "phase_id", "record_kind", "schema_version",
            "unblocks",
        }
        self.problems.require(
            set(checkpoint) == expected_keys,
            context,
            f"checkpoint keys must be exactly {sorted(expected_keys)}",
        )
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_checkpoint",
            "phase_id": PHASE_ID,
            "checkpoint_id": C0005_CHECKPOINT_ID,
            "parent_checkpoint_id": C0004_CHECKPOINT_ID,
            "commit_sha": C0005_CODE_SHA,
            "accepted_by": "primary-human",
            "milestones_satisfied": C0005_MILESTONES,
            "unblocks": [],
            "metrics": C0005_METRICS,
        }.items():
            self.problems.require(
                checkpoint.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {checkpoint.get(key)!r}",
            )
        accepted_at = checkpoint.get("accepted_at")
        self.problems.require(
            isinstance(accepted_at, str) and RFC3339_RE.fullmatch(accepted_at) is not None,
            f"{context}.accepted_at",
            "primary-human acceptance requires an RFC3339 timestamp",
        )
        acceptance_commit = (
            R07_ACCEPTED_CONTROL_SHA if self.r07_contract is not None else "HEAD"
        )
        acceptance_context = (
            "C0005 immutable acceptance-control commit"
            if self.r07_contract is not None
            else "C0005 acceptance-control commit"
        )
        parent = self.git(
            "show", "-s", "--format=%P", acceptance_commit, check=False
        )
        parents = parent.stdout.split() if parent.returncode == 0 else []
        parent_sha = parents[0] if len(parents) == 1 else ""
        changed = self.git(
            "diff",
            "--name-only",
            "--no-renames",
            C0005_CODE_SHA,
            acceptance_commit,
            "--",
            check=False,
        )
        changed_paths = (
            {normalize_path(line) for line in changed.stdout.splitlines() if line.strip()}
            if changed.returncode == 0
            else set()
        )
        validate_c0005_acceptance_commit_shape(
            parent_sha,
            changed_paths,
            self.problems,
            context=acceptance_context,
        )
        gates_path = self.phase_dir / "checkpoints/C0005-gates.md"
        final_gates_sha256 = (
            sha256_path(gates_path) if gates_path.is_file() else "<missing>"
        )
        try:
            final_gate_text = gates_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(self.relative(gates_path), f"cannot read: {error}")
        else:
            validate_c0005_final_gate_text(
                final_gate_text,
                str(accepted_at),
                self.problems,
                context=self.relative(gates_path),
            )
        for narrative in C0005_ACCEPTANCE_NARRATIVE_PATHS:
            narrative_path = self.root / narrative
            try:
                narrative_text = narrative_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(narrative, f"cannot read acceptance narrative: {error}")
                continue
            validate_c0005_acceptance_narrative(
                narrative_text,
                self.problems,
                context=narrative,
                r07_active=(
                    (self.root / R07_ACTIVATION_PATH).is_file()
                    and narrative in R07_ACTIVATION_CHANGED_PATHS
                ),
                r07_delivered=(
                    self.root / R07_INTEGRATION_AUTHORIZATION_PATH
                ).is_file(),
            )
        self.problems.require(
            checkpoint.get("inventory")
            == {
                "path": f"{DEFAULT_PHASE_DIR.as_posix()}/checkpoints/C0005-inventory.tsv",
                "sha256": C0005_INVENTORY_SHA256,
            },
            f"{context}.inventory",
            "must pin exact prepared C0005 inventory",
        )
        generation_command = (
            "python -B tools/architecture/generate_baseline.py --output-dir "
            "docs/architecture/phases/2026-08-repository-reorganization-completion/"
            "baselines --name C0005-combined --keep-dependency-tsv "
            "benchmark-results/C0005-combined.tsv"
        )
        self.problems.require(
            checkpoint.get("combined_baseline")
            == {
                "artifact": {
                    "path": f"{DEFAULT_PHASE_DIR.as_posix()}/baselines/C0005-combined.json",
                    "sha256": C0005_COMBINED_BASELINE_SHA256,
                },
                "format_version": 2,
                "generation_command": generation_command,
                "summary_artifact": {
                    "path": f"{DEFAULT_PHASE_DIR.as_posix()}/baselines/C0005-combined.md",
                    "sha256": C0005_COMBINED_SUMMARY_SHA256,
                },
            },
            f"{context}.combined_baseline",
            "must pin exact prepared format-2 baseline",
        )
        gates = checkpoint.get("gates")
        if not isinstance(gates, list):
            self.problems.add(f"{context}.gates", "expected a list")
        else:
            gate_ids = [gate.get("gate_id") for gate in gates if isinstance(gate, dict)]
            self.problems.require(
                len(gates) == len(gate_ids) == len(SUCCESSOR_GATE_IDS)
                and len(gate_ids) == len(set(gate_ids))
                and set(gate_ids) == SUCCESSOR_GATE_IDS,
                f"{context}.gates",
                "must contain every and only the 12 acceptance gates",
            )
            for index, gate in enumerate(gates):
                if not isinstance(gate, dict):
                    self.problems.add(f"{context}.gates[{index}]", "expected an object")
                    continue
                gate_id = gate.get("gate_id", index)
                evidence = gate.get("evidence")
                self.problems.require(
                    gate.get("status") == "PASS"
                    and gate.get("commit_sha") == C0005_CODE_SHA
                    and gate.get("executor_id") in {"primary-human", "github-actions"}
                    and evidence
                    == {
                        "path": f"{DEFAULT_PHASE_DIR.as_posix()}/checkpoints/C0005-gates.md",
                        "sha256": final_gates_sha256,
                    },
                    f"{context}.gates[{gate_id}]",
                    "gate must PASS at exact C0005 and link the final report digest",
                )

        milestones = self.phase.get("milestones")
        by_id = {
            item.get("milestone_id"): item
            for item in milestones or []
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        }
        expected_acceptance = {
            "M01": SUCCESSOR_CHECKPOINT_ID,
            "M02": SUCCESSOR_CHECKPOINT_ID,
            "M03": C0003_CHECKPOINT_ID,
            "M04": C0005_CHECKPOINT_ID,
            "M05": C0004_CHECKPOINT_ID,
            "M06": C0004_CHECKPOINT_ID,
            "M08": C0005_CHECKPOINT_ID,
            "M11": C0002_CHECKPOINT_ID,
            "M12": C0002_CHECKPOINT_ID,
        }
        for milestone_id, accepted_checkpoint in expected_acceptance.items():
            milestone = by_id.get(milestone_id, {})
            self.problems.require(
                milestone.get("status") == "accepted"
                and milestone.get("accepted_checkpoint_id") == accepted_checkpoint,
                f"phase.json.milestones[{milestone_id}]",
                f"must be accepted at {accepted_checkpoint}",
            )
        c0006_accepted = (
            self.phase_dir / "checkpoints/C0006.json"
        ).is_file()
        self.problems.require(
            by_id.get("M07", {}).get("status")
            == ("accepted" if c0006_accepted else "ready")
            and by_id.get("M07", {}).get("accepted_checkpoint_id")
            == (C0006_CHECKPOINT_ID if c0006_accepted else None),
            "phase.json.milestones[M07]",
            "C0005 may make R07 ready; only C0006 acceptance may accept it",
        )
        c0007_accepted = (
            self.phase_dir / "checkpoints/C0007.json"
        ).is_file()
        for milestone_id in ("M09", "M10"):
            milestone = by_id.get(milestone_id, {})
            self.problems.require(
                milestone.get("status")
                == ("accepted" if c0007_accepted else "planned")
                and milestone.get("accepted_checkpoint_id")
                == (C0007_CHECKPOINT_ID if c0007_accepted else None),
                f"phase.json.milestones[{milestone_id}]",
                "only C0007 acceptance may accept the R09/R10 pair",
            )
        # M13/I01 is the phase's last wave milestone: it stays planned across
        # every earlier accepted epoch and is accepted only by the C0008
        # record, exactly as M07 is gated on C0006 and the R09/R10 pair on
        # C0007.
        c0008_accepted = (
            self.phase_dir / "checkpoints/C0008.json"
        ).is_file()
        self.problems.require(
            by_id.get("M13", {}).get("status")
            == ("accepted" if c0008_accepted else "planned")
            and by_id.get("M13", {}).get("accepted_checkpoint_id")
            == (C0008_CHECKPOINT_ID if c0008_accepted else None),
            "phase.json.milestones[M13]",
            "must remain planned and unaccepted before C0008 and accepted at "
            "C0008 once its checkpoint record exists",
        )
        resolution_times: set[str] = set()
        for request_id in ("R0009", "R0010"):
            request = self.read_json(
                self.phase_dir / f"requests/{request_id}.json", f"{context}.{request_id}"
            )
            resolution = request.get("resolution") if isinstance(request, dict) else None
            if isinstance(resolution, dict) and isinstance(resolution.get("resolved_at"), str):
                resolution_times.add(resolution["resolved_at"])
        self.problems.require(
            resolution_times == {accepted_at},
            f"{context}.accepted_at",
            "both request resolution times must equal checkpoint acceptance time",
        )

    def validate_c0005_history(self) -> None:
        """Require exact true merges followed by union and README commits."""

        for commit, parents, label in (
            (C0005_R04_MERGE_SHA, C0005_R04_MERGE_PARENTS, "R04 merge"),
            (C0005_R08_MERGE_SHA, C0005_R08_MERGE_PARENTS, "R08 merge"),
            (C0005_UNION_INTEGRATION_SHA, (C0005_R08_MERGE_SHA,), "union integration"),
            (C0005_CODE_SHA, (C0005_UNION_INTEGRATION_SHA,), "README closeout"),
        ):
            process = self.git("rev-list", "--parents", "-n", "1", commit, check=False)
            actual = process.stdout.strip().split()
            expected = [commit, *parents]
            self.problems.require(
                process.returncode == 0 and actual == expected,
                f"C0005 {label} ancestry",
                f"expected {expected}, found {actual}",
            )
        for wave in ("R04", "R08"):
            delivery = C0005_BRANCH_FACTS[wave]["delivery_sha"]
            ancestry = self.git(
                "merge-base", "--is-ancestor", delivery, C0005_CODE_SHA, check=False
            )
            self.problems.require(
                ancestry.returncode == 0,
                f"C0005 {wave} delivery ancestry",
                f"{delivery} must be an ancestor of {C0005_CODE_SHA}",
            )
        live_ancestry = self.git(
            "merge-base", "--is-ancestor", C0005_CODE_SHA, "HEAD", check=False
        )
        validate_c0005_live_ancestry(
            live_ancestry.returncode,
            self.problems,
            context="C0005 live HEAD ancestry",
        )

    def validate_branches(self) -> None:
        base_paths = self.git_tree_paths(CODE_SHA)
        scope_rules = [PathRule(path, "exact") for path in self.scope_by_path]
        live_rules: dict[str, list[PathRule]] = {}
        statuses: set[str] = set()
        for branch_id, facts in BRANCH_FACTS.items():
            path = self.phase_dir / f"branches/{branch_id}.json"
            branch = self.read_json(path, self.relative(path))
            if branch is None:
                continue
            self.branch_records[branch_id] = branch
            for key, expected in {
                "schema_version": 1,
                "record_kind": "phase_branch",
                "phase_id": PHASE_ID,
                "branch_id": branch_id,
                "lane_id": facts["lane"],
                "wave_id": facts["wave"],
                "branch_name": facts["branch"],
                "owner_id": "primary-human",
                "base_checkpoint_id": CHECKPOINT_ID,
                "base_sha": CODE_SHA,
                "baseline_projection_id": facts["projection"],
            }.items():
                self.problems.require(
                    branch.get(key) == expected,
                    f"{branch_id}.{key}",
                    f"expected {expected!r}, found {branch.get(key)!r}",
                )
            operators = branch.get("operator_ids")
            self.problems.require(
                isinstance(operators, list) and operators == [facts["operator"]],
                f"{branch_id}.operator_ids",
                f"expected exactly [{facts['operator']!r}]",
            )
            status = branch.get("status")
            allowed_statuses = (
                {"delivered"}
                if self.current_checkpoint_id == CHECKPOINT_ID
                else {"retired"}
                if self.current_checkpoint_id
                in {
                    C0003_CHECKPOINT_ID,
                    C0004_CHECKPOINT_ID,
                    C0005_CHECKPOINT_ID,
                    C0006_CHECKPOINT_ID,
                    C0007_CHECKPOINT_ID,
                    C0008_CHECKPOINT_ID,
                }
                else {"accepted", "retired"}
            )
            self.problems.require(
                status in allowed_statuses,
                f"{branch_id}.status",
                f"must be one of {sorted(allowed_statuses)} while current checkpoint is "
                f"{self.current_checkpoint_id}",
            )
            if isinstance(status, str):
                statuses.add(status)
            owned = self.parse_rules(branch.get("owned_paths"), f"{branch_id}.owned_paths")
            actual_owned = {rule.path for rule in owned if rule.match == "exact"}
            self.problems.require(
                len(owned) == len(actual_owned) and actual_owned == facts["paths"],
                f"{branch_id}.owned_paths",
                "must be exact rules for every and only selector path",
            )
            destinations = self.parse_rules(
                branch.get("destination_prefixes"), f"{branch_id}.destination_prefixes"
            )
            if not destinations:
                self.problems.add(f"{branch_id}.destination_prefixes", "must not be empty")
            if any(rule.match != "prefix" for rule in destinations):
                self.problems.add(f"{branch_id}.destination_prefixes", "all destination rules must be prefixes")
            if branch_id == "B0001":
                actual_dest = {rule.path for rule in destinations}
                self.problems.require(
                    actual_dest == R01_DESTINATIONS,
                    f"{branch_id}.destination_prefixes",
                    f"must equal exact reviewed five-prefix set; found {sorted(actual_dest)}",
                )
            forbidden = self.parse_rules(
                branch.get("forbidden_paths"), f"{branch_id}.forbidden_paths"
            )
            self.problems.require(
                PathRule(MATRIX_ALGEBRA, "exact") in forbidden,
                f"{branch_id}.forbidden_paths",
                f"must protect exact {MATRIX_ALGEBRA}",
            )
            delivery = branch.get("delivery")
            delivery_required = status in {"delivered", "accepted", "retired"}
            if not isinstance(delivery, dict):
                self.problems.add(f"{branch_id}.delivery", "expected an object")
            elif delivery_required:
                self.problems.require(
                    delivery.get("commit_sha") == facts["delivery_sha"],
                    f"{branch_id}.delivery.commit_sha",
                    f"expected immutable delivery {facts['delivery_sha']}",
                )
                report = self.artifact(delivery.get("report"), f"{branch_id}.delivery.report")
                scope_evidence = self.artifact(
                    delivery.get("scope_evidence"), f"{branch_id}.delivery.scope_evidence"
                )
                for artifact, key in (
                    (report, "delivery_report"),
                    (scope_evidence, "scope_evidence"),
                ):
                    if artifact is not None:
                        self.problems.require(
                            artifact.path == facts[key]
                            and artifact.sha256 == facts[f"{key}_sha256"],
                            f"{branch_id}.delivery.{key}",
                            f"must exactly hash-pin {facts[key]} at "
                            f"{facts[f'{key}_sha256']}",
                        )
                self.validate_delivery_scope(
                    branch_id, facts, owned, destinations, forbidden
                )
            else:
                self.problems.require(
                    delivery
                    == {"commit_sha": None, "report": None, "scope_evidence": None},
                    f"{branch_id}.delivery",
                    "planned/active state requires an empty delivery record",
                )
            self.validate_branch_lifecycle(branch_id, branch, facts, status)
            evidence = branch.get("refresh", {}).get("evidence") if isinstance(branch.get("refresh"), dict) else None
            if not isinstance(evidence, list):
                self.problems.add(f"{branch_id}.refresh.evidence", "expected hash-pinned evidence list")
            else:
                for index, item in enumerate(evidence):
                    artifact = self.artifact(item, f"{branch_id}.refresh.evidence[{index}]")
                    if artifact is not None:
                        self.branch_evidence[branch_id].append(artifact)
            selector_path = self.phase_dir / f"selectors/{facts['wave']}.tsv"
            _, selector = self.read_tsv(
                selector_path, self.relative(selector_path), SELECTOR_HEADER
            )
            expected_rows = sorted(
                ((module_from_path(item), item) for item in facts["paths"]),
                key=lambda pair: pair[0],
            )
            actual_rows = [(row.get("module", ""), row.get("path", "")) for row in selector]
            self.problems.require(
                actual_rows == expected_rows,
                self.relative(selector_path),
                "selector must contain exact sorted module/path rows",
            )
            for own in owned:
                for shared in self.shared_rules:
                    if own.intersects(shared):
                        self.problems.add(
                            f"{branch_id} owner/shared collision",
                            f"{own.path} intersects {shared.path}",
                        )
            for dest in destinations:
                folded = dest.folded
                occupied = [
                    item for item in base_paths if is_equal_or_child(item.casefold(), folded)
                ]
                if occupied:
                    self.problems.add(
                        f"{branch_id}.destination_prefixes",
                        f"destination {dest.path} is not casefold-vacant at C0000: {occupied[:5]}",
                    )
                for rule in scope_rules + self.shared_rules + forbidden:
                    if dest.intersects(rule):
                        self.problems.add(
                            f"{branch_id}.destination_prefixes",
                            f"destination {dest.path} intersects protected/scope path {rule.path}",
                        )
            live_rules[branch_id] = owned + destinations
        self.problems.require(
            len(statuses) <= 1,
            "branch pair state",
            f"B0001/B0002 must transition together, found statuses {sorted(statuses)}",
        )
        if set(live_rules) == set(BRANCH_FACTS):
            left, right = live_rules["B0001"], live_rules["B0002"]
            for one in left:
                for two in right:
                    if one.intersects(two):
                        self.problems.add(
                            "B0001/B0002 ownership",
                            f"equal-or-ancestor collision {one.path} / {two.path}",
                        )

    def validate_branch_lifecycle(
        self,
        branch_id: str,
        branch: dict[str, Any],
        facts: dict[str, Any],
        status: Any,
    ) -> None:
        integration = branch.get("integration")
        remote_ref = f"refs/heads/{facts['branch']}"
        if self.current_checkpoint_id == CHECKPOINT_ID:
            self.problems.require(
                integration
                == {
                    "method": None,
                    "accepted_checkpoint_id": None,
                    "accepted_sha": None,
                },
                f"{branch_id}.integration",
                "C0000 delivery state requires an exact empty integration record",
            )
            expected_retirement = {
                "remote_ref": remote_ref,
                "rule": "delivery_ancestor_of_green_checkpoint",
                "status": "not_due",
                "retired_at": None,
                "retired_by": None,
                "ancestry_checkpoint_id": None,
            }
            self.problems.require(
                branch.get("retirement") == expected_retirement,
                f"{branch_id}.retirement",
                f"expected exact C0000 retirement state {expected_retirement!r}",
            )
            return

        expected_integration = {
            "method": "merge",
            "accepted_checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
            "accepted_sha": INTEGRATED_CODE_SHA,
        }
        self.problems.require(
            integration == expected_integration,
            f"{branch_id}.integration",
            f"expected exact true-merge integration record {expected_integration!r}",
        )
        retirement = branch.get("retirement")
        if not isinstance(retirement, dict):
            self.problems.add(f"{branch_id}.retirement", "expected an object")
            return
        exact_common = {
            "remote_ref": remote_ref,
            "rule": "delivery_ancestor_of_green_checkpoint",
        }
        for key, expected in exact_common.items():
            self.problems.require(
                retirement.get(key) == expected,
                f"{branch_id}.retirement.{key}",
                f"expected {expected!r}",
            )
        if status == "accepted":
            expected = {
                **exact_common,
                "status": "due",
                "retired_at": None,
                "retired_by": None,
                "ancestry_checkpoint_id": None,
            }
            self.problems.require(
                retirement == expected,
                f"{branch_id}.retirement",
                f"accepted branch must have exact due retirement state {expected!r}",
            )
        elif status == "retired":
            self.problems.require(
                retirement.get("status") == "retired"
                and retirement.get("retired_by") == "primary-human"
                and retirement.get("ancestry_checkpoint_id")
                == SUCCESSOR_CHECKPOINT_ID,
                f"{branch_id}.retirement",
                "retired branch must be retired by primary-human against exact C0001 ancestry",
            )
            retired_at = retirement.get("retired_at")
            self.problems.require(
                isinstance(retired_at, str)
                and RFC3339_RE.fullmatch(retired_at) is not None,
                f"{branch_id}.retirement.retired_at",
                "expected an RFC3339 retirement timestamp with timezone",
            )

    def git_tree_paths(self, revision: str) -> list[str]:
        return sorted(self.git_tree_blobs(revision))

    def git_tree_blobs(self, revision: str) -> dict[str, str]:
        if revision in self._git_tree_blobs:
            return self._git_tree_blobs[revision]
        try:
            output = self.git("ls-tree", "-r", "-z", revision).stdout
        except RuntimeError as error:
            self.problems.add("git tree", str(error))
            self._git_tree_blobs[revision] = {}
            return {}
        blobs: dict[str, str] = {}
        for record in output.split("\0"):
            if not record:
                continue
            try:
                metadata, path = record.split("\t", 1)
                _mode, kind, oid = metadata.split()
            except ValueError:
                self.problems.add("git tree", f"cannot parse ls-tree row {record!r}")
                continue
            if kind == "blob" and SHA1_RE.fullmatch(oid):
                blobs[normalize_path(path)] = oid
        self._git_tree_blobs[revision] = blobs
        return blobs

    def validate_delivery_scope(
        self,
        branch_id: str,
        facts: dict[str, Any],
        owned: list[PathRule],
        destinations: list[PathRule],
        forbidden: list[PathRule],
    ) -> None:
        delivery_sha = facts["delivery_sha"]
        ancestry = self.git(
            "merge-base", "--is-ancestor", CODE_SHA, delivery_sha, check=False
        )
        self.problems.require(
            ancestry.returncode == 0,
            f"{branch_id}.delivery",
            f"immutable delivery {delivery_sha} must descend from {CODE_SHA}",
        )
        try:
            output = self.git(
                "diff",
                "--name-status",
                "--no-renames",
                f"{CODE_SHA}..{delivery_sha}",
            ).stdout
        except RuntimeError as error:
            self.problems.add(f"{branch_id}.delivery scope", str(error))
            return
        rows: list[tuple[str, str]] = []
        for index, line in enumerate(output.splitlines(), 1):
            fields = line.split("\t")
            if len(fields) != 2 or fields[0] not in {"A", "M", "D"}:
                self.problems.add(
                    f"{branch_id}.delivery scope[{index}]",
                    f"malformed no-renames name-status row {line!r}",
                )
                continue
            rows.append((fields[0], normalize_path(fields[1])))
        self.problems.require(
            len(rows) == facts["changed_paths"],
            f"{branch_id}.delivery scope",
            f"expected {facts['changed_paths']} actual paths, found {len(rows)}",
        )
        self.problems.require(
            len({path for _, path in rows}) == len(rows),
            f"{branch_id}.delivery scope",
            "actual diff contains duplicate paths",
        )
        authorized = owned + destinations
        for status, path in rows:
            context = f"{branch_id}.delivery scope[{path}]"
            if not any(rule.matches(path) for rule in authorized):
                self.problems.add(context, "path is outside owner/destination authority")
            if any(rule.matches(path) for rule in forbidden):
                self.problems.add(context, "path is forbidden")
            if any(rule.matches(path) for rule in self.shared_rules):
                self.problems.add(context, "path is integrator-shared")
            parts = set(PurePosixPath(path).parts)
            if (
                parts & GENERATED_PARTS
                or PurePosixPath(path).suffix in GENERATED_SUFFIXES
                or path.startswith(GENERATED_PREFIXES)
            ):
                self.problems.add(context, "path is prohibited generated output")
            if status == "D":
                self.problems.add(context, "delivery may not delete a scoped path")

        evidence_path = self.root / facts["scope_evidence"]
        if branch_id == "B0001":
            try:
                evidence_text = evidence_path.read_text(encoding="utf-8")
            except OSError as error:
                self.problems.add(f"{branch_id}.delivery.scope_evidence", str(error))
            else:
                evidence_rows = re.findall(
                    r"(?m)^- `([AMD])` `([^`]+)`$", evidence_text
                )
                self.problems.require(
                    Counter(evidence_rows) == Counter(rows),
                    f"{branch_id}.delivery.scope_evidence",
                    "worker CHANGED_PATHS ledger must exactly equal the 98-row diff",
                )
        else:
            _, evidence_rows = self.read_tsv(
                evidence_path,
                self.relative(evidence_path),
                DELIVERY_SCOPE_HEADER,
            )
            parsed = [(row.get("status", ""), row.get("path", "")) for row in evidence_rows]
            self.problems.require(
                parsed == rows,
                f"{branch_id}.delivery.scope_evidence",
                "primary-human intake ledger must exactly equal the ordered 145-row diff",
            )
            categories = Counter()
            for status, path in rows:
                if path in R02_PATHS:
                    categories["owners"] += 1
                    if status != "M":
                        self.problems.add(path, "R02 owner must be modified")
                elif path.startswith("NumStabilityTest/Reorganization/R02/"):
                    categories["tests"] += 1
                elif path.startswith("docs/architecture/deliveries/R02/"):
                    categories["evidence"] += 1
                else:
                    categories["destinations"] += 1
                if path not in R02_PATHS and status != "A":
                    self.problems.add(path, "R02 non-owner delivery path must be added")
            expected = Counter(
                {"owners": 28, "destinations": 14, "tests": 63, "evidence": 40}
            )
            self.problems.require(
                categories == expected,
                f"{branch_id}.delivery scope classes",
                f"expected {dict(expected)}, found {dict(categories)}",
            )
            audit_path = self.phase_dir / "reviews/R02-intake-audit.md"
            try:
                audit = audit_path.read_text(encoding="utf-8")
            except OSError as error:
                self.problems.add(self.relative(audit_path), str(error))
            else:
                ledger_digest = sha256_path(evidence_path)
                for token in (
                    delivery_sha,
                    ledger_digest,
                    "113",
                    "145",
                    "28 owners",
                    "14 destinations",
                    "63",
                    "40",
                    "zero paths outside",
                    "142 relocated",
                    "123-row",
                    "P0002 replay records PASS",
                ):
                    if token.casefold() not in audit.casefold():
                        self.problems.add(
                            self.relative(audit_path), f"missing intake token {token!r}"
                        )

    def evidence_for(self, branch_id: str, filename: str) -> Artifact | None:
        expected = self.relative(self.phase_dir / "branches" / filename)
        matches = [item for item in self.branch_evidence.get(branch_id, []) if item.path == expected]
        if len(matches) != 1:
            self.problems.add(
                f"{branch_id}.refresh.evidence",
                f"must hash-pin exactly one {expected}",
            )
            return None
        return matches[0]

    def validate_routes_and_tests(self) -> None:
        route_header = (
            "baseline_owner_module",
            "baseline_declaration_name",
            "visibility",
            "kind",
            "baseline_order",
            "destination_module",
            "route_class",
            "normalization_decision",
        )
        private_header = ("old_private", "new_private", "destination_module")
        for branch_id, facts in BRANCH_FACTS.items():
            filenames = {
                "routes": f"{branch_id}-declaration-routes.tsv",
                "private": f"{branch_id}-private-normalization.tsv",
                "modules": f"{branch_id}-module-routes.tsv",
                "tests": f"{branch_id}-test-plan.tsv",
                "closure": f"{branch_id}-private-closure.tsv",
            }
            artifacts = {
                key: self.evidence_for(branch_id, filename)
                for key, filename in filenames.items()
            }
            route_path = self.phase_dir / "branches" / filenames["routes"]
            _, routes = self.read_tsv(
                route_path, self.relative(route_path), route_header
            )
            self.problems.require(
                len(routes) == facts["declarations"],
                self.relative(route_path),
                f"expected {facts['declarations']} exact declaration routes, found {len(routes)}",
            )
            identities = [
                (row.get("baseline_owner_module", ""), row.get("baseline_declaration_name", ""))
                for row in routes
            ]
            if len(identities) != len(set(identities)):
                self.problems.add(self.relative(route_path), "duplicate baseline declaration route")
            if identities != sorted(identities, key=lambda item: (item[0], self.numeric_order(routes, item))):
                # The exact order is independently frozen by baseline_order; only enforce
                # that baseline_order is a positive, unique integer per owner below.
                pass
            by_owner_orders: dict[str, list[int]] = defaultdict(list)
            private_names: set[str] = set()
            selector_modules = {module_from_path(path) for path in facts["paths"]}
            for index, row in enumerate(routes):
                owner = row.get("baseline_owner_module", "")
                declaration = row.get("baseline_declaration_name", "")
                destination = row.get("destination_module", "")
                decision = row.get("normalization_decision", "")
                if owner not in selector_modules:
                    self.problems.add(
                        f"{self.relative(route_path)}[{index}]",
                        f"owner {owner!r} is absent from the selector",
                    )
                if not declaration or not destination:
                    self.problems.add(
                        f"{self.relative(route_path)}[{index}]",
                        "declaration and destination_module must be nonempty",
                    )
                if not decision or DEFERRED_RE.search(decision):
                    self.problems.add(
                        f"{self.relative(route_path)}[{index}]",
                        "normalization decision must be explicit and reviewed before activation",
                    )
                try:
                    order = int(row.get("baseline_order", ""))
                    if order < 1:
                        raise ValueError
                except ValueError:
                    self.problems.add(
                        f"{self.relative(route_path)}[{index}].baseline_order",
                        "expected a positive integer",
                    )
                else:
                    by_owner_orders[owner].append(order)
                visibility = row.get("visibility", "").casefold()
                if visibility == "private":
                    private_names.add(declaration)
                elif visibility != "public":
                    self.problems.add(
                        f"{self.relative(route_path)}[{index}].visibility",
                        "expected public or private",
                    )
            self.problems.require(
                len(private_names) == facts["private"],
                self.relative(route_path),
                f"expected {facts['private']} private declaration routes, found {len(private_names)}",
            )
            for owner, orders in by_owner_orders.items():
                if len(orders) != len(set(orders)):
                    self.problems.add(self.relative(route_path), f"duplicate baseline_order in {owner}")
            private_path = self.phase_dir / "branches" / filenames["private"]
            _, private_rows = self.read_tsv(
                private_path, self.relative(private_path), private_header
            )
            self.problems.require(
                len(private_rows) == facts["private"],
                self.relative(private_path),
                f"expected {facts['private']} private normalizations, found {len(private_rows)}",
            )
            old_private = {row.get("old_private", "") for row in private_rows}
            self.problems.require(
                len(old_private) == len(private_rows) and "" not in old_private,
                self.relative(private_path),
                "old_private values must be nonempty and unique",
            )
            if old_private != private_names:
                self.problems.add(
                    self.relative(private_path),
                    f"private map must exactly cover route privates; missing={sorted(private_names-old_private)}, extra={sorted(old_private-private_names)}",
                )
            for index, row in enumerate(private_rows):
                for key in private_header:
                    value = row.get(key, "")
                    if not value or DEFERRED_RE.search(value):
                        self.problems.add(
                            f"{self.relative(private_path)}[{index}].{key}",
                            "private normalization must be explicit; no deferred worker decision",
                        )
            module_path = self.phase_dir / "branches" / filenames["modules"]
            module_header, module_rows = self.read_tsv(module_path, self.relative(module_path))
            module_column = self.choose_column(
                module_header, "module", "owner_module", "baseline_owner_module"
            )
            count_column = self.choose_column(module_header, "declaration_count", "baseline_declaration_count")
            if module_column is None or count_column is None:
                self.problems.add(
                    self.relative(module_path),
                    "module routes require module and declaration_count columns",
                )
            else:
                module_names = [row.get(module_column, "") for row in module_rows]
                self.problems.require(
                    set(module_names) == selector_modules and len(module_names) == len(selector_modules),
                    self.relative(module_path),
                    "module routes must cover every and only selector owner once",
                )
                counts: list[int] = []
                for index, row in enumerate(module_rows):
                    try:
                        value = int(row.get(count_column, ""))
                        if value < 0:
                            raise ValueError
                    except ValueError:
                        self.problems.add(
                            f"{self.relative(module_path)}[{index}].{count_column}",
                            "expected a nonnegative integer",
                        )
                    else:
                        counts.append(value)
                self.problems.require(
                    sum(counts) == facts["declarations"],
                    self.relative(module_path),
                    f"module declaration counts must sum to {facts['declarations']}",
                )
                self.problems.require(
                    sum(value == 0 for value in counts) == facts["declaration_free"],
                    self.relative(module_path),
                    f"expected {facts['declaration_free']} declaration-free modules",
                )
            closure_path = self.phase_dir / "branches" / filenames["closure"]
            closure_header, closure_rows = self.read_tsv(closure_path, self.relative(closure_path))
            closure_text = "\n".join("\t".join(row.values()) for row in closure_rows)
            self.problems.require(
                len(closure_rows) >= facts["private"],
                self.relative(closure_path),
                "full-graph private closure cannot be smaller than the selected private set",
            )
            for name in private_names:
                if name not in closure_text:
                    self.problems.add(self.relative(closure_path), f"private closure omits {name}")
            if not any("closure" in column.casefold() for column in closure_header):
                self.problems.add(self.relative(closure_path), "private closure TSV needs an explicit closure column")
            test_path = self.phase_dir / "branches" / filenames["tests"]
            test_header, test_rows = self.read_tsv(test_path, self.relative(test_path))
            class_column = self.choose_column(test_header, "test_class", "class", "plan_class")
            if class_column is None:
                self.problems.add(self.relative(test_path), "test plan requires a test_class column")
            else:
                found = {
                    row.get(class_column, "").casefold().replace("_", "-")
                    for row in test_rows
                }
                missing_classes = sorted(TEST_CLASSES - found)
                if missing_classes:
                    self.problems.add(
                        self.relative(test_path),
                        "missing test-plan class(es): " + ", ".join(missing_classes),
                    )
                for index, row in enumerate(test_rows):
                    joined = " ".join(row.values())
                    if DEFERRED_RE.search(joined):
                        self.problems.add(
                            f"{self.relative(test_path)}[{index}]",
                            "test plan may not defer design to the worker",
                        )

    @staticmethod
    def numeric_order(rows: list[dict[str, str]], identity: tuple[str, str]) -> int:
        for row in rows:
            if (
                row.get("baseline_owner_module", ""),
                row.get("baseline_declaration_name", ""),
            ) == identity:
                try:
                    return int(row.get("baseline_order", "0"))
                except ValueError:
                    return 0
        return 0

    @staticmethod
    def choose_column(header: Sequence[str], *names: str) -> str | None:
        for name in names:
            if name in header:
                return name
        return None

    def validate_projections(self) -> None:
        expected_status = (
            "active"
            if self.current_checkpoint_id == CHECKPOINT_ID
            else "retired"
        )
        for branch_id, facts in BRANCH_FACTS.items():
            projection_id = facts["projection"]
            path = self.phase_dir / f"projections/{projection_id}.json"
            projection = self.read_json(path, self.relative(path))
            if projection is None:
                continue
            for key, expected in {
                "schema_version": 1,
                "record_kind": "baseline_projection",
                "phase_id": PHASE_ID,
                "projection_id": projection_id,
                "wave_id": facts["wave"],
                "base_checkpoint_id": CHECKPOINT_ID,
                "status": expected_status,
            }.items():
                self.problems.require(
                    projection.get(key) == expected,
                    f"{projection_id}.{key}",
                    f"expected {expected!r}",
                )
            selector = projection.get("selector")
            selector_artifact = None
            if not isinstance(selector, dict) or selector.get("kind") != "module_path_tsv":
                self.problems.add(f"{projection_id}.selector", "expected module_path_tsv selector")
            else:
                selector_artifact = self.artifact(
                    selector.get("artifact"), f"{projection_id}.selector.artifact"
                )
            expected_selector = self.relative(
                self.phase_dir / f"selectors/{facts['wave']}.tsv"
            )
            if selector_artifact is not None:
                self.problems.require(
                    selector_artifact.path == expected_selector,
                    f"{projection_id}.selector.artifact.path",
                    f"expected {expected_selector}",
                )
            graph = self.artifact(
                projection.get("projection_graph"), f"{projection_id}.projection_graph"
            )
            if graph is not None:
                counts = self.parse_projection_graph(self.root / graph.path, projection_id)
                declared = projection.get("expected_counts")
                if not isinstance(declared, dict):
                    self.problems.add(f"{projection_id}.expected_counts", "expected an object")
                else:
                    for key, actual in counts.items():
                        self.problems.require(
                            declared.get(key) == actual,
                            f"{projection_id}.expected_counts.{key}",
                            f"expected actual graph count {actual}, found {declared.get(key)!r}",
                        )
                    self.problems.require(
                        counts.get("signature_edges", 0) > 0 and counts.get("body_edges", 0) > 0,
                        f"{projection_id}.projection_graph",
                        "format-2 graph must contain signature and body/proof edges",
                    )
            combined = self.artifact(
                projection.get("combined_baseline"), f"{projection_id}.combined_baseline"
            )
            if combined is not None and "C0000-combined" not in combined.path:
                self.problems.add(
                    f"{projection_id}.combined_baseline.path",
                    "projection must be rooted in C0000 combined baseline",
                )

    def parse_projection_graph(self, path: Path, context: str) -> dict[str, int]:
        declarations = 0
        signature = 0
        body = 0
        union: set[tuple[str, str]] = set()
        try:
            with gzip.open(path, "rt", encoding="utf-8", newline="") as handle:
                first = handle.readline().rstrip("\n")
                if first != "format\t2":
                    self.problems.add(context, "projection graph must start with format<TAB>2")
                for number, line in enumerate(handle, 2):
                    fields = line.rstrip("\n").split("\t")
                    if not fields or fields == [""]:
                        continue
                    if fields[0] == "declaration" and len(fields) == 5:
                        declarations += 1
                    elif fields[0] == "edge" and len(fields) == 4:
                        kind, source, target = fields[1:]
                        if kind == "signature":
                            signature += 1
                        elif kind == "body":
                            body += 1
                        else:
                            self.problems.add(context, f"unknown edge kind {kind!r} at line {number}")
                        union.add((source, target))
                    else:
                        self.problems.add(context, f"malformed format-2 row at line {number}")
        except (OSError, UnicodeError, gzip.BadGzipFile) as error:
            self.problems.add(context, f"cannot parse projection graph: {error}")
        return {
            "declarations": declarations,
            "signature_edges": signature,
            "body_edges": body,
            "union_edges": len(union),
        }

    def validate_overlap_reviews(self) -> None:
        for branch_id in BRANCH_FACTS:
            filename = f"{branch_id}-overlap-review.md"
            artifact = self.evidence_for(branch_id, filename)
            path = self.phase_dir / "branches" / filename
            try:
                text = path.read_text(encoding="utf-8")
            except OSError as error:
                self.problems.add(self.relative(path), f"cannot read overlap review: {error}")
                continue
            folded = " ".join(text.casefold().replace("_", "-").split())
            has_directions = (
                ("r01" in folded and "r02" in folded)
                and (
                    "either direction" in folded
                    or "both directions" in folded
                    or (
                        "ordered comparison" in folded
                        and folded.count("r01") >= 2
                        and folded.count("r02") >= 2
                    )
                    or ("r01 -> r02" in folded and "r02 -> r01" in folded)
                    or ("r01 → r02" in folded and "r02 → r01" in folded)
                    or ("r01-to-r02" in folded and "r02-to-r01" in folded)
                )
            )
            self.problems.require(
                has_directions,
                self.relative(path),
                "must prove R01/R02 results in both directions",
            )
            for name, tokens in OVERLAP_CATEGORIES.items():
                token_positions = [folded.find(token) for token in tokens]
                present = all(position >= 0 for position in token_positions)
                zero_near = False
                if present:
                    start = max(0, min(token_positions) - 80)
                    end = min(len(folded), max(token_positions) + 180)
                    window = folded[start:end]
                    zero_near = bool(re.search(r"\bzero\b|(?:^|\D)0(?:\D|$)", window))
                self.problems.require(
                    present and zero_near,
                    self.relative(path),
                    f"must explicitly declare zero {name} result",
                )
            for token in ("matrixalgebra", "c0000", "reviewed union"):
                if token not in folded.replace("/", "").replace(" ", "") and token not in folded:
                    self.problems.add(self.relative(path), f"missing joint-review token {token!r}")

    def validate_requests_and_postimages(self) -> None:
        request_dir = self.phase_dir / "requests"
        expected_status = (
            "active"
            if self.current_checkpoint_id == CHECKPOINT_ID
            else "applied"
        )
        request_specs = [
            ("R0001", "B0001"),
            ("R0002", "B0002"),
            ("R0002T", "B0002"),
        ]
        for request_id, branch_id in request_specs:
            path = request_dir / f"{request_id}.json"
            request = self.read_json(path, self.relative(path))
            if request is None:
                continue
            self.requests[request_id] = request
            facts = BRANCH_FACTS[branch_id]
            for key, expected in {
                "schema_version": 1,
                "record_kind": "shared_file_request",
                "phase_id": PHASE_ID,
                "request_id": request_id,
                "lane_id": facts["lane"],
                "wave_id": facts["wave"],
                "requester_id": (
                    "primary-human" if request_id == "R0002T" else facts["operator"]
                ),
                "target_checkpoint_id": CHECKPOINT_ID,
                "target_base_sha": CODE_SHA,
                "valid_through_checkpoint_id": CHECKPOINT_ID,
                "status": expected_status,
            }.items():
                self.problems.require(
                    request.get(key) == expected,
                    f"{request_id}.{key}",
                    f"expected {expected!r}, found {request.get(key)!r}",
                )
            paths = request.get("paths") if isinstance(request.get("paths"), list) else []
            if paths != sorted(set(paths)):
                self.problems.add(f"{request_id}.paths", "paths must be sorted and unique")
            self.problems.require(
                (
                    set(paths) == R0002T_PATHS
                    if request_id == "R0002T"
                    else facts["consumers"] <= set(paths)
                ),
                f"{request_id}.paths",
                (
                    f"must equal exact supplemental paths {sorted(R0002T_PATHS)}"
                    if request_id == "R0002T"
                    else "must include every required clean consumer postimage"
                ),
            )
            preimages = request.get("preimage_blobs") if isinstance(request.get("preimage_blobs"), list) else []
            parsed_preimages: dict[str, str | None] = {}
            for index, item in enumerate(preimages):
                if not isinstance(item, dict) or set(item) != {"path", "blob_oid"}:
                    self.problems.add(f"{request_id}.preimage_blobs[{index}]", "expected exactly path/blob_oid")
                    continue
                item_path, blob = item.get("path"), item.get("blob_oid")
                if isinstance(item_path, str) and (blob is None or isinstance(blob, str)):
                    parsed_preimages[item_path] = blob
                else:
                    self.problems.add(f"{request_id}.preimage_blobs[{index}]", "invalid preimage")
            self.problems.require(
                set(parsed_preimages) == set(paths),
                f"{request_id}.preimage_blobs",
                "preimage paths must exactly equal request paths",
            )
            for item_path, expected_blob in parsed_preimages.items():
                actual_blob = self.git_blob(CODE_SHA, item_path)
                self.problems.require(
                    actual_blob == expected_blob,
                    f"{request_id}.preimage_blobs[{item_path}]",
                    f"expected C0000 blob {actual_blob!r}, found {expected_blob!r}",
                )
            patch = self.artifact(request.get("patch"), f"{request_id}.patch")
            patch_path: Path | None = None
            if patch is not None:
                expected_patch = self.relative(request_dir / f"{request_id}.patch")
                self.problems.require(
                    patch.path == expected_patch,
                    f"{request_id}.patch.path",
                    f"expected {expected_patch}",
                )
                patch_path = self.root / patch.path
            post_name = f"{request_id}-postimages.tsv"
            post_path = request_dir / post_name
            post_digest = sha256_path(post_path) if post_path.is_file() else None
            post_header, post_rows = self.read_tsv(post_path, self.relative(post_path))
            postimages = self.validate_postimage_rows(
                post_header,
                post_rows,
                self.relative(post_path),
                set(paths),
                "postimage_sha256",
            )
            if patch_path is not None:
                self.materialize_patch_postimages(
                    request_id,
                    patch_path,
                    set(paths),
                    postimages,
                )
            rationale = request.get("rationale") if isinstance(request.get("rationale"), str) else ""
            if post_digest is not None:
                self.problems.require(
                    post_digest in rationale.upper(),
                    f"{request_id}.rationale",
                    f"must hash-pin {post_name} at SHA-256 {post_digest}",
                )
            self.validate_request_lifecycle(request_id, request)
        expected_links = {
            "B0001": ["R0001"],
            "B0002": ["R0002", "R0002T"],
        }
        for branch_id, expected in expected_links.items():
            branch = self.branch_records.get(branch_id, {})
            linked = (
                branch.get("shared_request_ids")
                if isinstance(branch.get("shared_request_ids"), list)
                else []
            )
            self.problems.require(
                linked == expected,
                f"{branch_id}.shared_request_ids",
                f"expected exactly {expected}",
            )
        if {"R0001", "R0002"} <= set(self.requests):
            first, second = self.requests["R0001"], self.requests["R0002"]
            first_pre = {item["path"]: item["blob_oid"] for item in first.get("preimage_blobs", []) if isinstance(item, dict) and "path" in item and "blob_oid" in item}
            second_pre = {item["path"]: item["blob_oid"] for item in second.get("preimage_blobs", []) if isinstance(item, dict) and "path" in item and "blob_oid" in item}
            overlap = set(first_pre) & set(second_pre)
            expected_overlap = {"NumStability/Algorithms.lean"}
            self.problems.require(
                overlap == expected_overlap,
                "request overlap",
                "independent request overlap must be exactly "
                f"{sorted(expected_overlap)}, found {sorted(overlap)}",
            )
            for path in overlap:
                if first_pre[path] != second_pre[path]:
                    self.problems.add(
                        "request overlap",
                        f"{path} is not independently based on the same C0000 blob",
                    )
            union_path = request_dir / "R0001-R0002-union-postimages.tsv"
            header, rows = self.read_tsv(union_path, self.relative(union_path))
            union_expected = set(first.get("paths", [])) | set(second.get("paths", []))
            union_postimages = self.validate_postimage_rows(
                header,
                rows,
                self.relative(union_path),
                union_expected,
                "union_postimage_sha256",
            )
            union_patch_path = request_dir / "R0001-R0002-union.patch"
            union_patch_context = self.relative(union_patch_path)
            union_patch_digest = (
                sha256_path(union_patch_path) if union_patch_path.is_file() else ""
            )
            if not union_patch_digest:
                self.problems.add(
                    union_patch_context,
                    "missing reviewed-union patch rooted at exact C0000",
                )
            else:
                self.materialize_patch_postimages(
                    "R0001-R0002 reviewed union",
                    union_patch_path,
                    union_expected,
                    union_postimages,
                )
                for branch_id in ("B0001", "B0002"):
                    matches = [
                        item
                        for item in self.branch_evidence.get(branch_id, [])
                        if item.path == union_patch_context
                    ]
                    self.problems.require(
                        len(matches) == 1
                        and matches[0].sha256 == union_patch_digest,
                        f"{branch_id}.refresh.evidence",
                        "must hash-pin exactly one reviewed-union patch at SHA-256 "
                        f"{union_patch_digest}",
                    )
            review_path = request_dir / "R0001-R0002-union-review.md"
            review = ""
            try:
                review = review_path.read_text(encoding="utf-8")
            except OSError as error:
                self.problems.add(self.relative(review_path), f"cannot read union review: {error}")
            else:
                folded = " ".join(review.casefold().split())
                for token in ("r0001", "r0002", "c0000", CODE_SHA):
                    if token.casefold() not in folded:
                        self.problems.add(self.relative(review_path), f"missing union evidence token {token!r}")
                self.problems.require(
                    ("reviewed union" in folded)
                    or ("union postimage" in folded and "reconcil" in folded),
                    self.relative(review_path),
                    "must explicitly record the reviewed/reconciled union postimage",
                )
                for path in sorted(overlap):
                    if path.casefold() not in folded:
                        self.problems.add(self.relative(review_path), f"union review omits overlap path {path}")
                if union_patch_digest and union_patch_digest.casefold() not in folded:
                    self.problems.add(
                        self.relative(review_path),
                        "union review must hash-pin reviewed-union patch SHA-256 "
                        f"{union_patch_digest}",
                    )
            union_manifest_digest = sha256_path(union_path) if union_path.is_file() else ""
            review_digest = sha256_path(review_path) if review_path.is_file() else ""
            for request_id in ("R0001", "R0002"):
                request = self.requests[request_id]
                rationale = str(request.get("rationale", "")).upper()
                for digest, label in (
                    (union_manifest_digest, "union postimages"),
                    (review_digest, "union review"),
                    (union_patch_digest, "reviewed-union patch"),
                ):
                    if digest and digest not in rationale:
                        self.problems.add(
                            f"{request_id}.rationale",
                            f"must hash-pin {label} SHA-256 {digest}",
                        )

    def validate_request_lifecycle(
        self, request_id: str, request: dict[str, Any]
    ) -> None:
        context = f"{request_id}.resolution"
        resolution = request.get("resolution")
        empty = {
            "checkpoint_id": None,
            "commit_sha": None,
            "reason": None,
            "resolved_at": None,
            "resolved_by": None,
            "validation_evidence": [],
        }
        if self.current_checkpoint_id == CHECKPOINT_ID:
            self.problems.require(
                resolution == empty,
                context,
                f"active C0000 request requires exact empty resolution {empty!r}",
            )
            return
        if not isinstance(resolution, dict):
            self.problems.add(context, "expected an object")
            return
        self.problems.require(
            set(resolution) == set(empty),
            context,
            f"expected exactly the resolution keys {sorted(empty)}",
        )
        for key, expected in {
            "checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
            "commit_sha": INTEGRATED_CODE_SHA,
            "resolved_by": "primary-human",
        }.items():
            self.problems.require(
                resolution.get(key) == expected,
                f"{context}.{key}",
                f"expected {expected!r}, found {resolution.get(key)!r}",
            )
        reason = resolution.get("reason")
        self.problems.require(
            isinstance(reason, str) and bool(reason.strip()),
            f"{context}.reason",
            "applied request requires a nonempty reason",
        )
        resolved_at = resolution.get("resolved_at")
        self.problems.require(
            isinstance(resolved_at, str)
            and RFC3339_RE.fullmatch(resolved_at) is not None,
            f"{context}.resolved_at",
            "expected an RFC3339 resolution timestamp with timezone",
        )
        evidence = resolution.get("validation_evidence")
        artifacts: list[Artifact] = []
        if not isinstance(evidence, list) or not evidence:
            self.problems.add(
                f"{context}.validation_evidence",
                "applied request requires nonempty hash-pinned validation evidence",
            )
        else:
            for index, item in enumerate(evidence):
                artifact = self.artifact(
                    item, f"{context}.validation_evidence[{index}]"
                )
                if artifact is not None:
                    artifacts.append(artifact)
        expected_path, expected_digest = REQUEST_RESOLUTION_EVIDENCE[request_id]
        matches = [
            artifact
            for artifact in artifacts
            if artifact.path == expected_path
            and artifact.sha256 == expected_digest
        ]
        self.problems.require(
            len(matches) == 1,
            f"{context}.validation_evidence",
            "must contain exactly one immutable acceptance pin "
            f"{expected_path} at SHA-256 {expected_digest}",
        )

    def validate_postimage_rows(
        self,
        header: Sequence[str],
        rows: list[dict[str, str]],
        context: str,
        expected_paths: set[str],
        post_column: str,
        *,
        base_sha: str = CODE_SHA,
        base_label: str = "C0000",
    ) -> dict[str, str]:
        path_column = self.choose_column(header, "path", "shared_path")
        pre_column = self.choose_column(header, "preimage_blob_oid", "c0000_blob_oid", "base_blob_oid")
        pre_sha_column = self.choose_column(header, "preimage_sha256")
        if (
            path_column is None
            or pre_column is None
            or pre_sha_column is None
            or post_column not in header
        ):
            self.problems.add(
                context,
                "postimage TSV requires path, base preimage blob/SHA-256, and exact "
                f"{post_column} column",
            )
            return {}
        paths = [row.get(path_column, "") for row in rows]
        self.problems.require(
            paths == sorted(set(paths)),
            context,
            "postimage rows must be sorted and unique by path",
        )
        self.problems.require(
            set(paths) == expected_paths,
            context,
            f"postimage paths must equal request union; missing={sorted(expected_paths-set(paths))}, extra={sorted(set(paths)-expected_paths)}",
        )
        postimages: dict[str, str] = {}
        actual_preimages = {
            path: self.git_blob(base_sha, path) for path in paths if path
        }
        preimage_payloads = self.git_blob_payloads(
            (
                oid
                for oid in actual_preimages.values()
                if isinstance(oid, str)
            ),
            f"{context} {base_label} preimages",
        )
        for index, row in enumerate(rows):
            path = row.get(path_column, "")
            actual_pre = actual_preimages.get(path)
            self.problems.require(
                row.get(pre_column) == (actual_pre or "-"),
                f"{context}[{index}].{pre_column}",
                f"expected {base_label} blob {(actual_pre or '-')!r}",
            )
            if actual_pre is not None:
                preimage = preimage_payloads.get(actual_pre)
                if preimage is None:
                    self.problems.add(
                        f"{context}[{index}].{pre_sha_column}",
                        f"cannot read {base_label} preimage blob {actual_pre}",
                    )
                else:
                    actual_pre_sha = hashlib.sha256(preimage).hexdigest().upper()
                    self.problems.require(
                        row.get(pre_sha_column, "").upper() == actual_pre_sha,
                        f"{context}[{index}].{pre_sha_column}",
                        f"expected {base_label} content SHA-256 {actual_pre_sha}",
                    )
            post_digest = row.get(post_column, "")
            if not SHA256_RE.fullmatch(post_digest):
                self.problems.add(
                    f"{context}[{index}].{post_column}",
                    "postimage SHA-256 must be exactly 64 hexadecimal characters",
                )
            elif path:
                postimages[path] = post_digest.upper()
        return postimages

    def git_blob(self, revision: str, path: str) -> str | None:
        return self.git_tree_blobs(revision).get(normalize_path(path))

    def materialize_patch_postimages(
        self,
        context: str,
        patch: Path,
        expected_paths: set[str],
        expected_sha256: dict[str, str],
        *,
        base_sha: str = CODE_SHA,
        base_label: str = "C0000",
        unidiff_zero: bool = False,
    ) -> None:
        """Apply *patch* to a disposable base index, hash results, then reverse."""

        with tempfile.TemporaryDirectory(prefix="completion-phase-index-") as directory:
            index = Path(directory) / "index"
            env = os.environ.copy()
            env["GIT_INDEX_FILE"] = str(index)
            read = self.git("read-tree", base_sha, check=False, env=env)
            if read.returncode:
                self.problems.add(
                    f"{context}.patch",
                    f"cannot initialize exact {base_label} index: {read.stderr.strip()}",
                )
                return
            apply_mode = ["--unidiff-zero"] if unidiff_zero else []
            applied = self.git(
                "apply",
                "--cached",
                *apply_mode,
                "--whitespace=nowarn",
                str(patch),
                check=False,
                env=env,
            )
            if applied.returncode:
                self.problems.add(
                    f"{context}.patch",
                    f"does not materialize independently from exact {base_label}: "
                    f"{applied.stderr.strip() or applied.stdout.strip()}",
                )
                return
            changed_process = self.git(
                "diff",
                "--cached",
                "--name-only",
                "-z",
                base_sha,
                "--",
                check=False,
                env=env,
            )
            if changed_process.returncode:
                self.problems.add(
                    f"{context}.patch",
                    "cannot enumerate materialized postimages: "
                    f"{changed_process.stderr.strip() or changed_process.stdout.strip()}",
                )
                return
            changed_paths = {
                normalize_path(path)
                for path in changed_process.stdout.split("\0")
                if path
            }
            self.problems.require(
                changed_paths == expected_paths,
                f"{context}.patch",
                "materialized changed paths must exactly equal manifest paths; "
                f"missing={sorted(expected_paths-changed_paths)}, "
                f"extra={sorted(changed_paths-expected_paths)}",
            )
            self.problems.require(
                set(expected_sha256) == expected_paths,
                f"{context}.postimages",
                "must provide exactly one valid SHA-256 for every manifest path; "
                f"missing={sorted(expected_paths-set(expected_sha256))}, "
                f"extra={sorted(set(expected_sha256)-expected_paths)}",
            )
            staged_process = self.git(
                "ls-files", "--stage", "-z", check=False, env=env
            )
            staged: dict[str, str] = {}
            if staged_process.returncode:
                self.problems.add(
                    f"{context}.postimages",
                    "cannot enumerate materialized stage-0 blobs: "
                    f"{staged_process.stderr.strip() or staged_process.stdout.strip()}",
                )
            else:
                for record in staged_process.stdout.split("\0"):
                    if not record:
                        continue
                    try:
                        metadata, staged_path = record.split("\t", 1)
                        _mode, oid, stage = metadata.split()
                    except ValueError:
                        self.problems.add(
                            f"{context}.postimages",
                            f"cannot parse staged index row {record!r}",
                        )
                        continue
                    if stage == "0" and SHA1_RE.fullmatch(oid):
                        staged[normalize_path(staged_path)] = oid
            materialized_payloads = self.git_blob_payloads(
                (
                    staged[path]
                    for path in expected_paths
                    if path in staged
                ),
                f"{context} materialized postimages",
                env=env,
            )
            for path in sorted(expected_paths):
                expected = expected_sha256.get(path)
                if expected is None:
                    continue
                oid = staged.get(path)
                if oid is None:
                    self.problems.add(
                        f"{context}.postimages[{path}]",
                        "cannot resolve materialized stage-0 blob",
                    )
                    continue
                content = materialized_payloads.get(oid)
                if content is None:
                    self.problems.add(
                        f"{context}.postimages[{path}]",
                        f"cannot read materialized blob {oid}",
                    )
                    continue
                actual = hashlib.sha256(content).hexdigest().upper()
                self.problems.require(
                    actual == expected,
                    f"{context}.postimages[{path}]",
                    f"materialized SHA-256 mismatch: manifest {expected}, actual {actual}",
                )
            reversed_patch = self.git(
                "apply",
                "--cached",
                "--reverse",
                *apply_mode,
                "--whitespace=nowarn",
                str(patch),
                check=False,
                env=env,
            )
            if reversed_patch.returncode:
                self.problems.add(
                    f"{context}.patch",
                    f"cannot reverse replay to exact {base_label}: "
                    f"{reversed_patch.stderr.strip() or reversed_patch.stdout.strip()}",
                )
                return
            remaining = self.git(
                "diff",
                "--cached",
                "--name-only",
                "-z",
                base_sha,
                "--",
                check=False,
                env=env,
            )
            if remaining.returncode:
                self.problems.add(
                    f"{context}.patch",
                    f"cannot verify reverse replay against exact {base_label}: "
                    f"{remaining.stderr.strip() or remaining.stdout.strip()}",
                )
            else:
                remaining_paths = {
                    normalize_path(path)
                    for path in remaining.stdout.split("\0")
                    if path
                }
                self.problems.require(
                    not remaining_paths,
                    f"{context}.patch",
                    f"reverse replay must restore exact {base_label}; "
                    f"remaining={sorted(remaining_paths)}",
                )

    def validate_next_wave_controls(self) -> None:
        """Validate the distinct C0001-rooted R11/R12 control epoch.

        The generic phase checker owns the reusable B/P/R schemas.  This
        method supplies the completion-phase ratchets: the exact graph-derived
        pair, its same-base evidence, and its independently replayable shared
        postimages.  It intentionally does not alter the historical B0001 /
        B0002 validation above.
        """

        context = "C0001-rooted R11/R12 controls"
        self.problems.require(
            self.current_checkpoint_id
            in {
                SUCCESSOR_CHECKPOINT_ID,
                C0002_CHECKPOINT_ID,
                C0003_CHECKPOINT_ID,
                C0004_CHECKPOINT_ID,
                C0005_CHECKPOINT_ID,
                C0006_CHECKPOINT_ID,
                C0007_CHECKPOINT_ID,
                C0008_CHECKPOINT_ID,
            },
            context,
            "next-wave controls require current checkpoint C0001 through C0007",
        )

        inventory_path = self.phase_dir / "checkpoints/C0001-inventory.tsv"
        if inventory_path.is_file():
            self.problems.require(
                sha256_path(inventory_path) == NEXT_INVENTORY_SHA256,
                self.relative(inventory_path),
                f"expected exact C0001 inventory SHA-256 {NEXT_INVENTORY_SHA256}",
            )
        _, inventory = self.read_tsv(
            inventory_path, self.relative(inventory_path), SCOPE_HEADER
        )
        self.problems.require(
            len(inventory) == SUCCESSOR_METRICS["production_modules"],
            self.relative(inventory_path),
            f"expected {SUCCESSOR_METRICS['production_modules']} C0001 rows",
        )
        inventory_by_path = {row.get("path", ""): row for row in inventory}
        self.problems.require(
            len(inventory_by_path) == len(inventory),
            self.relative(inventory_path),
            "C0001 inventory paths must be unique",
        )

        baseline_path = self.phase_dir / "baselines/C0001-combined.json"
        if baseline_path.is_file():
            self.problems.require(
                sha256_path(baseline_path) == NEXT_COMBINED_BASELINE_SHA256,
                self.relative(baseline_path),
                "C0001 combined baseline SHA-256 drifted from the activated epoch",
            )
        else:
            self.problems.add(self.relative(baseline_path), "missing C0001 combined baseline")

        self.validate_next_wave_authority()
        base_tree_paths = self.git_tree_paths(INTEGRATED_CODE_SHA)
        branch_rules: dict[str, list[PathRule]] = {}
        protected_consumers: dict[str, set[str]] = {}
        statuses: set[str] = set()

        for branch_id, facts in NEXT_BRANCH_FACTS.items():
            branch_path = self.phase_dir / f"branches/{branch_id}.json"
            branch = self.read_json(branch_path, self.relative(branch_path))
            if branch is None:
                continue
            self.branch_records[branch_id] = branch
            for key, expected in {
                "schema_version": 1,
                "record_kind": "phase_branch",
                "phase_id": PHASE_ID,
                "branch_id": branch_id,
                "lane_id": facts["lane"],
                "wave_id": facts["wave"],
                "branch_name": facts["branch"],
                "owner_id": "primary-human",
                "base_checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
                "base_sha": INTEGRATED_CODE_SHA,
                "baseline_projection_id": facts["projection"],
            }.items():
                self.problems.require(
                    branch.get(key) == expected,
                    f"{branch_id}.{key}",
                    f"expected {expected!r}, found {branch.get(key)!r}",
                )
            self.problems.require(
                branch.get("operator_ids") == [facts["operator"]],
                f"{branch_id}.operator_ids",
                f"expected exactly [{facts['operator']!r}]",
            )
            status = branch.get("status")
            allowed_statuses = next_branch_statuses(self.current_checkpoint_id)
            self.problems.require(
                status in allowed_statuses,
                f"{branch_id}.status",
                f"expected one of {sorted(allowed_statuses)} at "
                f"{self.current_checkpoint_id}",
            )
            if isinstance(status, str):
                statuses.add(status)

            refresh = branch.get("refresh")
            if not isinstance(refresh, dict):
                self.problems.add(f"{branch_id}.refresh", "expected an object")
                evidence: Any = []
            else:
                self.problems.require(
                    refresh.get("reviewed_checkpoint_id") == SUCCESSOR_CHECKPOINT_ID
                    and refresh.get("decision") == "current",
                    f"{branch_id}.refresh",
                    "must record a current review against exact C0001",
                )
                evidence = refresh.get("evidence")
            self.branch_evidence[branch_id] = []
            if not isinstance(evidence, list):
                self.problems.add(
                    f"{branch_id}.refresh.evidence", "expected a hash-pinned list"
                )
            else:
                evidence_paths: list[str] = []
                for index, item in enumerate(evidence):
                    artifact = self.artifact(
                        item, f"{branch_id}.refresh.evidence[{index}]"
                    )
                    if artifact is not None:
                        self.branch_evidence[branch_id].append(artifact)
                        evidence_paths.append(artifact.path)
                self.problems.require(
                    len(evidence_paths) == len(set(evidence_paths)),
                    f"{branch_id}.refresh.evidence",
                    "refresh evidence paths must be unique",
                )

            self.require_next_evidence(
                branch_id,
                self.relative(baseline_path),
                NEXT_COMBINED_BASELINE_SHA256,
            )
            self.require_next_evidence(
                branch_id,
                self.relative(inventory_path),
                NEXT_INVENTORY_SHA256,
            )

            selector_path = self.phase_dir / f"selectors/{facts['wave']}.tsv"
            _, selector_rows = self.read_tsv(
                selector_path, self.relative(selector_path), SELECTOR_HEADER
            )
            expected_selector = sorted(
                (
                    (row.get("module", ""), row.get("path", ""))
                    for row in inventory
                    if row.get("wave_id") == facts["wave"]
                ),
                key=lambda item: (item[0], item[1]),
            )
            actual_selector = [
                (row.get("module", ""), row.get("path", ""))
                for row in selector_rows
            ]
            self.problems.require(
                actual_selector == expected_selector
                and len(actual_selector) == facts["owned_count"],
                self.relative(selector_path),
                "selector must equal the exact sorted C0001 inventory wave",
            )
            for module, selected_path in expected_selector:
                row = inventory_by_path.get(selected_path, {})
                self.problems.require(
                    module_from_path(selected_path) == module,
                    f"{facts['wave']} selector[{selected_path}]",
                    "module/path identity mismatch",
                )
                self.problems.require(
                    row.get("phase_scope") == "in_scope"
                    and row.get("lane_id") == facts["lane"]
                    and row.get("wave_id") == facts["wave"],
                    f"{facts['wave']} selector[{selected_path}]",
                    "C0001 scope row must be in-scope on the exact immutable lane/wave",
                )
                actual_blob = self.git_blob(INTEGRATED_CODE_SHA, selected_path)
                self.problems.require(
                    actual_blob == row.get("base_blob_oid"),
                    f"{facts['wave']} selector[{selected_path}]",
                    f"C0001 blob mismatch: inventory {row.get('base_blob_oid')!r}, Git {actual_blob!r}",
                )

            owned = self.parse_rules(branch.get("owned_paths"), f"{branch_id}.owned_paths")
            expected_owned = {path for _, path in expected_selector}
            self.problems.require(
                len(owned) == len(expected_owned)
                and all(rule.match == "exact" for rule in owned)
                and {rule.path for rule in owned} == expected_owned,
                f"{branch_id}.owned_paths",
                "must contain exact rules for every and only selector path",
            )

            destinations = self.parse_rules(
                branch.get("destination_prefixes"),
                f"{branch_id}.destination_prefixes",
            )
            self.problems.require(
                all(rule.match == "prefix" for rule in destinations)
                and {rule.path for rule in destinations} == facts["destinations"],
                f"{branch_id}.destination_prefixes",
                f"must equal exact reviewed set {sorted(facts['destinations'])}",
            )
            for index, destination in enumerate(destinations):
                occupied = [
                    path
                    for path in base_tree_paths
                    if is_equal_or_child(path.casefold(), destination.folded)
                ]
                self.problems.require(
                    not occupied,
                    f"{branch_id}.destination_prefixes[{destination.path}]",
                    f"must be casefold-vacant at C0001; found {occupied[:5]}",
                )
                for other in destinations[index + 1 :]:
                    if destination.intersects(other):
                        self.problems.add(
                            f"{branch_id}.destination_prefixes",
                            f"internal equal/ancestor collision {destination.path} / {other.path}",
                        )

            forbidden = self.parse_rules(
                branch.get("forbidden_paths"), f"{branch_id}.forbidden_paths"
            )
            actual_forbidden_exact = {
                rule.path for rule in forbidden if rule.match == "exact"
            }
            actual_forbidden_prefix = {
                rule.path for rule in forbidden if rule.match == "prefix"
            }
            expected_forbidden_exact = set(inventory_by_path) - expected_owned
            peer_id = "B0004" if branch_id == "B0003" else "B0003"
            expected_forbidden_prefix = (
                set(NEXT_PROTECTED_PREFIXES)
                | set(NEXT_BRANCH_FACTS[peer_id]["destinations"])
            )
            self.problems.require(
                actual_forbidden_exact == expected_forbidden_exact
                and len(actual_forbidden_exact) == facts["forbidden_exact"],
                f"{branch_id}.forbidden_paths",
                "exact forbidden rules must be the exhaustive C0001 inventory complement",
            )
            self.problems.require(
                actual_forbidden_prefix == expected_forbidden_prefix
                and len(actual_forbidden_prefix) == facts["forbidden_prefix"],
                f"{branch_id}.forbidden_paths",
                "prefix forbidden rules must be guarded infrastructure plus every peer destination",
            )
            self.problems.require(
                len(forbidden)
                == facts["forbidden_exact"] + facts["forbidden_prefix"],
                f"{branch_id}.forbidden_paths",
                "forbidden rule count drifted",
            )
            for rule in owned + destinations:
                for shared in self.shared_rules:
                    if rule.intersects(shared):
                        self.problems.add(
                            f"{branch_id} authority",
                            f"worker rule {rule.path} intersects integrator-shared {shared.path}",
                        )

            self.validate_next_branch_lifecycle(branch_id, branch, facts)
            declarations = self.validate_next_projection(
                branch_id,
                facts,
                {module for module, _ in expected_selector},
            )
            protected_consumers[branch_id] = self.validate_next_routes_and_tests(
                branch_id,
                facts,
                expected_selector,
                declarations,
            )
            self.validate_next_overlap_review(branch_id, facts)
            branch_rules[branch_id] = owned + destinations

        self.problems.require(
            len(statuses) == 1,
            "B0003/B0004 state",
            "branches must transition synchronously through "
            "planned/active/delivered/accepted/retired; "
            f"found {sorted(statuses)}",
        )
        if set(branch_rules) == set(NEXT_BRANCH_FACTS):
            for left in branch_rules["B0003"]:
                for right in branch_rules["B0004"]:
                    if left.intersects(right):
                        self.problems.add(
                            "B0003/B0004 authority",
                            f"equal-or-ancestor collision {left.path} / {right.path}",
                        )
        state = next(iter(statuses)) if len(statuses) == 1 else None
        self.validate_next_joint_evidence(state)
        self.validate_next_requests(protected_consumers)

    def validate_next_wave_authority(self) -> None:
        authority = self.phase.get("authority")
        lanes = authority.get("lanes") if isinstance(authority, dict) else None
        lane = None
        if isinstance(lanes, list):
            matches = [
                item
                for item in lanes
                if isinstance(item, dict) and item.get("lane_id") == "claude-lane"
            ]
            if len(matches) == 1:
                lane = matches[0]
        planned_pair = (self.phase_dir / "branches/B0008.json").is_file()
        expected_operators = (
            ["claude-local", "codex-local"]
            if self.current_checkpoint_id == C0004_CHECKPOINT_ID and planned_pair
            else next_lane_operators(self.current_checkpoint_id)
        )
        self.problems.require(
            isinstance(lane, dict)
            and lane.get("owner_id") == "primary-human"
            and lane.get("operator_ids") == expected_operators,
            "phase.json.authority.lanes[claude-lane]",
            "claude-lane operators must equal the historical epoch authority or the "
            "exact temporary C0005 B0008 planning expansion",
        )

    def require_next_evidence(
        self, branch_id: str, path: str, expected_sha256: str | None = None
    ) -> Artifact | None:
        normalized = normalize_path(path)
        matches = [
            artifact
            for artifact in self.branch_evidence.get(branch_id, [])
            if artifact.path == normalized
        ]
        self.problems.require(
            len(matches) == 1,
            f"{branch_id}.refresh.evidence",
            f"must hash-pin exactly one {normalized}",
        )
        if len(matches) != 1:
            return None
        artifact = matches[0]
        if expected_sha256 is not None:
            self.problems.require(
                artifact.sha256 == expected_sha256,
                f"{branch_id}.refresh.evidence[{normalized}]",
                f"expected exact SHA-256 {expected_sha256}",
            )
        return artifact

    def validate_next_branch_lifecycle(
        self, branch_id: str, branch: dict[str, Any], facts: dict[str, Any]
    ) -> None:
        status = branch.get("status")
        report_path, report_sha256 = facts["delivery_report"]
        scope_path, scope_sha256 = facts["delivery_scope"]
        delivery_required = status in {"delivered", "accepted", "retired"}
        expected_delivery = (
            {
                "commit_sha": facts["delivery_sha"],
                "report": {"path": report_path, "sha256": report_sha256},
                "scope_evidence": {"path": scope_path, "sha256": scope_sha256},
            }
            if delivery_required
            else {"commit_sha": None, "report": None, "scope_evidence": None}
        )
        self.problems.require(
            branch.get("delivery") == expected_delivery,
            f"{branch_id}.delivery",
            f"expected exact {status} delivery record {expected_delivery!r}",
        )
        if delivery_required:
            ancestry = self.git(
                "merge-base",
                "--is-ancestor",
                facts["delivery_sha"],
                "HEAD",
                check=False,
            )
            self.problems.require(
                ancestry.returncode == 0,
                f"{branch_id}.delivery.commit_sha",
                "delivered tip must be an ancestor of the integrated tree",
            )
            parent_vector = self.git(
                "rev-list",
                "--parents",
                "-n",
                "1",
                facts["delivery_sha"],
                check=False,
            ).stdout.strip().split()
            self.problems.require(
                parent_vector == [facts["delivery_sha"], INTEGRATED_CODE_SHA],
                f"{branch_id}.delivery.commit_sha",
                "delivery must be a direct child of exact C0001",
            )
            for label, path, expected_sha256 in (
                ("report", report_path, report_sha256),
                ("scope_evidence", scope_path, scope_sha256),
            ):
                artifact_path = self.root / path
                self.problems.require(
                    artifact_path.is_file()
                    and sha256_path(artifact_path) == expected_sha256,
                    f"{branch_id}.delivery.{label}",
                    f"expected exact delivery artifact {path} at {expected_sha256}",
                )
        expected_integration = (
            {
                "method": "merge",
                "accepted_checkpoint_id": C0002_CHECKPOINT_ID,
                "accepted_sha": C0002_CODE_SHA,
            }
            if status in {"accepted", "retired"}
            else {
                "method": None,
                "accepted_checkpoint_id": None,
                "accepted_sha": None,
            }
        )
        self.problems.require(
            branch.get("integration") == expected_integration,
            f"{branch_id}.integration",
            f"expected exact {status} integration record {expected_integration!r}",
        )
        retirement_status = next_retirement_status(str(status))
        expected_retirement = {
            "remote_ref": f"refs/heads/{facts['branch']}",
            "rule": "delivery_ancestor_of_green_checkpoint",
            "status": retirement_status,
            "retired_at": None if status != "retired" else branch.get("retirement", {}).get("retired_at"),
            "retired_by": None if status != "retired" else "primary-human",
            "ancestry_checkpoint_id": None if status != "retired" else C0002_CHECKPOINT_ID,
        }
        self.problems.require(
            branch.get("retirement") == expected_retirement,
            f"{branch_id}.retirement",
            f"expected exact {status} retirement state {expected_retirement!r}",
        )
        if status == "retired":
            retired_at = branch.get("retirement", {}).get("retired_at")
            self.problems.require(
                isinstance(retired_at, str)
                and RFC3339_RE.fullmatch(retired_at) is not None,
                f"{branch_id}.retirement.retired_at",
                "retired branch requires an RFC3339 retirement timestamp",
            )

    def validate_next_projection(
        self,
        branch_id: str,
        facts: dict[str, Any],
        selector_modules: set[str],
    ) -> dict[tuple[str, str], tuple[str, str]]:
        projection_id = facts["projection"]
        path = self.phase_dir / f"projections/{projection_id}.json"
        projection = self.read_json(path, self.relative(path))
        if projection is None:
            return {}
        for key, expected in {
            "schema_version": 1,
            "record_kind": "baseline_projection",
            "phase_id": PHASE_ID,
            "projection_id": projection_id,
            "wave_id": facts["wave"],
            "base_checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
            "status": next_projection_status(self.current_checkpoint_id),
            "superseded_by": None,
        }.items():
            self.problems.require(
                projection.get(key) == expected,
                f"{projection_id}.{key}",
                f"expected {expected!r}, found {projection.get(key)!r}",
            )

        selector = projection.get("selector")
        selector_artifact = None
        if not isinstance(selector, dict) or selector.get("kind") != "module_path_tsv":
            self.problems.add(f"{projection_id}.selector", "expected module_path_tsv")
        else:
            selector_artifact = self.artifact(
                selector.get("artifact"), f"{projection_id}.selector.artifact"
            )
        expected_selector_path = self.relative(
            self.phase_dir / f"selectors/{facts['wave']}.tsv"
        )
        if selector_artifact is not None:
            self.problems.require(
                selector_artifact.path == expected_selector_path
                and selector_artifact.sha256 == facts["selector_sha256"],
                f"{projection_id}.selector.artifact",
                f"must pin {expected_selector_path} at {facts['selector_sha256']}",
            )

        graph = self.artifact(
            projection.get("projection_graph"), f"{projection_id}.projection_graph"
        )
        expected_graph_path = self.relative(
            self.phase_dir / f"projections/{projection_id}.tsv.gz"
        )
        declarations: dict[tuple[str, str], tuple[str, str]] = {}
        if graph is not None:
            self.problems.require(
                graph.path == expected_graph_path
                and graph.sha256 == facts["projection_sha256"],
                f"{projection_id}.projection_graph",
                f"must pin exact deterministic projection {facts['projection_sha256']}",
            )
            counts = self.parse_projection_graph(self.root / graph.path, projection_id)
            self.problems.require(
                counts == facts["counts"]
                and projection.get("expected_counts") == facts["counts"],
                f"{projection_id}.expected_counts",
                f"expected exact graph counts {facts['counts']}, found {counts}",
            )
            try:
                with gzip.open(self.root / graph.path, "rb") as handle:
                    payload_digest = hashlib.sha256(handle.read()).hexdigest().upper()
            except (OSError, gzip.BadGzipFile) as error:
                self.problems.add(projection_id, f"cannot hash projection payload: {error}")
            else:
                self.problems.require(
                    payload_digest == facts["projection_payload_sha256"],
                    f"{projection_id}.projection_graph",
                    "decompressed format-2 payload SHA-256 drifted",
                )
            declarations = self.parse_projection_declarations(
                self.root / graph.path, projection_id
            )
            declaration_owners = {owner for owner, _ in declarations}
            self.problems.require(
                declaration_owners <= selector_modules,
                f"{projection_id}.projection_graph",
                f"declaration owner outside selector: {sorted(declaration_owners-selector_modules)}",
            )

        combined = self.artifact(
            projection.get("combined_baseline"), f"{projection_id}.combined_baseline"
        )
        expected_combined = self.relative(
            self.phase_dir / "baselines/C0001-combined.json"
        )
        if combined is not None:
            self.problems.require(
                combined.path == expected_combined
                and combined.sha256 == NEXT_COMBINED_BASELINE_SHA256,
                f"{projection_id}.combined_baseline",
                "projection must use the exact official C0001 combined baseline",
            )

        checker = projection.get("checker")
        if not isinstance(checker, dict):
            self.problems.add(f"{projection_id}.checker", "expected an object")
        else:
            checker_artifact = self.artifact(
                checker.get("artifact"), f"{projection_id}.checker.artifact"
            )
            expected_checker_path = "tools/architecture/check_completion_phase_projection.py"
            if checker_artifact is not None:
                self.problems.require(
                    checker_artifact.path == expected_checker_path
                    and checker_artifact.sha256 == NEXT_PROJECTION_CHECKER_SHA256,
                    f"{projection_id}.checker.artifact",
                    "must pin the immutable private-aware projection checker",
                )
            production_prefixes = {
                destination
                for destination in facts["destinations"]
                if destination.startswith("NumStability/")
            }
            expected_arguments = sorted(
                [f"--allow-module={module}" for module in selector_modules]
                + [
                    f"--allow-prefix={module_from_path(prefix)}."
                    for prefix in production_prefixes
                ]
                + [
                    "--candidate=<candidate-format2.tsv>",
                    f"--private-map-sha256={facts['private_map_sha256']}",
                    "--private-map="
                    + self.relative(
                        self.phase_dir
                        / f"branches/{branch_id}-private-normalization.tsv"
                    ),
                    f"--projection-sha256={facts['projection_sha256']}",
                    f"--projection={expected_graph_path}",
                ]
            )
            self.problems.require(
                checker.get("arguments") == expected_arguments,
                f"{projection_id}.checker.arguments",
                "checker arguments must exactly bind owners, destinations, private map, and projection",
            )
        return declarations

    def parse_projection_declarations(
        self, path: Path, context: str
    ) -> dict[tuple[str, str], tuple[str, str]]:
        declarations: dict[tuple[str, str], tuple[str, str]] = {}
        try:
            with gzip.open(path, "rt", encoding="utf-8", newline="") as handle:
                if handle.readline().rstrip("\n") != "format\t2":
                    return declarations
                for number, line in enumerate(handle, 2):
                    fields = line.rstrip("\n").split("\t")
                    if not fields or fields[0] != "declaration" or len(fields) != 5:
                        continue
                    _, name, owner, kind, visibility = fields
                    identity = (owner, name)
                    if identity in declarations:
                        self.problems.add(
                            context,
                            f"duplicate declaration identity {identity!r} at line {number}",
                        )
                    declarations[identity] = (kind, visibility)
        except (OSError, UnicodeError, gzip.BadGzipFile) as error:
            self.problems.add(context, f"cannot parse projection declarations: {error}")
        return declarations

    def validate_next_routes_and_tests(
        self,
        branch_id: str,
        facts: dict[str, Any],
        selector: list[tuple[str, str]],
        declarations: dict[tuple[str, str], tuple[str, str]],
    ) -> set[str]:
        route_header = (
            "baseline_owner_module",
            "baseline_declaration_name",
            "visibility",
            "kind",
            "baseline_order",
            "destination_module",
            "route_class",
            "normalization_decision",
        )
        module_header = (
            "owner_module",
            "path",
            "declaration_count",
            "destination_modules",
            "compatibility_action",
            "review_status",
        )
        private_header = ("old_private", "new_private", "destination_module")
        closure_header = (
            "declaration",
            "owner_module",
            "visibility",
            "selected_owner",
            "closure_role",
        )
        test_header = ("test_class", "target", "purpose")
        filenames = {
            "routes": f"{branch_id}-declaration-routes.tsv",
            "modules": f"{branch_id}-module-routes.tsv",
            "private": f"{branch_id}-private-normalization.tsv",
            "closure": f"{branch_id}-private-closure.tsv",
            "tests": f"{branch_id}-test-plan.tsv",
        }
        evidence: dict[str, Artifact | None] = {}
        for key, filename in filenames.items():
            expected_digest = None
            if key == "private":
                expected_digest = facts["private_map_sha256"]
            elif key == "closure":
                expected_digest = facts["private_closure_sha256"]
            evidence[key] = self.require_next_evidence(
                branch_id,
                self.relative(self.phase_dir / "branches" / filename),
                expected_digest,
            )

        route_path = self.phase_dir / "branches" / filenames["routes"]
        _, routes = self.read_tsv(
            route_path, self.relative(route_path), route_header
        )
        self.problems.require(
            len(routes) == facts["counts"]["declarations"],
            self.relative(route_path),
            f"expected {facts['counts']['declarations']} declaration routes",
        )
        route_identities = [
            (
                row.get("baseline_owner_module", ""),
                row.get("baseline_declaration_name", ""),
            )
            for row in routes
        ]
        self.problems.require(
            len(route_identities) == len(set(route_identities)),
            self.relative(route_path),
            "declaration route identities must be unique",
        )
        self.problems.require(
            set(route_identities) == set(declarations),
            self.relative(route_path),
            "routes must cover every and only projected declaration identity",
        )

        orders: dict[str, list[int]] = defaultdict(list)
        per_owner_destinations: dict[str, set[str]] = defaultdict(set)
        destination_counts: Counter[str] = Counter()
        private_routes: dict[str, tuple[str, str]] = {}
        retained = 0
        relocated = 0
        ordered_keys: list[tuple[str, int]] = []
        for index, row in enumerate(routes):
            row_context = f"{self.relative(route_path)}[{index}]"
            owner = row.get("baseline_owner_module", "")
            name = row.get("baseline_declaration_name", "")
            destination = row.get("destination_module", "")
            expected_declaration = declarations.get((owner, name))
            if expected_declaration is not None:
                expected_kind, expected_visibility = expected_declaration
                self.problems.require(
                    row.get("kind") == expected_kind
                    and row.get("visibility") == expected_visibility,
                    row_context,
                    "kind/visibility must equal the frozen format-2 declaration",
                )
            try:
                order = int(row.get("baseline_order", ""))
                if order < 1:
                    raise ValueError
            except ValueError:
                self.problems.add(
                    f"{row_context}.baseline_order", "expected a positive integer"
                )
                order = 0
            orders[owner].append(order)
            ordered_keys.append((owner, order))
            per_owner_destinations[owner].add(destination)
            destination_counts[destination] += 1

            if destination == owner:
                retained += 1
                expected_class = "source_retained_outlier"
                expected_decision = "approved_retained_outlier"
            else:
                relocated += 1
                expected_class = (
                    "reusable"
                    if destination.startswith("NumStability.Algorithms.")
                    else "source"
                )
                expected_decision = (
                    "preserve_public_name"
                    if branch_id == "B0004"
                    else "approved_owner_block_route"
                )
            self.problems.require(
                row.get("route_class") == expected_class,
                f"{row_context}.route_class",
                f"expected {expected_class!r}",
            )
            decision = row.get("normalization_decision", "")
            self.problems.require(
                decision == expected_decision and DEFERRED_RE.search(decision) is None,
                f"{row_context}.normalization_decision",
                f"expected exact reviewed decision {expected_decision!r}",
            )
            if row.get("visibility") == "private":
                if name in private_routes:
                    self.problems.add(row_context, f"duplicate private name {name}")
                private_routes[name] = (owner, destination)

        self.problems.require(
            ordered_keys == sorted(ordered_keys),
            self.relative(route_path),
            "routes must be sorted by owner and frozen baseline order",
        )
        for owner, owner_orders in orders.items():
            self.problems.require(
                owner_orders == list(range(1, len(owner_orders) + 1)),
                self.relative(route_path),
                f"{owner} baseline_order must be the exact contiguous 1-based sequence",
            )
        self.problems.require(
            dict(destination_counts) == facts["destination_counts"],
            self.relative(route_path),
            f"destination declaration counts must equal {facts['destination_counts']}",
        )
        self.problems.require(
            relocated == facts["relocated"] and retained == facts["retained"],
            self.relative(route_path),
            f"expected relocated/retained {facts['relocated']}/{facts['retained']}, found {relocated}/{retained}",
        )
        self.problems.require(
            len(private_routes) == facts["private"],
            self.relative(route_path),
            f"expected {facts['private']} projected private declarations",
        )

        selector_by_module = {module: selected_path for module, selected_path in selector}
        projected_counts = Counter(owner for owner, _ in declarations)
        module_path = self.phase_dir / "branches" / filenames["modules"]
        _, module_rows = self.read_tsv(
            module_path, self.relative(module_path), module_header
        )
        module_names = [row.get("owner_module", "") for row in module_rows]
        self.problems.require(
            module_names == sorted(selector_by_module)
            and set(module_names) == set(selector_by_module),
            self.relative(module_path),
            "module routes must cover every selector owner once in sorted order",
        )
        declaration_free = 0
        for index, row in enumerate(module_rows):
            row_context = f"{self.relative(module_path)}[{index}]"
            owner = row.get("owner_module", "")
            self.problems.require(
                row.get("path") == selector_by_module.get(owner),
                f"{row_context}.path",
                "module route path must equal the selector path",
            )
            try:
                count = int(row.get("declaration_count", ""))
            except ValueError:
                self.problems.add(
                    f"{row_context}.declaration_count", "expected an integer"
                )
                count = -1
            expected_count = projected_counts.get(owner, 0)
            self.problems.require(
                count == expected_count,
                f"{row_context}.declaration_count",
                f"expected exact projected count {expected_count}",
            )
            if count == 0:
                declaration_free += 1
            listed_destinations = split_values(row.get("destination_modules", ""))
            self.problems.require(
                listed_destinations == sorted(set(listed_destinations)),
                f"{row_context}.destination_modules",
                "destination modules must be sorted and unique",
            )
            routed_destinations = per_owner_destinations.get(owner, set())
            if routed_destinations:
                self.problems.require(
                    set(listed_destinations) == routed_destinations,
                    f"{row_context}.destination_modules",
                    f"must equal routed destinations {sorted(routed_destinations)}",
                )
            else:
                self.problems.require(
                    set(listed_destinations) <= set(facts["destination_counts"]),
                    f"{row_context}.destination_modules",
                    "declaration-free wrapper may name only a reviewed declaration destination",
                )
            action = row.get("compatibility_action", "")
            self.problems.require(
                bool(action.strip()) and DEFERRED_RE.search(action) is None,
                f"{row_context}.compatibility_action",
                "compatibility action must be explicit before activation",
            )
            self.problems.require(
                row.get("review_status") == "approved_before_activation",
                f"{row_context}.review_status",
                "expected approved_before_activation",
            )
        self.problems.require(
            declaration_free == facts["declaration_free"],
            self.relative(module_path),
            f"expected {facts['declaration_free']} declaration-free owners",
        )

        private_path = self.phase_dir / "branches" / filenames["private"]
        _, private_rows = self.read_tsv(
            private_path, self.relative(private_path), private_header
        )
        self.problems.require(
            len(private_rows) == facts["private"],
            self.relative(private_path),
            f"expected exact {facts['private']}-row private map",
        )
        old_names = [row.get("old_private", "") for row in private_rows]
        new_names = [row.get("new_private", "") for row in private_rows]
        self.problems.require(
            old_names == sorted(private_routes)
            and set(old_names) == set(private_routes),
            self.relative(private_path),
            "private map must exactly cover projected private names in sorted order",
        )
        self.problems.require(
            len(new_names) == len(set(new_names)),
            self.relative(private_path),
            "normalized private names must be unique",
        )
        for index, row in enumerate(private_rows):
            row_context = f"{self.relative(private_path)}[{index}]"
            old = row.get("old_private", "")
            new = row.get("new_private", "")
            owner, destination = private_routes.get(old, ("", ""))
            self.problems.require(
                row.get("destination_module") == destination,
                f"{row_context}.destination_module",
                f"expected routed destination {destination!r}",
            )
            self.problems.require(
                bool(old) and bool(new) and DEFERRED_RE.search(" ".join(row.values())) is None,
                row_context,
                "private normalization must be complete and non-deferred",
            )
            if destination == owner:
                self.problems.require(
                    new == old,
                    f"{row_context}.new_private",
                    "retained-owner private identity must remain exact",
                )
            elif destination:
                self.problems.require(
                    new != old and f".{destination}." in new,
                    f"{row_context}.new_private",
                    "relocated private must receive only the reviewed owner-prefix rewrite",
                )

        closure_path = self.phase_dir / "branches" / filenames["closure"]
        _, closure_rows = self.read_tsv(
            closure_path, self.relative(closure_path), closure_header
        )
        self.problems.require(
            len(closure_rows) == facts["private_closure_rows"],
            self.relative(closure_path),
            f"expected exact {facts['private_closure_rows']}-row private closure",
        )
        closure_names = [row.get("declaration", "") for row in closure_rows]
        self.problems.require(
            len(closure_names) == len(set(closure_names)),
            self.relative(closure_path),
            "private closure declarations must be unique",
        )
        seeds = {
            row.get("declaration", "")
            for row in closure_rows
            if row.get("closure_role") == "private_seed"
        }
        self.problems.require(
            seeds == set(private_routes),
            self.relative(closure_path),
            "private closure seeds must exactly equal the private-normalization domain",
        )
        for index, row in enumerate(closure_rows):
            row_context = f"{self.relative(closure_path)}[{index}]"
            role = row.get("closure_role")
            expected_visibility = "private" if role == "private_seed" else "public"
            self.problems.require(
                role in {"private_seed", "reverse_dependent"}
                and row.get("visibility") == expected_visibility
                and row.get("selected_owner") in {"yes", "no"},
                row_context,
                "closure rows require typed seed/dependent role, visibility, and owner flag",
            )
            if role == "private_seed":
                expected_owner = private_routes.get(row.get("declaration", ""), ("", ""))[0]
                self.problems.require(
                    row.get("owner_module") == expected_owner,
                    f"{row_context}.owner_module",
                    f"private seed owner must be {expected_owner!r}",
                )

        test_path = self.phase_dir / "branches" / filenames["tests"]
        _, test_rows = self.read_tsv(
            test_path, self.relative(test_path), test_header
        )
        self.problems.require(
            len(test_rows) == facts["test_rows"],
            self.relative(test_path),
            f"expected exact {facts['test_rows']}-row test plan",
        )
        test_pairs = [
            (row.get("test_class", ""), row.get("target", ""))
            for row in test_rows
        ]
        self.problems.require(
            test_pairs == sorted(test_pairs) and len(test_pairs) == len(set(test_pairs)),
            self.relative(test_path),
            "test class/target pairs must be sorted and unique",
        )
        class_counts = Counter(row.get("test_class", "") for row in test_rows)
        self.problems.require(
            dict(class_counts) == facts["test_classes"],
            self.relative(test_path),
            f"expected exact test-class counts {facts['test_classes']}",
        )
        unique_targets = {row.get("target", "") for row in test_rows}
        self.problems.require(
            len(unique_targets) == facts["test_targets"],
            self.relative(test_path),
            f"expected {facts['test_targets']} distinct test targets",
        )
        by_class = {
            name: {
                row.get("target", "")
                for row in test_rows
                if row.get("test_class") == name
            }
            for name in facts["test_classes"]
        }
        relocated_destinations = {
            destination
            for (owner, _), _metadata in declarations.items()
            for destination in per_owner_destinations.get(owner, set())
            if destination != owner
        }
        self.problems.require(
            by_class.get("old_only", set()) == set(selector_by_module),
            self.relative(test_path),
            "old-only tests must cover every and only historical selector owner",
        )
        for test_class in ("canonical_only", "focused"):
            self.problems.require(
                by_class.get(test_class, set()) == relocated_destinations,
                self.relative(test_path),
                f"{test_class} tests must cover every and only relocated destination",
            )
        for index, row in enumerate(test_rows):
            purpose = row.get("purpose", "")
            self.problems.require(
                bool(purpose.strip()) and DEFERRED_RE.search(purpose) is None,
                f"{self.relative(test_path)}[{index}].purpose",
                "test purpose must be explicit and non-deferred",
            )
        return by_class.get("protected_consumer", set())

    def validate_next_overlap_review(
        self, branch_id: str, facts: dict[str, Any]
    ) -> None:
        path = self.phase_dir / f"branches/{branch_id}-overlap-review.md"
        self.require_next_evidence(branch_id, self.relative(path))
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(self.relative(path), f"cannot read overlap review: {error}")
            return
        folded = " ".join(text.casefold().replace("_", "-").split())
        required = (
            "r11",
            "r12",
            "both directions",
            "owner",
            "destination",
            "direct",
            "transitive",
            "signature",
            "body",
            INTEGRATED_CODE_SHA,
            facts["selector_sha256"].casefold(),
            facts["projection_sha256"].casefold(),
        )
        for token in required:
            if token not in folded:
                self.problems.add(self.relative(path), f"missing overlap token {token!r}")
        self.problems.require(
            "zero" in folded or re.search(r"(?:^|\D)0(?:\D|$)", folded) is not None,
            self.relative(path),
            "must state the zero cross-wave results explicitly",
        )
        self.problems.require(
            DEFERRED_RE.search(text) is None,
            self.relative(path),
            "overlap review may not defer an activation decision",
        )

    def validate_next_joint_evidence(self, state: str | None) -> None:
        authorization_path = self.phase_dir / "reviews/R11-R12-operator-authorization.md"
        overlap_path = self.phase_dir / "reviews/R11-R12-overlap-facts.md"
        projection_replay_path = (
            self.phase_dir / "reviews/R11-R12-projection-replay.md"
        )
        import_path = self.phase_dir / "reviews/R11-shared-import-replacements.tsv"
        union_patch_path = self.phase_dir / "requests/R0003-R0004-union.patch"
        for branch_id in NEXT_BRANCH_FACTS:
            self.require_next_evidence(
                branch_id,
                self.relative(authorization_path),
                NEXT_OPERATOR_AUTHORIZATION_SHA256,
            )
            self.require_next_evidence(
                branch_id,
                self.relative(overlap_path),
                NEXT_OVERLAP_FACTS_SHA256,
            )
            self.require_next_evidence(
                branch_id,
                self.relative(projection_replay_path),
                NEXT_PROJECTION_REPLAY_SHA256,
            )
            self.require_next_evidence(
                branch_id,
                self.relative(union_patch_path),
                NEXT_UNION_PATCH_SHA256,
            )
        self.require_next_evidence(
            "B0003", self.relative(import_path), NEXT_IMPORT_REVIEW_SHA256
        )

        try:
            authorization = authorization_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(
                self.relative(authorization_path),
                f"cannot read operator authorization: {error}",
            )
        else:
            folded = " ".join(authorization.casefold().split())
            for token in (
                "primary-human",
                "claude-lane",
                "claude-local",
                "codex-local",
                "b0004",
                "r12",
                "temporary",
                INTEGRATED_CODE_SHA,
            ):
                if token not in folded:
                    self.problems.add(
                        self.relative(authorization_path),
                        f"missing authority-expansion token {token!r}",
                    )
            self.problems.require(
                "expire" in folded,
                self.relative(authorization_path),
                "temporary operator expansion must state its expiry",
            )

        try:
            overlap = overlap_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(
                self.relative(overlap_path), f"cannot read joint overlap facts: {error}"
            )
        else:
            folded = " ".join(overlap.casefold().split())
            for token in (
                "r11",
                "r12",
                "c0001",
                INTEGRATED_CODE_SHA,
                NEXT_BRANCH_FACTS["B0003"]["selector_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0004"]["selector_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0003"]["projection_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0004"]["projection_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0003"]["request_path_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0004"]["request_path_sha256"].casefold(),
            ):
                if token not in folded:
                    self.problems.add(
                        self.relative(overlap_path),
                        f"missing exact joint-overlap token {token!r}",
                    )
            for category in (
                "owner",
                "destination",
                "direct",
                "transitive",
                "signature",
                "body",
            ):
                self.problems.require(
                    category in folded,
                    self.relative(overlap_path),
                    f"joint overlap evidence omits {category}",
                )
            self.problems.require(
                "both ways" in folded or "both directions" in folded,
                self.relative(overlap_path),
                "joint overlap evidence must cover both directed comparisons",
            )

        try:
            projection_replay = projection_replay_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(
                self.relative(projection_replay_path),
                f"cannot read same-candidate projection replay: {error}",
            )
        else:
            folded = " ".join(projection_replay.casefold().split())
            compact = folded.replace(",", "")
            for token in (
                "primary-human",
                "c0001",
                INTEGRATED_CODE_SHA,
                NEXT_CANDIDATE_SHA256.casefold(),
                NEXT_PROJECTION_CHECKER_SHA256.casefold(),
                NEXT_BRANCH_FACTS["B0003"]["projection_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0004"]["projection_sha256"].casefold(),
                NEXT_BRANCH_FACTS["B0003"]["private_map_sha256"].casefold(),
                "same exact",
                "passed",
            ):
                if token not in folded:
                    self.problems.add(
                        self.relative(projection_replay_path),
                        f"missing projection-replay token {token!r}",
                    )
            for token in ("56903", "649259", "1477", "34", "15172", "18056", "80", "133"):
                if token not in compact:
                    self.problems.add(
                        self.relative(projection_replay_path),
                        f"missing exact projection-replay count {token}",
                    )

        if state in {"active", "delivered", "accepted", "retired"}:
            activation_path = self.phase_dir / "reviews/R11-R12-activation.md"
            pins = [
                self.require_next_evidence(branch_id, self.relative(activation_path))
                for branch_id in NEXT_BRANCH_FACTS
            ]
            self.problems.require(
                all(pin is not None for pin in pins)
                and len({pin.sha256 for pin in pins if pin is not None}) == 1,
                "B0003/B0004 activation evidence",
                "activated branches must pin the same activation review SHA-256",
            )
            try:
                activation = activation_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(
                    self.relative(activation_path), f"cannot read activation review: {error}"
                )
            else:
                folded = " ".join(activation.casefold().split())
                for token in (
                    "primary-human",
                    "c0001",
                    INTEGRATED_CODE_SHA,
                    "b0003",
                    "b0004",
                    "r11",
                    "r12",
                    "active",
                ):
                    if token not in folded:
                        self.problems.add(
                            self.relative(activation_path),
                            f"missing activation token {token!r}",
                        )

    def validate_next_requests(
        self, protected_consumers: dict[str, set[str]]
    ) -> None:
        request_dir = self.phase_dir / "requests"
        controls = {
            "NumStabilityTest.lean",
            "docs/architecture/COMPATIBILITY.md",
            "docs/architecture/layout-exceptions.json",
            "docs/architecture/tiers.json",
        }
        expected_paths = {
            "R0003": {
                path_from_module(module)
                for module in protected_consumers.get("B0003", set())
            }
            | controls,
            "R0004": set(NEXT_REQUEST_OVERLAP),
        }
        request_to_branch = {"R0003": "B0003", "R0004": "B0004"}
        parsed_preimages: dict[str, dict[str, str | None]] = {}
        created_at: set[str] = set()

        for request_id, branch_id in request_to_branch.items():
            facts = NEXT_BRANCH_FACTS[branch_id]
            path = request_dir / f"{request_id}.json"
            request = self.read_json(path, self.relative(path))
            if request is None:
                continue
            self.requests[request_id] = request
            expected_request_status = next_request_status(self.current_checkpoint_id)
            for key, expected in {
                "schema_version": 1,
                "record_kind": "shared_file_request",
                "phase_id": PHASE_ID,
                "request_id": request_id,
                "lane_id": facts["lane"],
                "wave_id": facts["wave"],
                "requester_id": "primary-human",
                "target_checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
                "target_base_sha": INTEGRATED_CODE_SHA,
                "valid_through_checkpoint_id": SUCCESSOR_CHECKPOINT_ID,
                "status": expected_request_status,
                "depends_on": [],
                "blocks": [facts["wave"]],
                "supersedes": None,
                "superseded_by": None,
            }.items():
                self.problems.require(
                    request.get(key) == expected,
                    f"{request_id}.{key}",
                    f"expected {expected!r}, found {request.get(key)!r}",
                )
            timestamp = request.get("created_at")
            self.problems.require(
                isinstance(timestamp, str)
                and RFC3339_RE.fullmatch(timestamp) is not None,
                f"{request_id}.created_at",
                "expected an RFC3339 authority timestamp",
            )
            if isinstance(timestamp, str):
                created_at.add(timestamp)

            paths = request.get("paths")
            if not isinstance(paths, list) or not all(
                isinstance(item, str) for item in paths
            ):
                self.problems.add(f"{request_id}.paths", "expected a string list")
                paths = []
            wanted = expected_paths[request_id]
            self.problems.require(
                paths == sorted(wanted)
                and len(paths) == facts["request_paths"],
                f"{request_id}.paths",
                f"must equal exact reviewed {facts['request_paths']}-path set",
            )
            self.problems.require(
                path_list_sha256(paths) == facts["request_path_sha256"],
                f"{request_id}.paths",
                f"newline path-list SHA-256 must be {facts['request_path_sha256']}",
            )
            if expected_request_status == "active":
                shared_exact = {
                    rule.path for rule in self.shared_rules if rule.match == "exact"
                }
                self.problems.require(
                    set(paths) <= shared_exact,
                    f"{request_id}.paths",
                    "active request paths missing exact shared reservations: "
                    f"{sorted(set(paths)-shared_exact)}",
                )

            expected_preimages = []
            preimage_map: dict[str, str | None] = {}
            for affected in sorted(paths):
                oid = self.git_blob(INTEGRATED_CODE_SHA, affected)
                expected_preimages.append({"blob_oid": oid, "path": affected})
                preimage_map[affected] = oid
            self.problems.require(
                request.get("preimage_blobs") == expected_preimages,
                f"{request_id}.preimage_blobs",
                "must exactly record sorted C0001 blob OIDs for every requested path",
            )
            parsed_preimages[request_id] = preimage_map

            patch = self.artifact(request.get("patch"), f"{request_id}.patch")
            expected_patch_path = self.relative(request_dir / f"{request_id}.patch")
            patch_path: Path | None = None
            if patch is not None:
                self.problems.require(
                    patch.path == expected_patch_path
                    and patch.sha256 == facts["request_patch_sha256"],
                    f"{request_id}.patch",
                    f"must pin {expected_patch_path} at {facts['request_patch_sha256']}",
                )
                patch_path = self.root / patch.path

            post_path = request_dir / f"{request_id}-postimages.tsv"
            post_header, post_rows = self.read_tsv(
                post_path,
                self.relative(post_path),
                (
                    "path",
                    "preimage_blob_oid",
                    "preimage_sha256",
                    "postimage_sha256",
                ),
            )
            postimages = self.validate_postimage_rows(
                post_header,
                post_rows,
                self.relative(post_path),
                set(paths),
                "postimage_sha256",
                base_sha=INTEGRATED_CODE_SHA,
                base_label=SUCCESSOR_CHECKPOINT_ID,
            )
            if post_path.is_file():
                self.problems.require(
                    sha256_path(post_path) == facts["request_postimages_sha256"],
                    self.relative(post_path),
                    f"expected exact postimage SHA-256 {facts['request_postimages_sha256']}",
                )
            if patch_path is not None:
                self.materialize_patch_postimages(
                    request_id,
                    patch_path,
                    set(paths),
                    postimages,
                    base_sha=INTEGRATED_CODE_SHA,
                    base_label=SUCCESSOR_CHECKPOINT_ID,
                )

            if expected_request_status == "active":
                expected_resolution = {
                    "checkpoint_id": None,
                    "commit_sha": None,
                    "reason": None,
                    "resolved_at": None,
                    "resolved_by": None,
                    "validation_evidence": [],
                }
            else:
                resolution = request.get("resolution")
                resolved_at = (
                    resolution.get("resolved_at")
                    if isinstance(resolution, dict)
                    else None
                )
                reason = (
                    resolution.get("reason")
                    if isinstance(resolution, dict)
                    else None
                )
                expected_resolution = {
                    "checkpoint_id": C0002_CHECKPOINT_ID,
                    "commit_sha": C0002_CODE_SHA,
                    "reason": reason,
                    "resolved_at": resolved_at,
                    "resolved_by": "primary-human",
                    "validation_evidence": [
                        {
                            "path": self.relative(
                                request_dir / "R0003-R0004-union-review.md"
                            ),
                            "sha256": NEXT_UNION_REVIEW_SHA256,
                        }
                    ],
                }
                self.problems.require(
                    isinstance(reason, str) and bool(reason.strip()),
                    f"{request_id}.resolution.reason",
                    "applied request requires a nonempty reviewed-union reason",
                )
                self.problems.require(
                    isinstance(resolved_at, str)
                    and RFC3339_RE.fullmatch(resolved_at) is not None,
                    f"{request_id}.resolution.resolved_at",
                    "applied request requires an RFC3339 resolution timestamp",
                )
            self.problems.require(
                request.get("resolution") == expected_resolution,
                f"{request_id}.resolution",
                f"expected exact {expected_request_status} resolution",
            )
            rationale = str(request.get("rationale", "")).upper()
            for digest, label in (
                (facts["request_path_sha256"], "path list"),
                (facts["request_patch_sha256"], "request patch"),
                (facts["request_postimages_sha256"], "request postimages"),
                (NEXT_UNION_PATCH_SHA256, "reviewed union patch"),
                (NEXT_UNION_POSTIMAGES_SHA256, "reviewed union postimages"),
                (NEXT_UNION_REVIEW_SHA256, "reviewed union review"),
            ):
                if digest not in rationale:
                    self.problems.add(
                        f"{request_id}.rationale",
                        f"must hash-pin {label} SHA-256 {digest}",
                    )
            self.problems.require(
                INTEGRATED_CODE_SHA.upper() in rationale,
                f"{request_id}.rationale",
                "must name the exact C0001 code preimage",
            )

            branch = self.branch_records.get(branch_id, {})
            self.problems.require(
                branch.get("shared_request_ids") == [request_id],
                f"{branch_id}.shared_request_ids",
                f"expected exactly [{request_id!r}]",
            )

        self.problems.require(
            len(created_at) == 1,
            "R0003/R0004 created_at",
            "the independently generated request pair must share one authority timestamp",
        )
        if set(parsed_preimages) == {"R0003", "R0004"}:
            first, second = parsed_preimages["R0003"], parsed_preimages["R0004"]
            overlap = set(first) & set(second)
            self.problems.require(
                overlap == NEXT_REQUEST_OVERLAP,
                "R0003/R0004 request overlap",
                f"expected exact three-path intersection {sorted(NEXT_REQUEST_OVERLAP)}, found {sorted(overlap)}",
            )
            for affected in overlap:
                self.problems.require(
                    first[affected] == second[affected],
                    "R0003/R0004 request overlap",
                    f"{affected} is not rooted in the same C0001 preimage blob",
                )

        union_paths = expected_paths["R0003"] | expected_paths["R0004"]
        union_patch_path = request_dir / "R0003-R0004-union.patch"
        union_manifest_path = request_dir / "R0003-R0004-union-postimages.tsv"
        union_review_path = request_dir / "R0003-R0004-union-review.md"
        for artifact_path, expected_digest, label in (
            (union_patch_path, NEXT_UNION_PATCH_SHA256, "union patch"),
            (
                union_manifest_path,
                NEXT_UNION_POSTIMAGES_SHA256,
                "union postimages",
            ),
            (union_review_path, NEXT_UNION_REVIEW_SHA256, "union review"),
        ):
            if not artifact_path.is_file():
                self.problems.add(self.relative(artifact_path), f"missing {label}")
            else:
                self.problems.require(
                    sha256_path(artifact_path) == expected_digest,
                    self.relative(artifact_path),
                    f"expected exact SHA-256 {expected_digest}",
                )

        union_header, union_rows = self.read_tsv(
            union_manifest_path,
            self.relative(union_manifest_path),
            (
                "path",
                "preimage_blob_oid",
                "preimage_sha256",
                "union_postimage_sha256",
                "source_requests",
            ),
        )
        union_postimages = self.validate_postimage_rows(
            union_header,
            union_rows,
            self.relative(union_manifest_path),
            union_paths,
            "union_postimage_sha256",
            base_sha=INTEGRATED_CODE_SHA,
            base_label=SUCCESSOR_CHECKPOINT_ID,
        )
        for index, row in enumerate(union_rows):
            affected = row.get("path", "")
            expected_sources = (
                "R0003+R0004" if affected in NEXT_REQUEST_OVERLAP else "R0003"
            )
            self.problems.require(
                row.get("source_requests") == expected_sources,
                f"{self.relative(union_manifest_path)}[{index}].source_requests",
                f"expected exact provenance {expected_sources!r}",
            )
        if union_patch_path.is_file():
            self.materialize_patch_postimages(
                "R0003/R0004 reviewed union",
                union_patch_path,
                union_paths,
                union_postimages,
                base_sha=INTEGRATED_CODE_SHA,
                base_label=SUCCESSOR_CHECKPOINT_ID,
            )

        try:
            union_review = union_review_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(
                self.relative(union_review_path), f"cannot read union review: {error}"
            )
            union_review = ""
        folded_review = " ".join(union_review.casefold().split())
        for token in (
            "r0003",
            "r0004",
            "c0001",
            INTEGRATED_CODE_SHA,
            NEXT_BRANCH_FACTS["B0003"]["request_path_sha256"].casefold(),
            NEXT_BRANCH_FACTS["B0004"]["request_path_sha256"].casefold(),
            NEXT_BRANCH_FACTS["B0003"]["request_patch_sha256"].casefold(),
            NEXT_BRANCH_FACTS["B0004"]["request_patch_sha256"].casefold(),
            NEXT_UNION_PATCH_SHA256.casefold(),
            NEXT_UNION_POSTIMAGES_SHA256.casefold(),
            NEXT_IMPORT_REVIEW_SHA256.casefold(),
            "reverse",
        ):
            if token not in folded_review:
                self.problems.add(
                    self.relative(union_review_path),
                    f"missing reviewed-union token {token!r}",
                )
        for affected in sorted(NEXT_REQUEST_OVERLAP):
            if affected.casefold() not in folded_review:
                self.problems.add(
                    self.relative(union_review_path),
                    f"review omits exact intersection path {affected}",
                )
        self.problems.require(
            ("commute" in folded_review or "identical" in folded_review)
            and "sequential whole-file replacement" in folded_review,
            self.relative(union_review_path),
            "must record commutative same-preimage reconciliation without sequential replacement",
        )

        import_review_path = self.phase_dir / "reviews/R11-shared-import-replacements.tsv"
        _, import_rows = self.read_tsv(
            import_review_path,
            self.relative(import_review_path),
            ("consumer_path", "preimage_blob_oid", "old_import", "new_import"),
        )
        self.problems.require(
            len(import_rows) == 209,
            self.relative(import_review_path),
            "expected exact 209 reviewed import occurrences",
        )
        expected_consumers = {
            path_from_module(module)
            for module in protected_consumers.get("B0003", set())
        }
        actual_consumers = {row.get("consumer_path", "") for row in import_rows}
        self.problems.require(
            actual_consumers == expected_consumers,
            self.relative(import_review_path),
            "import-occurrence review must cover every and only R11 protected consumers",
        )
        for index, row in enumerate(import_rows):
            consumer = row.get("consumer_path", "")
            self.problems.require(
                row.get("preimage_blob_oid")
                == self.git_blob(INTEGRATED_CODE_SHA, consumer),
                f"{self.relative(import_review_path)}[{index}].preimage_blob_oid",
                "must equal the exact C0001 consumer blob",
            )
            self.problems.require(
                bool(row.get("old_import", ""))
                and bool(row.get("new_import", ""))
                and row.get("old_import") != row.get("new_import"),
                f"{self.relative(import_review_path)}[{index}]",
                "import replacement must name distinct nonempty old/new modules",
            )

    def r03_expected_digest(self, key: str, context: str) -> str | None:
        accepted_overrides = {
            "projection_record": R03_ACCEPTED_PROJECTION_RECORD_SHA256,
            "request_record": R03_APPLIED_REQUEST_RECORD_SHA256,
        }
        expected = (
            accepted_overrides.get(key, R03_ARTIFACT_SHA256.get(key))
            if self.current_checkpoint_id
            in {
                C0003_CHECKPOINT_ID,
                C0004_CHECKPOINT_ID,
                C0005_CHECKPOINT_ID,
                C0006_CHECKPOINT_ID,
                C0007_CHECKPOINT_ID,
                C0008_CHECKPOINT_ID,
            }
            else R03_ARTIFACT_SHA256.get(key)
        )
        if expected is None:
            self.problems.add(
                context,
                f"PENDING_R03_SHA256: validator constant for {key!r} has not been ratcheted",
            )
            return None
        self.problems.require(
            SHA256_RE.fullmatch(expected) is not None,
            context,
            f"malformed R03 SHA-256 constant for {key!r}",
        )
        return expected

    def require_r03_evidence(self, key: str) -> Artifact | None:
        path = R03_EVIDENCE_PATHS[key]
        matches = [
            artifact
            for artifact in self.branch_evidence.get(R03_BRANCH_ID, [])
            if artifact.path == path
        ]
        self.problems.require(
            len(matches) == 1,
            f"{R03_BRANCH_ID}.refresh.evidence",
            f"must hash-pin exactly one {path}",
        )
        if len(matches) != 1:
            return None
        expected = self.r03_expected_digest(key, f"R03 artifact {key}")
        if expected is not None:
            self.problems.require(
                matches[0].sha256 == expected,
                f"{R03_BRANCH_ID}.refresh.evidence[{path}]",
                f"expected exact SHA-256 {expected}",
            )
            evidence_path = self.root / matches[0].path
            if evidence_path.is_file():
                self.problems.require(
                    sha256_path(evidence_path) == expected,
                    matches[0].path,
                    f"R03 evidence content must equal exact SHA-256 {expected}",
                )
        return matches[0]

    def validate_r04_r08_epoch(self) -> None:
        """Ratchet the exact-C0004 R04/R08 packet through C0005 acceptance."""

        context = "C0004-rooted R04/R08 through C0005 epoch"
        self.problems.require(
            self.current_checkpoint_id
            in {
                C0004_CHECKPOINT_ID,
                C0005_CHECKPOINT_ID,
                C0006_CHECKPOINT_ID,
                C0007_CHECKPOINT_ID,
                C0008_CHECKPOINT_ID,
            },
            context,
            "R04/R08 controls require current checkpoint C0004 through C0007",
        )
        planned_ancestor = self.git(
            "merge-base",
            "--is-ancestor",
            C0005_PLANNED_CONTROL_SHA,
            "HEAD",
            check=False,
        )
        self.problems.require(
            planned_ancestor.returncode == 0,
            f"{context}.planned control",
            f"exact planned-control commit {C0005_PLANNED_CONTROL_SHA} must be an ancestor of HEAD",
        )
        planned_parent = self.git(
            "rev-parse", f"{C0005_PLANNED_CONTROL_SHA}^", check=False
        )
        self.problems.require(
            planned_parent.returncode == 0
            and planned_parent.stdout.strip() == C0005_PLANNED_CONTROL_PARENT_SHA,
            f"{context}.planned control",
            "planned-control commit must retain its exact reviewed parent",
        )
        production_scope = (
            "NumStability",
            "NumStability.lean",
            "NumStabilityTest",
            "NumStabilityTest.lean",
            "benchmark-results",
        )
        production_diff_args = ["diff", "--name-only", C0004_CODE_SHA]
        if (self.root / R07_INTEGRATION_AUTHORIZATION_PATH).is_file():
            production_diff_args.append(R07_ACCEPTED_CONTROL_SHA)
        production_diff_args.extend(["--", *production_scope])
        production_diff = self.git(*production_diff_args, check=False)
        live_production_paths = (
            {line.strip() for line in production_diff.stdout.splitlines() if line.strip()}
            if production_diff.returncode == 0
            else None
        )

        activation_path = self.root / C0005_ACTIVATION_REVIEW_PATH
        branch_records: dict[str, dict[str, Any]] = {}
        statuses: dict[str, Any] = {}
        for wave, facts in C0005_BRANCH_FACTS.items():
            branch_path = self.phase_dir / f"branches/{facts['branch_id']}.json"
            branch = self.read_json(branch_path, self.relative(branch_path))
            if branch is not None:
                branch_records[wave] = branch
                statuses[wave] = branch.get("status")
            else:
                statuses[wave] = None
            historical = self.git_bytes(
                "show",
                f"{C0005_PLANNED_CONTROL_SHA}:{self.relative(branch_path)}",
                check=False,
            )
            historical_digest = (
                hashlib.sha256(historical.stdout).hexdigest().upper()
                if historical.returncode == 0
                else None
            )
            self.problems.require(
                historical_digest == facts["planned_record_sha256"],
                f"{context}[{facts['branch_id']}].historical planned record",
                "planned-control history must retain exact branch-record SHA-256 "
                f"{facts['planned_record_sha256']}",
            )
        c0005_checkpoint_exists = (
            self.phase_dir / "checkpoints/C0005.json"
        ).is_file()
        state = validate_c0005_epoch_state(
            statuses,
            current_checkpoint_id=self.current_checkpoint_id,
            activation_review_exists=activation_path.is_file(),
            c0005_checkpoint_exists=c0005_checkpoint_exists,
            problems=self.problems,
            context=context,
        )
        terminal = state == "accepted"
        integrated = state in {"delivered", "accepted"}
        gates_path = self.phase_dir / "checkpoints/C0005-gates.md"
        gate_evidence_sha256 = (
            sha256_path(gates_path)
            if terminal and gates_path.is_file()
            else C0005_CANDIDATE_GATES_SHA256
        )
        if integrated:
            self.validate_c0005_prepared_evidence(candidate_gates=not terminal)

        if live_production_paths is None:
            self.problems.add(context, "cannot diff live production against exact C0004")
        elif integrated:
            # The integrated tree is exactly: both immutable delivery diffs, the
            # union's production paths, and the two reviewed integration
            # follow-ups.  Nothing else may differ from exact C0004.
            allowed: set[str] = set(C0005_INTEGRATION_FOLLOWUPS)
            for wave_facts in C0005_BRANCH_FACTS.values():
                delivery_diff = self.git(
                    "diff",
                    "--name-only",
                    C0004_CODE_SHA,
                    wave_facts["delivery_sha"],
                    "--",
                    *production_scope,
                    check=False,
                )
                if delivery_diff.returncode != 0:
                    self.problems.add(
                        context,
                        f"cannot diff delivery {wave_facts['delivery_sha']} against C0004",
                    )
                    continue
                allowed |= {
                    line.strip()
                    for line in delivery_diff.stdout.splitlines()
                    if line.strip()
                }
            union_manifest_path = (
                self.phase_dir / "requests/R0009-R0010-union-postimages.tsv"
            )
            _, union_manifest_rows = self.read_tsv(
                union_manifest_path,
                self.relative(union_manifest_path),
                ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
            )
            allowed |= {
                row.get("path")
                for row in union_manifest_rows
                if isinstance(row.get("path"), str)
                and row["path"].startswith(("NumStability", "benchmark-results"))
            }
            unexpected = sorted(live_production_paths - allowed)
            self.problems.require(
                not unexpected,
                context,
                "integrated production state may only differ from exact C0004 by the "
                "two immutable delivery diffs, the reviewed union, and the reviewed "
                f"integration follow-ups; unexpected: {unexpected[:5]}",
            )
        else:
            self.problems.require(
                not live_production_paths,
                context,
                "C0004-to-live control state must not change production, tests, or benchmark evidence",
            )
        if state in {"active", "delivered", "accepted"} and activation_path.is_file():
            self.problems.require(
                sha256_path(activation_path) == C0005_ACTIVATION_REVIEW_SHA256,
                C0005_ACTIVATION_REVIEW_PATH,
                "activation review must retain exact SHA-256 "
                f"{C0005_ACTIVATION_REVIEW_SHA256}",
            )
            try:
                activation_text = activation_path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(
                    C0005_ACTIVATION_REVIEW_PATH,
                    f"cannot read activation review: {error}",
                )
            else:
                validate_c0005_activation_review_text(
                    activation_text,
                    self.problems,
                    context=C0005_ACTIVATION_REVIEW_PATH,
                )

        milestones = self.phase.get("milestones")
        milestone_map = {
            item.get("milestone_id"): item
            for item in milestones
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        } if isinstance(milestones, list) else {}
        validate_c0005_milestone_lifecycle(
            milestone_map,
            state or "invalid",
            self.problems,
            context=f"{context}.milestones",
            m07_accepted=(
                self.phase_dir / "checkpoints/C0006.json"
            ).is_file(),
        )

        authority = self.phase.get("authority")
        lanes = authority.get("lanes") if isinstance(authority, dict) else None
        claude_lanes = [
            lane
            for lane in lanes or []
            if isinstance(lane, dict) and lane.get("lane_id") == "claude-lane"
        ]
        self.problems.require(
            len(claude_lanes) == 1
            and claude_lanes[0].get("owner_id") == "primary-human"
            and claude_lanes[0].get("operator_ids")
            == (["claude-local"] if terminal else ["claude-local", "codex-local"]),
            f"{context}.authority",
            "temporary B0008 Codex grant must expire exactly at C0005",
        )

        inventory_path = self.phase_dir / "checkpoints/C0004-inventory.tsv"
        _, inventory = self.read_tsv(
            inventory_path, self.relative(inventory_path), SCOPE_HEADER
        )
        self.problems.require(
            len(inventory) == C0004_METRICS["production_modules"],
            self.relative(inventory_path),
            "must retain all 2,766 exact C0004 inventory rows",
        )
        inventory_paths = {row.get("path", "") for row in inventory}
        self.problems.require(
            len(inventory_paths) == len(inventory),
            self.relative(inventory_path),
            "C0004 inventory paths must be unique",
        )
        base_tree_paths = self.git_tree_paths(C0004_CODE_SHA)
        selected_by_wave: dict[str, set[str]] = {}
        destination_prefixes: dict[str, list[str]] = {}

        route_header = (
            "baseline_owner_module",
            "baseline_declaration_name",
            "visibility",
            "kind",
            "baseline_order",
            "destination_module",
            "route_class",
            "normalization_decision",
        )
        private_header = ("old_private", "new_private", "destination_module")
        closure_header = (
            "declaration",
            "owner_module",
            "visibility",
            "selected_owner",
            "closure_role",
        )
        dag_header = (
            "from_destination",
            "to_destination",
            "signature_edges",
            "body_edges",
        )
        tier_header = ("module", "tier", "reason")
        test_header = ("test_class", "target", "purpose")
        consumer_header = (
            "consumer_module",
            "consumer_path",
            "consumer_scope",
            "old_import",
            "new_import",
        )

        for wave, facts in C0005_BRANCH_FACTS.items():
            branch_id = facts["branch_id"]
            wave_context = f"{context}[{branch_id}]"
            selector_path = self.phase_dir / f"selectors/{wave}.tsv"
            _, selector = self.read_tsv(
                selector_path, self.relative(selector_path), SELECTOR_HEADER
            )
            expected_selector = sorted(
                (
                    (row.get("module", ""), row.get("path", ""))
                    for row in inventory
                    if row.get("wave_id") == wave
                ),
                key=lambda row: row[0],
            )
            actual_selector = [
                (row.get("module", ""), row.get("path", "")) for row in selector
            ]
            self.problems.require(
                len(selector) == facts["selector_count"]
                and actual_selector == expected_selector,
                self.relative(selector_path),
                "selector must equal all and only exact C0004 inventory rows for the wave",
            )
            selected_paths = {path for _module, path in actual_selector}
            selected_modules = {module for module, _path in actual_selector}
            selected_by_wave[wave] = selected_paths

            branch_path = self.phase_dir / f"branches/{branch_id}.json"
            branch = branch_records.get(wave)
            if branch is None:
                continue
            if state in {"planned", "active"}:
                expected_record_sha256 = facts[f"{state}_record_sha256"]
                self.problems.require(
                    sha256_path(branch_path) == expected_record_sha256,
                    self.relative(branch_path),
                    f"{state} branch record must hash to {expected_record_sha256}",
                )
            validate_c0005_branch_header(
                branch,
                wave,
                facts,
                self.problems,
                expected_status=state or "invalid",
                context=wave_context,
            )
            validate_c0005_branch_lifecycle(
                branch,
                facts,
                state or "invalid",
                self.problems,
                context=wave_context,
            )
            if state in {"delivered", "accepted"}:
                delivered_record = self.git_json(
                    C0005_CODE_SHA,
                    branch_path,
                    f"{wave_context}.exact delivered record",
                )
                if delivered_record is not None:
                    expected_record = json.loads(json.dumps(delivered_record))
                    if state == "accepted":
                        expected_record["status"] = state
                        expected_record["integration"] = {
                            "accepted_checkpoint_id": C0005_CHECKPOINT_ID,
                            "accepted_sha": C0005_CODE_SHA,
                            "method": "merge",
                        }
                        expected_record["retirement"] = {
                            "ancestry_checkpoint_id": None,
                            "remote_ref": facts["remote_ref"],
                            "retired_at": None,
                            "retired_by": None,
                            "rule": "delivery_ancestor_of_green_checkpoint",
                            "status": "due",
                        }
                        terminal_paths = {
                            self.relative(
                                self.phase_dir
                                / f"projections/{facts['projection_id']}.json"
                            ),
                            self.relative(
                                self.phase_dir / f"requests/{facts['request_id']}.json"
                            ),
                        }
                        replacements: dict[str, str] = {}
                        for evidence_path in terminal_paths:
                            artifact_path = self.root / evidence_path
                            if artifact_path.is_file():
                                replacements[evidence_path] = sha256_path(artifact_path)
                            else:
                                self.problems.add(
                                    f"{wave_context}.terminal evidence",
                                    f"missing terminal artifact {evidence_path}",
                                )
                        expected_record = ratchet_c0005_terminal_evidence(
                            expected_record,
                            replacements,
                            self.problems,
                            context=f"{wave_context}.terminal evidence",
                        )
                    self.problems.require(
                        branch == expected_record,
                        self.relative(branch_path),
                        "only exact C0005 integration, due-retirement, and terminal P/R "
                        "evidence fields may differ from the immutable delivered record",
                    )

            owned = branch.get("owned_paths")
            actual_owned = {
                item.get("path")
                for item in owned or []
                if isinstance(item, dict) and item.get("match") == "exact"
            }
            self.problems.require(
                isinstance(owned, list)
                and len(owned) == len(actual_owned) == facts["selector_count"]
                and actual_owned == selected_paths,
                f"{wave_context}.owned_paths",
                "must be exact rules for every and only selector path",
            )
            prefix_file = self.phase_dir / f"branches/{branch_id}-branch-prefixes.txt"
            try:
                prefixes = prefix_file.read_text(encoding="utf-8").splitlines()
            except OSError as error:
                prefixes = []
                self.problems.add(self.relative(prefix_file), f"cannot read: {error}")
            actual_destinations = [
                item.get("path")
                for item in branch.get("destination_prefixes") or []
                if isinstance(item, dict) and item.get("match") == "prefix"
            ]
            self.problems.require(
                len(prefixes) == facts["prefix_count"]
                and actual_destinations == prefixes,
                f"{wave_context}.destination_prefixes",
                "must exactly equal the frozen casefold-vacant branch-prefix list",
            )
            destination_prefixes[wave] = prefixes
            folded = [prefix.casefold() for prefix in prefixes]
            self.problems.require(
                len(folded) == len(set(folded))
                and all(
                    not (left.startswith(right) or right.startswith(left))
                    for index, left in enumerate(folded)
                    for right in folded[index + 1 :]
                ),
                f"{wave_context}.destination_prefixes",
                "prefixes must be casefold-unique and mutually non-ancestor",
            )
            occupied = [
                (prefix, path)
                for prefix in folded
                for path in base_tree_paths
                if path.casefold() == prefix.rstrip("/") + ".lean"
                or path.casefold().startswith(prefix)
            ]
            self.problems.require(
                not occupied,
                f"{wave_context}.destination_prefixes",
                f"all prefixes must be vacant in exact C0004; found {occupied[:5]}",
            )

            forbidden = branch.get("forbidden_paths")
            forbidden_exact = {
                item.get("path")
                for item in forbidden or []
                if isinstance(item, dict) and item.get("match") == "exact"
            }
            forbidden_prefix = {
                normalize_path(item.get("path", ""))
                for item in forbidden or []
                if isinstance(item, dict) and item.get("match") == "prefix"
            }
            expected_prefix = set(NEXT_PROTECTED_PREFIXES) - {".github"}
            self.problems.require(
                len(forbidden_exact) == facts["forbidden_count"]
                and forbidden_exact == inventory_paths - selected_paths
                and forbidden_prefix == expected_prefix,
                f"{wave_context}.forbidden_paths",
                "must equal the exact selector complement plus five protected prefixes",
            )

            evidence = ((branch.get("refresh") or {}).get("evidence"))
            evidence_map: dict[str, str] = {}
            if not isinstance(evidence, list):
                self.problems.add(f"{wave_context}.refresh.evidence", "expected a list")
            else:
                for index, item in enumerate(evidence):
                    artifact_value = self.artifact(
                        item, f"{wave_context}.refresh.evidence[{index}]"
                    )
                    if artifact_value is not None:
                        evidence_map[artifact_value.path] = artifact_value.sha256
            for local_path, digest in facts["artifacts"].items():
                full_path = (DEFAULT_PHASE_DIR / local_path).as_posix()
                artifact_path = self.root / full_path
                self.problems.require(
                    evidence_map.get(full_path) == digest,
                    f"{wave_context}.refresh.evidence[{full_path}]",
                    f"must hash-pin exact artifact SHA-256 {digest}",
                )
                if artifact_path.is_file():
                    self.problems.require(
                        sha256_path(artifact_path) == digest,
                        full_path,
                        f"artifact content must hash to {digest}",
                    )

            route_path = self.phase_dir / f"branches/{branch_id}-declaration-routes.tsv"
            _, routes = self.read_tsv(
                route_path, self.relative(route_path), route_header
            )
            route_owners: dict[str, list[int]] = defaultdict(list)
            routed_declarations: set[str] = set()
            produced_destinations: set[str] = set()
            private_declarations: set[str] = set()
            for index, row in enumerate(routes):
                owner = row.get("baseline_owner_module", "")
                declaration = row.get("baseline_declaration_name", "")
                try:
                    order = int(row.get("baseline_order", ""))
                except ValueError:
                    order = -1
                    self.problems.add(
                        f"{self.relative(route_path)}[{index}].baseline_order",
                        "must be a zero-based integer",
                    )
                route_owners[owner].append(order)
                if declaration in routed_declarations:
                    self.problems.add(
                        self.relative(route_path),
                        f"duplicate routed declaration {declaration}",
                    )
                routed_declarations.add(declaration)
                destination = row.get("destination_module", "")
                if destination != "-":
                    produced_destinations.add(destination)
                if row.get("visibility") == "private":
                    private_declarations.add(declaration)
            self.problems.require(
                len(routes) == facts["route_count"]
                and set(route_owners) <= selected_modules
                and all(orders == list(range(len(orders))) for orders in route_owners.values()),
                self.relative(route_path),
                "routes must be total, unique, and zero-based contiguous per selected owner",
            )
            self.problems.require(
                len(produced_destinations) == facts["destination_count"],
                self.relative(route_path),
                "route destinations must equal the frozen production destination count",
            )

            private_path = self.phase_dir / f"branches/{branch_id}-private-normalization.tsv"
            _, private_rows = self.read_tsv(
                private_path, self.relative(private_path), private_header
            )
            old_private = [row.get("old_private", "") for row in private_rows]
            identity_count = sum(
                row.get("old_private") == row.get("new_private") for row in private_rows
            )
            self.problems.require(
                len(private_rows) == facts["private_count"]
                and len(set(old_private)) == len(old_private)
                and set(old_private) == private_declarations
                and identity_count == facts["private_identity_count"],
                self.relative(private_path),
                "private map must be total with the exact frozen identity census",
            )

            closure_path = self.phase_dir / f"branches/{branch_id}-private-closure.tsv"
            _, closure_rows = self.read_tsv(
                closure_path, self.relative(closure_path), closure_header
            )
            self.problems.require(
                len(closure_rows) == facts["closure_count"],
                self.relative(closure_path),
                "private reverse-closure row count drifted",
            )

            dag_path = self.phase_dir / f"branches/{branch_id}-destination-dag.tsv"
            _, dag_rows = self.read_tsv(dag_path, self.relative(dag_path), dag_header)
            adjacency: dict[str, set[str]] = defaultdict(set)
            nodes: set[str] = set()
            signature_total = body_total = 0
            for row in dag_rows:
                source = row.get("from_destination", "")
                target = row.get("to_destination", "")
                nodes.update((source, target))
                adjacency[source].add(target)
                try:
                    signature_total += int(row.get("signature_edges", ""))
                    body_total += int(row.get("body_edges", ""))
                except ValueError:
                    self.problems.add(self.relative(dag_path), "edge counts must be integers")
            indegree = {node: 0 for node in nodes}
            for targets in adjacency.values():
                for target in targets:
                    indegree[target] += 1
            queue = [node for node, degree in indegree.items() if degree == 0]
            visited = 0
            while queue:
                node = queue.pop()
                visited += 1
                for target in adjacency.get(node, set()):
                    indegree[target] -= 1
                    if indegree[target] == 0:
                        queue.append(target)
            self.problems.require(
                len(dag_rows) == facts["dag_count"]
                and signature_total == facts["dag_signature_edges"]
                and body_total == facts["dag_body_edges"]
                and visited == len(nodes),
                self.relative(dag_path),
                "destination DAG count or acyclicity drifted",
            )

            tier_path = self.phase_dir / f"branches/{branch_id}-tier-assignments.tsv"
            _, tier_rows = self.read_tsv(tier_path, self.relative(tier_path), tier_header)
            self.problems.require(
                Counter(row.get("tier", "") for row in tier_rows) == facts["tier_counts"],
                self.relative(tier_path),
                f"tier census must equal {facts['tier_counts']}",
            )
            test_path = self.phase_dir / f"branches/{branch_id}-test-plan.tsv"
            _, test_rows = self.read_tsv(test_path, self.relative(test_path), test_header)
            self.problems.require(
                len(test_rows) == facts["test_count"],
                self.relative(test_path),
                "branch-specific planned test census drifted",
            )
            manifest_path = self.phase_dir / f"branches/{branch_id}-post-move-import-manifest.tsv"
            _, manifest_rows = self.read_tsv(
                manifest_path, self.relative(manifest_path), None
            )
            self.problems.require(
                len(manifest_rows) == facts["import_manifest_count"],
                self.relative(manifest_path),
                "post-move import manifest row count drifted",
            )
            consumer_path = self.phase_dir / f"branches/{branch_id}-consumers.tsv"
            _, consumer_rows = self.read_tsv(
                consumer_path, self.relative(consumer_path), consumer_header
            )
            self.problems.require(
                all(all(value != "" for value in row.values()) for row in consumer_rows),
                self.relative(consumer_path),
                "consumer plan must not contain blank cells",
            )
            algorithm_rows = [
                row
                for row in consumer_rows
                if row.get("consumer_module") == "NumStability.Algorithms"
            ]
            if wave == "R04":
                self.problems.require(
                    len(algorithm_rows) == 17
                    and sum(row["old_import"] != row["new_import"] for row in algorithm_rows) == 12
                    and sum(row["old_import"] == row["new_import"] for row in algorithm_rows) == 5,
                    self.relative(consumer_path),
                    "R04 Algorithms plan must replace 12 imports and retain exactly five",
                )
            else:
                self.problems.require(
                    len(algorithm_rows) == 42
                    and all(row.get("new_import") == "-" for row in algorithm_rows),
                    self.relative(consumer_path),
                    "R08 Algorithms plan must contain exactly 42 deletions",
                )

            if state == "planned":
                for ref in (
                    facts["remote_ref"],
                    f"refs/remotes/origin/{facts['branch_name']}",
                ):
                    present = self.git("show-ref", "--verify", "--quiet", ref, check=False)
                    self.problems.require(
                        present.returncode != 0,
                        f"{wave_context}.ref",
                        f"planned control must not create {ref}",
                    )
                worktrees = self.git("worktree", "list", "--porcelain", check=False)
                self.problems.require(
                    facts["branch_name"] not in worktrees.stdout
                    and facts["planned_worktree"] not in worktrees.stdout
                    and not Path(facts["planned_worktree"]).exists(),
                    f"{wave_context}.worktree",
                    "planned control must not create the worker branch or named worktree",
                )

            projection_id = facts["projection_id"]
            projection_facts = C0005_PROJECTION_FACTS[projection_id]
            projection_record_path = self.phase_dir / f"projections/{projection_id}.json"
            projection = self.read_json(
                projection_record_path, self.relative(projection_record_path)
            )
            graph_path = self.phase_dir / f"projections/{projection_id}.tsv.gz"
            if terminal and projection is not None:
                active_projection = self.git_json(
                    C0005_CODE_SHA,
                    projection_record_path,
                    f"{wave_context}.active projection",
                )
                if active_projection is not None:
                    validate_c0005_retired_projection(
                        projection,
                        active_projection,
                        self.problems,
                        context=self.relative(projection_record_path),
                    )
            else:
                self.problems.require(
                    projection_record_path.is_file()
                    and sha256_path(projection_record_path)
                    == projection_facts["record_sha256"],
                    self.relative(projection_record_path),
                    "active projection record hash drifted",
                )
            self.problems.require(
                graph_path.is_file()
                and sha256_path(graph_path) == projection_facts["graph_sha256"],
                self.relative(graph_path),
                "planned projection graph hash drifted",
            )
            if projection is not None:
                self.problems.require(
                    projection.get("status") == ("retired" if terminal else "active")
                    and projection.get("wave_id") == wave
                    and projection.get("base_checkpoint_id") == C0004_CHECKPOINT_ID
                    and projection.get("expected_counts") == dict(projection_facts["counts"]),
                    self.relative(projection_record_path),
                    "projection must be active at C0004 with exact incident counts",
                )
            try:
                projection_payload = gzip.decompress(graph_path.read_bytes())
            except (OSError, gzip.BadGzipFile) as error:
                projection_payload = b""
                self.problems.add(self.relative(graph_path), f"cannot decompress: {error}")
            if projection_payload:
                self.problems.require(
                    hashlib.sha256(projection_payload).hexdigest().upper()
                    == projection_facts["payload_sha256"],
                    self.relative(graph_path),
                    "uncompressed projection payload hash drifted",
                )
                records = projection_payload.decode("utf-8").splitlines()
                declarations = [row for row in records if row.startswith("declaration\t")]
                signature_edges = [row for row in records if row.startswith("edge\tsignature\t")]
                body_edges = [row for row in records if row.startswith("edge\tbody\t")]
                union_edges = {
                    tuple(row.split("\t")[2:4])
                    for row in signature_edges + body_edges
                }
                actual_counts = Counter(
                    {
                        "declarations": len(declarations),
                        "signature_edges": len(signature_edges),
                        "body_edges": len(body_edges),
                        "union_edges": len(union_edges),
                    }
                )
                self.problems.require(
                    records[:1] == ["format\t2"]
                    and actual_counts == projection_facts["counts"],
                    self.relative(graph_path),
                    "projection payload must be exact format 2 with pinned counts",
                )

        self.problems.require(
            selected_by_wave.get("R04", set()).isdisjoint(selected_by_wave.get("R08", set())),
            context,
            "R04/R08 owner sets must be disjoint",
        )
        cross_prefix = [
            (left, right)
            for left in destination_prefixes.get("R04", [])
            for right in destination_prefixes.get("R08", [])
            if left.casefold() == right.casefold()
            or left.casefold().startswith(right.casefold())
            or right.casefold().startswith(left.casefold())
        ]
        self.problems.require(
            not cross_prefix,
            context,
            f"peer branch prefixes must have zero exact/ancestor overlap: {cross_prefix[:5]}",
        )

        request_paths: dict[str, set[str]] = {}
        request_postimages: dict[str, dict[str, str]] = {}
        request_records: dict[str, dict[str, Any]] = {}
        for request_id in ("R0009", "R0010"):
            facts = C0005_REQUEST_FACTS[request_id]
            request_context = f"{context}[{request_id}]"
            record_path = self.phase_dir / f"requests/{request_id}.json"
            patch_path = self.phase_dir / f"requests/{request_id}.patch"
            manifest_path = self.phase_dir / f"requests/{request_id}-postimages.tsv"
            record = self.read_json(record_path, self.relative(record_path))
            for path, expected in (
                (patch_path, facts["patch_sha256"]),
                (manifest_path, facts["postimages_sha256"]),
            ):
                self.problems.require(
                    path.is_file() and sha256_path(path) == expected,
                    self.relative(path),
                    f"must hash to exact planned value {expected}",
                )
            if terminal and record is not None:
                active_request = self.git_json(
                    C0005_CODE_SHA,
                    record_path,
                    f"{request_context}.active request",
                )
                if active_request is not None:
                    expected_request = json.loads(json.dumps(active_request))
                    expected_request["status"] = "applied"
                    expected_request["resolution"] = record.get("resolution")
                    self.problems.require(
                        record == expected_request,
                        self.relative(record_path),
                        "C0005 may change only request status and exact resolution",
                    )
            else:
                self.problems.require(
                    record_path.is_file()
                    and sha256_path(record_path) == facts["record_sha256"],
                    self.relative(record_path),
                    f"active request record must hash to {facts['record_sha256']}",
                )
            if record is None:
                continue
            request_records[request_id] = record
            paths = record.get("paths")
            path_set = set(paths) if isinstance(paths, list) else set()
            request_paths[request_id] = path_set
            self.problems.require(
                isinstance(paths, list)
                and paths == sorted(path_set)
                and len(paths) == facts["count"],
                f"{request_context}.paths",
                "request paths must be sorted, unique, and exact-count",
            )
            self.problems.require(
                record.get("schema_version") == 1
                and record.get("record_kind") == "shared_file_request"
                and record.get("request_id") == request_id
                and record.get("wave_id") == facts["wave"]
                and record.get("blocks") == [facts["wave"]]
                and record.get("lane_id") == "claude-lane"
                and record.get("requester_id") == "primary-human"
                and record.get("status") == ("applied" if terminal else "active")
                and record.get("target_checkpoint_id") == C0004_CHECKPOINT_ID
                and record.get("valid_through_checkpoint_id") == C0004_CHECKPOINT_ID
                and record.get("target_base_sha") == C0004_CODE_SHA,
                request_context,
                "request must have the exact lifecycle status and remain rooted at C0004",
            )
            preimages = record.get("preimage_blobs")
            expected_preimages = [
                {"blob_oid": self.git_blob(C0004_CODE_SHA, path), "path": path}
                for path in sorted(path_set)
            ]
            self.problems.require(
                preimages == expected_preimages,
                f"{request_context}.preimage_blobs",
                "must pin exact C0004 blobs in request path order",
            )
            _, rows = self.read_tsv(
                manifest_path,
                self.relative(manifest_path),
                ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
            )
            postimages = self.validate_postimage_rows(
                ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
                rows,
                self.relative(manifest_path),
                path_set,
                "postimage_sha256",
                base_sha=C0004_CODE_SHA,
                base_label="C0004",
            )
            request_postimages[request_id] = postimages
            self.materialize_patch_postimages(
                request_context,
                patch_path,
                path_set,
                postimages,
                base_sha=C0004_CODE_SHA,
                base_label="C0004",
                unidiff_zero=True,
            )
            selector_paths = selected_by_wave.get(facts["wave"], set())
            self.problems.require(
                path_set.isdisjoint(selector_paths),
                request_context,
                "shared request must not contain a worker-owned selector path",
            )

        r0009 = request_paths.get("R0009", set())
        r0010 = request_paths.get("R0010", set())
        union_paths = r0009 | r0010
        intersection = r0009 & r0010
        request_diff = self.git(
            "diff",
            "--name-only",
            C0005_PLANNED_CONTROL_SHA,
            "--",
            *sorted(union_paths),
            check=False,
        )
        validate_c0005_request_lifecycle(
            request_records,
            request_diff.returncode == 0
            and (
                not request_diff.stdout.strip()
                # Delivered: the union is applied, so its paths necessarily
                # differ from the planned-control tree.  Their exact content is
                # verified against the ledger postimages immediately below.
                or integrated
            ),
            self.problems,
            state=state or "invalid",
            gate_evidence_sha256=gate_evidence_sha256,
            context=f"{context}.request state",
        )
        self.problems.require(
            intersection == C0005_REQUEST_INTERSECTION
            and len(union_paths) == C0005_REQUEST_FACTS["union"]["count"]
            and hashlib.sha256(
                "".join(f"{path}\n" for path in sorted(union_paths)).encode("utf-8")
            ).hexdigest().upper()
            == C0005_REQUEST_UNION_PATH_SHA256,
            f"{context}.request union",
            "must contain the exact five-path overlap and reviewed 37-path union",
        )
        union_patch = self.phase_dir / "requests/R0009-R0010-union.patch"
        union_manifest = self.phase_dir / "requests/R0009-R0010-union-postimages.tsv"
        union_review = self.phase_dir / "requests/R0009-R0010-union-review.md"
        expected_ledger = (
            C0005_UNION_AMENDED_LEDGER_SHA256
            if integrated
            else C0005_REQUEST_FACTS["union"]["postimages_sha256"]
        )
        for path, expected in (
            (union_patch, C0005_REQUEST_FACTS["union"]["patch_sha256"]),
            (union_manifest, expected_ledger),
            (union_review, C0005_REQUEST_FACTS["union"]["review_sha256"]),
        ):
            self.problems.require(
                path.is_file() and sha256_path(path) == expected,
                self.relative(path),
                f"must hash to exact union value {expected}",
            )
        if integrated:
            # The as-reviewed ledger stays immutable in planned-control history,
            # and the re-anchor must be accompanied by its reviewed amendment.
            historical_ledger = self.git_bytes(
                "show",
                f"{C0005_PLANNED_CONTROL_SHA}:{self.relative(union_manifest)}",
                check=False,
            )
            self.problems.require(
                historical_ledger.returncode == 0
                and hashlib.sha256(historical_ledger.stdout).hexdigest().upper()
                == C0005_REQUEST_FACTS["union"]["postimages_sha256"],
                f"{context}.union ledger history",
                "planned-control history must retain the as-reviewed union ledger",
            )
            amendment = self.root / C0005_UNION_MIGRATION_AMENDMENT_PATH
            self.problems.require(
                amendment.is_file(),
                C0005_UNION_MIGRATION_AMENDMENT_PATH,
                "delivered union re-anchor requires its reviewed amendment",
            )
        _, union_rows = self.read_tsv(
            union_manifest,
            self.relative(union_manifest),
            ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
        )
        if integrated:
            # Validate the 36 C0004-anchored rows exactly as frozen, then the
            # re-anchored control-line row against its amendment constants.
            amended_row = next(
                (row for row in union_rows if row.get("path") == C0005_UNION_AMENDED_PATH),
                None,
            )
            self.problems.require(
                amended_row is not None
                and all(
                    amended_row.get(key) == value
                    for key, value in C0005_UNION_AMENDED_ROW.items()
                ),
                f"{context}.union[{C0005_UNION_AMENDED_PATH}]",
                "re-anchored union row must carry the reviewed amendment values",
            )
            anchored_rows = [
                row for row in union_rows if row.get("path") != C0005_UNION_AMENDED_PATH
            ]
            anchored_paths = union_paths - {C0005_UNION_AMENDED_PATH}
            union_postimages = self.validate_postimage_rows(
                ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
                anchored_rows,
                self.relative(union_manifest),
                anchored_paths,
                "postimage_sha256",
                base_sha=C0004_CODE_SHA,
                base_label="C0004",
            )
            # The frozen patch still legitimately produces all 37 paths from
            # exact C0004, including the stale control-line postimage; verify it
            # unchanged, then hold the live tree to the amended row instead.
            self.materialize_patch_postimages(
                f"{context}[union]",
                union_patch,
                union_paths,
                {
                    **union_postimages,
                    C0005_UNION_AMENDED_PATH: C0005_REQUEST_FACTS["union"][
                        "frozen_migration_postimage_sha256"
                    ],
                },
                base_sha=C0004_CODE_SHA,
                base_label="C0004",
                unidiff_zero=True,
            )
            union_postimages[C0005_UNION_AMENDED_PATH] = C0005_UNION_AMENDED_ROW[
                "postimage_sha256"
            ]
            # Applied, not merely reviewed: every union path must match its
            # ledger postimage.  At accepted C0005 only the MIGRATION narrative
            # may advance in the live acceptance-control commit; hold its exact
            # integrated-code blob to the immutable union postimage instead.
            for path in sorted(union_paths):
                live = self.root / path
                code_sha256 = None
                if terminal and path in C0005_ACCEPTANCE_NARRATIVE_PATHS:
                    code = self.git_bytes(
                        "show", f"{C0005_CODE_SHA}:{path}", check=False
                    )
                    if code.returncode == 0:
                        code_sha256 = hashlib.sha256(code.stdout).hexdigest().upper()
                live_sha256 = sha256_path(live) if live.is_file() else None
                if (
                    (self.root / R07_INTEGRATION_AUTHORIZATION_PATH).is_file()
                    and path not in C0005_ACCEPTANCE_NARRATIVE_PATHS
                ):
                    historical_live = self.git_bytes(
                        "show", f"{R07_ACCEPTED_CONTROL_SHA}:{path}", check=False
                    )
                    live_sha256 = (
                        hashlib.sha256(historical_live.stdout).hexdigest().upper()
                        if historical_live.returncode == 0
                        else None
                    )
                validate_c0005_union_materialization(
                    path,
                    union_postimages.get(path),
                    live_sha256,
                    code_sha256,
                    terminal,
                    self.problems,
                    context=f"{context}.union applied[{path}]",
                )
        else:
            union_postimages = self.validate_postimage_rows(
                ("path", "preimage_blob_oid", "preimage_sha256", "postimage_sha256"),
                union_rows,
                self.relative(union_manifest),
                union_paths,
                "postimage_sha256",
                base_sha=C0004_CODE_SHA,
                base_label="C0004",
            )
            self.materialize_patch_postimages(
                f"{context}[union]",
                union_patch,
                union_paths,
                union_postimages,
                base_sha=C0004_CODE_SHA,
                base_label="C0004",
                unidiff_zero=True,
            )
        for path in sorted(r0009 - r0010):
            self.problems.require(
                union_postimages.get(path) == request_postimages.get("R0009", {}).get(path),
                f"{context}.union[{path}]",
                "R0009-only union postimage must equal standalone R0009",
            )
        for path in sorted(r0010 - r0009):
            if integrated and path == C0005_UNION_AMENDED_PATH:
                # The standalone R0010 postimage carries the same stale anchor
                # the amendment corrects, so equality no longer holds here.
                continue
            self.problems.require(
                union_postimages.get(path) == request_postimages.get("R0010", {}).get(path),
                f"{context}.union[{path}]",
                "R0010-only union postimage must equal standalone R0010",
            )
        for path in sorted(intersection):
            self.problems.require(
                union_postimages.get(path)
                not in {
                    request_postimages.get("R0009", {}).get(path),
                    request_postimages.get("R0010", {}).get(path),
                },
                f"{context}.union[{path}]",
                "shared union postimage must compose both independent request semantics",
            )

        try:
            accepted_phase = json.loads(
                self.git(
                    "show",
                    f"{C0004_ACCEPTANCE_CONTROL_SHA}:{(DEFAULT_PHASE_DIR / 'phase.json').as_posix()}",
                ).stdout
            )
        except (RuntimeError, json.JSONDecodeError) as error:
            accepted_phase = {}
            self.problems.add(context, f"cannot load accepted C0004 phase: {error}")
        accepted_exact = {
            row.get("path")
            for row in accepted_phase.get("shared_paths", [])
            if isinstance(row, dict) and row.get("match") == "exact"
        }
        accepted_prefix = [
            row.get("path")
            for row in accepted_phase.get("shared_paths", [])
            if isinstance(row, dict) and row.get("match") == "prefix"
        ]
        live_exact = {
            rule.path for rule in self.shared_rules if rule.match == "exact"
        }
        live_prefix = [
            rule.path for rule in self.shared_rules if rule.match == "prefix"
        ]
        if terminal and self.r07_contract is None:
            self.problems.require(
                len(live_exact) == 155
                and len(live_prefix) == 5
                and live_exact == accepted_exact
                and live_prefix == [normalize_path(path) for path in accepted_prefix],
                f"{context}.shared paths",
                "C0005 acceptance must restore exact C0004 shared-path reservations",
            )
        elif not terminal:
            self.problems.require(
                len(live_exact) == 187
                and len(live_prefix) == 5
                and live_exact - accepted_exact == union_paths - accepted_exact
                and len(live_exact - accepted_exact) == 32
                and live_prefix == [normalize_path(path) for path in accepted_prefix],
                f"{context}.shared paths",
                "phase must add exactly the 32 new union reservations and retain five prefixes",
            )

        for local_path, digest in C0006_REVIEW_FACTS.items():
            path = self.phase_dir / local_path
            self.problems.require(
                path.is_file() and sha256_path(path) == digest,
                self.relative(path),
                f"reviewed C0006 planning document must hash to {digest}",
            )
        for local_path, digest in C0005_REVIEW_FACTS.items():
            path = self.phase_dir / local_path
            self.problems.require(
                path.is_file() and sha256_path(path) == digest,
                self.relative(path),
                f"planned review must hash to {digest}",
            )
    def validate_r05_r06_epoch(self) -> None:
        """Ratchet the C0003-rooted R05/R06 pair through C0004 acceptance."""

        context = "C0003-rooted R05/R06 epoch"
        self.problems.require(
            self.current_checkpoint_id
            in {
                C0003_CHECKPOINT_ID,
                C0004_CHECKPOINT_ID,
                C0005_CHECKPOINT_ID,
                C0006_CHECKPOINT_ID,
                C0007_CHECKPOINT_ID,
                C0008_CHECKPOINT_ID,
            },
            context,
            "R05/R06 controls require current checkpoint C0003 through C0007",
        )
        request_path_sets: dict[str, set[str]] = {}
        r05r06_records: dict[str, dict[str, Any]] = {}
        for wave in ("R05", "R06"):
            facts = R05R06_PLANNED_FACTS[wave]
            branch_id = facts["branch_id"]
            wave_context = f"{context}[{branch_id}]"
            record = self.read_json(
                self.phase_dir / f"branches/{branch_id}.json", wave_context
            )
            if record is None:
                continue
            r05r06_records[branch_id] = record
            evidence = (record.get("refresh") or {}).get("evidence")
            if not isinstance(evidence, list) or not evidence:
                self.problems.add(
                    f"{wave_context}.refresh.evidence", "evidence list is required"
                )
            else:
                for index, entry in enumerate(evidence):
                    self.artifact(
                        entry, f"{wave_context}.refresh.evidence[{index}]"
                    )
            delivery = record.get("delivery")
            if isinstance(delivery, dict):
                for label, fact_key in (
                    ("report", "delivery_report"),
                    ("scope_evidence", "delivery_scope"),
                ):
                    expected_path, expected_sha256 = facts[fact_key]
                    artifact = self.artifact(
                        delivery.get(label), f"{wave_context}.delivery.{label}"
                    )
                    self.problems.require(
                        artifact == Artifact(expected_path, expected_sha256),
                        f"{wave_context}.delivery.{label}",
                        f"must hash-pin exact delivery artifact {expected_path} "
                        f"at {expected_sha256}",
                    )
            parent_vector = self.git(
                "rev-list",
                "--parents",
                "-n",
                "1",
                facts["delivery_sha"],
                check=False,
            ).stdout.strip().split()
            self.problems.require(
                parent_vector == [facts["delivery_sha"], R05R06_CODE_SHA],
                f"{wave_context}.delivery.commit_sha",
                "delivery must be the exact reviewed direct child of C0003",
            )
            for rel, expected, label in (
                (f"selectors/{wave}.tsv", facts["selector_sha256"], "selector"),
                (
                    f"projections/{facts['projection_id']}.tsv.gz",
                    facts["projection_sha256"],
                    "projection",
                ),
                (
                    f"requests/{facts['request_id']}.patch",
                    facts["patch_sha256"],
                    "request patch",
                ),
                (
                    f"branches/{branch_id}-declaration-routes.tsv",
                    facts["declaration_routes_sha256"],
                    "declaration routes",
                ),
                (
                    f"branches/{branch_id}-private-normalization.tsv",
                    facts["private_normalization_sha256"],
                    "private normalization",
                ),
            ):
                path = self.phase_dir / rel
                if not path.is_file():
                    self.problems.add(f"{wave_context}.{label}", f"missing {rel}")
                    continue
                self.problems.require(
                    sha256_path(path) == expected,
                    f"{wave_context}.{label}",
                    f"route/hash drift: expected SHA-256 {expected}",
                )
            routes_path = self.phase_dir / f"branches/{branch_id}-declaration-routes.tsv"
            if routes_path.is_file():
                class_counts: Counter[str] = Counter()
                bad_rows = 0
                with routes_path.open(encoding="utf-8") as stream:
                    header = stream.readline()
                    for line in stream:
                        fields = line.rstrip("\n").split("\t")
                        if len(fields) != 8:
                            bad_rows += 1
                            continue
                        route_class = fields[6]
                        destination = fields[5]
                        if route_class not in R05R06_ROUTE_CLASSES:
                            bad_rows += 1
                            continue
                        if route_class in {"relocate_whole", "umbrella_extract"}:
                            if not destination.startswith("NumStability.") or "," in destination:
                                bad_rows += 1
                        elif destination != "-":
                            bad_rows += 1
                self.problems.require(
                    bad_rows == 0,
                    f"{wave_context}.declaration-routes",
                    "every declaration row must carry a frozen route class and a "
                    "single whole-owner destination (or '-' for retained rows)",
                )
            module_routes = self.phase_dir / f"branches/{branch_id}-module-routes.tsv"
            if module_routes.is_file():
                counts: Counter[str] = Counter()
                with module_routes.open(encoding="utf-8") as stream:
                    stream.readline()
                    for line in stream:
                        fields = line.rstrip("\n").split("\t")
                        if len(fields) >= 7:
                            counts[fields[6]] += 1
                self.problems.require(
                    dict(counts) == facts["route_counts"],
                    f"{wave_context}.module-routes",
                    f"whole-owner route-class census must be exactly {facts['route_counts']}",
                )
            request = self.read_json(
                self.phase_dir / f"requests/{facts['request_id']}.json", wave_context
            )
            if request is not None:
                paths = request.get("paths")
                request_path_sets[wave] = set(paths or ())
                self.problems.require(
                    isinstance(paths, list)
                    and len(paths) == facts["request_paths"]
                    and request.get("target_base_sha") == R05R06_CODE_SHA
                    and request.get("target_checkpoint_id") == "C0003"
                    and request.get("wave_id") == wave,
                    f"{wave_context}.request",
                    f"frozen {facts['request_id']} must pin exact C0003 with "
                    f"{facts['request_paths']} paths",
                )
                if self.current_checkpoint_id == C0003_CHECKPOINT_ID:
                    expected_empty = {
                        "checkpoint_id": None,
                        "commit_sha": None,
                        "reason": None,
                        "resolved_at": None,
                        "resolved_by": None,
                        "validation_evidence": [],
                    }
                    self.problems.require(
                        request.get("status") == "active"
                        and request.get("resolution") == expected_empty,
                        f"{wave_context}.request.lifecycle",
                        "C0003 requires active request status and exact empty resolution",
                    )
                else:
                    validate_r05r06_terminal_request(request, wave, self.problems)
            projection = self.read_json(
                self.phase_dir / f"projections/{facts['projection_id']}.json",
                wave_context,
            )
            if projection is not None:
                self.problems.require(
                    projection.get("expected_counts") == facts["counts"]
                    and (projection.get("projection_graph") or {}).get("sha256")
                    == facts["projection_sha256"],
                    f"{wave_context}.projection",
                    "frozen projection counts or graph hash drifted",
                )
                validate_r05r06_projection_status(
                    projection, wave, self.current_checkpoint_id, self.problems
                )
        if len(request_path_sets) == 2:
            overlap = request_path_sets["R05"] & request_path_sets["R06"]
            self.problems.require(
                overlap == set(R05R06_REQUEST_OVERLAP),
                f"{context}.request-overlap",
                "R0006/R0007 may share exactly the five reviewed integrator paths",
            )
        active_statuses = {
            r05r06_records.get(R05R06_PLANNED_FACTS[w]["branch_id"], {}).get(
                "status"
            )
            for w in ("R05", "R06")
        }
        if active_statuses - {"planned"}:
            activation = self.phase_dir / "reviews/R05-R06-activation.md"
            if not activation.is_file():
                self.problems.add(
                    f"{context}.activation",
                    "active/delivered controls require reviews/R05-R06-activation.md",
                )
            else:
                self.problems.require(
                    sha256_path(activation) == R05R06_ACTIVATION_REVIEW_SHA256,
                    f"{context}.activation",
                    "activation review hash drifted from "
                    f"{R05R06_ACTIVATION_REVIEW_SHA256}",
                )
                text = activation.read_text(encoding="utf-8")
                for token in (
                    R05R06_CODE_SHA,
                    R05R06_PLANNED_CONTROL_SHA,
                    R05R06_PLANNED_CONTROL_CI_RUN,
                    R05R06_PLANNED_FACTS["R05"]["branch_name"],
                    R05R06_PLANNED_FACTS["R06"]["branch_name"],
                    R05R06_PLANNED_FACTS["R05"]["planned_worktree"],
                    R05R06_PLANNED_FACTS["R06"]["planned_worktree"],
                ):
                    self.problems.require(
                        str(token) in text,
                        f"{context}.activation",
                        f"activation review is missing exact fact {token!r}",
                    )
        for rel, expected, label in (
            (
                "requests/R0006-R0007-union.patch",
                R05R06_UNION_PATCH_SHA256,
                "reviewed union patch",
            ),
            (
                "requests/R0006-R0007-union-review.md",
                R05R06_UNION_REVIEW_SHA256,
                "reviewed union acceptance evidence",
            ),
            (
                "reviews/R05-R06-operator-authorization.md",
                R05R06_AUTH_REVIEW_SHA256,
                "operator authorization review",
            ),
            (
                "reviews/C0003-R05-R06-selection.md",
                R05R06_SELECTION_REVIEW_SHA256,
                "pair selection review",
            ),
            (
                "reviews/R05-R06-projection-replay.md",
                R05R06_REPLAY_REVIEW_SHA256,
                "projection replay review",
            ),
        ):
            path = self.phase_dir / rel
            if not path.is_file():
                self.problems.add(f"{context}.{label}", f"missing {rel}")
                continue
            self.problems.require(
                sha256_path(path) == expected,
                f"{context}.{label}",
                f"hash drift: expected SHA-256 {expected}",
            )

        amendment_path = self.phase_dir / "requests/R0008.json"
        amendment_context = f"{context}[R0008]"
        amendment = self.read_json(amendment_path, amendment_context)
        if amendment is not None:
            for key, expected in R0008_ARTIFACTS.items():
                artifact = self.artifact(
                    amendment.get(key), f"{amendment_context}.{key}"
                )
                self.problems.require(
                    artifact == Artifact(*expected),
                    f"{amendment_context}.{key}",
                    f"must hash-pin exact reviewed artifact {expected[0]} at {expected[1]}",
                )
            predecessor = amendment.get("predecessor_postimages")
            predecessor_artifact = None
            if isinstance(predecessor, list) and len(predecessor) == 1:
                predecessor_artifact = self.artifact(
                    predecessor[0],
                    f"{amendment_context}.predecessor_postimages[0]",
                )
            self.problems.require(
                predecessor_artifact == Artifact(*R0008_PREDECESSOR_POSTIMAGES),
                f"{amendment_context}.predecessor_postimages",
                "must hash-pin the exact immutable R0006-R0007 union postimages",
            )

        predecessor_path = self.root / R0008_PREDECESSOR_POSTIMAGES[0]
        _, predecessor_rows = self.read_tsv(
            predecessor_path,
            self.relative(predecessor_path),
            R0008_MANIFEST_HEADER,
        )
        postimage_path = self.root / R0008_ARTIFACTS["postimages"][0]
        _, postimage_rows = self.read_tsv(
            postimage_path,
            self.relative(postimage_path),
            R0008_MANIFEST_HEADER,
        )
        if self.current_checkpoint_id == C0003_CHECKPOINT_ID:
            amendment_json_sha256 = (
                sha256_path(amendment_path) if amendment_path.is_file() else ""
            )
            validate_r0008_c0003_contract(
                amendment,
                r05r06_records,
                predecessor_rows,
                postimage_rows,
                amendment_json_sha256,
                self.problems,
            )
        else:
            validate_r0008_c0004_contract(
                amendment,
                r05r06_records,
                predecessor_rows,
                postimage_rows,
                self.problems,
            )
            self.validate_r05r06_c0004_record_hashes(
                r05r06_records, amendment_path
            )
            self.validate_r05r06_terminal_postimages(
                predecessor_rows, postimage_rows
            )

    def validate_r05r06_c0004_record_hashes(
        self,
        branch_records: dict[str, dict[str, Any]],
        amendment_path: Path,
    ) -> None:
        """Pin accepted records while allowing the later reviewed retired state."""

        for record_id, digest in R05R06_ACCEPTED_RECORD_SHA256.items():
            kind = (
                "branches"
                if record_id.startswith("B")
                else "projections"
                if record_id.startswith("P")
                else "requests"
            )
            path = self.phase_dir / f"{kind}/{record_id}.json"
            if record_id.startswith("B"):
                record = branch_records.get(record_id, {})
                if record.get("status") == "retired":
                    continue
            self.problems.require(
                path.is_file() and sha256_path(path) == digest,
                self.relative(path),
                f"accepted C0004 record must hash to {digest}",
            )
        self.problems.require(
            amendment_path.is_file()
            and sha256_path(amendment_path) == R0008_APPLIED_RECORD_SHA256,
            self.relative(amendment_path),
            f"applied R0008 record must hash to {R0008_APPLIED_RECORD_SHA256}",
        )

    def validate_r05r06_terminal_postimages(
        self,
        predecessor_rows: list[dict[str, str]],
        postimage_rows: list[dict[str, str]],
    ) -> None:
        """Prove 61 union and all 27 R0008 postimages at exact C0004."""

        union = {
            row.get("path", ""): row.get("postimage_sha256", "").upper()
            for row in predecessor_rows
        }
        amendment = {
            row.get("path", ""): row.get("postimage_sha256", "").upper()
            for row in postimage_rows
        }
        paths = set(union) | set(amendment)
        blobs = {
            path: self.git_blob(C0004_CODE_SHA, path) for path in paths if path
        }
        payloads = self.git_blob_payloads(
            (oid for oid in blobs.values() if isinstance(oid, str)),
            "C0004 terminal R05/R06 postimages",
        )
        actual: dict[str, str] = {}
        for path, oid in blobs.items():
            payload = payloads.get(oid) if isinstance(oid, str) else None
            if payload is None:
                self.problems.add(
                    f"C0004 terminal postimage[{path}]",
                    "cannot read exact C0004 blob payload",
                )
                continue
            actual[path] = hashlib.sha256(payload).hexdigest().upper()
        terminal_union = (
            set(union)
            - set(R0008_UNION_OVERLAP)
            - set(C0004_AGGREGATE_FOLLOWUPS)
        )
        self.problems.require(
            len(terminal_union) == 61,
            "C0004 terminal union postimages",
            "expected exactly 61 byte-terminal union paths",
        )
        for path in sorted(terminal_union):
            self.problems.require(
                actual.get(path) == union.get(path),
                f"C0004 terminal union postimage[{path}]",
                "exact C0004 content must equal immutable union postimage SHA-256",
            )
        for path in sorted(R0008_PATHS):
            self.problems.require(
                actual.get(path) == amendment.get(path),
                f"C0004 R0008 postimage[{path}]",
                "exact C0004 content must equal authoritative R0008 postimage SHA-256",
            )
        superseded = set(R0008_UNION_OVERLAP)
        aggregate_deviations = set(union) & set(C0004_AGGREGATE_FOLLOWUPS)
        self.problems.require(
            len(superseded) == 4
            and len(aggregate_deviations) == 2
            and all(actual.get(path) != union.get(path) for path in superseded)
            and all(
                actual.get(path) != union.get(path)
                for path in aggregate_deviations
            ),
            "C0004 terminal union supersessions",
            "exactly four union paths must be superseded by R0008 and exactly two "
            "by reviewed aggregate follow-ups",
        )

    def validate_r03_epoch(self) -> None:
        """Ratchet the singleton exact-C0002 R03 packet through C0003."""

        context = "C0002-rooted R03 epoch"
        self.problems.require(
            self.current_checkpoint_id
            in {
                C0002_CHECKPOINT_ID,
                C0003_CHECKPOINT_ID,
                C0004_CHECKPOINT_ID,
                C0005_CHECKPOINT_ID,
                C0006_CHECKPOINT_ID,
                C0007_CHECKPOINT_ID,
                C0008_CHECKPOINT_ID,
            },
            context,
            "R03 controls require current checkpoint C0002 through C0007",
        )
        r07_milestone_status = self.validate_r03_milestones()
        lane_operators = self.validate_r03_authority()
        inventory, inventory_by_path, selector = self.validate_r03_selector()
        branch, worker_rules, activation_evidence = self.validate_r03_branch(
            inventory_by_path, selector
        )
        projection, declarations = self.validate_r03_projection(
            {module for module, _path in selector}
        )
        consumer_sets = self.validate_r03_consumers()
        self.validate_r03_routes_and_tests(
            selector, inventory_by_path, declarations, worker_rules, consumer_sets
        )
        self.validate_r03_reviews()
        request, request_paths, unreserved = self.validate_r03_request(
            worker_rules, consumer_sets
        )
        if branch is not None and branch.get("status") == "planned":
            self.validate_r03_ref_and_worktree_absence()
        elif branch is not None and branch.get("status") in {
            "active",
            "accepted",
            "retired",
        }:
            self.validate_r03_activation_review()

        if branch is not None and projection is not None and request is not None:
            shared_leaks = tuple(
                sorted(
                    {
                        f"{rule.path} -> {shared.path}"
                        for rule in worker_rules
                        for shared in self.shared_rules
                        if rule.intersects(shared)
                    }
                )
            )
            selector_path = self.phase_dir / "selectors/R03.tsv"
            route_path = self.phase_dir / "branches/B0005-declaration-routes.tsv"
            selector_sha = sha256_path(selector_path) if selector_path.is_file() else ""
            route_sha = sha256_path(route_path) if route_path.is_file() else ""
            selector_expected = sorted(
                (row.get("module", ""), row.get("path", ""))
                for row in inventory
                if row.get("wave_id") == R03_WAVE_ID
            )
            snapshot = R03EpochSnapshot(
                branch_base_checkpoint_id=str(branch.get("base_checkpoint_id", "")),
                branch_base_sha=str(branch.get("base_sha", "")),
                branch_status=str(branch.get("status", "")),
                operator_ids=tuple(branch.get("operator_ids", ()))
                if isinstance(branch.get("operator_ids"), list)
                else (),
                lane_operator_ids=lane_operators,
                selector_sha256=selector_sha,
                selector_rows=len(selector),
                selector_matches_inventory=selector == selector_expected,
                route_sha256=route_sha,
                activation_evidence=activation_evidence,
                delivery=branch.get("delivery", {})
                if isinstance(branch.get("delivery"), dict)
                else {},
                integration=branch.get("integration", {})
                if isinstance(branch.get("integration"), dict)
                else {},
                retirement=branch.get("retirement", {})
                if isinstance(branch.get("retirement"), dict)
                else {},
                projection_base_checkpoint_id=str(
                    projection.get("base_checkpoint_id", "")
                ),
                projection_status=str(projection.get("status", "")),
                projection_selector_sha256=str(
                    projection.get("selector", {})
                    .get("artifact", {})
                    .get("sha256", "")
                )
                if isinstance(projection.get("selector"), dict)
                else "",
                request_target_checkpoint_id=str(
                    request.get("target_checkpoint_id", "")
                ),
                request_target_base_sha=str(request.get("target_base_sha", "")),
                request_status=str(request.get("status", "")),
                request_resolution=request.get("resolution", {})
                if isinstance(request.get("resolution"), dict)
                else {},
                r07_milestone_status=r07_milestone_status,
                worker_shared_leaks=shared_leaks,
                request_unreserved_paths=tuple(sorted(unreserved)),
            )
            expected_route = self.r03_expected_digest(
                "declaration_routes", "R03 declaration-route snapshot"
            )
            validate_r03_epoch_snapshot(
                snapshot,
                self.problems,
                expected_route_sha256=expected_route or "<pending>",
                expected_r07_status=(
                    "accepted"
                    if self.current_checkpoint_id
                    in {C0006_CHECKPOINT_ID, C0007_CHECKPOINT_ID, C0008_CHECKPOINT_ID}
                    else "ready"
                    if self.current_checkpoint_id == C0005_CHECKPOINT_ID
                    else "planned"
                ),
            )

    def validate_r03_milestones(self) -> str:
        milestones = self.phase.get("milestones")
        if not isinstance(milestones, list):
            self.problems.add("phase.json.milestones", "expected a list")
            return ""
        by_id = {
            item.get("milestone_id"): item
            for item in milestones
            if isinstance(item, dict) and isinstance(item.get("milestone_id"), str)
        }
        m03 = by_id.get("M03", {})
        if self.current_checkpoint_id in {
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.problems.require(
                m03.get("wave_ids") == [R03_WAVE_ID]
                and m03.get("status") == "accepted"
                and m03.get("accepted_checkpoint_id") == C0003_CHECKPOINT_ID,
                "phase.json.milestones[M03]",
                "M03 must be accepted exactly at C0003",
            )
        else:
            self.problems.require(
                m03.get("wave_ids") == [R03_WAVE_ID]
                and m03.get("status") == "ready"
                and m03.get("accepted_checkpoint_id") is None,
                "phase.json.milestones[M03]",
                "M03 alone must be ready for R03 with accepted_checkpoint_id null",
            )
        for milestone_id, milestone in sorted(by_id.items()):
            if milestone.get("accepted_checkpoint_id") is not None:
                continue
            expected = (
                "ready"
                if (
                    self.current_checkpoint_id == C0002_CHECKPOINT_ID
                    and milestone_id == "M03"
                )
                or (
                    self.current_checkpoint_id == C0003_CHECKPOINT_ID
                    and milestone_id in {"M05", "M06"}
                )
                or (
                    self.current_checkpoint_id == C0004_CHECKPOINT_ID
                    and milestone_id in {"M04", "M08"}
                )
                or (
                    self.current_checkpoint_id == C0005_CHECKPOINT_ID
                    and milestone_id == "M07"
                )
                else "planned"
            )
            self.problems.require(
                milestone.get("status") == expected,
                f"phase.json.milestones[{milestone_id}]",
                f"unaccepted milestone must remain {expected!r}",
            )
        expected_r07_status = (
            "accepted"
            if self.current_checkpoint_id
            in {C0006_CHECKPOINT_ID, C0007_CHECKPOINT_ID, C0008_CHECKPOINT_ID}
            else "ready"
            if self.current_checkpoint_id == C0005_CHECKPOINT_ID
            else "planned"
        )
        self.problems.require(
            by_id.get("M07", {}).get("status") == expected_r07_status,
            "phase.json.milestones[M07]",
            "R07 must remain planned before C0005, ready at C0005, and accepted "
            "from C0006 onward",
        )
        return str(by_id.get("M07", {}).get("status", ""))

    def validate_r03_authority(self) -> tuple[str, ...]:
        authority = self.phase.get("authority")
        lanes = authority.get("lanes") if isinstance(authority, dict) else None
        matches = [
            lane
            for lane in lanes or []
            if isinstance(lane, dict) and lane.get("lane_id") == R03_LANE_ID
        ]
        lane = matches[0] if len(matches) == 1 else {}
        operators = (
            tuple(lane.get("operator_ids", ()))
            if isinstance(lane.get("operator_ids"), list)
            else ()
        )
        expected_operators = (
            (R03_OPERATOR_ID,)
            if self.current_checkpoint_id
            in {
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }
            else R05R06_OPERATOR_PAIR
            if self.current_checkpoint_id == C0003_CHECKPOINT_ID
            else R03_OPERATOR_IDS
        )
        # At C0006 the R09/R10 planned control may additionally carry the
        # reviewed B0012-scoped pair from reviews/R10-operator-authorization.md,
        # because the immutable scope assigns R10 to codex-lane while
        # claude-local operates it.
        allowed_operator_sets = {expected_operators}
        # The widened pair is accepted only while the reviewed authorization is
        # present with its exact pinned bytes, so the executable allowance and
        # the governance record cannot drift apart.
        _auth_rel = "reviews/R10-operator-authorization.md"
        _auth_path = self.phase_dir / _auth_rel
        _auth_ok = (
            _auth_path.is_file()
            and sha256_path(_auth_path) == C0006_REVIEW_FACTS[_auth_rel]
        )
        allowed_operator_sets = allowed_codex_lane_operator_sets(
            self.current_checkpoint_id, expected_operators, _auth_ok
        )
        self.problems.require(
            len(matches) == 1
            and lane.get("owner_id") == "primary-human"
            and operators in allowed_operator_sets,
            f"phase.json.authority.lanes[{R03_LANE_ID}]",
            "codex-lane requires the reviewed R03 pair before C0003 and, after the "
            "R05/R06 planning control, the reviewed B0006-scoped pair recorded in "
            "reviews/R05-R06-operator-authorization.md (expiring at C0004)",
        )
        return operators

    def validate_r03_selector(
        self,
    ) -> tuple[
        list[dict[str, str]],
        dict[str, dict[str, str]],
        list[tuple[str, str]],
    ]:
        inventory_path = self.phase_dir / "checkpoints/C0002-inventory.tsv"
        if inventory_path.is_file():
            self.problems.require(
                sha256_path(inventory_path) == C0002_INVENTORY_SHA256,
                self.relative(inventory_path),
                f"expected exact C0002 inventory SHA-256 {C0002_INVENTORY_SHA256}",
            )
        _, inventory = self.read_tsv(
            inventory_path, self.relative(inventory_path), SCOPE_HEADER
        )
        self.problems.require(
            len(inventory) == C0002_METRICS["production_modules"],
            self.relative(inventory_path),
            f"expected {C0002_METRICS['production_modules']} exact C0002 inventory rows",
        )
        inventory_by_path = {row.get("path", ""): row for row in inventory}
        self.problems.require(
            len(inventory_by_path) == len(inventory),
            self.relative(inventory_path),
            "C0002 inventory paths must be unique",
        )
        expected = sorted(
            (row.get("module", ""), row.get("path", ""))
            for row in inventory
            if row.get("wave_id") == R03_WAVE_ID
        )
        selector_path = self.phase_dir / "selectors/R03.tsv"
        if selector_path.is_file():
            self.problems.require(
                sha256_path(selector_path) == R03_SELECTOR_SHA256,
                self.relative(selector_path),
                f"expected exact R03 selector SHA-256 {R03_SELECTOR_SHA256}",
            )
        _, selector_rows = self.read_tsv(
            selector_path, self.relative(selector_path), SELECTOR_HEADER
        )
        actual = [
            (row.get("module", ""), row.get("path", "")) for row in selector_rows
        ]
        self.problems.require(
            actual == expected and len(actual) == R03_OWNER_COUNT,
            self.relative(selector_path),
            "selector must equal the exact sorted 47-owner C0002 R03 inventory wave",
        )
        selected_rows = [inventory_by_path.get(path, {}) for _module, path in expected]
        debt_counts = Counter(
            flag
            for row in selected_rows
            for flag in split_values(row.get("debt_flags", ""))
        )
        self.problems.require(
            {key: debt_counts.get(key, 0) for key in R03_DEBT_COUNTS}
            == R03_DEBT_COUNTS,
            "R03 C0002 debt facts",
            f"expected exact debt counts {R03_DEBT_COUNTS}",
        )
        for module, path in expected:
            row = inventory_by_path.get(path, {})
            self.problems.require(
                module_from_path(path) == module
                and row.get("phase_scope") == "in_scope"
                and row.get("lane_id") == R03_LANE_ID,
                f"R03 selector[{path}]",
                "module/path and immutable in-scope lane assignment must match C0002",
            )
            actual_blob = self.git_blob(C0002_CODE_SHA, path)
            self.problems.require(
                actual_blob == row.get("base_blob_oid"),
                f"R03 selector[{path}]",
                f"C0002 blob mismatch: inventory {row.get('base_blob_oid')!r}, Git {actual_blob!r}",
            )
        baseline_path = self.phase_dir / "baselines/C0002-combined.json"
        if baseline_path.is_file():
            self.problems.require(
                sha256_path(baseline_path) == C0002_COMBINED_BASELINE_SHA256,
                self.relative(baseline_path),
                "C0002 combined baseline drifted",
            )
        else:
            self.problems.add(self.relative(baseline_path), "missing C0002 combined baseline")
        return inventory, inventory_by_path, actual

    def validate_r03_branch(
        self,
        inventory_by_path: dict[str, dict[str, str]],
        selector: list[tuple[str, str]],
    ) -> tuple[dict[str, Any] | None, list[PathRule], tuple[Artifact, ...]]:
        path = self.phase_dir / "branches/B0005.json"
        branch = self.read_json(path, self.relative(path))
        if branch is None:
            return None, [], ()
        self.branch_records[R03_BRANCH_ID] = branch
        exact_keys = {
            "schema_version",
            "record_kind",
            "phase_id",
            "branch_id",
            "lane_id",
            "wave_id",
            "branch_name",
            "owner_id",
            "operator_ids",
            "base_checkpoint_id",
            "base_sha",
            "owned_paths",
            "destination_prefixes",
            "forbidden_paths",
            "baseline_projection_id",
            "shared_request_ids",
            "status",
            "refresh",
            "delivery",
            "integration",
            "retirement",
        }
        self.problems.require(
            set(branch) == exact_keys,
            self.relative(path),
            "must retain the strict generic phase_branch schema (no ad-hoc activation/worktree fields)",
        )
        for key, expected in {
            "schema_version": 1,
            "record_kind": "phase_branch",
            "phase_id": PHASE_ID,
            "branch_id": R03_BRANCH_ID,
            "lane_id": R03_LANE_ID,
            "wave_id": R03_WAVE_ID,
            "branch_name": R03_BRANCH_NAME,
            "owner_id": "primary-human",
            "operator_ids": list(R03_OPERATOR_IDS),
            "base_checkpoint_id": C0002_CHECKPOINT_ID,
            "base_sha": C0002_CODE_SHA,
            "baseline_projection_id": R03_PROJECTION_ID,
            "shared_request_ids": [R03_REQUEST_ID],
        }.items():
            self.problems.require(
                branch.get(key) == expected,
                f"{R03_BRANCH_ID}.{key}",
                f"expected {expected!r}, found {branch.get(key)!r}",
            )
        status = branch.get("status")
        allowed_statuses = (
            {"retired"}
            if self.current_checkpoint_id
            in {
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }
            else {"accepted", "retired"}
            if self.current_checkpoint_id == C0003_CHECKPOINT_ID
            else {"planned", "active"}
        )
        self.problems.require(
            status in allowed_statuses,
            f"{R03_BRANCH_ID}.status",
            f"expected one of {sorted(allowed_statuses)} at {self.current_checkpoint_id}",
        )

        refresh = branch.get("refresh")
        evidence: Any = []
        if not isinstance(refresh, dict) or set(refresh) != {
            "reviewed_checkpoint_id",
            "decision",
            "evidence",
        }:
            self.problems.add(
                f"{R03_BRANCH_ID}.refresh",
                "expected exactly reviewed_checkpoint_id/decision/evidence",
            )
        else:
            self.problems.require(
                refresh.get("reviewed_checkpoint_id") == C0002_CHECKPOINT_ID
                and refresh.get("decision") == "current",
                f"{R03_BRANCH_ID}.refresh",
                "must record a current review against exact C0002",
            )
            evidence = refresh.get("evidence")
        artifacts: list[Artifact] = []
        if not isinstance(evidence, list):
            self.problems.add(
                f"{R03_BRANCH_ID}.refresh.evidence", "expected a hash-pinned list"
            )
        else:
            for index, item in enumerate(evidence):
                artifact = self.artifact(
                    item, f"{R03_BRANCH_ID}.refresh.evidence[{index}]"
                )
                if artifact is not None:
                    artifacts.append(artifact)
        self.branch_evidence[R03_BRANCH_ID] = artifacts
        evidence_paths = [artifact.path for artifact in artifacts]
        expected_evidence_paths = set(R03_EVIDENCE_PATHS.values())
        if status in {"active", "accepted", "retired"}:
            expected_evidence_paths.add(R03_ACTIVATION_REVIEW_PATH)
            expected_evidence_paths.add(R03_OPERATOR_AUTH_REVIEW_PATH)
            expected_evidence_paths.add(R03_ROUTE_AMENDMENT_REVIEW_PATH)
        self.problems.require(
            evidence_paths == sorted(evidence_paths)
            and len(evidence_paths) == len(set(evidence_paths))
            and set(evidence_paths) == expected_evidence_paths,
            f"{R03_BRANCH_ID}.refresh.evidence",
            "must be the exact sorted R03 evidence manifest for the branch lifecycle state",
        )
        for key in R03_EVIDENCE_PATHS:
            self.require_r03_evidence(key)
        activation_evidence = tuple(
            sorted(
                (
                    artifact
                    for artifact in artifacts
                    if artifact.path == R03_ACTIVATION_REVIEW_PATH
                ),
                key=lambda artifact: (artifact.path, artifact.sha256),
            )
        )
        if status == "planned":
            self.problems.require(
                not activation_evidence
                and not any(
                    any(
                        token in evidence_path.casefold()
                        for token in ("activation", "base-tip", "ref-tip", "worktree")
                    )
                    for evidence_path in evidence_paths
                ),
                f"{R03_BRANCH_ID}.refresh.evidence",
                "planned packet may not contain activation, base-tip, ref-tip, or worktree evidence",
            )
        elif status in {"active", "accepted", "retired"}:
            self.problems.require(
                activation_evidence
                == (
                    Artifact(
                        R03_ACTIVATION_REVIEW_PATH,
                        R03_ACTIVATION_REVIEW_SHA256,
                    ),
                ),
                f"{R03_BRANCH_ID}.refresh.evidence",
                "active packet must hash-pin the exact R03 activation review",
            )
            authorization_evidence = tuple(
                artifact
                for artifact in artifacts
                if artifact.path == R03_OPERATOR_AUTH_REVIEW_PATH
            )
            self.problems.require(
                authorization_evidence
                == (
                    Artifact(
                        R03_OPERATOR_AUTH_REVIEW_PATH,
                        R03_OPERATOR_AUTH_REVIEW_SHA256,
                    ),
                ),
                f"{R03_BRANCH_ID}.refresh.evidence",
                "active packet must hash-pin the exact R03 operator-authorization review",
            )
            amendment_evidence = tuple(
                artifact
                for artifact in artifacts
                if artifact.path == R03_ROUTE_AMENDMENT_REVIEW_PATH
            )
            self.problems.require(
                amendment_evidence
                == (
                    Artifact(
                        R03_ROUTE_AMENDMENT_REVIEW_PATH,
                        R03_ROUTE_AMENDMENT_REVIEW_SHA256,
                    ),
                ),
                f"{R03_BRANCH_ID}.refresh.evidence",
                "active packet must hash-pin the exact R03 route-amendment review",
            )

        if status in {"accepted", "retired"}:
            delivery = branch.get("delivery")
            if isinstance(delivery, dict):
                for key, expected in (
                    ("report", R03_DELIVERY_REPORT),
                    ("scope_evidence", R03_DELIVERY_SCOPE),
                ):
                    artifact = self.artifact(
                        delivery.get(key), f"{R03_BRANCH_ID}.delivery.{key}"
                    )
                    if artifact is not None:
                        self.problems.require(
                            (artifact.path, artifact.sha256) == expected,
                            f"{R03_BRANCH_ID}.delivery.{key}",
                            f"must pin exact R03 delivery artifact {expected}",
                        )
                        artifact_path = self.root / artifact.path
                        if artifact_path.is_file():
                            self.problems.require(
                                sha256_path(artifact_path) == artifact.sha256,
                                artifact.path,
                                "delivery artifact content drifted",
                            )

        expected_owned = {selected_path for _module, selected_path in selector}
        owned = self.parse_rules(branch.get("owned_paths"), f"{R03_BRANCH_ID}.owned_paths")
        self.problems.require(
            len(owned) == R03_OWNER_COUNT
            and all(rule.match == "exact" for rule in owned)
            and {rule.path for rule in owned} == expected_owned,
            f"{R03_BRANCH_ID}.owned_paths",
            "must own every and only exact R03 selector path",
        )
        destinations = self.parse_rules(
            branch.get("destination_prefixes"),
            f"{R03_BRANCH_ID}.destination_prefixes",
        )
        expected_destinations = R03_DESTINATIONS
        if expected_destinations is None:
            self.problems.add(
                f"{R03_BRANCH_ID}.destination_prefixes",
                "PENDING_R03_DESTINATIONS: exact reviewed destination set is not ratcheted",
            )
        else:
            self.problems.require(
                all(rule.match == "prefix" for rule in destinations)
                and {rule.path for rule in destinations} == expected_destinations,
                f"{R03_BRANCH_ID}.destination_prefixes",
                f"must equal exact reviewed set {sorted(expected_destinations)}",
            )
        base_paths = self.git_tree_paths(C0002_CODE_SHA)
        for index, destination in enumerate(destinations):
            occupied = [
                tree_path
                for tree_path in base_paths
                if is_equal_or_child(tree_path.casefold(), destination.folded)
            ]
            self.problems.require(
                not occupied,
                f"{R03_BRANCH_ID}.destination_prefixes[{destination.path}]",
                f"must be casefold-vacant at C0002; found {occupied[:5]}",
            )
            for other in destinations[index + 1 :]:
                self.problems.require(
                    not destination.intersects(other),
                    f"{R03_BRANCH_ID}.destination_prefixes",
                    f"equal-or-ancestor collision {destination.path} / {other.path}",
                )

        forbidden = self.parse_rules(
            branch.get("forbidden_paths"), f"{R03_BRANCH_ID}.forbidden_paths"
        )
        forbidden_exact = {rule.path for rule in forbidden if rule.match == "exact"}
        forbidden_prefix = {rule.path for rule in forbidden if rule.match == "prefix"}
        self.problems.require(
            forbidden_exact == set(inventory_by_path) - expected_owned
            and len(forbidden_exact) == R03_FORBIDDEN_EXACT_COUNT,
            f"{R03_BRANCH_ID}.forbidden_paths",
            "exact forbidden rules must be the exhaustive 2,595-path C0002 complement",
        )
        self.problems.require(
            forbidden_prefix == set(R03_PROTECTED_PREFIXES),
            f"{R03_BRANCH_ID}.forbidden_paths",
            "prefix forbidden rules must be the exact guarded infrastructure set",
        )
        worker_rules = owned + destinations
        for rule in worker_rules:
            for shared in self.shared_rules:
                if rule.intersects(shared):
                    self.problems.add(
                        f"{R03_BRANCH_ID} authority",
                        f"worker rule {rule.path} intersects integrator-shared {shared.path}",
                    )
        return branch, worker_rules, activation_evidence

    def validate_r03_projection(
        self, selector_modules: set[str]
    ) -> tuple[
        dict[str, Any] | None,
        dict[tuple[str, str], tuple[str, str]],
    ]:
        path = self.phase_dir / "projections/P0005.json"
        projection = self.read_json(path, self.relative(path))
        if projection is None:
            return None, {}
        exact_keys = {
            "schema_version",
            "record_kind",
            "phase_id",
            "projection_id",
            "wave_id",
            "base_checkpoint_id",
            "selector",
            "projection_graph",
            "combined_baseline",
            "expected_counts",
            "checker",
            "status",
            "superseded_by",
        }
        self.problems.require(
            set(projection) == exact_keys,
            self.relative(path),
            "must retain the strict generic baseline_projection schema",
        )
        for key, expected in {
            "schema_version": 1,
            "record_kind": "baseline_projection",
            "phase_id": PHASE_ID,
            "projection_id": R03_PROJECTION_ID,
            "wave_id": R03_WAVE_ID,
            "base_checkpoint_id": C0002_CHECKPOINT_ID,
            "status": (
                "retired"
                if self.current_checkpoint_id
                in {
                    C0003_CHECKPOINT_ID,
                    C0004_CHECKPOINT_ID,
                    C0005_CHECKPOINT_ID,
                    C0006_CHECKPOINT_ID,
                    C0007_CHECKPOINT_ID,
                    C0008_CHECKPOINT_ID,
                }
                else "active"
            ),
            "superseded_by": None,
            "expected_counts": R03_COUNTS,
        }.items():
            self.problems.require(
                projection.get(key) == expected,
                f"{R03_PROJECTION_ID}.{key}",
                f"expected {expected!r}, found {projection.get(key)!r}",
            )

        selector = projection.get("selector")
        selector_artifact = None
        if not isinstance(selector, dict) or set(selector) != {"kind", "artifact"}:
            self.problems.add(
                f"{R03_PROJECTION_ID}.selector", "expected exactly kind/artifact"
            )
        else:
            self.problems.require(
                selector.get("kind") == "module_path_tsv",
                f"{R03_PROJECTION_ID}.selector.kind",
                "expected module_path_tsv",
            )
            selector_artifact = self.artifact(
                selector.get("artifact"), f"{R03_PROJECTION_ID}.selector.artifact"
            )
        if selector_artifact is not None:
            self.problems.require(
                selector_artifact.path == R03_EVIDENCE_PATHS["selector"]
                and selector_artifact.sha256 == R03_SELECTOR_SHA256,
                f"{R03_PROJECTION_ID}.selector.artifact",
                "must pin exact C0002 R03 selector",
            )

        graph = self.artifact(
            projection.get("projection_graph"),
            f"{R03_PROJECTION_ID}.projection_graph",
        )
        declarations: dict[tuple[str, str], tuple[str, str]] = {}
        if graph is not None:
            self.problems.require(
                graph.path == R03_EVIDENCE_PATHS["projection_graph"]
                and graph.sha256 == R03_PROJECTION_SHA256,
                f"{R03_PROJECTION_ID}.projection_graph",
                f"must pin deterministic graph {R03_PROJECTION_SHA256}",
            )
            graph_path = self.root / graph.path
            counts = self.parse_projection_graph(graph_path, R03_PROJECTION_ID)
            self.problems.require(
                counts == R03_COUNTS,
                f"{R03_PROJECTION_ID}.expected_counts",
                f"expected exact format-2 counts {R03_COUNTS}, found {counts}",
            )
            try:
                with gzip.open(graph_path, "rb") as handle:
                    payload_sha = hashlib.sha256(handle.read()).hexdigest().upper()
            except (OSError, gzip.BadGzipFile) as error:
                self.problems.add(
                    f"{R03_PROJECTION_ID}.projection_graph",
                    f"cannot hash decompressed payload: {error}",
                )
            else:
                self.problems.require(
                    payload_sha == R03_PROJECTION_PAYLOAD_SHA256,
                    f"{R03_PROJECTION_ID}.projection_graph",
                    f"expected payload SHA-256 {R03_PROJECTION_PAYLOAD_SHA256}",
                )
            declarations = self.parse_projection_declarations(
                graph_path, R03_PROJECTION_ID
            )
            owners = {owner for owner, _name in declarations}
            self.problems.require(
                owners == selector_modules,
                f"{R03_PROJECTION_ID}.projection_graph",
                "every and only R03 selector owner must contribute declarations",
            )
            self.problems.require(
                Counter(visibility for _kind, visibility in declarations.values()).get(
                    "private", 0
                )
                == R03_PRIVATE_COUNT,
                f"{R03_PROJECTION_ID}.projection_graph",
                f"expected exact {R03_PRIVATE_COUNT} private declarations",
            )

        combined = self.artifact(
            projection.get("combined_baseline"),
            f"{R03_PROJECTION_ID}.combined_baseline",
        )
        if combined is not None:
            self.problems.require(
                combined.path == R03_EVIDENCE_PATHS["baseline"]
                and combined.sha256 == C0002_COMBINED_BASELINE_SHA256,
                f"{R03_PROJECTION_ID}.combined_baseline",
                "must use the exact official C0002 combined baseline",
            )

        checker = projection.get("checker")
        if not isinstance(checker, dict) or set(checker) != {"artifact", "arguments"}:
            self.problems.add(
                f"{R03_PROJECTION_ID}.checker",
                "expected exactly artifact/arguments",
            )
        else:
            checker_artifact = self.artifact(
                checker.get("artifact"), f"{R03_PROJECTION_ID}.checker.artifact"
            )
            if checker_artifact is not None:
                self.problems.require(
                    checker_artifact.path
                    == "tools/architecture/check_completion_phase_projection.py"
                    and checker_artifact.sha256 == NEXT_PROJECTION_CHECKER_SHA256,
                    f"{R03_PROJECTION_ID}.checker.artifact",
                    "must pin the exact private-aware projection checker",
                )
            destinations = R03_DESTINATIONS or frozenset()
            if R03_DESTINATIONS is None:
                self.problems.add(
                    f"{R03_PROJECTION_ID}.checker.arguments",
                    "PENDING_R03_DESTINATIONS: cannot ratchet allow-prefix vector",
                )
            private_map_sha = self.r03_expected_digest(
                "private_map", f"{R03_PROJECTION_ID}.checker.arguments"
            )
            expected_arguments = sorted(
                [f"--allow-module={module}" for module in selector_modules]
                + [
                    f"--allow-prefix={module_from_path(prefix)}."
                    for prefix in destinations
                    if prefix.startswith("NumStability/")
                ]
                + [
                    "--candidate=<candidate-format2.tsv>",
                    f"--candidate-sha256={R03_CANDIDATE_SHA256}",
                    f"--private-map-sha256={private_map_sha or '<pending>'}",
                    f"--private-map={R03_EVIDENCE_PATHS['private_map']}",
                    f"--projection-sha256={R03_PROJECTION_SHA256}",
                    f"--projection={R03_EVIDENCE_PATHS['projection_graph']}",
                ]
            )
            arguments = checker.get("arguments")
            self.problems.require(
                isinstance(arguments, list)
                and len(arguments) == len(set(arguments))
                and set(arguments) == set(expected_arguments),
                f"{R03_PROJECTION_ID}.checker.arguments",
                "checker vector must exactly and uniquely bind all owners, destinations, private map, and graph",
            )
        return projection, declarations

    def validate_r03_consumers(self) -> dict[str, set[str]]:
        path = self.phase_dir / "branches/B0005-consumers.tsv"
        header = (
            "record_kind",
            "direction",
            "consumer_module",
            "consumer_path",
            "consumer_scope",
            "consumer_wave",
            "target_wave",
            "target_owner",
            "relation",
            "edge_kind",
            "source_declaration",
            "targets",
            "witness",
            "details",
        )
        _, rows = self.read_tsv(path, self.relative(path), header)
        expected_counts = {
            "common_direct_project_dependency": 7,
            "owner_reachability": 47,
            "r03_external_declaration_consumer": 14287,
            "r03_module_consumer": 2058,
            "shared_direct_outside_consumer": 5,
        }
        counts = Counter(row.get("record_kind", "") for row in rows)
        self.problems.require(
            dict(counts) == expected_counts,
            self.relative(path),
            f"expected exact consumer/reachability row counts {expected_counts}",
        )
        identities = [tuple(row.get(column, "") for column in header) for row in rows]
        self.problems.require(
            len(identities) == len(set(identities)),
            self.relative(path),
            "consumer evidence rows must be unique",
        )
        reach = Counter(
            row.get("direction", "")
            for row in rows
            if row.get("record_kind") == "owner_reachability"
        )
        self.problems.require(
            reach
            == Counter(
                {
                    "R03->R07": R03_R07_OVERLAP_COUNTS[
                        "r03_to_r07_transitive_owner_pairs"
                    ],
                    "R07->R03": R03_R07_OVERLAP_COUNTS[
                        "r07_to_r03_transitive_owner_pairs"
                    ],
                }
            ),
            self.relative(path),
            "must contain exact 24/23 directed transitive owner-reachability rows",
        )
        self.problems.require(
            counts.get("common_direct_project_dependency", 0)
            == R03_R07_OVERLAP_COUNTS["common_direct_project_dependencies"]
            and counts.get("shared_direct_outside_consumer", 0)
            == R03_R07_OVERLAP_COUNTS["shared_outside_consumers"],
            self.relative(path),
            "must contain exact seven common dependencies and five shared outside consumers",
        )
        allowed_kinds = set(expected_counts)
        for index, row in enumerate(rows):
            row_context = f"{self.relative(path)}[{index}]"
            kind = row.get("record_kind", "")
            module = row.get("consumer_module", "")
            consumer_path = row.get("consumer_path", "")
            self.problems.require(
                kind in allowed_kinds
                and bool(module)
                and consumer_path == path_from_module(module),
                row_context,
                "consumer kind/module/path must be complete and canonical",
            )
            self.problems.require(
                DEFERRED_RE.search(" ".join(row.values())) is None,
                row_context,
                "consumer evidence may not contain deferred review text",
            )
            if kind == "owner_reachability":
                self.problems.require(
                    row.get("relation") == "transitive"
                    and bool(row.get("target_owner"))
                    and " -> " in row.get("witness", ""),
                    row_context,
                    "owner reachability requires a transitive target and concrete witness",
                )
            elif kind == "common_direct_project_dependency":
                self.problems.require(
                    row.get("target_wave") == "R03+R07"
                    and row.get("relation") == "direct_dependency",
                    row_context,
                    "common dependency must be a direct R03+R07 project dependency",
                )
            elif kind == "shared_direct_outside_consumer":
                self.problems.require(
                    row.get("target_wave") == "R03+R07"
                    and row.get("relation") == "direct_both",
                    row_context,
                    "shared outside consumer must directly consume both waves",
                )
            elif kind == "r03_module_consumer":
                self.problems.require(
                    row.get("target_wave") == R03_WAVE_ID
                    and row.get("relation") in {"direct", "transitive_only"},
                    row_context,
                    "R03 module consumer requires direct or transitive-only relation",
                )
            elif kind == "r03_external_declaration_consumer":
                self.problems.require(
                    row.get("target_wave") == R03_WAVE_ID
                    and row.get("relation") == "declaration_edge"
                    and row.get("edge_kind")
                    in {"signature", "body", "signature+body"}
                    and bool(row.get("source_declaration")),
                    row_context,
                    "external declaration consumer requires typed format-2 edge evidence",
                )
        return {
            "module_consumers": {
                row.get("consumer_module", "")
                for row in rows
                if row.get("record_kind") == "r03_module_consumer"
            },
            "external_consumer_modules": {
                row.get("consumer_module", "")
                for row in rows
                if row.get("record_kind") == "r03_external_declaration_consumer"
            },
            "shared_outside_consumers": {
                row.get("consumer_module", "")
                for row in rows
                if row.get("record_kind") == "shared_direct_outside_consumer"
            },
            "common_dependencies": {
                row.get("consumer_module", "")
                for row in rows
                if row.get("record_kind") == "common_direct_project_dependency"
            },
        }

    def validate_r03_routes_and_tests(
        self,
        selector: list[tuple[str, str]],
        inventory_by_path: dict[str, dict[str, str]],
        declarations: dict[tuple[str, str], tuple[str, str]],
        worker_rules: list[PathRule],
        consumer_sets: dict[str, set[str]],
    ) -> None:
        branch_dir = self.phase_dir / "branches"
        route_path = branch_dir / "B0005-declaration-routes.tsv"
        _, routes = self.read_tsv(
            route_path,
            self.relative(route_path),
            R03_DECLARATION_ROUTE_HEADER,
        )
        self.problems.require(
            len(routes) == R03_COUNTS["declarations"],
            self.relative(route_path),
            f"expected exact {R03_COUNTS['declarations']} declaration routes",
        )
        route_identities = [
            (
                row.get("baseline_owner_module", ""),
                row.get("baseline_declaration_name", ""),
            )
            for row in routes
        ]
        self.problems.require(
            len(route_identities) == len(set(route_identities))
            and set(route_identities) == set(declarations),
            self.relative(route_path),
            "routes must uniquely cover every and only projected declaration",
        )
        orders: dict[str, list[int]] = defaultdict(list)
        owner_destinations: dict[str, set[str]] = defaultdict(set)
        private_routes: dict[str, tuple[str, str]] = {}
        route_keys: list[tuple[str, int]] = []
        public_names: set[str] = set()
        for index, row in enumerate(routes):
            row_context = f"{self.relative(route_path)}[{index}]"
            owner = row.get("baseline_owner_module", "")
            name = row.get("baseline_declaration_name", "")
            destination = row.get("destination_module", "")
            expected = declarations.get((owner, name))
            if expected is not None:
                self.problems.require(
                    (row.get("kind", ""), row.get("visibility", "")) == expected,
                    row_context,
                    "kind/visibility must equal the frozen format-2 declaration",
                )
            try:
                order = int(row.get("baseline_order", ""))
                if order < 1:
                    raise ValueError
            except ValueError:
                self.problems.add(
                    f"{row_context}.baseline_order", "expected a positive integer"
                )
                order = 0
            orders[owner].append(order)
            route_keys.append((owner, order))
            owner_destinations[owner].add(destination)
            self.problems.require(
                row.get("route_class") in {"reusable", "source", "internal"},
                f"{row_context}.route_class",
                "R03 route class must be exactly reusable, source, or internal",
            )
            expected_decision = (
                "private_name_hash_pinned"
                if row.get("visibility") == "private"
                else "preserve_name_and_signature"
            )
            self.problems.require(
                row.get("normalization_decision") == expected_decision,
                f"{row_context}.normalization_decision",
                f"expected exact decision {expected_decision!r}",
            )
            self.problems.require(
                destination.startswith("NumStability.")
                and "Chapter72" not in destination,
                f"{row_context}.destination_module",
                "destination must be a reviewed NumStability module and may not use invalid Chapter72",
            )
            if row.get("visibility") == "private":
                self.problems.require(
                    name not in private_routes,
                    row_context,
                    f"duplicate private declaration {name}",
                )
                private_routes[name] = (owner, destination)
            else:
                public_names.add(name)
        self.problems.require(
            route_keys == sorted(route_keys),
            self.relative(route_path),
            "routes must be sorted by owner and frozen baseline order",
        )
        for owner, owner_orders in orders.items():
            self.problems.require(
                owner_orders == list(range(1, len(owner_orders) + 1)),
                self.relative(route_path),
                f"{owner} baseline_order must be a contiguous 1-based sequence",
            )
        self.problems.require(
            len(private_routes) == R03_PRIVATE_COUNT,
            self.relative(route_path),
            f"expected exact {R03_PRIVATE_COUNT} private declaration routes",
        )
        rump_destinations = owner_destinations.get(
            "NumStability.Algorithms.Higham726Rump", set()
        )
        self.problems.require(
            bool(rump_destinations)
            and all(
                destination.startswith(
                    "NumStability.Source.Higham.Chapter07.Equation26."
                )
                for destination in rump_destinations
            ),
            self.relative(route_path),
            "Higham726Rump must route only through Higham Chapter 7 Equation 26",
        )

        selector_by_module = {module: path for module, path in selector}
        projected_counts = Counter(owner for owner, _name in declarations)
        module_path = branch_dir / "B0005-module-routes.tsv"
        _, module_rows = self.read_tsv(
            module_path,
            self.relative(module_path),
            R03_MODULE_ROUTE_HEADER,
        )
        module_names = [row.get("owner_module", "") for row in module_rows]
        self.problems.require(
            module_names == sorted(selector_by_module)
            and set(module_names) == set(selector_by_module)
            and len(module_names) == R03_OWNER_COUNT,
            self.relative(module_path),
            "module routes must cover every selector owner once in sorted order",
        )
        mixed_count = 0
        missing_doc_count = 0
        noncanonical_count = 0
        umbrella_count = 0
        unclassified_count = 0
        semantic_classes: Counter[str] = Counter()
        for index, row in enumerate(module_rows):
            row_context = f"{self.relative(module_path)}[{index}]"
            owner = row.get("owner_module", "")
            selected_path = selector_by_module.get(owner, "")
            inventory_row = inventory_by_path.get(selected_path, {})
            self.problems.require(
                row.get("path") == selected_path
                and row.get("base_blob_oid") == inventory_row.get("base_blob_oid")
                and row.get("current_tier") == inventory_row.get("current_tier")
                and row.get("debt_flags") == inventory_row.get("debt_flags"),
                row_context,
                "path/blob/tier/debt flags must exactly mirror C0002 inventory",
            )
            flags = set(split_values(row.get("debt_flags", "")))
            unclassified_count += "unclassified_modules" in flags
            mixed_count += "mixed_modules" in flags
            missing_doc_count += "missing_module_docstrings" in flags
            noncanonical_count += "noncanonical_modules" in flags
            umbrella_count += "declaration_bearing_umbrellas" in flags
            try:
                declaration_count = int(row.get("declaration_count", ""))
            except ValueError:
                self.problems.add(
                    f"{row_context}.declaration_count", "expected an integer"
                )
                declaration_count = -1
            self.problems.require(
                declaration_count == projected_counts.get(owner, 0),
                f"{row_context}.declaration_count",
                f"expected exact projected count {projected_counts.get(owner, 0)}",
            )
            listed = split_values(row.get("destination_modules", ""))
            self.problems.require(
                listed == sorted(set(listed))
                and set(listed) == owner_destinations.get(owner, set()),
                f"{row_context}.destination_modules",
                f"must equal exact declaration destinations {sorted(owner_destinations.get(owner, set()))}",
            )
            semantic = row.get("semantic_classification", "")
            semantic_parts = (
                semantic.removeprefix("mixed_split_").split("_")
                if semantic.startswith("mixed_split_")
                else split_values(semantic)
            )
            semantic_classes.update(semantic_parts)
            self.problems.require(
                bool(semantic_parts)
                and set(semantic_parts) <= {"reusable", "source", "internal"},
                f"{row_context}.semantic_classification",
                "must explicitly classify declarations as reusable/source/internal",
            )
            if inventory_row.get("current_tier") == "mixed":
                routed_classes = {
                    route.get("route_class", "")
                    for route in routes
                    if route.get("baseline_owner_module") == owner
                }
                self.problems.require(
                    all(
                        bool(row.get(key, "").strip())
                        and DEFERRED_RE.search(row.get(key, "")) is None
                        for key in ("split_rationale", "dependency_rationale")
                    ),
                    row_context,
                    "each mixed owner requires an explicit declaration classification/split and dependency rationale",
                )
                self.problems.require(
                    set(semantic_parts) == (routed_classes - {"internal"})
                    and routed_classes <= {"reusable", "source", "internal"},
                    f"{row_context}.semantic_classification",
                    "mixed-owner module classification must equal its declaration-level reusable/source roles (internal support may be additional)",
                )
            # `approved_route_amendment` is accepted ONLY for the single owner whose
            # route the hash-pinned reviews/R03-route-amendment.md repairs: the fanIn7
            # private helper is used by both public declarations, so the pre-activation
            # split was uncompilable and the primary-human amended it post-activation.
            allowed_status = {"approved_before_activation"}
            if row.get("owner_module") == (
                "NumStability.Algorithms.HighamChapters1To9SourceClosure"
            ):
                allowed_status.add("approved_route_amendment")
            self.problems.require(
                bool(row.get("compatibility_action", "").strip())
                and DEFERRED_RE.search(row.get("compatibility_action", "")) is None
                and row.get("review_status") in allowed_status,
                row_context,
                "compatibility action must be explicit and primary-human reviewed "
                "(before activation, or via the pinned R03 route amendment)",
            )
        self.problems.require(
            {
                "unclassified_modules": unclassified_count,
                "mixed_modules": mixed_count,
                "missing_module_docstrings": missing_doc_count,
                "noncanonical_modules": noncanonical_count,
                "declaration_bearing_umbrellas": umbrella_count,
            }
            == R03_DEBT_COUNTS,
            self.relative(module_path),
            f"module route debt facts must equal {R03_DEBT_COUNTS}",
        )

        private_path = branch_dir / "B0005-private-normalization.tsv"
        _, private_rows = self.read_tsv(
            private_path, self.relative(private_path), R03_PRIVATE_HEADER
        )
        self.problems.require(
            len(private_rows) == R03_PRIVATE_COUNT,
            self.relative(private_path),
            f"expected exact {R03_PRIVATE_COUNT}-row private map",
        )
        old_names = [row.get("old_private", "") for row in private_rows]
        new_names = [row.get("new_private", "") for row in private_rows]
        self.problems.require(
            old_names == sorted(private_routes)
            and set(old_names) == set(private_routes)
            and len(new_names) == len(set(new_names)),
            self.relative(private_path),
            "private map must exactly cover projected private names with unique postimages",
        )
        for index, row in enumerate(private_rows):
            row_context = f"{self.relative(private_path)}[{index}]"
            old = row.get("old_private", "")
            new = row.get("new_private", "")
            owner, destination = private_routes.get(old, ("", ""))
            self.problems.require(
                row.get("destination_module") == destination,
                f"{row_context}.destination_module",
                f"expected routed destination {destination!r}",
            )
            expected_prefix = f"_private.{destination}."
            self.problems.require(
                bool(old)
                and bool(new)
                and (new == old if destination == owner else new.startswith(expected_prefix))
                and DEFERRED_RE.search(" ".join(row.values())) is None,
                row_context,
                "private normalization must be complete and use only the reviewed destination prefix",
            )

        closure_path = branch_dir / "B0005-private-closure.tsv"
        _, closure_rows = self.read_tsv(
            closure_path,
            self.relative(closure_path),
            R03_PRIVATE_CLOSURE_HEADER,
        )
        roles = Counter(row.get("closure_role", "") for row in closure_rows)
        selected_owner_rows = sum(
            row.get("selected_owner") == "yes" for row in closure_rows
        )
        self.problems.require(
            len(closure_rows) == R03_PRIVATE_CLOSURE_ROWS
            and roles
            == Counter(
                {
                    "private_seed": R03_PRIVATE_COUNT,
                    "reverse_dependent": R03_PRIVATE_REVERSE_DEPENDENTS,
                }
            )
            and selected_owner_rows == R03_PRIVATE_SELECTED_OWNER_ROWS,
            self.relative(closure_path),
            "private reverse closure must be exact 2,502 = 398 seeds + 2,104 dependents with 2,063 selected-owner rows",
        )
        closure_names = [row.get("declaration", "") for row in closure_rows]
        seeds = {
            row.get("declaration", "")
            for row in closure_rows
            if row.get("closure_role") == "private_seed"
        }
        self.problems.require(
            len(closure_names) == len(set(closure_names))
            and seeds == set(private_routes),
            self.relative(closure_path),
            "closure declarations must be unique and seeds must equal private-map domain",
        )
        for index, row in enumerate(closure_rows):
            role = row.get("closure_role", "")
            self.problems.require(
                row.get("visibility")
                == ("private" if role == "private_seed" else "public")
                and row.get("selected_owner") in {"yes", "no"},
                f"{self.relative(closure_path)}[{index}]",
                "closure role/visibility/selected-owner typing drifted",
            )

        test_path = branch_dir / "B0005-test-plan.tsv"
        _, test_rows = self.read_tsv(
            test_path, self.relative(test_path), R03_TEST_HEADER
        )
        pairs = [
            (row.get("test_class", ""), row.get("target", ""))
            for row in test_rows
        ]
        classes = {row.get("test_class", "") for row in test_rows}
        self.problems.require(
            pairs == sorted(pairs)
            and len(pairs) == len(set(pairs))
            and classes == R03_TEST_CLASSES,
            self.relative(test_path),
            f"test plan must be sorted/unique and cover exactly {sorted(R03_TEST_CLASSES)}",
        )
        by_class = {
            test_class: {
                row.get("target", "")
                for row in test_rows
                if row.get("test_class") == test_class
            }
            for test_class in R03_TEST_CLASSES
        }
        relocated_destinations = {
            destination
            for owner, destinations in owner_destinations.items()
            for destination in destinations
            if destination != owner
        }
        relocated_owners = {
            owner
            for owner, destinations in owner_destinations.items()
            if any(destination != owner for destination in destinations)
        }
        self.problems.require(
            by_class["old_only"] == relocated_owners,
            self.relative(test_path),
            "old-only tests must cover every and only relocated historical owners",
        )
        self.problems.require(
            by_class["canonical_only"] == relocated_destinations,
            self.relative(test_path),
            "canonical-only tests must cover every and only relocated destinations",
        )
        self.problems.require(
            by_class["focused"] == {"NumStabilityTest.Reorganization.R03.All"},
            self.relative(test_path),
            "focused plan must compile the exact R03 test umbrella",
        )
        protected_expected = (
            consumer_sets.get("module_consumers", set())
            | consumer_sets.get("external_consumer_modules", set())
        )
        self.problems.require(
            by_class["protected_consumer"] == protected_expected,
            self.relative(test_path),
            "protected-consumer tests must cover every exact module/declaration consumer",
        )
        self.problems.require(
            by_class["aggregate_entrypoint"]
            == {
                "NumStability",
                "NumStability.Algorithms",
                "NumStability.Analysis",
                "NumStability.Analysis.FloatingPointArithmetic",
                "NumStability.Source",
                "NumStability.Source.Higham",
                "NumStability.Source.Higham.Chapter12.IterativeRefinement",
            },
            self.relative(test_path),
            "aggregate/entry-point tests must equal the seven reviewed public entry points",
        )
        for index, row in enumerate(test_rows):
            purpose = row.get("purpose", "")
            self.problems.require(
                bool(purpose.strip()) and DEFERRED_RE.search(purpose) is None,
                f"{self.relative(test_path)}[{index}].purpose",
                "test purpose must be explicit and non-deferred",
            )

    def validate_r03_request(
        self,
        worker_rules: list[PathRule],
        consumer_sets: dict[str, set[str]],
    ) -> tuple[dict[str, Any] | None, set[str], set[str]]:
        request_dir = self.phase_dir / "requests"
        path = request_dir / "R0005.json"
        request = self.read_json(path, self.relative(path))
        if request is None:
            return None, set(), set()
        self.requests[R03_REQUEST_ID] = request
        exact_keys = {
            "schema_version",
            "record_kind",
            "phase_id",
            "request_id",
            "lane_id",
            "wave_id",
            "requester_id",
            "created_at",
            "target_checkpoint_id",
            "target_base_sha",
            "paths",
            "preimage_blobs",
            "rationale",
            "patch",
            "depends_on",
            "blocks",
            "valid_through_checkpoint_id",
            "status",
            "supersedes",
            "superseded_by",
            "resolution",
        }
        self.problems.require(
            set(request) == exact_keys,
            self.relative(path),
            "must retain the strict generic shared_file_request schema",
        )
        for key, expected in {
            "schema_version": 1,
            "record_kind": "shared_file_request",
            "phase_id": PHASE_ID,
            "request_id": R03_REQUEST_ID,
            "lane_id": R03_LANE_ID,
            "wave_id": R03_WAVE_ID,
            "requester_id": "primary-human",
            "target_checkpoint_id": C0002_CHECKPOINT_ID,
            "target_base_sha": C0002_CODE_SHA,
            "depends_on": [],
            "blocks": [R03_WAVE_ID],
            "valid_through_checkpoint_id": C0002_CHECKPOINT_ID,
            "status": (
                "applied"
                if self.current_checkpoint_id
                in {
                    C0003_CHECKPOINT_ID,
                    C0004_CHECKPOINT_ID,
                    C0005_CHECKPOINT_ID,
                    C0006_CHECKPOINT_ID,
                    C0007_CHECKPOINT_ID,
                    C0008_CHECKPOINT_ID,
                }
                else "active"
            ),
            "supersedes": None,
            "superseded_by": None,
        }.items():
            self.problems.require(
                request.get(key) == expected,
                f"{R03_REQUEST_ID}.{key}",
                f"expected {expected!r}, found {request.get(key)!r}",
            )
        created_at = request.get("created_at")
        self.problems.require(
            isinstance(created_at, str)
            and RFC3339_RE.fullmatch(created_at) is not None,
            f"{R03_REQUEST_ID}.created_at",
            "expected an RFC3339 primary-human authority timestamp",
        )
        raw_paths = request.get("paths")
        paths = (
            raw_paths
            if isinstance(raw_paths, list)
            and all(isinstance(item, str) for item in raw_paths)
            else []
        )
        self.problems.require(
            paths == sorted(set(paths)) and bool(paths),
            f"{R03_REQUEST_ID}.paths",
            "request paths must be a nonempty sorted unique string list",
        )
        if R03_REQUEST_PATH_COUNT is None or R03_REQUEST_PATH_SHA256 is None:
            self.problems.add(
                f"{R03_REQUEST_ID}.paths",
                "PENDING_R03_REQUEST: exact path count/digest is not ratcheted",
            )
        else:
            self.problems.require(
                len(paths) == R03_REQUEST_PATH_COUNT
                and path_list_sha256(paths) == R03_REQUEST_PATH_SHA256,
                f"{R03_REQUEST_ID}.paths",
                f"expected exact {R03_REQUEST_PATH_COUNT}-path set at {R03_REQUEST_PATH_SHA256}",
            )
        shared_exact = {
            rule.path for rule in self.shared_rules if rule.match == "exact"
        }
        unreserved = set(paths) - shared_exact
        if self.current_checkpoint_id in {
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            self.problems.require(
                len(unreserved) == 91 and len(set(paths) & shared_exact) == 30,
                f"{R03_REQUEST_ID}.paths",
                "accepted request must release exactly 91 request-only reservations "
                "and retain exactly 30 pre-existing controls",
            )
        else:
            self.problems.require(
                not unreserved,
                f"{R03_REQUEST_ID}.paths",
                f"active request paths lack exact shared reservations: {sorted(unreserved)}",
            )
        for requested in paths:
            requested_rule = PathRule(requested, "exact")
            for worker in worker_rules:
                self.problems.require(
                    not requested_rule.intersects(worker),
                    f"{R03_REQUEST_ID}.paths[{requested}]",
                    f"integrator request leaks into worker rule {worker.path}",
                )

        expected_preimages = [
            {"blob_oid": self.git_blob(C0002_CODE_SHA, requested), "path": requested}
            for requested in paths
        ]
        self.problems.require(
            request.get("preimage_blobs") == expected_preimages,
            f"{R03_REQUEST_ID}.preimage_blobs",
            "must exactly record sorted C0002 blob OIDs for every request path",
        )
        patch = self.artifact(request.get("patch"), f"{R03_REQUEST_ID}.patch")
        patch_expected = self.r03_expected_digest(
            "request_patch", f"{R03_REQUEST_ID}.patch"
        )
        patch_path: Path | None = None
        if patch is not None:
            self.problems.require(
                patch.path == R03_EVIDENCE_PATHS["request_patch"]
                and patch.sha256 == (patch_expected or "<pending>"),
                f"{R03_REQUEST_ID}.patch",
                "must pin the exact independently replayable R0005 patch",
            )
            patch_path = self.root / patch.path

        post_path = request_dir / "R0005-postimages.tsv"
        post_header, post_rows = self.read_tsv(
            post_path,
            self.relative(post_path),
            (
                "path",
                "preimage_blob_oid",
                "preimage_sha256",
                "postimage_sha256",
            ),
        )
        postimages = self.validate_postimage_rows(
            post_header,
            post_rows,
            self.relative(post_path),
            set(paths),
            "postimage_sha256",
            base_sha=C0002_CODE_SHA,
            base_label=C0002_CHECKPOINT_ID,
        )
        post_expected = self.r03_expected_digest(
            "request_postimages", self.relative(post_path)
        )
        if post_path.is_file() and post_expected is not None:
            self.problems.require(
                sha256_path(post_path) == post_expected,
                self.relative(post_path),
                f"expected exact postimage SHA-256 {post_expected}",
            )
        if patch_path is not None:
            self.materialize_patch_postimages(
                R03_REQUEST_ID,
                patch_path,
                set(paths),
                postimages,
                base_sha=C0002_CODE_SHA,
                base_label=C0002_CHECKPOINT_ID,
                unidiff_zero=True,
            )

        replacement_path = request_dir / "R0005-replacements.tsv"
        replacement_header, replacement_rows = self.read_tsv(
            replacement_path, self.relative(replacement_path)
        )
        allowed_headers = {
            ("old_import", "new_import", "path", "occurrences"),
            ("path", "old_import", "new_import", "occurrences"),
            ("path", "old_import", "old_occurrences", "new_imports"),
            (
                "consumer_path",
                "preimage_blob_oid",
                "old_import",
                "new_import",
            ),
        }
        self.problems.require(
            tuple(replacement_header) in allowed_headers,
            self.relative(replacement_path),
            "replacement TSV must use an approved exact import-replacement schema",
        )
        replacement_paths: list[str] = []
        replacement_keys: list[tuple[str, str, str]] = []
        for index, row in enumerate(replacement_rows):
            row_context = f"{self.relative(replacement_path)}[{index}]"
            replacement_path_value = row.get("path") or row.get("consumer_path", "")
            old_import = row.get("old_import", "")
            new_import = row.get("new_import") or row.get("new_imports", "")
            new_import_values = split_values(new_import)
            replacement_paths.append(replacement_path_value)
            replacement_keys.append(
                (replacement_path_value, old_import, new_import)
            )
            self.problems.require(
                replacement_path_value in set(paths)
                and bool(old_import)
                and bool(new_import_values)
                and old_import not in new_import_values
                and new_import_values == sorted(set(new_import_values)),
                row_context,
                "replacement must name a requested path and sorted distinct old/new imports",
            )
            occurrence_field = (
                "occurrences" if "occurrences" in row else "old_occurrences"
            )
            if occurrence_field in row:
                try:
                    occurrence_count = int(row.get(occurrence_field, ""))
                except ValueError:
                    occurrence_count = 0
                self.problems.require(
                    occurrence_count > 0,
                    f"{row_context}.{occurrence_field}",
                    "occurrence count must be a positive integer",
                )
            if "preimage_blob_oid" in row:
                self.problems.require(
                    row.get("preimage_blob_oid")
                    == self.git_blob(C0002_CODE_SHA, replacement_path_value),
                    f"{row_context}.preimage_blob_oid",
                    "replacement must pin exact C0002 consumer blob",
                )
        self.problems.require(
            replacement_keys == sorted(set(replacement_keys))
            and bool(replacement_rows),
            self.relative(replacement_path),
            "replacement rows must be nonempty, sorted, and unique",
        )
        expected_consumer_paths = {
            path_from_module(module)
            for module in consumer_sets.get("module_consumers", set())
        }
        self.problems.require(
            set(replacement_paths) <= expected_consumer_paths,
            self.relative(replacement_path),
            "every replacement path must be an exact graph-derived R03 consumer",
        )

        if self.current_checkpoint_id in {
            C0003_CHECKPOINT_ID,
            C0004_CHECKPOINT_ID,
            C0005_CHECKPOINT_ID,
            C0006_CHECKPOINT_ID,
            C0007_CHECKPOINT_ID,
            C0008_CHECKPOINT_ID,
        }:
            resolution = request.get("resolution")
            if not isinstance(resolution, dict):
                self.problems.add(
                    f"{R03_REQUEST_ID}.resolution", "expected an object"
                )
            else:
                resolved_at = resolution.get("resolved_at")
                expected_without_time = {
                    "checkpoint_id": C0003_CHECKPOINT_ID,
                    "commit_sha": C0003_CODE_SHA,
                    "reason": R03_ACCEPTED_RESOLUTION_REASON,
                    "resolved_by": "primary-human",
                    "validation_evidence": [
                        {
                            "path": (
                                f"{R03_PHASE_PREFIX}/checkpoints/C0003-gates.md"
                            ),
                            "sha256": C0003_GATES_SHA256,
                        }
                    ],
                }
                actual_without_time = {
                    key: value
                    for key, value in resolution.items()
                    if key != "resolved_at"
                }
                self.problems.require(
                    actual_without_time == expected_without_time
                    and isinstance(resolved_at, str)
                    and RFC3339_RE.fullmatch(resolved_at) is not None,
                    f"{R03_REQUEST_ID}.resolution",
                    "applied request must record exact C0003/e20 resolution, reason, "
                    "gate evidence, primary-human authority, and RFC3339 time",
                )
        else:
            expected_resolution = {
                "checkpoint_id": None,
                "commit_sha": None,
                "reason": None,
                "resolved_at": None,
                "resolved_by": None,
                "validation_evidence": [],
            }
            self.problems.require(
                request.get("resolution") == expected_resolution,
                f"{R03_REQUEST_ID}.resolution",
                "planned request must remain active and completely unresolved",
            )
        rationale = str(request.get("rationale", "")).upper()
        rationale_digests = [
            R03_REQUEST_PATH_SHA256,
            patch_expected,
            post_expected,
            self.r03_expected_digest(
                "request_replacements", f"{R03_REQUEST_ID}.rationale"
            ),
        ]
        for digest in rationale_digests:
            if digest is not None and digest not in rationale:
                self.problems.add(
                    f"{R03_REQUEST_ID}.rationale",
                    f"must hash-pin exact SHA-256 {digest}",
                )
        self.problems.require(
            C0002_CODE_SHA.upper() in rationale,
            f"{R03_REQUEST_ID}.rationale",
            "must name the exact C0002 preimage",
        )
        branch = self.branch_records.get(R03_BRANCH_ID, {})
        self.problems.require(
            branch.get("shared_request_ids") == [R03_REQUEST_ID],
            f"{R03_BRANCH_ID}.shared_request_ids",
            f"expected exactly [{R03_REQUEST_ID!r}]",
        )
        return request, set(paths), unreserved

    def validate_r03_reviews(self) -> None:
        required_artifacts = {
            "selection_review": (
                "c0002",
                C0002_CODE_SHA,
                "r03",
                "r07",
                "singleton",
                "defer",
                "m03",
                "m05",
                "m06",
                "24",
                "23",
                "7",
                "5",
                R03_SELECTOR_SHA256.casefold(),
            ),
            "route_review": (
                "primary-human",
                "r03",
                "c0002",
                C0002_CODE_SHA,
                "higham726rump",
                "chapter72",
                "chapter07",
                "equation26",
                "public",
                "signature",
                "private",
                "mixed",
            ),
            "projection_replay": (
                "c0002",
                C0002_CODE_SHA,
                "r03",
                R03_SELECTOR_SHA256.casefold(),
                R03_PROJECTION_SHA256.casefold(),
                R03_PROJECTION_PAYLOAD_SHA256.casefold(),
                str(R03_COUNTS["declarations"]),
                str(R03_COUNTS["signature_edges"]),
                str(R03_COUNTS["body_edges"]),
                str(R03_COUNTS["union_edges"]),
                "reverse",
            ),
            "overlap_review": (
                "c0002",
                C0002_CODE_SHA,
                "r03",
                "r07",
                "singleton",
                "24",
                "23",
                "7",
                "5",
                R03_SELECTOR_SHA256.casefold(),
                R03_PROJECTION_SHA256.casefold(),
            ),
        }
        for key, tokens in required_artifacts.items():
            path = self.root / R03_EVIDENCE_PATHS[key]
            try:
                text = path.read_text(encoding="utf-8")
            except (OSError, UnicodeError) as error:
                self.problems.add(
                    R03_EVIDENCE_PATHS[key], f"cannot read reviewed evidence: {error}"
                )
                continue
            folded = " ".join(text.casefold().replace("_", "-").split())
            for token in tokens:
                if token.casefold() not in folded:
                    self.problems.add(
                        R03_EVIDENCE_PATHS[key],
                        f"missing exact reviewed token {token!r}",
                    )
            if key in {"route_review", "projection_replay"}:
                self.problems.require(
                    re.search(
                        r"\b(?:tbd|todo|pending|unreviewed|undecided|worker decides|decide later)\b",
                        text,
                        re.IGNORECASE,
                    )
                    is None,
                    R03_EVIDENCE_PATHS[key],
                    "R03 route/projection decisions may not remain deferred",
                )
        route_text_path = self.root / R03_EVIDENCE_PATHS["route_review"]
        try:
            route_text = route_text_path.read_text(encoding="utf-8").casefold()
        except (OSError, UnicodeError):
            route_text = ""
        self.problems.require(
            "chapter72" in route_text
            and any(
                token in route_text
                for token in ("invalid", "reject", "forbidden", "not a valid")
            )
            and "chapter07" in route_text
            and "equation26" in route_text,
            R03_EVIDENCE_PATHS["route_review"],
            "must explicitly reject Chapter72 and freeze Chapter07 Equation26",
        )

    def validate_r03_ref_and_worktree_absence(self) -> None:
        """Check only local state; remote absence remains hash-pinned review evidence."""

        ref = self.git("show-ref", "--verify", "--quiet", R03_REMOTE_REF, check=False)
        self.problems.require(
            ref.returncode == 1,
            "R03 pre-activation ref",
            f"planned epoch must not create local {R03_REMOTE_REF}",
        )
        if os.name == "nt":
            worktree = Path(R03_PLANNED_WORKTREE)
            self.problems.require(
                not worktree.exists(),
                "R03 pre-activation worktree",
                f"planned epoch must not create {R03_PLANNED_WORKTREE}",
            )

    def validate_r03_activation_review(self) -> None:
        """Validate hash-pinned external ref/worktree facts without requiring local state."""

        path = self.root / R03_ACTIVATION_REVIEW_PATH
        if not path.is_file():
            self.problems.add(
                R03_ACTIVATION_REVIEW_PATH,
                "active R03 epoch requires the activation review",
            )
            return
        self.problems.require(
            sha256_path(path) == R03_ACTIVATION_REVIEW_SHA256,
            R03_ACTIVATION_REVIEW_PATH,
            f"expected exact activation review SHA-256 {R03_ACTIVATION_REVIEW_SHA256}",
        )
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            self.problems.add(
                R03_ACTIVATION_REVIEW_PATH,
                f"cannot read activation review: {error}",
            )
            return
        validate_r03_activation_review_text(text, self.problems)

    def validate_milestone_dag(self) -> None:
        path = self.phase_dir / "reviews/milestone-dag.tsv"
        header, rows = self.read_tsv(path, self.relative(path))
        edge_columns = {
            "importer_wave",
            "imported_wave",
            "direct_module_edges",
            "milestone_dependency",
            "reviewed_ordering_decision",
        }
        summary_columns = {
            "milestone_id",
            "wave_id",
            "depends_on",
            "direct_import_quotient_edges",
            "reviewed_ordering_decision",
        }
        edge_mode = edge_columns <= set(header)
        summary_mode = summary_columns <= set(header)
        if not edge_mode and not summary_mode:
            self.problems.add(
                self.relative(path),
                "milestone DAG requires either the edge-level or milestone-summary schema",
            )
            return
        scope_waves = {
            row.get("wave_id", "")
            for row in self.scope
            if row.get("phase_scope") == "in_scope"
        }
        worker_waves = scope_waves - {"I01"}
        phase_milestones = self.phase.get("milestones")
        if not isinstance(phase_milestones, list):
            self.problems.add("phase.json.milestones", "expected a list")
            return
        wave_to_milestone: dict[str, str] = {}
        dependencies: dict[str, set[str]] = {}
        for index, item in enumerate(phase_milestones):
            if not isinstance(item, dict):
                self.problems.add(f"phase.json.milestones[{index}]", "expected an object")
                continue
            milestone = item.get("milestone_id")
            waves = item.get("wave_ids")
            deps = item.get("depends_on")
            if not isinstance(milestone, str) or not isinstance(waves, list) or not isinstance(deps, list):
                self.problems.add(
                    f"phase.json.milestones[{index}]",
                    "requires milestone_id, wave_ids, and depends_on",
                )
                continue
            dependencies[milestone] = {value for value in deps if isinstance(value, str)}
            for wave in waves:
                if not isinstance(wave, str) or wave in wave_to_milestone:
                    self.problems.add(
                        f"phase.json.milestones[{index}]",
                        f"invalid or duplicate wave {wave!r}",
                    )
                else:
                    wave_to_milestone[wave] = milestone
        self.problems.require(
            set(wave_to_milestone) == scope_waves,
            "phase.json.milestones",
            f"milestones must cover every in-scope wave; missing={sorted(scope_waves-set(wave_to_milestone))}, extra={sorted(set(wave_to_milestone)-scope_waves)}",
        )
        known_milestones = set(dependencies)
        for milestone, deps in dependencies.items():
            unknown = deps - known_milestones
            if unknown:
                self.problems.add(self.relative(path), f"{milestone} has unknown dependencies {sorted(unknown)}")
        self.check_acyclic(dependencies, self.relative(path))
        live_edges = self.live_wave_import_edges(
            worker_waves,
            commit=(
                R07_ACCEPTED_CONTROL_SHA
                if (self.root / R07_INTEGRATION_AUTHORIZATION_PATH).is_file()
                else None
            ),
        )
        declared_edges: Counter[tuple[str, str]] = Counter()
        if edge_mode:
            edge_rows = [
                (index, row)
                for index, row in enumerate(rows)
                if row.get("importer_wave", "") not in {"", "-"}
            ]
            for index, row in edge_rows:
                importer = row.get("importer_wave", "")
                imported = row.get("imported_wave", "")
                context = f"{self.relative(path)}[{index}]"
                try:
                    count = int(row.get("direct_module_edges", ""))
                except ValueError:
                    count = 0
                self.record_dag_edge(
                    declared_edges,
                    importer,
                    imported,
                    count,
                    row.get("reviewed_ordering_decision", ""),
                    context,
                    worker_waves,
                    wave_to_milestone,
                    dependencies,
                    row.get("milestone_dependency", ""),
                )
        else:
            for index, row in enumerate(rows):
                context = f"{self.relative(path)}[{index}]"
                decision = row.get("reviewed_ordering_decision", "")
                if not decision or DEFERRED_RE.search(decision):
                    self.problems.add(context, "ordering decision must be explicit before activation")
                value = row.get("direct_import_quotient_edges", "")
                if value in {"", "-"}:
                    continue
                for encoded in split_values(value):
                    match = re.fullmatch(r"(R\d{2})->(R\d{2}):(\d+)", encoded)
                    if match is None:
                        self.problems.add(
                            context,
                            f"invalid direct-import quotient edge {encoded!r}",
                        )
                        continue
                    importer, imported, count_text = match.groups()
                    importer_milestone = wave_to_milestone.get(importer)
                    imported_milestone = wave_to_milestone.get(imported)
                    dependency_text = ""
                    if (
                        imported_milestone
                        and importer_milestone in dependencies.get(imported_milestone, set())
                    ):
                        dependency_text = f"{imported_milestone} depends on {importer_milestone}"
                    elif (
                        importer_milestone
                        and imported_milestone in dependencies.get(importer_milestone, set())
                    ):
                        dependency_text = f"{importer_milestone} depends on {imported_milestone}"
                    self.record_dag_edge(
                        declared_edges,
                        importer,
                        imported,
                        int(count_text),
                        decision,
                        context,
                        worker_waves,
                        wave_to_milestone,
                        dependencies,
                        dependency_text,
                    )
        if declared_edges != live_edges:
            self.problems.add(
                self.relative(path),
                "edge ledger must exactly equal live direct-import quotient; "
                f"missing={sorted((live_edges-declared_edges).items())}, "
                f"extra={sorted((declared_edges-live_edges).items())}",
            )
        milestone_columns = {"milestone_id", "wave_id", "depends_on"}
        if milestone_columns <= set(header):
            declared_milestones: dict[str, tuple[str, set[str]]] = {}
            for index, row in enumerate(rows):
                milestone = row.get("milestone_id", "")
                if milestone in {"", "-"}:
                    continue
                wave = row.get("wave_id", "")
                if milestone in declared_milestones or wave in {"", "-"}:
                    self.problems.add(
                        f"{self.relative(path)}[{index}]",
                        "milestone summary rows require unique milestone_id and wave_id",
                    )
                    continue
                declared_milestones[milestone] = (
                    wave,
                    set(split_values(row.get("depends_on", ""))),
                )
            expected_milestones = {
                milestone: (
                    next(wave for wave, owner in wave_to_milestone.items() if owner == milestone),
                    deps,
                )
                for milestone, deps in dependencies.items()
            }
            self.problems.require(
                declared_milestones == expected_milestones,
                self.relative(path),
                "milestone summary rows must exactly reproduce phase.json",
            )
        for wave in ("R01", "R02"):
            milestone = wave_to_milestone.get(wave)
            if milestone is not None and dependencies.get(milestone):
                self.problems.add(
                    self.relative(path),
                    f"activation wave {wave} must have no unaccepted successor dependencies",
                )

    def record_dag_edge(
        self,
        declared_edges: Counter[tuple[str, str]],
        importer: str,
        imported: str,
        count: int,
        decision: str,
        context: str,
        worker_waves: set[str],
        wave_to_milestone: dict[str, str],
        dependencies: dict[str, set[str]],
        dependency_text: str,
    ) -> None:
        if importer not in worker_waves or imported not in worker_waves or importer == imported:
            self.problems.add(context, "edge waves must be distinct known worker waves")
            return
        if count < 1:
            self.problems.add(context, "direct module-edge count must be positive")
            return
        declared_edges[importer, imported] += count
        if not decision or DEFERRED_RE.search(decision):
            self.problems.add(context, "ordering decision must be explicit before activation")
        match = re.fullmatch(r"(M\d{2}) depends on (M\d{2})", dependency_text)
        if match is None:
            self.problems.add(
                context,
                "direct-import endpoints must have a reviewed milestone dependency in one direction",
            )
            return
        milestone, dependency = match.groups()
        if dependency not in dependencies.get(milestone, set()):
            self.problems.add(
                context,
                f"{dependency_text} is absent from phase.json milestone dependencies",
            )
        endpoint_milestones = {
            wave_to_milestone.get(importer),
            wave_to_milestone.get(imported),
        }
        if {milestone, dependency} != endpoint_milestones:
            self.problems.add(
                context,
                "milestone dependency must order the two direct-import endpoint waves",
            )

    def check_acyclic(self, graph: dict[str, set[str]], context: str) -> None:
        visiting: set[str] = set()
        visited: set[str] = set()

        def visit(node: str) -> None:
            if node in visiting:
                self.problems.add(context, f"milestone dependency cycle includes {node}")
                return
            if node in visited:
                return
            visiting.add(node)
            for dependency in graph.get(node, set()):
                if dependency in graph:
                    visit(dependency)
            visiting.remove(node)
            visited.add(node)

        for node in graph:
            visit(node)

    def live_wave_import_edges(
        self, worker_waves: set[str], *, commit: str | None = None
    ) -> Counter[tuple[str, str]]:
        path_to_wave = {
            row["path"]: row["wave_id"]
            for row in self.scope
            if row.get("phase_scope") == "in_scope" and row.get("wave_id") in worker_waves
        }
        module_to_path = {module_from_path(path): path for path in path_to_wave}
        quotient: Counter[tuple[str, str]] = Counter()
        historical_payloads: dict[str, bytes] = {}
        if commit is not None:
            tree_blobs = self.git_tree_blobs(commit)
            path_oids = {
                path: tree_blobs[path]
                for path in path_to_wave
                if path in tree_blobs
            }
            blob_payloads = self.git_blob_payloads(
                path_oids.values(), "milestone immutable import graph"
            )
            historical_payloads = {
                path: blob_payloads[oid]
                for path, oid in path_oids.items()
                if oid in blob_payloads
            }
        for path, wave in path_to_wave.items():
            if commit is None:
                source = self.root / path
                try:
                    text = source.read_text(encoding="utf-8-sig", errors="replace")
                except OSError as error:
                    self.problems.add(
                        "milestone import graph", f"cannot read {path}: {error}"
                    )
                    continue
            else:
                payload = historical_payloads.get(path)
                if payload is None:
                    self.problems.add(
                        "milestone import graph",
                        f"cannot read {path} at immutable control {commit}",
                    )
                    continue
                text = payload.decode("utf-8-sig", errors="replace")
            for imported in IMPORT_RE.findall(remove_lean_comments(text)):
                target = module_to_path.get(imported)
                if target is None:
                    continue
                target_wave = path_to_wave[target]
                if target_wave != wave:
                    quotient[wave, target_wave] += 1
        return quotient



def allowed_codex_lane_operator_sets(
    checkpoint_id: str | None,
    base_expected: tuple[str, ...],
    authorization_valid: bool,
) -> set[tuple[str, ...]]:
    """Operator sets codex-lane may legitimately carry at `checkpoint_id`.

    The R09/R10 planned control may additionally carry the reviewed
    B0012-scoped pair, but only at C0006 and only while
    reviews/R10-operator-authorization.md is present with its exact pinned
    bytes, so the executable allowance cannot outlive its governance record.
    """
    allowed = {base_expected}
    if checkpoint_id == C0006_CHECKPOINT_ID and authorization_valid:
        allowed.add(R09R10_OPERATOR_PAIR)
    return allowed

