def parse_args(argv: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--phase-dir",
        type=Path,
        default=DEFAULT_PHASE_DIR,
        help=f"successor phase directory (default: {DEFAULT_PHASE_DIR.as_posix()})",
    )
    parser.add_argument(
        "--self-test",
        action="store_true",
        help="run isolated positive/negative helper tests without phase artifacts",
    )
    return parser.parse_args(argv)


def main(argv: Sequence[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    if args.self_test:
        return run_self_test()
    validator = CompletionValidator(ROOT, args.phase_dir)
    problems = validator.run()
    if problems.messages:
        for message in problems.messages:
            print(f"completion phase violation: {message}", file=sys.stderr)
        print(
            f"completion phase failed with {len(problems.messages)} violation(s)",
            file=sys.stderr,
        )
        return 1
    r07_lifecycle = {
        "planned": "planned controls",
        "active": (
            "active six-path activation control with exact planned-CI/ref/worktree evidence"
        ),
        "delivered": (
            "delivered-but-unaccepted immutable 166-path true merge plus exact "
            "R0011/correction integration control"
        ),
        "integrated": (
            "CI-attested integrated code with B0010 still delivered/unaccepted, "
            "P0010 active, and R0011 active/unresolved"
        ),
    }.get(validator.r07_state, validator.r07_state)
    print(
        f"completion phase passed: {validator.current_checkpoint_id} control state, "
        "C0000-pinned 2,593-row freeze, 492-row scope, exact R01/R02 98/145-path "
        "delivery evidence, projections, routes, private closure, tests, "
        "overlap proofs, postimages, reviewed union, milestone DAG, and exact "
        "C0001-pinned synchronous R11/R12 planned/active/delivered or C0002-C0004 "
        "accepted/retired controls with exact checkpoint evidence; plus the singleton "
        "exact-C0002 B0005/P0005/R0005 planned/active or C0003 accepted/retired R03 "
        "epoch with corrected 115+6 request identity and 21 bounded follow-ups; plus "
        "the C0003-rooted R05/R06 pair epoch through C0004 acceptance/retirement, the "
        "five-artifact R0008 amendment through exact application, its four-path predecessor "
        "SHA chain, and the C0004 61-union/27-amendment terminal postimage ratchet; plus "
        "the exact-C0004 planned/active/delivered B0008/P0008/R0009 and "
        "B0009/P0009/R0010 pair through exact C0005 synchronous acceptance, its reviewed "
        "37-path common-base union and migration re-anchor, retired projections, applied "
        "requests, restored shared-path reservations, due branch retirement, M07 readiness, "
        "and exact integrated-code ancestry of live HEAD"
        + (
        f"; plus authenticated exact-C0005 B0010/P0010/R0011 {r07_lifecycle}, "
            "semantic routes/private closure/DAG/supply/tests, 46-path disposable-index "
            "replay, 191-exact/five-prefix reservations, and R09=72/R10=18 queue"
            if validator.r07_contract is not None
            else ""
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
